/**
 * ADR-323 — typed memory provenance. Regression guard for the
 * `--provenance` / `--provenance-filter` wiring added to `memory store` /
 * `memory search`, plus the crash discovered while implementing it: an
 * earlier version of the provenance-filtered search path skipped the
 * RaBitQ/HNSW acceleration branches entirely, which crashed the CLI process
 * on exit (a libuv assertion on Windows) even though it printed correct
 * results first. The fix keeps those branches unconditional and applies the
 * provenance filter as a lookup within/after them instead of skipping them.
 *
 * Real end-to-end guard: drives the built CLI in a temp cwd exactly like a
 * user would, because the crash only reproduced through the actual CLI
 * process (not under the vitest/module-import transform).
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { dirname } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const CLI = join(HERE, '..', 'bin', 'cli.js');
const CLI_BUILT = existsSync(CLI);

function run(args: string[], cwd: string): { stdout: string; exit: number | null } {
  try {
    const stdout = execFileSync('node', [CLI, ...args], {
      cwd,
      encoding: 'utf-8',
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: 60_000,
    });
    return { stdout, exit: 0 };
  } catch (err) {
    const e = err as { status?: number | null; stdout?: Buffer; stderr?: Buffer };
    return {
      stdout: (e.stdout?.toString() ?? '') + (e.stderr?.toString() ?? ''),
      exit: e.status ?? null,
    };
  }
}

function searchJson(query: string, cwd: string, extraArgs: string[] = []) {
  const { stdout } = run(['memory', 'search', '-q', query, '-n', 'adr323', '--threshold', '0.05', '--format', 'json', ...extraArgs], cwd);
  const start = stdout.indexOf('{');
  expect(start).toBeGreaterThanOrEqual(0);
  return JSON.parse(stdout.slice(start)) as { results: Array<{ key: string; provenanceType?: string }> };
}

describe.skipIf(!CLI_BUILT)('ADR-323 typed memory provenance', () => {
  let workdir: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'ruflo-adr323-'));
    run(['memory', 'init'], workdir);
    run(['memory', 'store', '-k', 'user/goal', '-n', 'adr323', '--value', 'ship the deploy by Friday', '--provenance', 'user_claim'], workdir);
    run(['memory', 'store', '-k', 'agent/plan', '-n', 'adr323', '--value', 'deploy plan generated by planner agent', '--provenance', 'agent_output'], workdir);
    run(['memory', 'store', '-k', 'tool/deploy', '-n', 'adr323', '--value', 'deploy status reported by tool', '--provenance', 'tool_result'], workdir);
    run(['memory', 'store', '-k', 'misc/note', '-n', 'adr323', '--value', 'deploy notes without explicit provenance'], workdir);
  }, 60_000);

  afterAll(() => {
    try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it('store rejects an invalid --provenance value with a non-zero exit', () => {
    const { stdout, exit } = run(
      ['memory', 'store', '-k', 'bad/entry', '-n', 'adr323', '--value', 'x', '--provenance', 'not_a_real_type'],
      workdir,
    );
    expect(exit).not.toBe(0);
    expect(stdout.toLowerCase()).toMatch(/provenance/);
  });

  it('an entry stored without --provenance defaults to "unknown"', () => {
    const r = searchJson('notes', workdir);
    const entry = r.results.find(x => x.key === 'misc/note');
    expect(entry).toBeDefined();
    expect(entry!.provenanceType).toBe('unknown');
  });

  it('search with no --provenance-filter returns entries of every provenance type', () => {
    const r = searchJson('deploy', workdir);
    const keys = r.results.map(x => x.key);
    expect(keys).toContain('user/goal');
    expect(keys).toContain('agent/plan');
    expect(keys).toContain('misc/note');
  });

  it('persists explicit provenance through the native bridge and HNSW refresh', () => {
    const r = searchJson('deploy', workdir);
    expect(r.results.find(x => x.key === 'user/goal')?.provenanceType).toBe('user_claim');
    expect(r.results.find(x => x.key === 'agent/plan')?.provenanceType).toBe('agent_output');
    expect(r.results.find(x => x.key === 'tool/deploy')?.provenanceType).toBe('tool_result');
  });

  it('--provenance-filter user_claim returns only the user-claim entry', () => {
    const r = searchJson('deploy', workdir, ['--provenance-filter', 'user_claim']);
    const keys = r.results.map(x => x.key);
    expect(keys).toContain('user/goal');
    expect(keys).not.toContain('agent/plan');
    expect(keys).not.toContain('misc/note');
  });

  it('--provenance-filter accepts a comma-separated list (OR semantics)', () => {
    const r = searchJson('deploy', workdir, ['--provenance-filter', 'agent_output,tool_result']);
    const keys = r.results.map(x => x.key);
    expect(keys).toContain('agent/plan');
    expect(keys).not.toContain('user/goal');
    expect(keys).not.toContain('misc/note');
  });

  it('enforces provenance filtering in keyword and hybrid modes', () => {
    for (const searchType of ['keyword', 'hybrid']) {
      const r = searchJson('deploy', workdir, ['--type', searchType, '--provenance-filter', 'tool_result']);
      const keys = r.results.map(x => x.key);
      expect(keys).toContain('tool/deploy');
      expect(keys).not.toContain('user/goal');
      expect(keys).not.toContain('agent/plan');
      expect(keys).not.toContain('misc/note');
    }
  });

  it('enforces provenance filtering inside SmartRetrieval query expansion', () => {
    const r = searchJson('deploy', workdir, ['--smart', '--provenance-filter', 'user_claim']);
    const keys = r.results.map(x => x.key);
    expect(keys).toContain('user/goal');
    expect(keys).not.toContain('agent/plan');
    expect(keys).not.toContain('tool/deploy');
    expect(keys).not.toContain('misc/note');
  });

  it('preserves an existing provenance type when an upsert omits the flag', () => {
    const updated = run(
      ['memory', 'store', '-k', 'agent/plan', '-n', 'adr323', '--value', 'updated deploy plan'],
      workdir,
    );
    expect(updated.exit).toBe(0);
    const r = searchJson('updated deploy', workdir, ['--provenance-filter', 'agent_output']);
    const entry = r.results.find(x => x.key === 'agent/plan');
    expect(entry).toBeDefined();
    expect(entry?.provenanceType).toBe('agent_output');
  });

  it('search rejects an invalid --provenance-filter value with a non-zero exit', () => {
    const { stdout, exit } = run(
      ['memory', 'search', '-q', 'deploy', '-n', 'adr323', '--provenance-filter', 'not_a_type', '--format', 'json'],
      workdir,
    );
    expect(exit).not.toBe(0);
    expect(stdout.toLowerCase()).toMatch(/provenance/);
  });

  // Regression for the crash found during implementation: a
  // provenance-filtered search must exit cleanly (code 0), not just print
  // correct JSON and then crash on process teardown.
  it('a provenance-filtered search exits cleanly, run repeatedly', () => {
    for (let i = 0; i < 3; i++) {
      const { exit } = run(
        ['memory', 'search', '-q', 'deploy', '-n', 'adr323', '--threshold', '0.05', '--provenance-filter', 'user_claim', '--format', 'json'],
        workdir,
      );
      expect(exit).toBe(0);
    }
  });
});

/**
 * advisor-tip.ts — ADR-316 co-pilot advisor tip.
 *
 * Every test injects a fake FableHarness-shaped object (or a fully
 * constructed FableHarness with an injected spawnClaude) so no test ever
 * shells out to `claude` or spends a cent. Coverage:
 *   • consent gate (never refreshes without 'advisor-tips' consent)
 *   • TTL gate (never re-spends within ADVISOR_REFRESH_TTL_MS)
 *   • cache read/write shape, including the "no-tip" case (still stamps
 *     _ts so a "nothing to say" answer isn't re-asked all window long)
 *   • readAdvisorTip() is a pure, synchronous cache reader — TTL-expired
 *     entries return null
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { recordConsent } from '../src/funnel/consent.js';
import {
  ADVISOR_REFRESH_TTL_MS,
  readAdvisorTip,
  refreshAdvisorTipIfStale,
} from '../src/funnel/advisor-tip.js';
import type { FableHarness as FableHarnessType } from '../src/services/fable-harness.js';

let stateDir: string;
let savedEnv: NodeJS.ProcessEnv;

beforeEach(() => {
  stateDir = fs.mkdtempSync(path.join(os.tmpdir(), 'advisor-tip-test-'));
  savedEnv = { ...process.env };
  process.env.RUFLO_STATE_DIR = stateDir;
});

afterEach(() => {
  process.env = savedEnv;
  fs.rmSync(stateDir, { recursive: true, force: true });
});

describe('refreshAdvisorTipIfStale — consent gate', () => {
  it('never calls the harness without advisor-tips consent', async () => {
    let called = false;
    const harness = { adviseCoPilotTip: async () => { called = true; return null; } } as unknown as FableHarnessType;
    const result = await refreshAdvisorTipIfStale({}, { harness });
    expect(result).toEqual({ refreshed: false, reason: 'not-consented' });
    expect(called).toBe(false);
  });

  it('calls the harness once consent is granted', async () => {
    recordConsent('advisor-tips', true, 'test');
    let called = false;
    const harness = {
      adviseCoPilotTip: async () => { called = true; return { headline: 'x', detail: 'y', confidence: 0.5 }; },
    } as unknown as FableHarnessType;
    const result = await refreshAdvisorTipIfStale({}, { harness });
    expect(result).toEqual({ refreshed: true });
    expect(called).toBe(true);
  });
});

describe('refreshAdvisorTipIfStale — TTL gate (at most once per window)', () => {
  it('does not re-spend within the TTL window', async () => {
    recordConsent('advisor-tips', true, 'test');
    let calls = 0;
    const harness = {
      adviseCoPilotTip: async () => { calls++; return { headline: 'tip', detail: 'd', confidence: 0.9 }; },
    } as unknown as FableHarnessType;
    const t0 = new Date(0);
    const first = await refreshAdvisorTipIfStale({}, { now: t0, harness });
    expect(first.refreshed).toBe(true);
    expect(calls).toBe(1);

    const stillFresh = new Date(t0.getTime() + ADVISOR_REFRESH_TTL_MS - 1000);
    const second = await refreshAdvisorTipIfStale({}, { now: stillFresh, harness });
    expect(second).toEqual({ refreshed: false, reason: 'fresh' });
    expect(calls).toBe(1); // no second spawn
  });

  it('re-spends once the TTL window has elapsed', async () => {
    recordConsent('advisor-tips', true, 'test');
    let calls = 0;
    const harness = {
      adviseCoPilotTip: async () => { calls++; return { headline: 'tip', detail: 'd', confidence: 0.9 }; },
    } as unknown as FableHarnessType;
    const t0 = new Date(0);
    await refreshAdvisorTipIfStale({}, { now: t0, harness });
    const afterTtl = new Date(t0.getTime() + ADVISOR_REFRESH_TTL_MS + 1000);
    const result = await refreshAdvisorTipIfStale({}, { now: afterTtl, harness });
    expect(result.refreshed).toBe(true);
    expect(calls).toBe(2);
  });
});

describe('refreshAdvisorTipIfStale — cache write shape', () => {
  it('writes headline+detail to the cache on a real tip', async () => {
    recordConsent('advisor-tips', true, 'test');
    const harness = {
      adviseCoPilotTip: async () => ({ headline: 'Commit your work', detail: '50 files uncommitted.', confidence: 0.8 }),
    } as unknown as FableHarnessType;
    const now = new Date();
    await refreshAdvisorTipIfStale({ gitUncommittedCount: 50 }, { now, harness });
    const tip = readAdvisorTip(now);
    expect(tip).toEqual({ headline: 'Commit your work', detail: '50 files uncommitted.' });
  });

  it('stamps the cache even when the model finds nothing worth surfacing (no re-ask within the window)', async () => {
    recordConsent('advisor-tips', true, 'test');
    let calls = 0;
    const harness = { adviseCoPilotTip: async () => { calls++; return null; } } as unknown as FableHarnessType;
    const now = new Date();
    const first = await refreshAdvisorTipIfStale({}, { now, harness });
    expect(first).toEqual({ refreshed: true, reason: 'no-tip' });
    expect(readAdvisorTip(now)).toBeNull(); // nothing to show, but...
    const second = await refreshAdvisorTipIfStale({}, { now: new Date(now.getTime() + 1000), harness });
    expect(second).toEqual({ refreshed: false, reason: 'fresh' }); // ...not re-asked
    expect(calls).toBe(1);
  });

  it('surfaces harness errors as refreshed:false without throwing', async () => {
    recordConsent('advisor-tips', true, 'test');
    const harness = { adviseCoPilotTip: async () => { throw new Error('spawn failed'); } } as unknown as FableHarnessType;
    const result = await refreshAdvisorTipIfStale({}, { harness });
    expect(result).toEqual({ refreshed: false, reason: 'error' });
  });
});

describe('readAdvisorTip — pure cache reader', () => {
  it('returns null when nothing has been cached', () => {
    expect(readAdvisorTip()).toBeNull();
  });

  it('returns null for an expired cache entry', async () => {
    recordConsent('advisor-tips', true, 'test');
    const harness = {
      adviseCoPilotTip: async () => ({ headline: 'tip', detail: 'd', confidence: 0.9 }),
    } as unknown as FableHarnessType;
    const t0 = new Date(0);
    await refreshAdvisorTipIfStale({}, { now: t0, harness });
    const expired = new Date(t0.getTime() + ADVISOR_REFRESH_TTL_MS + 1);
    expect(readAdvisorTip(expired)).toBeNull();
  });
});

/**
 * Regression guard for ruvnet/ruflo#1906 — model aliases must map to
 * current (Claude 4.x) model ids, not the deprecated Claude-3.x ids that
 * the Anthropic API now 404s.
 */
import { describe, it, expect } from 'vitest';
import { resolveAnthropicModel, DEFAULT_ANTHROPIC_MODEL } from '../src/mcp-tools/agent-execute-core.js';

describe('#1906 — agent_execute model aliases resolve to current Claude 4.x ids', () => {
  it('haiku → claude-haiku-4-5-20251001', () => {
    expect(resolveAnthropicModel('haiku')).toBe('claude-haiku-4-5-20251001');
  });
  it('sonnet → claude-sonnet-5 (bumped from 4-6)', () => {
    expect(resolveAnthropicModel('sonnet')).toBe('claude-sonnet-5');
  });
  it('sonnet-4.6 reaches the prior pin', () => {
    expect(resolveAnthropicModel('sonnet-4.6')).toBe('claude-sonnet-4-6');
  });
  it('opus → claude-opus-4-8 (#2232 alias bump)', () => {
    expect(resolveAnthropicModel('opus')).toBe('claude-opus-4-8');
  });
  it('opus-4.7 reaches the prior pin', () => {
    expect(resolveAnthropicModel('opus-4.7')).toBe('claude-opus-4-7');
  });
  it('inherit → the default (sonnet 5)', () => {
    expect(resolveAnthropicModel('inherit')).toBe('claude-sonnet-5');
    expect(DEFAULT_ANTHROPIC_MODEL).toBe('claude-sonnet-5');
  });
  it('undefined → the default', () => {
    expect(resolveAnthropicModel(undefined)).toBe(DEFAULT_ANTHROPIC_MODEL);
  });
  it('anthropic:<id> prefix is stripped', () => {
    expect(resolveAnthropicModel('anthropic:claude-opus-4-7')).toBe('claude-opus-4-7');
  });
  it('a bare model id passes through unchanged', () => {
    expect(resolveAnthropicModel('claude-sonnet-4-6')).toBe('claude-sonnet-4-6');
  });
  it('no alias resolves to a deprecated claude-3.x id (#1906 regression)', () => {
    for (const alias of ['haiku', 'sonnet', 'opus', 'inherit', undefined]) {
      expect(resolveAnthropicModel(alias as string | undefined)).not.toMatch(/^claude-3[.-]/);
    }
  });
});

/**
 * Regression guard for ruvnet/ruflo#1916.
 *
 *  (a) `agent_logs` MCP tool must be registered — the `ruflo agent logs <id>`
 *      CLI subcommand called `callMCPTool('agent_logs', …)` against a tool
 *      that didn't exist → `MCP tool not found: agent_logs`.
 *  (b) `agent_status` / `agent_list` / `agent_logs` must resolve hive-mind-
 *      spawned workers — `hive-mind_spawn` writes workers to
 *      `.claude-flow/agents.json`, a *different* file from the canonical
 *      `.claude-flow/agents/store.json` the agent tools read, so
 *      `agent status <hive-worker-id>` returned `not_found`.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { agentTools } from '../src/mcp-tools/agent-tools.js';

const tool = (name: string) => {
  const t = agentTools.find(t => t.name === name);
  if (!t) throw new Error(`MCP tool not registered: ${name}`);
  return t;
};

describe('#1916 — agent_logs registered + hive-worker resolution', () => {
  let dir: string;
  let prevCwd: string | undefined;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'ruflo-1916-'));
    prevCwd = process.env.CLAUDE_FLOW_CWD;
    process.env.CLAUDE_FLOW_CWD = dir;
    // hive-mind_spawn writes here:
    mkdirSync(join(dir, '.claude-flow'), { recursive: true });
    writeFileSync(
      join(dir, '.claude-flow', 'agents.json'),
      JSON.stringify({
        agents: {
          'hive-worker-1716-abcd': {
            agentId: 'hive-worker-1716-abcd',
            agentType: 'worker',
            status: 'idle',
            health: 1.0,
            taskCount: 0,
            config: { role: 'worker', hiveRole: 'worker' },
            createdAt: '2026-05-11T00:00:00.000Z',
            domain: 'hive-mind',
          },
        },
      }),
    );
  });

  afterEach(() => {
    if (prevCwd === undefined) delete process.env.CLAUDE_FLOW_CWD;
    else process.env.CLAUDE_FLOW_CWD = prevCwd;
    rmSync(dir, { recursive: true, force: true });
  });

  it('(a) agent_logs is a registered MCP tool', () => {
    expect(agentTools.some(t => t.name === 'agent_logs')).toBe(true);
  });

  it('(a) agent_logs returns the documented shape for an unknown agent (no throw)', async () => {
    const res = await (tool('agent_logs').handler as any)({ agentId: 'agent-does-not-exist' });
    expect(res).toMatchObject({ agentId: 'agent-does-not-exist', entries: [], total: 0, error: 'Agent not found' });
  });

  it('(b) agent_status resolves a hive-mind-spawned worker', async () => {
    const res = await (tool('agent_status').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res.status).not.toBe('not_found');
    expect(res).toMatchObject({ agentId: 'hive-worker-1716-abcd', agentType: 'worker', status: 'idle' });
  });

  it('(b) agent_list includes hive-mind-spawned workers', async () => {
    const res = await (tool('agent_list').handler as any)({});
    expect(res.agents.map((a: any) => a.agentId)).toContain('hive-worker-1716-abcd');
  });

  it('(b) agent_logs resolves a hive-mind-spawned worker and returns entries', async () => {
    const res = await (tool('agent_logs').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res.error).toBeUndefined();
    expect(res.agentId).toBe('hive-worker-1716-abcd');
    expect(Array.isArray(res.entries)).toBe(true);
    expect(res.entries.length).toBeGreaterThan(0); // at least the synthetic "agent created" entry
  });

  it('canonical store wins on id collision', async () => {
    // Same id in the canonical store with a richer record:
    mkdirSync(join(dir, '.claude-flow', 'agents'), { recursive: true });
    writeFileSync(
      join(dir, '.claude-flow', 'agents', 'store.json'),
      JSON.stringify({
        version: '3.0.0',
        agents: {
          'hive-worker-1716-abcd': {
            agentId: 'hive-worker-1716-abcd',
            agentType: 'coder',
            status: 'busy',
            health: 0.9,
            taskCount: 3,
            config: {},
            createdAt: '2026-05-11T01:00:00.000Z',
          },
        },
      }),
    );
    const res = await (tool('agent_status').handler as any)({ agentId: 'hive-worker-1716-abcd' });
    expect(res).toMatchObject({ agentType: 'coder', status: 'busy', taskCount: 3 });
  });
});

/**
 * Regression guard for ruvnet/ruflo#2962 — explicit provider/model selection
 * (`providers configure`, `agent spawn --provider/--model`) did not
 * propagate into actual agent execution. Backend/model selection at
 * `agent_execute` time was driven solely by env vars, never by the
 * persisted `agents.providers` config or the agent's own `config.provider`
 * / `config.model`.
 *
 * Precedence implemented: explicit per-agent flag → env vars → persisted
 * `agents.providers` config → key-presence inference (unchanged, last
 * resort).
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { agentTools } from '../src/mcp-tools/agent-tools.js';
import { callAnthropicMessages, executeAgentTask } from '../src/mcp-tools/agent-execute-core.js';
import { configManager } from '../src/services/config-file-manager.js';

const tool = (name: string) => {
  const t = agentTools.find(t => t.name === name);
  if (!t) throw new Error(`MCP tool not registered: ${name}`);
  return t;
};

const ENV_KEYS = [
  'ANTHROPIC_API_KEY',
  'OPENROUTER_API_KEY',
  'OLLAMA_API_KEY',
  'OLLAMA_BASE_URL',
  'RUFLO_PROVIDER',
] as const;

describe('#2962 — provider/model config propagates into agent execution', () => {
  let dir: string;
  let prevCwd: string | undefined;
  let prevEnv: Record<string, string | undefined>;
  let fetchSpy: ReturnType<typeof vi.spyOn>;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'ruflo-2962-'));
    prevCwd = process.env.CLAUDE_FLOW_CWD;
    process.env.CLAUDE_FLOW_CWD = dir;

    prevEnv = {};
    for (const key of ENV_KEYS) {
      prevEnv[key] = process.env[key];
      delete process.env[key];
    }

    // configManager is a module-level singleton that caches its loaded
    // config + resolved path across calls; reset its private state so each
    // test's fresh tmp-dir config file is actually re-read from disk
    // instead of reusing a previous test's cached config/path.
    (configManager as unknown as { config: unknown }).config = null;
    (configManager as unknown as { configPath: unknown }).configPath = null;
  });

  afterEach(() => {
    if (prevCwd === undefined) delete process.env.CLAUDE_FLOW_CWD;
    else process.env.CLAUDE_FLOW_CWD = prevCwd;
    for (const key of ENV_KEYS) {
      if (prevEnv[key] === undefined) delete process.env[key];
      else process.env[key] = prevEnv[key];
    }
    (configManager as unknown as { config: unknown }).config = null;
    (configManager as unknown as { configPath: unknown }).configPath = null;
    rmSync(dir, { recursive: true, force: true });
    fetchSpy?.mockRestore();
  });

  function writeConfig(agentsProviders: unknown[]): void {
    writeFileSync(
      join(dir, 'claude-flow.config.json'),
      JSON.stringify({ agents: { providers: agentsProviders } }),
    );
  }

  function mockOpenAICompatFetch() {
    fetchSpy = vi.spyOn(globalThis, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => ({
        id: 'chatcmpl-test',
        model: 'qwen3.6:27b',
        choices: [{ message: { role: 'assistant', content: 'hi' }, finish_reason: 'stop' }],
        usage: { prompt_tokens: 1, completion_tokens: 1, total_tokens: 2 },
      }),
    } as unknown as Response);
  }

  // (1) callAnthropicMessages() selects Ollama from the persisted config,
  // not just env vars — no OLLAMA_API_KEY set, agents.providers has an
  // enabled ollama entry with a self-hosted baseUrl → the Ollama branch is
  // taken with no Authorization header sent (no fake credential required).
  it('callAnthropicMessages() dispatches to a self-hosted Ollama endpoint from persisted config alone', async () => {
    writeConfig([
      { name: 'ollama', enabled: true, baseUrl: 'http://127.0.0.1:11434', model: 'qwen3.6:27b' },
    ]);
    mockOpenAICompatFetch();

    const result = await callAnthropicMessages({ prompt: 'say hi' });

    expect(result.success).toBe(true);
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    const [url, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
    expect(url).toBe('http://127.0.0.1:11434/v1/chat/completions');
    // Self-hosted, unauthenticated endpoint: no Authorization header, no
    // fake 'local' credential should have been required to reach it.
    expect((init.headers as Record<string, string>).Authorization).toBeUndefined();
  });

  // (2) determineAgentModel() accepts an arbitrary non-Claude model string
  // as an explicit selection (via the modelId fast-path), and that
  // selection is NOT silently substituted for a default when re-read
  // downstream by executeAgentTask — verified by inspecting the actual
  // model sent on the wire, not just the stored record.
  it('an arbitrary non-alias --model string survives spawn and reaches the dispatch call unchanged', async () => {
    process.env.ANTHROPIC_API_KEY = 'sk-ant-test';
    mockOpenAICompatFetch();
    fetchSpy.mockResolvedValue({
      ok: true,
      json: async () => ({
        id: 'msg-test',
        model: 'qwen3.6:27b',
        content: [{ type: 'text', text: 'hi' }],
        stop_reason: 'end_turn',
        usage: { input_tokens: 1, output_tokens: 1 },
      }),
    } as unknown as Response);

    const spawnResult = (await tool('agent_spawn').handler({
      agentType: 'researcher',
      config: { model: 'qwen3.6:27b' },
    })) as { agentId: string; model: string; modelRoutedBy: string; modelId?: string };

    expect(spawnResult.modelRoutedBy).toBe('explicit');
    expect(spawnResult.modelId).toBe('qwen3.6:27b');

    await executeAgentTask({ agentId: spawnResult.agentId, prompt: 'say hi' });

    expect(fetchSpy).toHaveBeenCalledTimes(1);
    const [, init] = fetchSpy.mock.calls[0] as [string, RequestInit];
    const body = JSON.parse(init.body as string);
    // Before the fix: config.model fell through determineAgentModel's
    // alias-only check, agent.modelId was never set, and this would be
    // 'claude-sonnet-5' (the silently-substituted default).
    expect(body.model).toBe('qwen3.6:27b');
  });

  // (3) Full round-trip with no environment variables set at all:
  // providers configure (config-file write) → agent spawn
  // --provider ollama --model <tag> → the resulting agent record's
  // provider/modelId fields are populated → executeAgentTask's dispatch
  // call is constructed with that provider forwarded to a self-hosted
  // endpoint.
  it('round-trip: providers-configure + spawn --provider ollama --model reaches Ollama with zero env vars', async () => {
    // Simulates `providers configure -p ollama -m qwen3.6:27b -e http://127.0.0.1:11434`
    writeConfig([
      { name: 'ollama', enabled: true, baseUrl: 'http://127.0.0.1:11434', model: 'qwen3.6:27b' },
    ]);
    mockOpenAICompatFetch();

    // Simulates `agent spawn --type researcher --provider ollama --model qwen3.6:27b`
    // (commands/agent.ts always sets config.provider — 'ollama' here is an
    // unambiguous explicit choice, unlike the CLI's silent 'anthropic' default)
    const spawnResult = (await tool('agent_spawn').handler({
      agentType: 'researcher',
      config: { provider: 'ollama', model: 'qwen3.6:27b' },
    })) as { agentId: string; provider?: string; modelId?: string };

    expect(spawnResult.provider).toBe('ollama');
    expect(spawnResult.modelId).toBe('qwen3.6:27b');

    const execResult = await executeAgentTask({ agentId: spawnResult.agentId, prompt: 'say hi' });

    expect(execResult.success).toBe(true);
    expect(fetchSpy).toHaveBeenCalledTimes(1);
    const [url] = fetchSpy.mock.calls[0] as [string, RequestInit];
    expect(url).toBe('http://127.0.0.1:11434/v1/chat/completions');
  });
});

/**
 * Tests for agentbbs MCP tools (ADR-164 Phase 1).
 *
 * Two surfaces under test:
 *   1. STRUCTURAL — exposure, schema, validation. Runs regardless of agentbbs presence.
 *   2. HAPPY PATH — gated on agentbbs being importable via it.skipIf(!havePkg).
 *
 * The degraded path is exercised structurally: when agentbbs is missing,
 * every handler returns `{degraded: true, reason: 'agentbbs-not-found'}`
 * matching the metaharness / agenticow / testgen contract.
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, rmSync, existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { agentbbsTools } from '../src/mcp-tools/agentbbs-tools.js';

function findTool(name: string) {
  const t = agentbbsTools.find(t => t.name === name);
  if (!t) throw new Error(`tool not found: ${name}`);
  return t;
}

// Detect agentbbs availability at module scope so it.skipIf evaluates correctly.
let havePkg = false;
try { await import('agentbbs'); havePkg = true; } catch { havePkg = false; }

describe('agentbbs MCP tools — structural contract', () => {
  it('exposes exactly 4 tools (register / publish / watch / human_join)', () => {
    const names = agentbbsTools.map(t => t.name).sort();
    expect(names).toEqual([
      'federation_bbs_human_join',
      'federation_bbs_publish',
      'federation_bbs_register',
      'federation_bbs_watch',
    ]);
  });

  it('every tool has an object inputSchema with handler + ≥80-char description', () => {
    for (const t of agentbbsTools) {
      expect(t.inputSchema.type).toBe('object');
      expect(t.inputSchema.properties).toBeDefined();
      expect(typeof t.handler).toBe('function');
      expect(t.description.length).toBeGreaterThanOrEqual(80);
      // ADR-112 — descriptions must carry "Use when ... is wrong because ..." guidance.
      expect(t.description).toMatch(/Use when/i);
      expect(t.description).toMatch(/wrong because/i);
    }
  });

  it('register rejects path traversal in basePath', async () => {
    const register = findTool('federation_bbs_register');
    await expect(register.handler({
      basePath: '../../../../etc/passwd',
      roomLabel: '#sales',
    })).rejects.toThrow(/disallowed characters/);
  });

  it('register rejects an illegal roomLabel', async () => {
    const register = findTool('federation_bbs_register');
    await expect(register.handler({
      roomLabel: 'evil; rm -rf /',
    })).rejects.toThrow(/may only contain/);
  });

  it('register accepts conventional #-prefixed room labels', async () => {
    // Even when agentbbs is missing we should validate inputs first OR degrade
    // — but the contract is: validation errors must surface as throws.
    // With agentbbs missing we get a degraded result instead of validation.
    // So this test only meaningfully covers regex acceptance shape.
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('#sales')).toBe(true);
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('finance')).toBe(true);
    expect(/^[A-Za-z0-9_.\-:/@#]+$/.test('hr/onboarding')).toBe(true);
  });

  it('publish rejects malformed msgType (validation runs before optional-dep check)', async () => {
    const publish = findTool('federation_bbs_publish');
    await expect(publish.handler({
      roomId: 'sales-12345678',
      msgType: 'bad type with spaces',
      payload: {},
    })).rejects.toThrow(/msgType must be alnum/);
  });

  it('publish rejects non-object payload', async () => {
    const publish = findTool('federation_bbs_publish');
    await expect(publish.handler({
      roomId: 'sales-12345678',
      msgType: 'task-result',
      payload: 'not an object',
    })).rejects.toThrow(/payload must be a JSON object/);
  });

  it('all 4 tools return {degraded:true, reason:"agentbbs-not-found"} when agentbbs is missing', async () => {
    if (havePkg) return; // happy-path case is covered elsewhere
    for (const t of agentbbsTools) {
      const minimalInput: Record<string, unknown> =
        t.name === 'federation_bbs_register'    ? { roomLabel: '#sales' } :
        t.name === 'federation_bbs_publish'     ? { roomId: 'sales-12345678', msgType: 'task-result', payload: {} } :
        t.name === 'federation_bbs_watch'       ? { roomId: 'sales-12345678' } :
        t.name === 'federation_bbs_human_join'  ? { roomId: 'sales-12345678' } :
        {};
      const r: any = await t.handler(minimalInput);
      expect(r.success).toBe(true);
      expect(r.degraded).toBe(true);
      expect(r.reason).toBe('agentbbs-not-found');
    }
  });
});

describe('agentbbs MCP tools — happy path (real package)', () => {
  let workdir: string;
  let roomId: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'agentbbs-tools-'));
  });

  afterAll(() => {
    try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it.skipIf(!havePkg)('register: creates a room and persists registry', async () => {
    const register = findTool('federation_bbs_register');
    const r: any = await register.handler({ basePath: workdir, roomLabel: '#sales' });
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.trustLevel).toBe('attested');
    expect(r.roomId).toMatch(/^sales-[0-9a-f]{8}$/);
    expect(r.nodeId).toMatch(/^[0-9a-f]{16}$/);
    roomId = r.roomId;
    const reg = JSON.parse(readFileSync(join(workdir, 'rooms.json'), 'utf-8'));
    expect(reg[roomId]).toBeDefined();
    expect(reg[roomId].roomLabel).toBe('#sales');
  });

  it.skipIf(!havePkg)('publish: writes a ReplicateMessage envelope to the room log', async () => {
    const publish = findTool('federation_bbs_publish');
    const r: any = await publish.handler({
      basePath: workdir,
      roomId,
      msgType: 'task-result',
      payload: { agent: 'lead-gen', leadsQualified: 3 },
    });
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.envelopeId).toBeTruthy();
    expect(r.recipientHopCount).toBe(0);
    expect(existsSync(join(workdir, `room-${roomId}.jsonl`))).toBe(true);
  });

  it.skipIf(!havePkg)('watch: returns envelopes from the room log with monotonic seq', async () => {
    const watch = findTool('federation_bbs_watch');
    const r: any = await watch.handler({ basePath: workdir, roomId, limit: 50 });
    expect(r.success).toBe(true);
    expect(r.envelopes.length).toBeGreaterThan(0);
    // Seq must be strictly monotonic
    let lastSeq = 0;
    for (const e of r.envelopes) {
      expect(e.seq).toBeGreaterThan(lastSeq);
      lastSeq = e.seq;
    }
  });

  it.skipIf(!havePkg)('human_join: mints a single-use Ed25519-signed token that expires in the future', async () => {
    const join = findTool('federation_bbs_human_join');
    const before = Date.now();
    const r: any = await join.handler({ roomId: 'sales-12345678', ttlSeconds: 120 });
    const after = Date.now();
    expect(r.success).toBe(true);
    expect(r.degraded).toBeUndefined();
    expect(r.handshakeToken).toBeTruthy();
    expect(r.handshakeToken.length).toBeGreaterThan(50);
    expect(r.webUrl).toMatch(/^https:\/\/agentbbs\.local\//);
    expect(r.sshCommand).toMatch(/^ssh /);
    const expiresAt = new Date(r.expiresAt).getTime();
    expect(expiresAt).toBeGreaterThan(before);
    // Expiry must be ≤ ttlSeconds from now (within a wide margin to absorb scheduling jitter).
    expect(expiresAt - after).toBeLessThanOrEqual(120 * 1000 + 1000);
    expect(expiresAt - before).toBeGreaterThanOrEqual(120 * 1000 - 1000);
  });
});

/**
