/**
 * Tests for agenticow MCP tools.
 *
 * Two surfaces under test:
 *   1. The HAPPY PATH — agenticow is installed (real package). The tool round-trips
 *      through actual COW branch / checkpoint / rollback / promote semantics on
 *      a temp .rvf file.
 *   2. The DEGRADED PATH — agenticow is NOT installed (we vi.mock() it as
 *      ERR_MODULE_NOT_FOUND). Every tool must return `{degraded: true}` with no
 *      throw, matching the metaharness-tools / testgen-tools contract.
 *
 * Why both: agenticow is in `optionalDependencies`. CI runs with deps installed
 * (happy path) but production users may not have it — the degraded path is
 * the load-bearing architectural rule (zero hard runtime dep).
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { mkdtempSync, rmSync, existsSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { agenticowTools } from '../src/mcp-tools/agenticow-tools.js';

function findTool(name: string) {
  const t = agenticowTools.find(t => t.name === name);
  if (!t) throw new Error(`tool not found: ${name}`);
  return t;
}

function dirBytes(p: string): number {
  if (!existsSync(p)) return 0;
  const st = statSync(p);
  if (st.isFile()) return st.size;
  let total = 0;
  for (const e of readdirSync(p)) total += dirBytes(join(p, e));
  return total;
}

// Detect agenticow availability at module scope (top-level await is allowed
// in vitest ESM modules). We need this before the `it.skipIf(...)` calls,
// which evaluate at definition time.
let havePkg = false;
try { await import('agenticow'); havePkg = true; } catch { havePkg = false; }

describe('agenticow MCP tools — happy path (real package)', () => {
  let workdir: string;
  let basePath: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'agenticow-tools-'));
    basePath = join(workdir, 'base.rvf');
  });

  afterAll(() => {
    try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
  });

  it('exposes 9 tools (lifecycle + read/write verbs)', () => {
    const names = agenticowTools.map(t => t.name).sort();
    expect(names).toEqual([
      'agenticow_branch',
      'agenticow_checkpoint',
      'agenticow_diff',
      'agenticow_ingest',
      'agenticow_lineage',
      'agenticow_promote',
      'agenticow_query',
      'agenticow_rollback',
      'agenticow_status',
    ]);
  });

  it.skipIf(!havePkg)('ingest → query round-trips vectors + text across a COW branch (issue: text persistence)', async () => {
    const ingest = findTool('agenticow_ingest');
    const query = findTool('agenticow_query');
    const branch = findTool('agenticow_branch');
    const v = (s: number) => Array.from({ length: 8 }, (_, i) => Math.sin(s + i));
    const base = join(workdir, 'rw-base.rvf');
    const br = join(workdir, 'rw-branch.rvf');

    const ing = await ingest.handler({ path: base, records: [
      { id: 1, vector: v(1), text: 'alpha' }, { id: 2, vector: v(2), text: 'beta' },
    ], dimension: 8 }) as any;
    expect(ing.success).toBe(true);
    expect(ing.ingested.accepted).toBe(2);

    // branch with the native ANN fast path, then ingest a branch-only vector
    const b = await branch.handler({ basePath: base, branchPath: br, label: 'rw', nativeAnn: true }) as any;
    expect(b.nativeAnn).toBe(true);
    await ingest.handler({ path: br, records: [{ id: 3, vector: v(3), text: 'gamma' }] });

    // query the branch: sees base ∪ branch, and text survives (0.2.4 fix)
    const q = await query.handler({ path: br, vector: v(1), k: 3 }) as any;
    expect(q.success).toBe(true);
    const hit = q.hits.find((h: any) => h.id === 1);
    expect(hit).toBeDefined();
    expect(hit.text).toBe('alpha');
  });

  it.skipIf(!havePkg)('diff / lineage / status report branch state', async () => {
    const ingest = findTool('agenticow_ingest');
    const diff = findTool('agenticow_diff');
    const lineage = findTool('agenticow_lineage');
    const status = findTool('agenticow_status');
    const v = (s: number) => Array.from({ length: 8 }, (_, i) => Math.cos(s + i));
    const p = join(workdir, 'introspect.rvf');
    await ingest.handler({ path: p, records: [{ id: 10, vector: v(1), text: 'x' }], dimension: 8 });

    const d = await diff.handler({ path: p }) as any;
    expect(d.success).toBe(true);
    expect(Array.isArray(d.diff.added)).toBe(true);

    const lin = await lineage.handler({ path: p }) as any;
    expect(lin.success).toBe(true);
    expect(lin.lineage.some((n: any) => n.role === 'working' || n.role === 'base')).toBe(true);

    const st = await status.handler({ path: p }) as any;
    expect(st.success).toBe(true);
    expect(st.status.dimension).toBe(8);
  });

  it('new read/write verbs degrade + validate like the lifecycle verbs', async () => {
    // path-traversal rejection is shared via resolveMemoryPath
    const query = findTool('agenticow_query');
    await expect(query.handler({ path: '../../etc/passwd', vector: [1, 2] })).rejects.toThrow(/disallowed/);
    const ingest = findTool('agenticow_ingest');
    await expect(ingest.handler({ path: 'ok.rvf', records: [] })).rejects.toThrow(/non-empty/);
  });

  it('every tool has a JSON-schema input + handler', () => {
    for (const t of agenticowTools) {
      expect(t.inputSchema.type).toBe('object');
      expect(t.inputSchema.properties).toBeDefined();
      expect(typeof t.handler).toBe('function');
    }
  });

  it.skipIf(!havePkg)('agenticow_branch creates a tiny COW branch on a real base', async () => {
    const branch = findTool('agenticow_branch');
    // Use a small dim for test speed
    const branchPath = join(workdir, 'b1.rvf');
    const result: any = await branch.handler({
      basePath, branchPath,
      label: 'test-branch',
      dimension: 32,
    });
    expect(result.success).toBe(true);
    expect(result.degraded).toBeUndefined();
    expect(result.label).toBe('test-branch');
    expect(existsSync(branchPath)).toBe(true);
    // The size win is the load-bearing claim — assert it's tiny
    expect(dirBytes(branchPath)).toBeLessThan(2048);
  });

  it.skipIf(!havePkg)('agenticow_checkpoint persists state across reopen, agenticow_rollback restores it', async () => {
    const cp = findTool('agenticow_checkpoint');
    const rb = findTool('agenticow_rollback');

    // checkpoint must persist via the .agenticow.json manifest. The base file
    // was created earlier by the branch test (which writes the manifest).
    const cpResult: any = await cp.handler({ path: basePath, label: 'cp-1' });
    expect(cpResult.success).toBe(true);
    expect(cpResult.label).toBe('cp-1');
    // Manifest file should now exist next to the .rvf
    expect(existsSync(`${basePath}.agenticow.json`)).toBe(true);

    // Rollback now finds the checkpoint via the persisted manifest
    const rbResult: any = await rb.handler({ path: basePath });
    expect(rbResult.success).toBe(true);
    expect(rbResult.rolledBack).toBe(true);
  });

  it('agenticow_branch rejects path traversal in basePath', async () => {
    const branch = findTool('agenticow_branch');
    await expect(branch.handler({
      basePath: '../../../../etc/passwd',
      branchPath: join(workdir, 'evil.rvf'),
      label: 'evil',
      dimension: 32,
    })).rejects.toThrow(/disallowed characters/);
  });

  it('agenticow_branch rejects a malformed label', async () => {
    const branch = findTool('agenticow_branch');
    await expect(branch.handler({
      basePath,
      branchPath: join(workdir, 'b2.rvf'),
      label: 'evil; rm -rf /',
      dimension: 32,
    })).rejects.toThrow(/may only contain/);
  });

  it('agenticow_branch requires dimension when creating a new memory file', async () => {
    const branch = findTool('agenticow_branch');
    const freshBase = join(workdir, 'nonexistent.rvf');
    await expect(branch.handler({
      basePath: freshBase,
      branchPath: join(workdir, 'b3.rvf'),
      label: 'fresh',
      // no dimension
    })).rejects.toThrow(/dimension is required/);
  });
});

/**
 * V3 CLI AGNTCY/SLIM command scaffold tests — ADR-380.
 *
 * Asserts the "works without AGNTCY installed" smoke contract each command
 * must satisfy (mirroring ADR-150's CI-gate precedent, §1 of ADR-380):
 * with no `RUFLO_AGNTCY_SLIM_ENDPOINT` set (the default, real-world state
 * today since no runtime package exists to install), every command must
 * run to completion without throwing, exit 0, and print the documented
 * "not configured" fallback message.
 *
 * Lives under the package's top-level `__tests__/agntcy/` (mirroring
 * `__tests__/ruvector/` and `__tests__/services/`, which mirror
 * `src/ruvector/` and `src/services/` respectively) so it's picked up by
 * the package's `vitest.config.ts` `include: ['__tests__/**\/*.test.ts']`
 * glob — the original `src/commands/agntcy/__tests__/` location was never
 * reachable by that glob and left this suite unrun by `npm test`.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtemp, writeFile, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';

import { transportCommand, useCommand } from '../../src/commands/agntcy/transport.js';
import { agentPublishCommand, validateOasfRecordShape } from '../../src/commands/agntcy/publish.js';
import { swarmJoinCommand, validateNamespace } from '../../src/commands/agntcy/swarm-join.js';
import {
  detectAgntcyRuntime,
  AGNTCY_ENDPOINT_ENV,
  AGNTCY_NOT_CONFIGURED_MESSAGE,
} from '../../src/commands/agntcy/runtime.js';
import { output } from '../../src/output.js';

import type { CommandContext, CommandResult } from '../../src/types.js';

function makeCtx(args: string[] = [], flags: Record<string, unknown> = {}): CommandContext {
  return {
    args,
    flags: { _: args, ...flags } as CommandContext['flags'],
    cwd: process.cwd(),
    interactive: false,
  };
}

async function runAction(
  cmd: { action?: (ctx: CommandContext) => Promise<CommandResult | void> },
  ctx: CommandContext,
): Promise<CommandResult | void> {
  if (!cmd.action) throw new Error('command has no action');
  return cmd.action(ctx);
}

describe('agntcy command scaffold (ADR-380) — not-configured fallback', () => {
  const originalEndpoint = process.env[AGNTCY_ENDPOINT_ENV];

  beforeEach(() => {
    delete process.env[AGNTCY_ENDPOINT_ENV];
  });

  afterEach(() => {
    if (originalEndpoint === undefined) {
      delete process.env[AGNTCY_ENDPOINT_ENV];
    } else {
      process.env[AGNTCY_ENDPOINT_ENV] = originalEndpoint;
    }
    vi.restoreAllMocks();
  });

  describe('runtime.ts — detectAgntcyRuntime', () => {
    it('reports not configured when the endpoint env var is unset', async () => {
      const status = await detectAgntcyRuntime({});
      expect(status.configured).toBe(false);
      expect(status.reason).toContain(AGNTCY_ENDPOINT_ENV);
      expect(status.endpoint).toBeUndefined();
    });

    it('reports configured when the endpoint is set and the optional package resolves', async () => {
      // @agntcy/slim-bindings is pinned to the confirmed-working alpha
      // (2.0.0-alpha.5, see package.json + runtime.ts's header comment for
      // why — agntcy/slim#1916) and is a real optionalDependency here, so
      // this genuinely exercises the "package installed and importable"
      // path rather than asserting the old "not installed" fallback.
      const status = await detectAgntcyRuntime({ [AGNTCY_ENDPOINT_ENV]: 'https://slim.example.com' });
      expect(status.configured).toBe(true);
      expect(status.endpoint).toBe('https://slim.example.com');
      expect(status.reason).toMatch(/resolved/);
    });

    it('still degrades gracefully if the optional package genuinely is not installed', async () => {
      // Regression guard for the "works without AGNTCY installed" contract
      // this file's header describes — simulate a MODULE_NOT_FOUND by
      // probing a package name guaranteed not to exist, exercising the
      // same catch branch a real "not installed" environment would hit.
      const status = await detectAgntcyRuntime(
        { [AGNTCY_ENDPOINT_ENV]: 'https://slim.example.com' },
        '@agntcy/this-package-does-not-exist-in-any-registry',
      );
      expect(status.configured).toBe(false);
      expect(status.endpoint).toBe('https://slim.example.com');
      expect(status.reason).toMatch(/not installed|error probing/);
    });

    it('never throws regardless of env shape', async () => {
      await expect(detectAgntcyRuntime({} as NodeJS.ProcessEnv)).resolves.toBeDefined();
    });
  });

  describe('ruflo transport use slim', () => {
    it('exposes a "use" subcommand on the transport command tree', () => {
      expect(transportCommand.name).toBe('transport');
      expect(transportCommand.subcommands?.map((c) => c.name)).toContain('use');
    });

    it('falls back to local transport without throwing, exit 0, expected message', async () => {
      const infoSpy = vi.spyOn(output, 'printInfo').mockImplementation(() => {});

      const result = await runAction(useCommand, makeCtx(['slim']));

      expect(result).toBeDefined();
      expect(result?.success).toBe(true);
      expect(result?.exitCode).toBeUndefined();
      expect((result?.data as Record<string, unknown>)?.transport).toBe('local');
      expect(infoSpy).toHaveBeenCalledWith(AGNTCY_NOT_CONFIGURED_MESSAGE);
    });

    it('rejects an unsupported transport name with exit 1 (usage error, not a fallback)', async () => {
      const result = await runAction(useCommand, makeCtx(['not-a-real-transport']));
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });

    it('requires a transport name argument', async () => {
      const result = await runAction(useCommand, makeCtx([]));
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });

    it('parent "transport" command action runs without throwing', async () => {
      const result = await runAction(transportCommand, makeCtx([]));
      expect(result?.success).toBe(true);
    });
  });

  describe('ruflo agent publish', () => {
    let tmpDir: string;
    let manifestPath: string;

    beforeEach(async () => {
      tmpDir = await mkdtemp(join(tmpdir(), 'agntcy-publish-'));
      manifestPath = join(tmpDir, 'agent.oasf.json');
      await writeFile(manifestPath, JSON.stringify({ name: 'test-agent', version: '0.1.0' }), 'utf-8');
    });

    afterEach(async () => {
      await rm(tmpDir, { recursive: true, force: true });
    });

    it('validateOasfRecordShape accepts a minimal valid record', () => {
      expect(validateOasfRecordShape({ name: 'a', version: '1.0.0' }).valid).toBe(true);
    });

    it('validateOasfRecordShape rejects missing fields, non-objects, and null', () => {
      expect(validateOasfRecordShape({}).valid).toBe(false);
      expect(validateOasfRecordShape({ name: 'a' }).valid).toBe(false);
      expect(validateOasfRecordShape(null).valid).toBe(false);
      expect(validateOasfRecordShape('nope').valid).toBe(false);
      expect(validateOasfRecordShape([]).valid).toBe(false);
    });

    it('falls back gracefully (exit 0) when not configured, after validating the manifest locally', async () => {
      const infoSpy = vi.spyOn(output, 'printInfo').mockImplementation(() => {});

      const result = await runAction(agentPublishCommand, makeCtx([], { manifest: manifestPath }));

      expect(result).toBeDefined();
      expect(result?.success).toBe(true);
      expect(result?.exitCode).toBeUndefined();
      expect((result?.data as Record<string, unknown>)?.published).toBe(false);
      expect(infoSpy).toHaveBeenCalledWith(AGNTCY_NOT_CONFIGURED_MESSAGE);
    });

    it('errors (exit 1) on a missing manifest file, independent of AGNTCY configuration', async () => {
      const result = await runAction(
        agentPublishCommand,
        makeCtx([], { manifest: join(tmpDir, 'does-not-exist.json') }),
      );
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });

    it('errors (exit 1) on a manifest that is valid JSON but not a valid OASF record', async () => {
      const badManifest = join(tmpDir, 'bad.json');
      await writeFile(badManifest, JSON.stringify({ notAName: true }), 'utf-8');

      const result = await runAction(agentPublishCommand, makeCtx([], { manifest: badManifest }));
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });
  });

  describe('ruflo swarm join <namespace>', () => {
    it('validateNamespace accepts slash-delimited alphanumeric namespaces', () => {
      expect(validateNamespace('cognitum/research/security').valid).toBe(true);
      expect(validateNamespace('single-segment').valid).toBe(true);
    });

    it('validateNamespace rejects empty and malformed namespaces', () => {
      expect(validateNamespace('').valid).toBe(false);
      expect(validateNamespace('   ').valid).toBe(false);
      expect(validateNamespace('bad namespace!').valid).toBe(false);
      expect(validateNamespace('cognitum//security').valid).toBe(false);
    });

    it('falls back to local coordination without throwing, exit 0, expected message', async () => {
      const infoSpy = vi.spyOn(output, 'printInfo').mockImplementation(() => {});

      const result = await runAction(swarmJoinCommand, makeCtx(['cognitum/research/security']));

      expect(result).toBeDefined();
      expect(result?.success).toBe(true);
      expect(result?.exitCode).toBeUndefined();
      expect((result?.data as Record<string, unknown>)?.joined).toBe(false);
      expect(infoSpy).toHaveBeenCalledWith(AGNTCY_NOT_CONFIGURED_MESSAGE);
    });

    it('requires a namespace argument', async () => {
      const result = await runAction(swarmJoinCommand, makeCtx([]));
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });

    it('rejects an invalid namespace with exit 1 (usage error, not a fallback)', async () => {
      const result = await runAction(swarmJoinCommand, makeCtx(['not a namespace!']));
      expect(result?.success).toBe(false);
      expect(result?.exitCode).toBe(1);
    });
  });
});

/**
 * ADR-306 demand-driven access-token refresh. These tests use an isolated
 * state directory and an in-memory keychain double; no real credential store
 * or Cognitum endpoint is touched.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const secrets = new Map<string, string>();
const events: string[] = [];
const refreshTokenMock = vi.fn();
const setSecretMock = vi.fn(async (_service: string, account: string, value: string) => {
  events.push('persist-refresh-token');
  secrets.set(account, value);
});

class MockOAuthError extends Error {
  constructor(message: string, public readonly code: 'network' | 'protocol' | 'unexpected_shape') {
    super(message);
  }
}

vi.mock('../src/auth/security-bridge.js', () => ({
  loadSecurityOAuth: async () => ({
    refreshToken: refreshTokenMock,
    createKeychainAdapter: async () => ({
      isAvailable: async () => true,
      getSecret: async (_service: string, account: string) => secrets.get(account) ?? null,
      setSecret: setSecretMock,
      deleteSecret: async () => {},
    }),
    OAuthError: MockOAuthError,
  }),
}));

import { setProfile, getProfile } from '../src/auth/state.js';
import { getSessionToken, setSessionToken, clearSessionToken } from '../src/auth/session.js';
import {
  ACCESS_TOKEN_REFRESH_WINDOW_MS,
  getValidAccessToken,
  NotLoggedInError,
  SessionOnlyExpiredError,
} from '../src/auth/client.js';
import { recordConsent } from '../src/funnel/index.js';
import type { CommandContext } from '../src/types.js';

let stateDir: string;
let serial = 0;

function profileName(label: string): string {
  serial += 1;
  return `${label}-${serial}`;
}

function writeProfile(name: string, keychainRef: string | null): void {
  setProfile(name, {
    accountId: 'before@example.test',
    scopes: ['account.create'],
    accessTokenExpiresAt: new Date(Date.now() - 1_000).toISOString(),
    keychainRef,
    profile: name,
    loginMethod: 'pkce',
    linkedAt: new Date(Date.now() - 60_000).toISOString(),
  });
  recordConsent('account', true, 'auth-token-refresh-test');
}

beforeEach(() => {
  stateDir = mkdtempSync(join(tmpdir(), 'ruflo-auth-refresh-'));
  process.env.RUFLO_STATE_DIR = stateDir;
  secrets.clear();
  events.length = 0;
  refreshTokenMock.mockReset();
  setSecretMock.mockClear();
});

afterEach(() => {
  delete process.env.RUFLO_STATE_DIR;
  rmSync(stateDir, { recursive: true, force: true });
});

describe('getValidAccessToken', () => {
  it('returns a cached token without touching the keychain or network', async () => {
    const name = profileName('cached');
    writeProfile(name, name);
    setSessionToken(name, 'cached-access', Date.now() + ACCESS_TOKEN_REFRESH_WINDOW_MS + 10_000);

    await expect(getValidAccessToken(name)).resolves.toBe('cached-access');
    expect(refreshTokenMock).not.toHaveBeenCalled();
    expect(setSecretMock).not.toHaveBeenCalled();
    clearSessionToken(name);
  });

  it('rejects an unknown profile with an actionable login error', async () => {
    const name = profileName('missing');
    await expect(getValidAccessToken(name)).rejects.toBeInstanceOf(NotLoggedInError);
  });

  it('fails cleanly when an expired session-only profile cannot refresh', async () => {
    const name = profileName('session-only');
    writeProfile(name, null);
    await expect(getValidAccessToken(name)).rejects.toBeInstanceOf(SessionOnlyExpiredError);
    expect(refreshTokenMock).not.toHaveBeenCalled();
  });

  it('persists a rotated refresh token before publishing the new access token', async () => {
    const name = profileName('rotate');
    writeProfile(name, name);
    secrets.set(name, 'old-refresh');
    refreshTokenMock.mockImplementation(async (value: string) => {
      expect(value).toBe('old-refresh');
      events.push('refresh-response');
      return {
        access_token: 'new-access',
        refresh_token: 'new-refresh',
        token_type: 'Bearer',
        expires_in: 900,
        account_email: 'after@example.test',
      };
    });

    await expect(getValidAccessToken(name)).resolves.toBe('new-access');
    expect(events).toEqual(['refresh-response', 'persist-refresh-token']);
    expect(secrets.get(name)).toBe('new-refresh');
    expect(getSessionToken(name)).toBe('new-access');
    expect(getProfile(name)?.accountId).toBe('after@example.test');
    clearSessionToken(name);
  });

  it('does not cache the access token when rotated-token persistence fails', async () => {
    const name = profileName('rotation-failure');
    writeProfile(name, name);
    secrets.set(name, 'old-refresh');
    refreshTokenMock.mockResolvedValue({
      access_token: 'must-not-escape',
      refresh_token: 'new-refresh',
      token_type: 'Bearer',
      expires_in: 900,
    });
    setSecretMock.mockRejectedValueOnce(new Error('keychain write failed'));

    await expect(getValidAccessToken(name)).rejects.toThrow('keychain write failed');
    expect(getSessionToken(name)).toBeNull();
  });
});

