/**
 * Benchmark corpus + held-out gate + accept() conjunction (ADR-176 phase 2).
 */
import { describe, it, expect } from 'vitest';
import {
  hashCorpus, verifyCorpus, scoreOnTasks, computeHeldOutSplit, accept,
  type BenchTask, type HarnessBenchmarkCorpus, type PromotionVerdict,
} from '../src/services/harness-benchmark.js';

function tasks(n: number): BenchTask[] {
  // task i: input=i, expected=2*i. A "candidate" is a multiplier.
  return Array.from({ length: n }, (_, i) => ({ id: `t${String(i).padStart(3, '0')}`, input: i, expected: 2 * i }));
}
const evalFn = (input: unknown, mult: number) => (input as number) * mult;
const gradeFn = (out: unknown, exp: unknown) => (out === exp ? 1 : 0);

describe('corpus integrity', () => {
  it('hash matches its tasks; tampering breaks verify', () => {
    const c: HarnessBenchmarkCorpus = { version: 'v1', tasks: tasks(10), corpusHash: hashCorpus(tasks(10)) };
    expect(verifyCorpus(c)).toBe(true);
    const tampered = { ...c, tasks: [...c.tasks.slice(1), { id: 't999', input: 1, expected: 999 }] };
    expect(verifyCorpus(tampered)).toBe(false);
  });
});

describe('held-out split (deterministic, disjoint)', () => {
  it('splits ~holdoutFrac, disjoint, reproducible', () => {
    const t = tasks(100);
    const a = computeHeldOutSplit(t, 0.2);
    const b = computeHeldOutSplit([...t].reverse(), 0.2); // order-independent
    expect(a.heldOut.length).toBe(20);
    expect(a.train.length).toBe(80);
    const trainIds = new Set(a.train.map(x => x.id));
    expect(a.heldOut.every(x => !trainIds.has(x.id))).toBe(true); // disjoint
    expect(a.heldOut.map(x => x.id)).toEqual(b.heldOut.map(x => x.id)); // reproducible
  });
});

describe('scoring — measured, not marketing', () => {
  it('a correct candidate scores 1.0; a wrong one lower', () => {
    const t = tasks(50);
    const good = scoreOnTasks(t, 2, evalFn, gradeFn);   // mult=2 is exactly right
    const bad = scoreOnTasks(t, 3, evalFn, gradeFn);
    expect(good.fitness).toBe(1);
    expect(good.passRate).toBe(1);
    expect(bad.fitness).toBeLessThan(1);
    // eslint-disable-next-line no-console
    console.log(`[bench] candidate mult=2 held-out fitness=${good.fitness} vs mult=3 fitness=${bad.fitness.toFixed(3)}`);
  });

  it('held-out delta: improved candidate beats baseline on the held-out split', () => {
    const t = tasks(100);
    const { heldOut } = computeHeldOutSplit(t, 0.2);
    // baseline mult=3 (wrong), champion mult=2 (right) — improvement is measured on held-out.
    const baseline = scoreOnTasks(heldOut, 3, evalFn, gradeFn);
    const champion = scoreOnTasks(heldOut, 2, evalFn, gradeFn);
    expect(champion.fitness).toBeGreaterThan(baseline.fitness);
  });
});

describe('accept() — conjunction of externally-measurable predicates', () => {
  const passing: PromotionVerdict = {
    heldOutScore: 0.82, baselineHeldOutScore: 0.79,
    redblue: 'PASS', drift: 0.01, driftThreshold: 0.05,
    replayDeterministic: true, receiptCoverage: 1,
    canaryRollbackRate: 0.02, baselineRollbackRate: 0.03,
  };

  it('accepts when every term holds', () => {
    const r = accept(passing);
    expect(r.accept).toBe(true);
    expect(r.failed).toEqual([]);
  });

  it('rejects on ANY single failing term', () => {
    expect(accept({ ...passing, heldOutScore: 0.79 }).failed).toContain('held_out_improves');
    expect(accept({ ...passing, redblue: 'FAIL' }).failed).toContain('redblue_pass');
    expect(accept({ ...passing, drift: 0.1 }).failed).toContain('drift_within');
    expect(accept({ ...passing, replayDeterministic: false }).failed).toContain('replay_deterministic');
    expect(accept({ ...passing, receiptCoverage: 0.9 }).failed).toContain('receipt_coverage_full');
    expect(accept({ ...passing, canaryRollbackRate: 0.05 }).failed).toContain('canary_no_worse');
    // each of the above is accept:false
    for (const over of [{ heldOutScore: 0.79 }, { redblue: 'FAIL' as const }, { drift: 0.1 }, { replayDeterministic: false }, { receiptCoverage: 0.9 }, { canaryRollbackRate: 0.05 }]) {
      expect(accept({ ...passing, ...over }).accept).toBe(false);
    }
  });
});

/**
 * Canary — bounded live-slice telemetry + no-worse gate (ADR-176 phase 5).
 */
import { describe, it, expect } from 'vitest';
import { runCanary, compareCanary, type CanaryRunner, type CanaryTelemetry } from '../src/services/harness-canary.js';

function slice(n: number) {
  return Array.from({ length: n }, (_, i) => ({ id: 't' + String(i).padStart(4, '0'), input: i }));
}

describe('runCanary', () => {
  it('bounds the sample by fraction and maxSamples', () => {
    const runner: CanaryRunner<number> = () => ({ ok: true, rolledBack: false, latencyMs: 10, costUsd: 0.001, accepted: true });
    expect(runCanary(0, slice(1000), runner, { sampleFraction: 0.1, maxSamples: 50 }).n).toBe(50); // cap
    expect(runCanary(0, slice(200), runner, { sampleFraction: 0.1 }).n).toBeLessThanOrEqual(20 + 1);
  });

  it('aggregates rollback/failure/acceptance rates + p95 latency + cost', () => {
    // 20% roll back, latencies spread 1..100, cost 0.002 each.
    const runner: CanaryRunner<number> = (input) => {
      const i = input as number;
      const rolledBack = i % 5 === 0;
      return { ok: !rolledBack, rolledBack, latencyMs: (i % 100) + 1, costUsd: 0.002, accepted: !rolledBack };
    };
    const t = runCanary(0, slice(100), runner, { sampleFraction: 1, maxSamples: 100 });
    expect(t.n).toBe(100);
    expect(t.rollbackRate).toBeCloseTo(0.2, 5);
    expect(t.failureRate).toBeCloseTo(0.2, 5);
    expect(t.costPerTask).toBeCloseTo(0.002, 5);
    expect(t.latencyP95).toBeGreaterThan(t.latencyMean); // p95 above mean for a spread dist
    // eslint-disable-next-line no-console
    console.log(`[bench] canary: n=${t.n} rollback=${t.rollbackRate} p95=${t.latencyP95}ms cost/task=$${t.costPerTask}`);
  });

  it('treats a throwing runner as a rollback/failure (fail-closed)', () => {
    const t = runCanary(0, slice(10), () => { throw new Error('boom'); }, { sampleFraction: 1 });
    expect(t.rollbackRate).toBe(1);
    expect(t.failureRate).toBe(1);
  });
});

describe('compareCanary — no-worse gate', () => {
  const base: CanaryTelemetry = { n: 100, rollbackRate: 0.05, failureRate: 0.05, acceptanceRate: 0.9, latencyP95: 100, latencyMean: 50, costPerTask: 0.003, costTotalUsd: 0.3 };

  it('passes when candidate is no worse', () => {
    const better: CanaryTelemetry = { ...base, rollbackRate: 0.02, latencyP95: 90, costPerTask: 0.0025 };
    expect(compareCanary(better, base).pass).toBe(true);
  });

  it('fails when rollback / latency / cost regress', () => {
    expect(compareCanary({ ...base, rollbackRate: 0.06 }, base).failed).toContain('rollback_no_worse');
    expect(compareCanary({ ...base, latencyP95: 200 }, base).failed).toContain('latency_no_worse');
    expect(compareCanary({ ...base, costPerTask: 0.01 }, base).failed).toContain('cost_no_worse');
  });
});

/**
 * Feedback applier — close the loop (ADR-176 phase 9).
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { applyChampion, rollbackActivePolicy, activeChampion, ADOPTED_CONFIG_FILE } from '../src/config/harness-feedback-applier.js';

function project(champion?: { championId: string; layer?: string; previous?: string | null }): string {
  const cwd = mkdtempSync(join(tmpdir(), 'feedback-'));
  mkdirSync(join(cwd, '.claude'), { recursive: true });
  if (champion) {
    writeFileSync(join(cwd, '.claude', ADOPTED_CONFIG_FILE), JSON.stringify({
      championId: champion.championId,
      manifest: { layer: champion.layer },
      previous: champion.previous ?? null,
    }));
  }
  return cwd;
}

describe('applyChampion', () => {
  it('applies the adopted champion to the active policy, provenance-tagged', () => {
    const cwd = project({ championId: 'sha256:aaa', layer: 'framework/node-cli' });
    const r = applyChampion(cwd, { now: 1000 });
    expect(r.applied).toBe(true);
    expect(r.to).toBe('sha256:aaa');
    const active = activeChampion(cwd)!;
    expect(active.championId).toBe('sha256:aaa');
    expect(active.provenanceTier).toBe('oracle:test-exec'); // never proxy
    expect(active.layer).toBe('framework/node-cli');
  });

  it('is idempotent — re-applying the same champion is a no-op', () => {
    const cwd = project({ championId: 'sha256:bbb' });
    expect(applyChampion(cwd, { now: 1 }).applied).toBe(true);
    expect(applyChampion(cwd, { now: 2 }).applied).toBe(false); // already active
  });

  it('carries the manifest policy.value into the active policy params (ADR-176/177 last mile)', () => {
    const cwd = mkdtempSync(join(tmpdir(), 'feedback-'));
    mkdirSync(join(cwd, '.claude'), { recursive: true });
    writeFileSync(join(cwd, '.claude', ADOPTED_CONFIG_FILE), JSON.stringify({
      championId: 'sha256:ccc',
