const tasks: BenchTask[] = Array.from({ length: 40 }, (_, i) => ({ id: 't' + i, input: i, expected: 2 * i }));
const trajectories: Trajectory[] = [
  { id: 'a', steps: [{ action: 'x', tier: 'oracle:test-exec' }], outcome: 'success', benchmarkTaskId: 'k', inputs: {}, recordedOutputs: { ok: 1 } },
];
const replay: ReplayFn = (t) => t.recordedOutputs;
const canaryRunner: CanaryRunner<number> = (_i, m) => ({ ok: m === 2, rolledBack: m !== 2, latencyMs: 5, costUsd: 0.001, accepted: m === 2 });

function fullInput(): HarnessWorkerInput {
  return {
    trajectories, corpus: { version: 'v1', tasks, corpusHash: hashCorpus(tasks) },
    baseline: 3, candidate: 2, evalFn: (i, m) => (i as number) * (m as number), gradeFn: (o, e) => (o === e ? 1 : 0),
    replay, verify: { redblue: async () => 'PASS', drift: async () => 0.01 }, canaryRunner,
    policyRefOf: (c) => 'sha256:' + c, layer: 'framework/node-cli',
  } as HarnessWorkerInput;
}

describe('runHarnessLoopWorker', () => {
  it('is a no-op when not opted in (RUFLO_HARNESS_LOOP off) — safe default', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'hw-'));
    const r = await runHarnessLoopWorker(cwd, { optInOverride: false, loadInput: fullInput });
    expect(r.ran).toBe(false);
    expect(r.reason).toMatch(/opt-in/);
  });

  it('is a no-op when opted in but no input is configured ($0 default)', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'hw-'));
    const r = await runHarnessLoopWorker(cwd, { optInOverride: true }); // default loadInput = null
    expect(r.ran).toBe(false);
    expect(r.reason).toMatch(/no harness input/);
  });

  it('runs + stages the unsigned champion when opted in with a promotable input', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'hw-'));
    const r = await runHarnessLoopWorker(cwd, { optInOverride: true, loadInput: fullInput });
    expect(r.ran).toBe(true);
    expect(r.accepted).toBe(true);
    expect(r.staged).toBe(true);
    const staged = join(cwd, '.claude-flow', STAGED_CHAMPION_FILE);
    expect(existsSync(staged)).toBe(true);
    const manifest = JSON.parse(readFileSync(staged, 'utf-8'));
    expect(manifest.policy.ref).toBe('sha256:2');
    expect(manifest.signature).toBeUndefined(); // UNSIGNED — publish signs
  });

  it('runs but stages nothing when the candidate is rejected', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'hw-'));
    const bad = () => ({ ...fullInput(), baseline: 2, candidate: 3 }); // candidate worse
    const r = await runHarnessLoopWorker(cwd, { optInOverride: true, loadInput: bad });
    expect(r.ran).toBe(true);
    expect(r.accepted).toBe(false);
    expect(r.staged).toBe(false);
    expect(existsSync(join(cwd, '.claude-flow', STAGED_CHAMPION_FILE))).toBe(false);
  });
});

/**
 * Version-stamped critical-helper auto-refresh.
 *
 * The propagation gap: Claude Code hooks run the project-local
 * `.claude/helpers/*.cjs`, not the npm package, so hook fixes don't reach
 * existing users without a manual re-init. This test proves the stamp-and-
 * refresh path closes it: a stale-stamped project silently re-copies the
 * current helpers on the next CLI startup; a current one is a no-op; and a
 * non-ruflo directory is never touched.
 *
 * The successful-copy tests use an ISOLATED, throwaway-keypair-signed
 * fixture (`makeSignedSource()`) rather than this repo's own real
 * `.claude/helpers` + its real Ed25519 signature. That coupling is
 * deliberately avoided: the real manifest is re-signed at publish time
 * (scripts/sign-helpers.mjs, needs a GCP secret or a local PEM key) and is
 * routinely stale mid-development whenever a critical helper changes without
 * an immediate re-sign — this suite must pass regardless of that state, and
 * only actually exercises `writeCriticalHelpers`' verify → hash → copy logic
 * when it does.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, readdirSync, unlinkSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { generateKeyPairSync, sign as edSign } from 'node:crypto';
import * as semver from 'semver';

import {
  autoRefreshHelpersIfStale,
  getInstalledCliVersion,
  HELPERS_REFRESH_LOCK_FILE,
  HELPERS_STAMP_FILE,
} from '../src/init/helper-refresh.js';
import { canonicalManifestBytes, sha256Hex } from '../src/init/helper-signing.js';

function makeProject(): { cwd: string; helpersDir: string } {
  const cwd = mkdtempSync(join(tmpdir(), 'helper-refresh-'));
  const helpersDir = join(cwd, '.claude', 'helpers');
  mkdirSync(helpersDir, { recursive: true });
  return { cwd, helpersDir };
}

/**
 * Build a throwaway-keypair-signed `.claude/helpers` source fixture:
 * `hook-handler.cjs` with recognizable NEW content + a validly-signed
 * manifest for it. Returns the source dir and the matching public key PEM
 * to inject via `pubkeyPemOverride`.
 */
function makeSignedSource(
  version: string,
  content = 'intelligence.feedback(!toolFailed); // NEW, real failure capture\n',
): { sourceDir: string; pubkeyPem: string } {
  const sourceDir = mkdtempSync(join(tmpdir(), 'helper-refresh-source-'));
  writeFileSync(join(sourceDir, 'hook-handler.cjs'), content);

  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  const manifest = { version, files: { 'hook-handler.cjs': sha256Hex(content) } };
  const signature = edSign(null, canonicalManifestBytes(manifest), privateKey).toString('base64');
  writeFileSync(
    join(sourceDir, 'helpers.manifest.json'),
    JSON.stringify({ manifest, signature, algorithm: 'ed25519' }),
  );

  return { sourceDir, pubkeyPem: publicKey.export({ type: 'spki', format: 'pem' }).toString() };
}

function makeWriteGate(): {
  reached: Promise<void>;
  release: () => void;
  beforeWrite: () => Promise<void>;
} {
  let signalReached!: () => void;
  const reached = new Promise<void>((resolve) => { signalReached = resolve; });
  let release!: () => void;
  const mayWrite = new Promise<void>((resolve) => { release = resolve; });
  return { reached, release, beforeWrite: async () => { signalReached(); await mayWrite; } };
}

describe('autoRefreshHelpersIfStale', () => {
  let version: string;
  beforeEach(() => { version = getInstalledCliVersion(); });

  it('refreshes a project whose helpers are stamped with an older version', async () => {
    const { cwd, helpersDir } = makeProject();
    // Old, hardcoded-success hook-handler + a stale stamp.
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'intelligence.feedback(true); // OLD, no failure capture\n');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '0.0.1-old');
    const { sourceDir, pubkeyPem } = makeSignedSource(version);

    const r = await autoRefreshHelpersIfStale(cwd, { sourceDirOverride: sourceDir, pubkeyPemOverride: pubkeyPem });
    expect(r.refreshed).toBe(true);
    expect(r.from).toBe('0.0.1-old');
    expect(r.to).toBe(version);

    // The stamp now matches the installed version.
    expect(readFileSync(join(helpersDir, HELPERS_STAMP_FILE), 'utf-8').trim()).toBe(version);
    // And the copied hook-handler carries the NEW failure-capture logic.
    const refreshed = readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8');
    expect(refreshed).toMatch(/toolFailed/);
    expect(refreshed).not.toContain('// OLD, no failure capture');
  });

  it('refuses to refresh when the source manifest signature does not verify (fail-closed)', async () => {
    const { cwd, helpersDir } = makeProject();
    const marker = 'PROJECT-HANDLER-UNTOUCHED-ON-BAD-SIGNATURE';
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), marker);
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '0.0.1-old');
    // Sign with one keypair, verify with an unrelated one — signature must fail.
    const { sourceDir } = makeSignedSource(version);
    const { publicKey: wrongPubkey } = generateKeyPairSync('ed25519');

    const r = await autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: sourceDir,
      pubkeyPemOverride: wrongPubkey.export({ type: 'spki', format: 'pem' }).toString(),
    });
    expect(r.refreshed).toBe(false);
    expect(r.blocked).toMatch(/signature invalid|missing/);
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe(marker);
  });

  it('is a no-op when the stamp already matches the installed version', async () => {
    const { cwd, helpersDir } = makeProject();
    const marker = 'CURRENT-HANDLER-DO-NOT-OVERWRITE';
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), marker);
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), version);

    const r = await autoRefreshHelpersIfStale(cwd);
    expect(r.refreshed).toBe(false);
    // Untouched — the fast path never copied over our marker file.
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe(marker);
  });

  it('refreshes an UNSTAMPED (pre-feature) project on first run', async () => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'intelligence.feedback(true);\n');
    // no stamp file at all
    const { sourceDir, pubkeyPem } = makeSignedSource(version);

    const r = await autoRefreshHelpersIfStale(cwd, { sourceDirOverride: sourceDir, pubkeyPemOverride: pubkeyPem });
    expect(r.refreshed).toBe(true);
    expect(r.from).toBe('(unstamped)');
    expect(existsSync(join(helpersDir, HELPERS_STAMP_FILE))).toBe(true);
  });

  it('is a safe no-op outside a ruflo project (never creates files)', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'not-ruflo-'));
    const r = await autoRefreshHelpersIfStale(cwd);
    expect(r.refreshed).toBe(false);
    expect(existsSync(join(cwd, '.claude'))).toBe(false); // did not scaffold anything
  });

  it('never downgrades — an OLDER installed version than the stamp is a no-op', async () => {
    // Real trigger: a stray/older installed binary (stale npx cache,
    // marketplace install lagging an unpublished dev-tree fix) running any
    // command against a project whose helpers are stamped with a NEWER
    // version than that binary reports. Must never silently overwrite the
    // project's (fresher, hand-fixed) helpers with the older binary's own.
    const { cwd, helpersDir } = makeProject();
    const marker = 'NEWER-HANDLER-DO-NOT-DOWNGRADE';
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), marker);
    const futureVersion = `${semver.major(version) + 1}.0.0`;
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), futureVersion);

    const r = await autoRefreshHelpersIfStale(cwd);
    expect(r.refreshed).toBe(false);
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe(marker);
    // Stamp itself is also left untouched — not silently rolled back either.
    expect(readFileSync(join(helpersDir, HELPERS_STAMP_FILE), 'utf-8').trim()).toBe(futureVersion);
  });

  it('alsoRefreshGlobal:true refreshes ~/.claude/helpers under a redirected HOME (regression: pre-3.31.3 the global copy never refreshed, so the 2026-07-13 promo row never reached existing installs)', async () => {
    const { cwd } = makeProject(); // project dir is a real ruflo project so the project pass has something to do
    const projectHelpers = join(cwd, '.claude', 'helpers');
    writeFileSync(join(projectHelpers, 'hook-handler.cjs'), 'intelligence.feedback(true); // OLD project\n');
    writeFileSync(join(projectHelpers, HELPERS_STAMP_FILE), '0.0.1-old');

    // Redirect HOME so we don't touch the developer's real ~/.claude/helpers.
    // Populate the "global" helpers dir with a stale-stamped hook-handler.
    const fakeHome = mkdtempSync(join(tmpdir(), 'helper-refresh-home-'));
    const globalHelpers = join(fakeHome, '.claude', 'helpers');
    mkdirSync(globalHelpers, { recursive: true });
    writeFileSync(join(globalHelpers, 'hook-handler.cjs'), 'intelligence.feedback(true); // OLD global\n');
    writeFileSync(join(globalHelpers, HELPERS_STAMP_FILE), '0.0.1-old');

    const { sourceDir, pubkeyPem } = makeSignedSource(version);
    const savedHome = process.env.HOME;
    const savedUserProfile = process.env.USERPROFILE;
    process.env.HOME = fakeHome;
    process.env.USERPROFILE = fakeHome; // Node's os.homedir() reads USERPROFILE on Windows
    try {
      const r = await autoRefreshHelpersIfStale(cwd, {
        sourceDirOverride: sourceDir,
        pubkeyPemOverride: pubkeyPem,
        alsoRefreshGlobal: true,
      });
      // Project pass fired (top-level fields are the project result — API compat)
      expect(r.refreshed).toBe(true);
      expect(r.to).toBe(version);
      // Global pass ALSO fired, carried in the new `global` field
      expect(r.global?.refreshed).toBe(true);
      expect(r.global?.from).toBe('0.0.1-old');
      expect(r.global?.to).toBe(version);
      // Global hook-handler was actually rewritten (not just the stamp)
      const refreshedGlobal = readFileSync(join(globalHelpers, 'hook-handler.cjs'), 'utf-8');
      expect(refreshedGlobal).toMatch(/toolFailed/);
      expect(refreshedGlobal).not.toContain('// OLD global');
    } finally {
      if (savedHome === undefined) delete process.env.HOME; else process.env.HOME = savedHome;
      if (savedUserProfile === undefined) delete process.env.USERPROFILE; else process.env.USERPROFILE = savedUserProfile;
    }
  });

  it('alsoRefreshGlobal defaults to false — tests without the flag never touch $HOME (invariant that keeps every OTHER test in this file safe)', async () => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'intelligence.feedback(true);\n');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '0.0.1-old');

    // Redirect HOME to an empty scratch dir with no .claude/helpers. If the
    // global pass fired despite the flag being unset, this test would either
    // create files under fakeHome (assertion below catches it) or surface a
    // `global` field on the result (also checked).
    const fakeHome = mkdtempSync(join(tmpdir(), 'helper-refresh-should-not-touch-home-'));
    const savedHome = process.env.HOME;
    const savedUserProfile = process.env.USERPROFILE;
    process.env.HOME = fakeHome;
    process.env.USERPROFILE = fakeHome;
    try {
      const { sourceDir, pubkeyPem } = makeSignedSource(version);
      const r = await autoRefreshHelpersIfStale(cwd, { sourceDirOverride: sourceDir, pubkeyPemOverride: pubkeyPem });
      expect(r.refreshed).toBe(true); // project pass still fired
      expect(r.global).toBeUndefined(); // global pass DID NOT fire
      expect(existsSync(join(fakeHome, '.claude'))).toBe(false); // never scaffolded under HOME
    } finally {
      if (savedHome === undefined) delete process.env.HOME; else process.env.HOME = savedHome;
      if (savedUserProfile === undefined) delete process.env.USERPROFILE; else process.env.USERPROFILE = savedUserProfile;
    }
  });

  it('never downgrades — an EQUAL-but-differently-formatted stamp is a no-op', async () => {
    // e.g. stamp has a build/prerelease suffix that string-compares unequal
    // to the installed version but is semver-equal or newer.
    const { cwd, helpersDir } = makeProject();
    const marker = 'SAME-VERSION-DIFFERENT-STRING';
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), marker);
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), `${version}+build.1`);

    const r = await autoRefreshHelpersIfStale(cwd);
    expect(r.refreshed).toBe(false);
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe(marker);
  });

  it.each([
    ['older checks first', '2.0.0', 'OLDER-HANDLER', '3.0.0', 'NEWER-HANDLER'],
    ['newer checks first', '3.0.0', 'NEWER-HANDLER', '2.0.0', 'OLDER-HANDLER'],
  ])('serializes competing refreshes when %s', async (_label, firstVersion, firstContent, secondVersion, secondContent) => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'INITIAL-HANDLER');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '1.0.0');
    const first = makeSignedSource(firstVersion, firstContent);
    const second = makeSignedSource(secondVersion, secondContent);
    const gate = makeWriteGate();

    const firstRefresh = autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: first.sourceDir,
      pubkeyPemOverride: first.pubkeyPem,
      versionOverride: firstVersion,
      beforeWriteOverride: gate.beforeWrite,
    });
    await gate.reached;
    const secondRefresh = autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: second.sourceDir,
      pubkeyPemOverride: second.pubkeyPem,
      versionOverride: secondVersion,
    });
    gate.release();
    await Promise.all([firstRefresh, secondRefresh]);

    expect(readFileSync(join(helpersDir, HELPERS_STAMP_FILE), 'utf-8').trim()).toBe('3.0.0');
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe('NEWER-HANDLER');
    expect(readdirSync(helpersDir).filter((name) => name.includes('.tmp-'))).toEqual([]);
  });

  it('does not let a same-version waiter replace the completed helper set', async () => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'INITIAL-HANDLER');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '1.0.0');
    const first = makeSignedSource('2.0.0', 'FIRST-SAME-VERSION-HANDLER');
    const second = makeSignedSource('2.0.0', 'SECOND-SAME-VERSION-HANDLER');

    const gate = makeWriteGate();
    const firstRefresh = autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: first.sourceDir,
      pubkeyPemOverride: first.pubkeyPem,
      versionOverride: '2.0.0',
      beforeWriteOverride: gate.beforeWrite,
    });
    await gate.reached;

    const secondRefresh = autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: second.sourceDir,
      pubkeyPemOverride: second.pubkeyPem,
      versionOverride: '2.0.0',
    });
    gate.release();
    const [, secondResult] = await Promise.all([firstRefresh, secondRefresh]);

    expect(secondResult.refreshed).toBe(false);
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe('FIRST-SAME-VERSION-HANDLER');
  });

  it('fails closed while another live process owns the refresh lock', async () => {
    const { cwd, helpersDir } = makeProject();
    const marker = 'LIVE-LOCK-HANDLER';
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), marker);
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '1.0.0');
    const lockPath = join(helpersDir, HELPERS_REFRESH_LOCK_FILE);
    writeFileSync(lockPath, JSON.stringify({ pid: process.pid, token: 'test-owner' }));

    try {
      const r = await autoRefreshHelpersIfStale(cwd, {
        versionOverride: '2.0.0',
        lockWaitMsOverride: 0,
      });
      expect(r.refreshed).toBe(false);
      expect(r.blocked).toMatch(/already in progress/);
      expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe(marker);
    } finally {
      unlinkSync(lockPath);
    }
  });

  it('honors .LOCKED before attempting to acquire the refresh lock', async () => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'HAND-MAINTAINED');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '1.0.0');
    writeFileSync(join(helpersDir, '.LOCKED'), '');
    const lockPath = join(helpersDir, HELPERS_REFRESH_LOCK_FILE);
    writeFileSync(lockPath, JSON.stringify({ pid: process.pid, token: 'other-owner' }));

    try {
      const r = await autoRefreshHelpersIfStale(cwd, {
        versionOverride: '2.0.0',
        lockWaitMsOverride: 0,
      });
      expect(r.refreshed).toBe(false);
      expect(r.blocked).toMatch(/\.LOCKED marker present/);
      expect(readFileSync(lockPath, 'utf-8')).toContain('other-owner');
    } finally {
      unlinkSync(lockPath);
    }
  });

  it('recovers an abandoned lock created before owner metadata was written', async () => {
    const { cwd, helpersDir } = makeProject();
    writeFileSync(join(helpersDir, 'hook-handler.cjs'), 'INITIAL-HANDLER');
    writeFileSync(join(helpersDir, HELPERS_STAMP_FILE), '1.0.0');
    const lockPath = join(helpersDir, HELPERS_REFRESH_LOCK_FILE);
    writeFileSync(lockPath, '');
    const source = makeSignedSource('2.0.0', 'RECOVERED-HANDLER');

    const r = await autoRefreshHelpersIfStale(cwd, {
      sourceDirOverride: source.sourceDir,
      pubkeyPemOverride: source.pubkeyPem,
      versionOverride: '2.0.0',
      malformedLockStaleMsOverride: 0,
    });

    expect(r.refreshed).toBe(true);
    expect(readFileSync(join(helpersDir, 'hook-handler.cjs'), 'utf-8')).toBe('RECOVERED-HANDLER');
    expect(existsSync(lockPath)).toBe(false);
  });
});

/**
 * Ed25519 provenance gate for the helper auto-refresh (ADR-174 security).
 *
 * The auto-refresh copies auto-executing hook code from the installed package.
 * These tests prove the fail-closed gate: a validly-signed manifest verifies,
 * ANY tampering (hash, signature, algorithm) is rejected, and the ACTUAL
 * shipped manifest is both signed by ruflo's key and matches the shipped
 * helper files byte-for-byte.
 */
import { describe, it, expect } from 'vitest';
import { generateKeyPairSync, sign as edSign } from 'node:crypto';
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  verifyHelpersManifest, canonicalManifestBytes, sha256Hex,
  RUFLO_HELPERS_PUBKEY, HELPERS_MANIFEST_FILE,
  type HelpersManifest,
} from '../src/init/helper-signing.js';

const PKG_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HELPERS_DIR = join(PKG_ROOT, '.claude', 'helpers');

function makeSigned(manifest: HelpersManifest, privPem: string, algorithm = 'ed25519') {
  const sig = edSign(null, canonicalManifestBytes(manifest), privPem).toString('base64');
  return JSON.stringify({ manifest, signature: sig, algorithm });
}

describe('verifyHelpersManifest — fail-closed Ed25519 gate', () => {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519', {
    publicKeyEncoding: { type: 'spki', format: 'pem' },
    privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
  });
  const manifest: HelpersManifest = { version: '9.9.9', files: { 'hook-handler.cjs': 'a'.repeat(64), 'intelligence.cjs': 'b'.repeat(64) } };

  it('accepts a validly-signed manifest and returns the trusted map', () => {
    const out = verifyHelpersManifest(makeSigned(manifest, privateKey), publicKey);
    expect(out).not.toBeNull();
    expect(out!.files['hook-handler.cjs']).toBe('a'.repeat(64));
  });

  it('REJECTS a manifest whose hash was tampered after signing', () => {
    const signed = JSON.parse(makeSigned(manifest, privateKey));
    signed.manifest.files['hook-handler.cjs'] = 'c'.repeat(64); // flip a hash, keep old signature
    expect(verifyHelpersManifest(JSON.stringify(signed), publicKey)).toBeNull();
  });

  it('REJECTS a manifest signed by a DIFFERENT key (wrong provenance)', () => {
    const other = generateKeyPairSync('ed25519', { privateKeyEncoding: { type: 'pkcs8', format: 'pem' }, publicKeyEncoding: { type: 'spki', format: 'pem' } });
    expect(verifyHelpersManifest(makeSigned(manifest, other.privateKey), publicKey)).toBeNull();
  });

  it('REJECTS a non-ed25519 algorithm and malformed input', () => {
    expect(verifyHelpersManifest(makeSigned(manifest, privateKey, 'rsa'), publicKey)).toBeNull();
    expect(verifyHelpersManifest('not json', publicKey)).toBeNull();
    expect(verifyHelpersManifest('{}', publicKey)).toBeNull();
    expect(verifyHelpersManifest(JSON.stringify({ manifest, algorithm: 'ed25519' }), publicKey)).toBeNull(); // no signature
  });
});

describe('shipped helpers manifest — real signature + real content', () => {
  const manifestPath = join(HELPERS_DIR, HELPERS_MANIFEST_FILE);

  it('exists and verifies against the baked ruflo public key', () => {
    expect(existsSync(manifestPath)).toBe(true);
    const trusted = verifyHelpersManifest(readFileSync(manifestPath, 'utf-8'), RUFLO_HELPERS_PUBKEY);
    expect(trusted).not.toBeNull();
  });

  it('its hashes match the actual shipped helper files (a byte flip would break the gate)', () => {
    const trusted = verifyHelpersManifest(readFileSync(manifestPath, 'utf-8'), RUFLO_HELPERS_PUBKEY)!;
    for (const [name, expected] of Object.entries(trusted.files)) {
      const p = join(HELPERS_DIR, name);
      expect(existsSync(p), `${name} shipped`).toBe(true);
      expect(sha256Hex(readFileSync(p)), `${name} integrity`).toBe(expected);
    }
    // A tampered helper would NOT match → the refresh gate refuses.
    const anyName = Object.keys(trusted.files)[0];
    expect(sha256Hex(readFileSync(join(HELPERS_DIR, anyName)) + '// tampered')).not.toBe(trusted.files[anyName]);
  });
});

/**
 * Hermes-Agent Tier-1 adoptions (see docs/reviews/intelligence-system-audit-2026-05-29.md
 * → Hermes capability map):
 *   #14 — reasoning-tag scrubbing keeps extended-thinking blocks out of the
 *         learning trajectory (so DISTILL doesn't embed reasoning tokens).
 *   #6  — tool-loop circuit breaker warns/blocks on repeated consecutive
 *         failures of the same command.
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { scrubReasoningBlocks } from '../src/mcp-tools/hooks-tools.js';
import {
  checkCommandLoop,
  recordCommandOutcome,
  _resetLoopHistory,
} from '../src/mcp-tools/tool-loop-guardrail.js';

describe('#14 — reasoning-tag scrubbing', () => {
  it('strips paired thinking/reasoning blocks', () => {
    expect(scrubReasoningBlocks('did it <think>secret CoT</think> ok')).toBe('did it  ok');
    expect(scrubReasoningBlocks('a<thinking>x</thinking>b')).toBe('ab');
    expect(scrubReasoningBlocks('a<reasoning>y</reasoning>b')).toBe('ab');
    expect(scrubReasoningBlocks('a<REASONING_SCRATCHPAD>z</REASONING_SCRATCHPAD>b')).toBe('ab');
  });
  it('leaves prose that merely mentions the tag untouched (boundary-gated)', () => {
    expect(scrubReasoningBlocks('We document the <think> tag here')).toBe('We document the <think> tag here');
  });
  it('is a no-op on tag-free text and non-strings', () => {
    expect(scrubReasoningBlocks('plain output')).toBe('plain output');
    expect(scrubReasoningBlocks(undefined as unknown as string)).toBe(undefined);
  });
});

describe('#6 — tool-loop circuit breaker', () => {
  beforeEach(() => _resetLoopHistory());

  it('allows until the warn threshold, then warns, then blocks', () => {
    const cmd = 'npm run flaky';
    expect(checkCommandLoop(cmd).verdict).toBe('allow');
    recordCommandOutcome(cmd, false);
    recordCommandOutcome(cmd, false);
    expect(checkCommandLoop(cmd).verdict).toBe('allow'); // 2 fails
    recordCommandOutcome(cmd, false);
    expect(checkCommandLoop(cmd).verdict).toBe('warn');  // 3 fails
    recordCommandOutcome(cmd, false);
    recordCommandOutcome(cmd, false);
    const v = checkCommandLoop(cmd);
    expect(v.verdict).toBe('block'); // 5 fails
    expect(v.consecutiveFailures).toBe(5);
    expect(v.hint).toMatch(/failed 5/);
  });

  it('a success resets the streak', () => {
    const cmd = 'pytest';
    for (let i = 0; i < 5; i++) recordCommandOutcome(cmd, false);
    expect(checkCommandLoop(cmd).verdict).toBe('block');
    recordCommandOutcome(cmd, true);
    expect(checkCommandLoop(cmd).verdict).toBe('allow');
  });

  it('interleaved other commands do not break the streak (exact-match only)', () => {
    recordCommandOutcome('build', false);
    recordCommandOutcome('ls', true);     // different command
    recordCommandOutcome('build', false);
    recordCommandOutcome('git status', true);
    recordCommandOutcome('build', false);
    expect(checkCommandLoop('build').verdict).toBe('warn'); // 3 build failures, ls/git ignored
    expect(checkCommandLoop('ls').verdict).toBe('allow');
  });
});

/**
 * agentdb_hierarchical-store durability contract (#2887).
 *
 * agentdb removed its `HierarchicalMemory` export at 3.0.0-alpha.17, so every
 * hierarchical-store call lands in @claude-flow/memory's TieredMemoryStore
 * fallback. While that fallback was purely in-process, the bridge still
 * reported `success: true` for writes that never reached disk and were never
 * recallable — silent data loss.
 *
 * These tests pin the decision the bridge makes about a store's durability:
 * a volatile backing store must never be described as durable, and every
 * result must name the controller actually in use plus why it was chosen.
 */

import { describe, expect, it } from 'vitest';
import { describeHierarchicalStore } from '../src/memory/memory-bridge.js';
import { agentdbHierarchicalStore, agentdbTools } from '../src/mcp-tools/agentdb-tools.js';

/** Minimal TieredMemoryStore stand-in with a switchable durability mode. */
function fakeTieredStore(durable: boolean) {
  return {
    isDurable: () => durable,
    getPersistence: () => (durable ? 'sqlite' : 'volatile'),
    countPersisted: () => (durable ? 1 : null),
  };
}

describe('describeHierarchicalStore — durability contract (#2887)', () => {
  it('marks a SQLite-backed fallback durable and names its cause', () => {
    const info = describeHierarchicalStore(fakeTieredStore(true), {
      reason: 'agentdb-export-missing',
    });

    expect(info).toEqual({
      controller: 'tieredMemoryStore',
      fallbackFrom: 'agentdb-export-missing',
      durable: true,
      persistence: 'sqlite',
    });
  });

  it('never describes a volatile fallback as durable', () => {
    const info = describeHierarchicalStore(fakeTieredStore(false), {
      reason: 'agentdb-unavailable',
    });

    expect(info.durable).toBe(false);
    expect(info.persistence).toBe('volatile');
    expect(info.controller).toBe('tieredMemoryStore');
  });

  it('still names the fallback when the registry cannot report a reason', () => {
    const info = describeHierarchicalStore(fakeTieredStore(true), null);

    expect(info.controller).toBe('tieredMemoryStore');
    expect(info.fallbackFrom).toBe('hierarchicalMemory');
  });

  it('treats a native agentdb controller (no isDurable) as the durable path', () => {
    const nativeHm = { getStats: () => ({}), promote: () => {}, store: async () => 'id' };

    const info = describeHierarchicalStore(nativeHm, null);

    expect(info).toEqual({
      controller: 'hierarchicalMemory',
      durable: true,
      persistence: 'agentdb',
    });
  });
});

describe('agentdb_hierarchical-store MCP surface (#2887)', () => {
  it('is registered as an MCP tool', () => {
    expect(agentdbTools.map((t) => t.name)).toContain('agentdb_hierarchical-store');
  });

  it('rejects an invalid tier without claiming a write happened', async () => {
    const result = await agentdbHierarchicalStore.handler({
      key: 'k',
      value: 'v',
      tier: 'not-a-real-tier',
    });

    expect(result.success).toBe(false);
    expect(result.error).toMatch(/tier/i);
  });

  it('never returns a bare success — a durability verdict always accompanies it', async () => {
    const result = await agentdbHierarchicalStore.handler({
      key: 'durability-contract-probe',
      value: 'probe',
      tier: 'working',
    });

    // The bridge may be unavailable in a bare test env; what must never happen
    // is success:true with no statement about whether the write is durable.
    if (result.success === true) {
      expect(result.durable).toBe(true);
      expect(typeof result.persistence).toBe('string');
      expect(typeof result.controller).toBe('string');
    } else {
      expect(typeof result.error).toBe('string');
    }
  });
});

/**
 * Regression test for #2269.
 *
 * The arg parser's normalizeKey converts kebab-case CLI flags to camelCase and
 * stores ONLY the normalized key. Code in hive-mind.ts that previously read
 * `flags['dangerously-skip-permissions']` was therefore always undefined, and
 * `=== true` always evaluated false, so `--dangerously-skip-permissions` was
 * silently dropped from the spawned `claude` process — every Edit/Write call
 * landed in `permission_denials` and headless runs couldn't change any files.
 *
 * The fix mirrors the dual-key fallback used elsewhere in hive-mind.ts (e.g.
 * isNonInteractive): accept either the kebab key or the camelCase key.
 *
 * This test pins down both the parser's normalization behavior AND the
 * predicate from the fix, so a future refactor of either piece can't
 * silently regress the flag-drop bug.
 */

import { describe, it, expect } from 'vitest';
import { CommandParser } from '../src/parser.js';

// The exact predicate from v3/@claude-flow/cli/src/commands/hive-mind.ts
// (kept inline rather than importing the whole spawn action, which spawns a
// real child process at module-load time).
function shouldSkipPermissions(flags: Record<string, unknown>): boolean {
  return (
    (flags['dangerously-skip-permissions'] === true || flags.dangerouslySkipPermissions === true) &&
    !(flags['no-auto-permissions'] || flags.noAutoPermissions || flags.autoPermissions === false)
  );
}

describe('#2269 hive-mind --dangerously-skip-permissions flag handling', () => {
  it('parser normalizes the kebab flag to camelCase and leaves the kebab key undefined', () => {
    const parser = new CommandParser({ allowUnknownFlags: true });
    const { flags } = parser.parse(['--dangerously-skip-permissions']);

    // This is the heart of the bug: reading the kebab key alone is always
    // undefined because the parser stores the normalized key.
    expect(flags['dangerously-skip-permissions']).toBeUndefined();
    expect(flags.dangerouslySkipPermissions).toBe(true);
  });

  it('skipPermissions=true when the CLI passes --dangerously-skip-permissions', () => {
    const parser = new CommandParser({ allowUnknownFlags: true });
    const { flags } = parser.parse(['--dangerously-skip-permissions']);

    expect(shouldSkipPermissions(flags as Record<string, unknown>)).toBe(true);
  });

  it('skipPermissions=false when --no-auto-permissions is also passed', () => {
    const parser = new CommandParser({ allowUnknownFlags: true });
    const { flags } = parser.parse([
      '--dangerously-skip-permissions',
      '--no-auto-permissions',
    ]);

    expect(shouldSkipPermissions(flags as Record<string, unknown>)).toBe(false);
  });

  it('skipPermissions=false when neither key is set', () => {
    expect(shouldSkipPermissions({})).toBe(false);
  });

  it('predicate accepts the camelCase key directly (parser-independent contract)', () => {
    // Belt-and-braces: even if a future caller hand-constructs the flags
    // object with only the camelCase key, the predicate still works.
    expect(shouldSkipPermissions({ dangerouslySkipPermissions: true })).toBe(true);
    expect(shouldSkipPermissions({
      dangerouslySkipPermissions: true,
      noAutoPermissions: true,
    })).toBe(false);
  });

  it('predicate still accepts the legacy kebab key (back-compat with hand-built flag maps)', () => {
    // Some callers (tests, programmatic invocations) may build the flags
    // object manually with the kebab key. The fix is intentionally a dual
    // read, so this path keeps working.
    expect(shouldSkipPermissions({ 'dangerously-skip-permissions': true })).toBe(true);
  });

  it('parser produces the yargs-style negation autoPermissions:false for --no-auto-permissions', () => {
    // This pins the parser contract that drives the deny-clause third term.
    // If the parser ever changes its negation idiom (e.g. starts storing
    // noAutoPermissions:true instead), this test fails BEFORE the predicate
    // silently goes back to ignoring --no-auto-permissions in production.
    const parser = new CommandParser({ allowUnknownFlags: true });
    const { flags } = parser.parse(['--no-auto-permissions']);
    expect(flags.autoPermissions).toBe(false);
    expect(flags['no-auto-permissions']).toBeUndefined();
    expect(flags.noAutoPermissions).toBeUndefined();
  });

  it('predicate denies when only the yargs-style negation key is set', () => {
    // Belt-and-braces for the parser-produced shape, independent of the
    // CLI integration test above.
    expect(shouldSkipPermissions({
      dangerouslySkipPermissions: true,
      autoPermissions: false,
    })).toBe(false);
  });

  it('predicate ignores autoPermissions:true (a positive autoPermissions does NOT enable skip on its own)', () => {
    // Guard against an over-broad reading of the third term: only
    // autoPermissions === false should be treated as the negation signal.
    expect(shouldSkipPermissions({ autoPermissions: true })).toBe(false);
    // And it still allows skip when the negation is absent.
    expect(shouldSkipPermissions({
      dangerouslySkipPermissions: true,
      autoPermissions: true,
    })).toBe(true);
  });
});

/**
 * Drift guard: `.claude/helpers/hook-handler.cjs` (root) vs.
 * `v3/@claude-flow/cli/.claude/helpers/hook-handler.cjs` (package).
 *
 * These are two committed copies of the same critical helper (ADR-174) — the
 * package copy is what ships; the root copy is this repo's own dogfood
 * install. They are NOT generated from `helpers-generator.ts`'s
 * `generateHookHandler()` — that function is a deliberately simpler inline
 * fallback used only when copying the real file from the package fails
 * (see its own doc comment), so comparing against it would be the wrong
 * guard. The two committed .cjs files themselves must simply never diverge:
 * a prior session's hand-edits DID diverge (the fix for the promo-cache bug
 * and the ADR-312/313 rate-limit nudge landed in the package copy but never
 * got synced to root), and the drift went unnoticed until this test was
 * written, which is exactly the failure mode this guards against.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync } from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { generateHookHandler } from '../src/init/helpers-generator.js';

describe('hook-handler.cjs — root/package artifact parity', () => {
  it('the root and package copies are byte-identical', () => {
    const here = path.dirname(fileURLToPath(import.meta.url));
    const rootArtifact = path.resolve(here, '../../../../.claude/helpers/hook-handler.cjs');
    const pkgArtifact = path.resolve(here, '../.claude/helpers/hook-handler.cjs');
    if (!existsSync(rootArtifact)) return; // package tested in isolation; nothing to guard
    expect(readFileSync(rootArtifact, 'utf-8')).toBe(readFileSync(pkgArtifact, 'utf-8'));
  });
});

describe('hook-handler.cjs — resolveCliBinForHook validates a real dist, not just bin/cli.js', () => {
  // Claude Code's own plugin marketplace mechanism installs by git clone/pull
  // with no build step, so ~/.claude/plugins/marketplaces/ruflo is a
  // source-only checkout by construction: bin/cli.js exists on disk, but
  // importing dist/src/index.js from it throws MODULE_NOT_FOUND on every
  // real command (confirmed live — only --version happens to survive it).
  // Before this fix, resolveCliBinForHook() picked that doomed candidate and
  // spawnDetachedFunnelRefresh()/spawnDetachedAdvisorRefresh() had no
  // fallback, so a marketplace install's promo/advisor refresh silently
  // never fired, on any OS.
  const here = path.dirname(fileURLToPath(import.meta.url));
  const rootArtifact = path.resolve(here, '../../../../.claude/helpers/hook-handler.cjs');
  const pkgArtifact = path.resolve(here, '../.claude/helpers/hook-handler.cjs');
  const source = readFileSync(existsSync(rootArtifact) ? rootArtifact : pkgArtifact, 'utf-8');

  it('checks for a compiled dist/src/index.js before trusting a candidate', () => {
    expect(source).toContain("path.join(path.dirname(p), '..', 'dist', 'src', 'index.js')");
  });

  it('falls back to npx (not a silent no-op) when no local candidate has a real dist', () => {
    const idx = source.indexOf('function spawnDetachedHookRefresh');
    expect(idx).toBeGreaterThan(-1);
    const body = source.slice(idx, idx + 700);
    expect(body).toContain('@claude-flow/cli');
    expect(body).toContain('--prefer-offline');
    expect(body).not.toContain('if (!cliBin) return;');
  });
});

describe('generateHookHandler() fallback — funnel refresh wiring (#2661-adjacent)', () => {
  // Unlike the committed .cjs artifacts above, this fallback IS generated
  // from generateHookHandler() directly — it's the inline template used
  // when copying the real file from the package fails. Its own
  // session-restore handler must still spawn the funnel refresh, or a
  // fallback-only install would never populate the promo cache.
  const source = generateHookHandler();

  it('defines spawnFunnelRefresh as a detached, unref\'d, best-effort spawn', () => {
    expect(source).toContain('function spawnFunnelRefresh()');
    expect(source).toContain('detached: true');
    expect(source).toContain('child.unref()');
  });

  it('wires spawnFunnelRefresh() into the session-restore handler', () => {
    const idx = source.indexOf("'session-restore':");
    expect(idx).toBeGreaterThan(-1);
    const handlerBody = source.slice(idx, idx + 200);
    expect(handlerBody).toContain('spawnFunnelRefresh();');
  });

  it('is syntactically valid JavaScript', () => {
    const withoutShebang = source.replace(/^#!.*\n/, '');
    expect(() => new Function(withoutShebang)).not.toThrow();
  });
});

/**
 * Hooks Intelligence Learning — Audit Fix Smoke Tests
 *
 * AUDIT FINDINGS #4 & #5:
 *  (A) hooks_intelligence_trajectory-end must feed the EWC consolidator a
 *      gradient derived from the trajectory's REAL embedding (via
 *      generateEmbedding) — NOT a synthetic sine wave. If no real embedding is
 *      available, it must SKIP the EWC update rather than inject noise.
 *  (B) hooks_intelligence_learn must actually TRIGGER a real learning/
 *      consolidation cycle (distillLearning), not merely echo stats.
 *
 * These tests isolate the handlers with mocks so no real DB/ONNX is required.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';

// --- Mocks (must be declared before importing the module under test) ---

// Capture the gradient passed to EWC so we can assert it is the real embedding.
const recordGradient = vi.fn();
const getConsolidationStats = vi.fn(() => ({
  avgPenalty: 0.42,
  consolidationCount: 1,
  highImportancePatterns: 0,
  totalPatterns: 1,
}));

vi.mock('../src/memory/ewc-consolidation.js', () => ({
  getEWCConsolidator: vi.fn(async () => ({
    recordGradient,
    getConsolidationStats,
  })),
}));

// SONA optimizer present and "learns" so the success branch runs.
vi.mock('../src/memory/sona-optimizer.js', () => ({
  getSONAOptimizer: vi.fn(async () => ({
    processTrajectoryOutcome: vi.fn(() => ({
      learned: true,
      patternKey: 'pattern-x',
      confidence: 0.9,
    })),
    getStats: vi.fn(() => ({
      totalPatterns: 3,
      successfulRoutings: 2,
      failedRoutings: 1,
      trajectoriesProcessed: 3,
      avgConfidence: 0.7,
    })),
  })),
}));

// REAL embedding signal — a distinctive vector that is clearly NOT a sine wave.
const REAL_EMBEDDING = new Array(384).fill(0).map((_, i) => (i % 2 === 0 ? 0.5 : 0.25));
vi.mock('../src/memory/memory-initializer.js', () => ({
  generateEmbedding: vi.fn(async () => ({
    embedding: REAL_EMBEDDING,
    dimensions: REAL_EMBEDDING.length,
    model: 'mock-onnx',
  })),
  // storeEntry must succeed so the success/learning branch (which contains the
  // EWC update) is reached in trajectory-end.
  storeEntry: vi.fn(async () => ({ success: true, id: 'mock-trajectory-id' })),
}));

// Intelligence layer — distillLearning is the real DISTILL+CONSOLIDATE path.
const distillLearning = vi.fn(async () => ({ patternsDistilled: 5, ewcPenalty: 0.13 }));
const runBackgroundLearning = vi.fn(async () => {});
vi.mock('../src/memory/intelligence.js', () => ({
  distillLearning,
  runBackgroundLearning,
}));

// graph-edge-writer is fire-and-forget; stub it.
vi.mock('../src/memory/graph-edge-writer.js', () => ({
  insertGraphEdge: vi.fn(async () => {}),
}));

import {
  hooksTrajectoryStart,
  hooksTrajectoryStep,
  hooksTrajectoryEnd,
  hooksIntelligenceLearn,
} from '../src/mcp-tools/hooks-tools.js';
import { generateEmbedding } from '../src/memory/memory-initializer.js';

describe('AUDIT FIX #4 — trajectory-end feeds REAL embedding gradient to EWC', () => {
  beforeEach(() => {
    recordGradient.mockClear();
    (generateEmbedding as ReturnType<typeof vi.fn>).mockClear();
  });

  it('records a gradient equal to the real trajectory embedding, not a sine wave', async () => {
    const started = (await hooksTrajectoryStart.handler({ task: 'do work', agent: 'coder' })) as any;
    const trajectoryId = started.trajectoryId as string;

    await hooksTrajectoryStep.handler({ trajectoryId, action: 'edit-file', result: 'ok', quality: 0.9 });

    const ended = (await hooksTrajectoryEnd.handler({ trajectoryId, success: true })) as any;

    // generateEmbedding was used to derive the gradient (mirrors DISTILL path)
    expect(generateEmbedding).toHaveBeenCalledTimes(1);

    // EWC received the REAL embedding, not synthetic noise
    expect(recordGradient).toHaveBeenCalledTimes(1);
    const passedGradient = recordGradient.mock.calls[0][1] as number[];
    expect(passedGradient).toEqual(REAL_EMBEDDING);

    // Guard: the OLD synthetic gradient was sin(i*0.01)*(steps/10). With 1 step
    // that produced values like sin(0)=0, sin(0.01)*0.1 ~= 0.001 — confirm the
    // gradient is NOT that degenerate sine sequence.
    expect(passedGradient[0]).not.toBeCloseTo(Math.sin(0) * (1 / 10), 6);
    expect(passedGradient[1]).not.toBeCloseTo(Math.sin(0.01) * (1 / 10), 6);

    expect(ended.learning.ewcConsolidation).toBe(true);
  });

  it('SKIPS the EWC update (no synthetic gradient) when no real embedding is available', async () => {
    (generateEmbedding as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
      embedding: [],
      dimensions: 0,
      model: 'none',
    });

    const started = (await hooksTrajectoryStart.handler({ task: 'task2', agent: 'coder' })) as any;
    const trajectoryId = started.trajectoryId as string;
    await hooksTrajectoryStep.handler({ trajectoryId, action: 'a', result: 'ok' });

    const ended = (await hooksTrajectoryEnd.handler({ trajectoryId, success: true })) as any;

    // No gradient recorded — we skip rather than inject noise.
    expect(recordGradient).not.toHaveBeenCalled();
    expect(ended.learning.ewcConsolidation).toBe(false);
  });
});

describe('AUDIT FIX #5 — hooks_intelligence_learn actually triggers a learning cycle', () => {
  beforeEach(() => {
    distillLearning.mockClear();
    runBackgroundLearning.mockClear();
  });

  it('calls the real distillLearning (DISTILL+CONSOLIDATE) path, not just stats echo', async () => {
    const result = (await hooksIntelligenceLearn.handler({ consolidate: true })) as any;

    expect(distillLearning).toHaveBeenCalledTimes(1);
    expect(result.cycleTriggered).toBe(true);
    expect(result.patternsDistilled).toBe(5);
    expect(result.implementation).toBe('real-distill-consolidate');
    expect(result.learned).toBe(true);
  });
});

/**
 * #2940: `hooks intelligence --train` exited 0 and printed a full success
 * dashboard (Neural Persistence + V3 Performance Gains tables) without ever
 * training anything. The `--train` handler (`hooks_intelligence` MCP tool)
 * declared a `forceTraining` input but never read it — `commands/hooks.ts`'s
 * CLI action just slept 500ms and printed a canned "Training cycle
 * completed". `lastAdaptation` (what `--status` reports as "Last Training")
 * never moved, so it could only ever *age*, no matter how many times
 * `--train` ran — a naive read looked like "the number changed" when it had
 * changed in the wrong direction.
 *
 * Fixed by actually calling `distillLearning()` (memory/intelligence.ts,
 * already existed and already bumps `lastAdaptation` when it runs) from the
 * `hooks_intelligence` handler when `forceTraining` is set, and reporting
 * what happened instead of a fixed message: distilled N patterns, ran with
 * nothing new to distill, or could not run.
 *
 * Black-box against the real built CLI — same pattern as
 * mcp-http-foreground-2984.test.ts — because the bug is in how two command
 * modules communicate a real outcome through the MCP-tool boundary, not
 * pure logic a unit test could isolate.
 */
import { describe, it, expect } from 'vitest';
import { spawnSync } from 'child_process';
import { existsSync, mkdtempSync, rmSync } from 'fs';
import { fileURLToPath } from 'url';
import { join } from 'path';
import { tmpdir } from 'os';

const CLI_BIN = fileURLToPath(new URL('../bin/cli.js', import.meta.url));
const CLI_BUILT = existsSync(CLI_BIN);

// `output.printWarning` writes to stderr — merge both streams so assertions
// can see a warning-path message the same way a terminal user would.
function cli(args: string[], cwd: string): { out: string; code: number } {
  const result = spawnSync(process.execPath, [CLI_BIN, ...args], {
    encoding: 'utf-8',
    timeout: 30_000,
    cwd,
  });
  return { out: `${result.stdout ?? ''}${result.stderr ?? ''}`, code: result.status ?? 1 };
}

function lastTrainingSeconds(statusOut: string): number | null {
  const m = statusOut.match(/Last Training:\s*(?:(\d+)s ago|(Never))/);
  if (!m) return null;
  if (m[2]) return null; // "Never"
  return Number(m[1]);
}

describe.skipIf(!CLI_BUILT)('#2940 hooks intelligence --train actually trains', () => {
  it('moves "Last Training" to ~0s ago instead of only ever aging', () => {
    const cwd = mkdtempSync(join(tmpdir(), 'ruflo-2940-'));
    try {
      const init = cli(['memory', 'init'], cwd);
      expect(init.code).toBe(0);

      const before = cli(['hooks', 'intelligence', '--status'], cwd);
      expect(before.code).toBe(0);
      expect(lastTrainingSeconds(before.out)).toBeNull(); // "Never" — no training has run yet

      const trained = cli(['hooks', 'intelligence', '--train'], cwd);
      expect(trained.code).toBe(0);
      // Pre-fix: this printed the exact same "Training cycle completed" no
      // matter what happened. Post-fix: it's conditioned on a real outcome,
      // so it always contains one of these two honest phrases.
      expect(trained.out).toMatch(/Training cycle completed|Training cycle ran/);

      const after = cli(['hooks', 'intelligence', '--status'], cwd);
      expect(after.code).toBe(0);
      const seconds = lastTrainingSeconds(after.out);
      // Pre-fix: still "Never" (lastAdaptation was never written) — the
      // defect this test pins. Post-fix: a fresh, small elapsed time.
      expect(seconds).not.toBeNull();
      expect(seconds as number).toBeLessThan(30);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  }, 60_000);
});

/**
 * Regression guards for the 2026-07-27 "clean exit, no real work reflected"
 * batch — three reader/writer-mismatch bugs reported by vidaunited:
 *
 *   #2797 — hooks metrics Pattern Learning always 0 (pattern reader filtered
 *           on a key/type shape no writer produces)
 *   #2798 — memory backup silent no-op under CLAUDE_FLOW_ENCRYPT_AT_REST
 *           (better-sqlite3 online backup can't open the RFE1 blob)
 *   #2799 — swarm status always Total 0 agents (read .swarm/agents/ that
 *           no writer creates, while agent spawn writes swarm-activity.json)
 *
 * All three exercised via real execFileSync against bin/cli.js in temp cwds.
 */

import { describe, it, expect } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, rmSync, existsSync, readdirSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomBytes } from 'node:crypto';

const CLI = join(__dirname, '..', 'bin', 'cli.js');

function run(args: string[], cwd: string, env: NodeJS.ProcessEnv = {}): { stdout: string; exit: number } {
  try {
    const stdout = execFileSync('node', [CLI, ...args], {
      cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'pipe'],
      env: { ...process.env, ...env },
    });
    return { stdout, exit: 0 };
  } catch (err) {
    const e = err as { status?: number; stdout?: Buffer; stderr?: Buffer };
    return { stdout: (e.stdout?.toString() ?? '') + (e.stderr?.toString() ?? ''), exit: e.status ?? -1 };
  }
}

describe('#2797 hooks metrics Pattern Learning counts real writes', () => {
  it('Pattern Learning total is non-zero after a store-results post-task', () => {
    const wd = mkdtempSync(join(tmpdir(), 'ruflo-2797-'));
    try {
      run(['memory', 'init'], wd);
      run(['hooks', 'post-task', '-i', 't1', '--success', 'true', '-q', '0.95', '--task', 'some task', '--agent', 'coder', '--store-results'], wd);
      run(['hooks', 'post-task', '-i', 't2', '--success', 'false', '-q', '0.2', '--task', 'failed task', '--agent', 'coder', '--store-results'], wd);
      const { stdout } = run(['hooks', 'metrics', '--format', 'json'], wd);
      const data = JSON.parse(stdout.slice(stdout.indexOf('{')));
      expect(data.patterns.total).toBe(2);
      expect(data.patterns.successful).toBe(1);
      expect(data.patterns.failed).toBe(1);
      expect(data.patterns.successful + data.patterns.failed).toBeLessThanOrEqual(data.patterns.total);
      expect(data.patterns.described).toBe(2);
      expect(data.patterns.descriptionCoverage).toBe(1);
      expect(data.agents.routingAccuracy).toBeNull();
      expect(data.agents.averageConfidence).toBeGreaterThan(0);
      expect(data.agents.outcomeSuccessRate).toBe(0.5);
    } finally {
      try { rmSync(wd, { recursive: true, force: true }); } catch { /* */ }
    }
  }, 60_000);
});

describe('#2798 memory backup falls back to byte-copy under encryption', () => {
  it('produces a snapshot when CLAUDE_FLOW_ENCRYPT_AT_REST=1 (RFE1 blob)', () => {
    const wd = mkdtempSync(join(tmpdir(), 'ruflo-2798-'));
    const key = randomBytes(32).toString('hex');
    const env = { CLAUDE_FLOW_ENCRYPT_AT_REST: '1', CLAUDE_FLOW_ENCRYPTION_KEY: key };
    try {
      run(['memory', 'init'], wd, env);
      run(['memory', 'store', '--key', 'k', '--value', 'encrypted note'], wd, env);
      // Confirm the source really is the encrypted RFE1 blob (not native SQLite).
      const header = readFileSync(join(wd, '.swarm', 'memory.db')).subarray(0, 4).toString('latin1');
      expect(header).toBe('RFE1');
      const { stdout } = run(['memory', 'backup'], wd, env);
      expect(stdout).toMatch(/Backed up →/);
      const backups = existsSync(join(wd, '.swarm', 'backups'))
        ? readdirSync(join(wd, '.swarm', 'backups')).filter((f) => /^memory-.*\.db$/.test(f))
        : [];
      expect(backups.length).toBeGreaterThan(0);
    } finally {
      try { rmSync(wd, { recursive: true, force: true }); } catch { /* */ }
    }
  }, 60_000);
});

describe('#2799 swarm status reflects spawned agents', () => {
  it('swarm status agent total matches agent spawn count (via swarm-activity.json)', () => {
    const wd = mkdtempSync(join(tmpdir(), 'ruflo-2799-'));
    try {
      run(['swarm', 'init', '--topology', 'mesh', '--max-agents', '5'], wd);
      for (const a of ['coder', 'reviewer', 'researcher', 'tester']) {
        run(['agent', 'spawn', '--type', a, '--name', `x-${a}`], wd);
      }
      const status = run(['swarm', 'status'], wd).stdout;
      // The Agents section's Total must now be 4, not 0. Match the "Total | 4"
      // row in the agents table (allow ANSI/box chars around it).
      expect(status).toMatch(/Total\D+4/);
      expect(status).toMatch(/Active\D+0/);
      expect(status).toMatch(/Idle\D+4/);
      const list = run(['agent', 'list'], wd).stdout;
      expect(list).toMatch(/\| agent-\d+/);
      // Sanity: the activity file the fix reads was actually written.
      const activityPath = join(wd, '.claude-flow', 'metrics', 'swarm-activity.json');
      if (existsSync(activityPath)) {
        const activity = JSON.parse(readFileSync(activityPath, 'utf-8'));
        expect(activity.swarm.agent_count).toBe(4);
      }
    } finally {
      try { rmSync(wd, { recursive: true, force: true }); } catch { /* */ }
    }
  }, 60_000);
});

/**
 * #2961: `ruflo hooks post-task` (CLI) reliably dropped the ADR-130 Phase 3
 * "reinforced-by" graph edge that the identical `hooks_post-task` MCP tool
 * handler writes when invoked from a long-running MCP server.
 *
 * Root cause: the edge write was a fire-and-forget async IIFE, never
 * `await`ed by the handler. The long-running MCP server stays alive long
 * enough for the detached write to finish in the background — invisible
 * there. But `hooks post-task` (CLI) is the exact same handler, invoked
 * from a one-shot process that calls `process.exit(0)` immediately after
 * the command action resolves (bin/cli.js, #1552) — the still-pending
 * dynamic `import(...)` + `insertGraphEdge()` call was killed before its
 * first tick, every time, not intermittently.
 *
 * Fixed by awaiting the write in `mcp-tools/hooks-tools.ts`'s post-task
 * handler.
 *
 * Verification pitfall this test deliberately avoids: an sql.js read of the
 * main `.swarm/memory.db` image file misses rows that landed in the
 * `-wal` sidecar and haven't been checkpointed back yet — a native
 * better-sqlite3 read (what `countGraphEdges` uses) sees them correctly.
 * Reading via sql.js here would produce a false "still 0 edges" negative
 * even against the fixed code, masking the fix as broken.
 *
 * Black-box against the real built CLI (matches this session's other
 * end-to-end regression tests) because the bug is specifically about the
 * one-shot-process exit race, which only a real spawned process exhibits.
 */
import { describe, it, expect } from 'vitest';
import { execFileSync } from 'child_process';
import { existsSync, mkdtempSync, rmSync } from 'fs';
import { fileURLToPath } from 'url';
import { join } from 'path';
import { tmpdir } from 'os';

const CLI_BIN = fileURLToPath(new URL('../bin/cli.js', import.meta.url));
const CLI_BUILT = existsSync(CLI_BIN);

describe.skipIf(!CLI_BUILT)('#2961 hooks post-task (CLI) writes the reinforced-by edge', () => {
  it('a successful CLI post-task call leaves a graph_edges row behind, not just a trajectory', async () => {
    const cwd = mkdtempSync(join(tmpdir(), 'ruflo-2961-'));
    try {
      execFileSync(process.execPath, [CLI_BIN, 'memory', 'init'], { cwd, timeout: 30_000, stdio: 'pipe' });
      execFileSync(
        process.execPath,
        [CLI_BIN, 'hooks', 'post-task', '--task-id', 'quenzibar2961', '--success', 'true', '-q', '0.9'],
        { cwd, timeout: 30_000, stdio: 'pipe' },
      );

      const { _resetBridgeDb, countGraphEdges } = await import('../src/memory/graph-edge-writer.js');
      _resetBridgeDb();
      const dbPath = join(cwd, '.swarm', 'memory.db');
      const count = await countGraphEdges(dbPath);

      // Pre-fix: the CLI process exits before the detached write's first
      // await resolves — this is exactly 0 every time, not flaky.
      expect(count).toBeGreaterThan(0);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  }, 60_000);
});

/**
 * ADR-147 P2 — Nested-subagent spawn-tree capture in post-task hook.
 *
 * Verifies that `hooks_post-task` MCP tool accepts the optional
 * `parentAgentId` and `depth` fields (sourced from Claude Code's
 * `parent_agent_id` OTel span tag / `x-claude-code-parent-agent-id`
 * header) and propagates them through to `bridgeRecordFeedback`.
 *
 * Why this is testable today without nested spawning being live:
 * the OTel tag the binary emits already exists for FLAT depth-1
 * spawns. The same code path that captures parent_agent_id for
 * a flat spawn will capture it for a depth-5 chain once the
 * Task-tool denylist (documented in ADR-147) is lifted upstream.
 */

import { describe, it, expect, vi, beforeEach } from 'vitest';

// Capture the bridge call so we can assert on what it receives.
const bridgeRecordFeedback = vi.fn(async () => ({ success: true, controller: 'mock', updated: 1 }));
const bridgeRecordCausalEdge = vi.fn(async () => ({ success: true, controller: 'mock' }));
const bridgeStoreEntry = vi.fn(async () => ({ success: true, controller: 'mock' }));

vi.mock('../src/memory/memory-bridge.js', () => ({
  bridgeRecordFeedback,
  bridgeRecordCausalEdge,
  bridgeStoreEntry,
}));

// Stub intelligence/trajectory + graph-edge-writer so the handler runs cleanly.
vi.mock('../src/memory/intelligence.js', () => ({
  recordTrajectory: vi.fn(async () => undefined),
}));
vi.mock('../src/memory/graph-edge-writer.js', () => ({
  insertGraphEdge: vi.fn(async () => undefined),
}));

// Import after mocks are declared.
const { hooksPostTask } = await import('../src/mcp-tools/hooks-tools.js');

beforeEach(() => {
  bridgeRecordFeedback.mockClear();
  bridgeRecordCausalEdge.mockClear();
  bridgeStoreEntry.mockClear();
});

describe('ADR-147 P2 — post-task parentAgentId + depth propagation', () => {
  it('propagates parentAgentId and depth to the bridge when supplied', async () => {
    await hooksPostTask.handler({
      taskId: 'task-with-lineage',
      success: true,
      agent: 'coder',
      quality: 0.9,
      parentAgentId: 'parent-abc-123',
      depth: 2,
    });

    expect(bridgeRecordFeedback).toHaveBeenCalledTimes(1);
    const call = bridgeRecordFeedback.mock.calls[0][0] as Record<string, unknown>;
    expect(call.taskId).toBe('task-with-lineage');
    expect(call.parentAgentId).toBe('parent-abc-123');
    expect(call.depth).toBe(2);
  });

  it('omits parentAgentId and depth from the bridge call when caller does not supply them (top-level lead)', async () => {
    await hooksPostTask.handler({
      taskId: 'task-no-lineage',
      success: true,
      agent: 'coder',
      quality: 0.9,
    });

    expect(bridgeRecordFeedback).toHaveBeenCalledTimes(1);
    const call = bridgeRecordFeedback.mock.calls[0][0] as Record<string, unknown>;
    expect(call.parentAgentId).toBeUndefined();
    expect(call.depth).toBeUndefined();
  });

  it('accepts depth=0 (lead session) — boundary case must propagate, not be coerced to undefined', async () => {
    await hooksPostTask.handler({
      taskId: 'task-lead',
      success: true,
      agent: 'lead',
      quality: 1.0,
      parentAgentId: 'root',
      depth: 0,
    });

    expect(bridgeRecordFeedback).toHaveBeenCalledTimes(1);
    const call = bridgeRecordFeedback.mock.calls[0][0] as Record<string, unknown>;
    expect(call.depth).toBe(0);
  });

  it('rejects parentAgentId that fails identifier validation', async () => {
    const result = await hooksPostTask.handler({
      taskId: 'task-bad-parent',
      success: true,
      agent: 'coder',
      parentAgentId: 'has spaces and; semicolons',
    });

    expect((result as { success: boolean }).success).toBe(false);
    expect(bridgeRecordFeedback).not.toHaveBeenCalled();
  });

  it('rejects negative depth', async () => {
    const result = await hooksPostTask.handler({
      taskId: 'task-neg-depth',
      success: true,
      agent: 'coder',
      depth: -1,
    });

    expect((result as { success: boolean }).success).toBe(false);
    expect((result as { error: string }).error).toMatch(/depth must be a non-negative integer/);
    expect(bridgeRecordFeedback).not.toHaveBeenCalled();
  });

  it('rejects non-integer depth', async () => {
    const result = await hooksPostTask.handler({
      taskId: 'task-frac-depth',
      success: true,
      agent: 'coder',
      depth: 1.5,
    });

    expect((result as { success: boolean }).success).toBe(false);
    expect(bridgeRecordFeedback).not.toHaveBeenCalled();
  });

  it('rejects depth > 32 (defensive upper bound)', async () => {
    const result = await hooksPostTask.handler({
      taskId: 'task-deep-depth',
      success: true,
      agent: 'coder',
      depth: 33,
    });

    expect((result as { success: boolean }).success).toBe(false);
    expect(bridgeRecordFeedback).not.toHaveBeenCalled();
  });
});

/**
 * Regression guard for #2786 fix-2 — `hooks_post-task --store-results`
 * dual-writes routing decisions into `.claude-flow/memory/store.json` so
 * the sync reader `getIntelligenceStatsFromMemory()` (which powers the
 * "Pattern Learning" / "Agent Routing" numbers in `hooks_metrics`)
 * actually sees the writes.
 *
 * Before this fix, the CLI wrote routing outcomes only to AgentDB
 * (namespace `patterns`, keys `routing-decision:*`), but the reader
 * only reads `.claude-flow/memory/store.json`. Result: counters stuck
 * at zero for the life of the install.
 *
 * The test runs `hooksPostTask.handler` in a temp cwd, then reads the
 * resulting store.json off disk and asserts the shape the reader
 * filters for (`key.includes('routing') || metadata.type === 'routing-decision'`).
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, readFileSync, rmSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

// Bridge is mocked so the AgentDB path is a no-op — we only care about
// the JSON dual-write here. The bridge's real behavior is covered elsewhere.
const bridgeRecordFeedback = vi.fn(async () => ({ success: true, controller: 'mock', updated: 1 }));
const bridgeRecordCausalEdge = vi.fn(async () => ({ success: true, controller: 'mock' }));
const bridgeStoreEntry = vi.fn(async () => ({ success: true, controller: 'mock' }));

vi.mock('../src/memory/memory-bridge.js', () => ({
  bridgeRecordFeedback,
  bridgeRecordCausalEdge,
  bridgeStoreEntry,
}));

vi.mock('../src/memory/intelligence.js', () => ({
  recordTrajectory: vi.fn(async () => undefined),
}));
vi.mock('../src/memory/graph-edge-writer.js', () => ({
  insertGraphEdge: vi.fn(async () => undefined),
}));

const { hooksPostTask } = await import('../src/mcp-tools/hooks-tools.js');

let origCwd: string;
let workdir: string;

beforeEach(() => {
  origCwd = process.cwd();
  workdir = mkdtempSync(join(tmpdir(), 'ruflo-2786-'));
  process.chdir(workdir);
  bridgeRecordFeedback.mockClear();
  bridgeStoreEntry.mockClear();
});

afterEach(() => {
  process.chdir(origCwd);
  try { rmSync(workdir, { recursive: true, force: true }); } catch { /* ignore */ }
});

describe('#2786 fix-2 — hooks_post-task JSON dual-write for metrics reader', () => {
  it('writes a routing-decision entry into .claude-flow/memory/store.json when storeDecisions=true', async () => {
    await hooksPostTask.handler({
      taskId: 'task-2786-dual-write',
      task: 'implement auth token refresh',
      agent: 'coder',
      success: true,
      quality: 0.9,
      storeDecisions: true,
    });

    const storePath = join(workdir, '.claude-flow', 'memory', 'store.json');
    expect(existsSync(storePath)).toBe(true);

    const store = JSON.parse(readFileSync(storePath, 'utf-8')) as { entries: Record<string, any> };
    const routingKey = 'routing-decision:task-2786-dual-write';
    expect(store.entries[routingKey]).toBeDefined();

    const entry = store.entries[routingKey];
    // The reader's filter matches on key containing 'routing' OR metadata.type === 'routing-decision'
    expect(entry.key.includes('routing')).toBe(true);
    expect(entry.metadata?.type).toBe('routing-decision');
    // The confidence field is read to compute avgConfidence — quality maps to confidence.
    expect(entry.metadata?.confidence).toBe(0.9);
    // Namespace matches the AgentDB write (patterns) for parity.
    expect(entry.namespace).toBe('patterns');
    expect(bridgeRecordFeedback).toHaveBeenCalledWith(expect.objectContaining({
      task: 'implement auth token refresh',
    }));
  });

  it('does NOT write to store.json when storeDecisions is omitted (backwards compatible)', async () => {
    await hooksPostTask.handler({
      taskId: 'task-2786-no-store',
      task: 'implement auth token refresh',
      agent: 'coder',
      success: true,
      quality: 0.9,
      // storeDecisions omitted
    });

    const storePath = join(workdir, '.claude-flow', 'memory', 'store.json');
    // File may or may not exist depending on other write paths, but if it
    // does, the routing-decision key should NOT be there.
    if (existsSync(storePath)) {
      const store = JSON.parse(readFileSync(storePath, 'utf-8')) as { entries: Record<string, any> };
      expect(store.entries['routing-decision:task-2786-no-store']).toBeUndefined();
    }
  });
});

/**
 * Tests for http_fetch MCP tool (ADR-164 §5.1.8, Phase 4).
 *
 * Coverage:
 *   - URL allowlist (default-blocks file://, ftp://, RFC-1918, loopback, link-local)
 *   - Opt-in via CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE=1 reaches a local server
 *   - Header sanitization (default-rejects Authorization / Cookie / X-Auth-*)
 *   - Opt-in via CLAUDE_FLOW_HTTP_FETCH_ALLOW_AUTH=1 passes the header
 *   - Hard timeout aborts via AbortController
 *   - Response truncation honours maxResponseBytes
 *   - Happy path against a local mock node:http server
 *   - Default User-Agent injected if caller did not provide one
 */
import { describe, it, expect, beforeAll, afterAll, beforeEach, afterEach } from 'vitest';
import http from 'node:http';
import type { AddressInfo } from 'node:net';

import {
  httpFetchTools,
  httpFetchExecute,
  validateUrl,
  validateHeaders,
  HttpFetchValidationError,
} from '../src/mcp-tools/http-fetch-tools.js';

function findTool(name: string) {
  const t = httpFetchTools.find((x) => x.name === name);
  if (!t) throw new Error(`tool not found: ${name}`);
  return t;
}

// ---------- mock server for happy-path + truncation + timeout tests --------

let server: http.Server;
let port: number;
let lastUA: string | undefined;
let lastAuth: string | undefined;
let lastMethod: string | undefined;
let lastBody: string | undefined;

beforeAll(async () => {
  await new Promise<void>((resolve) => {
    server = http.createServer((req, res) => {
      lastUA = req.headers['user-agent'] as string | undefined;
      lastAuth = req.headers['authorization'] as string | undefined;
      lastMethod = req.method;

      // Collect body
      const chunks: Buffer[] = [];
      req.on('data', (c) => chunks.push(c));
      req.on('end', () => {
        lastBody = Buffer.concat(chunks).toString('utf-8');

        const url = req.url ?? '/';
        if (url === '/ok') {
          res.writeHead(200, { 'content-type': 'text/plain', 'x-server': 'mock' });
          res.end('hello-world');
        } else if (url === '/big') {
          // 1MB+ body — should trigger truncation when maxResponseBytes < 1MB
          res.writeHead(200, { 'content-type': 'application/octet-stream' });
          res.end(Buffer.alloc(2 * 1024 * 1024, 0x41));
        } else if (url === '/slow') {
          // Never respond — caller must abort
          // Keep connection open. Don't write headers either.
          // Will be terminated when the test server closes.
        } else if (url === '/echo') {
          res.writeHead(200, { 'content-type': 'application/json' });
          res.end(JSON.stringify({ method: req.method, body: lastBody }));
        } else if (url === '/500') {
          res.writeHead(500, { 'content-type': 'text/plain' });
          res.end('server-error');
        } else {
          res.writeHead(404);
          res.end('not-found');
        }
      });
    });
    server.listen(0, '127.0.0.1', () => {
      port = (server.address() as AddressInfo).port;
      resolve();
    });
  });
});

afterAll(async () => {
  // Force-close to terminate any lingering /slow request
  await new Promise<void>((resolve) => {
    server.closeAllConnections?.();
    server.close(() => resolve());
  });
});

// ---------- env-flag isolation -----------------------------------

const originalEnv = { ...process.env };
beforeEach(() => {
  delete process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE;
  delete process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_AUTH;
});
afterEach(() => {
  process.env = { ...originalEnv };
});

// ---------- URL allowlist tests ----------------------------------

describe('http_fetch — URL allowlist (default-deny)', () => {
  it('rejects file:// URLs', () => {
    expect(() => validateUrl('file:///etc/passwd')).toThrow(HttpFetchValidationError);
  });

  it('rejects ftp:// URLs', () => {
    expect(() => validateUrl('ftp://example.com/x')).toThrow(/protocol/);
  });

  it('rejects localhost', () => {
    expect(() => validateUrl('http://localhost/foo')).toThrow(/loopback|private/i);
  });

  it('rejects 127.0.0.1', () => {
    expect(() => validateUrl('http://127.0.0.1/foo')).toThrow(/loopback|private/i);
  });

  it('rejects 10.x RFC1918', () => {
    expect(() => validateUrl('http://10.0.0.5/foo')).toThrow(/loopback|private/i);
  });

  it('rejects 192.168.x.x RFC1918', () => {
    expect(() => validateUrl('http://192.168.1.1/foo')).toThrow(/loopback|private/i);
  });

  it('rejects 172.16.x.x RFC1918', () => {
    expect(() => validateUrl('http://172.20.0.1/foo')).toThrow(/loopback|private/i);
  });

  it('rejects 169.254.x.x link-local', () => {
    expect(() => validateUrl('http://169.254.169.254/latest')).toThrow(/loopback|private/i);
  });

  it('allows public host (example.com) by hostname check alone', () => {
    expect(() => validateUrl('https://example.com/foo')).not.toThrow();
  });

  it('opt-in CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE=1 unlocks private addresses', () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    expect(() => validateUrl('http://127.0.0.1/foo')).not.toThrow();
    expect(() => validateUrl('http://10.0.0.5/foo')).not.toThrow();
  });
});

// ---------- header sanitization tests ----------------------------

describe('http_fetch — header sanitization (default-deny auth)', () => {
  it('rejects Authorization header by default', () => {
    expect(() => validateHeaders({ Authorization: 'Bearer abc' })).toThrow(/not allowed/i);
  });
  it('rejects Cookie header by default', () => {
    expect(() => validateHeaders({ Cookie: 'sid=abc' })).toThrow(/not allowed/i);
  });
  it('rejects X-Auth-Token by default', () => {
    expect(() => validateHeaders({ 'X-Auth-Token': 'abc' })).toThrow(/not allowed/i);
  });
  it('accepts benign headers', () => {
    const h = validateHeaders({ Accept: 'application/json', 'X-Pod': 'ops' });
    expect(h.Accept).toBe('application/json');
    expect(h['X-Pod']).toBe('ops');
  });
  it('opt-in CLAUDE_FLOW_HTTP_FETCH_ALLOW_AUTH=1 unlocks auth headers', () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_AUTH = '1';
    expect(() => validateHeaders({ Authorization: 'Bearer abc' })).not.toThrow();
  });
});

// ---------- happy path / timeout / truncation --------------------

describe('http_fetch — execution path against a mock server', () => {
  it('happy-path GET returns 200 and body', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({ url: `http://127.0.0.1:${port}/ok` });
    expect(result.success).toBe(true);
    expect(result.status).toBe(200);
    expect(result.body).toBe('hello-world');
    expect(result.bodyTruncated).toBe(false);
  });

  it('default User-Agent is sent when caller omits it', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    lastUA = undefined;
    await httpFetchExecute({ url: `http://127.0.0.1:${port}/ok` });
    expect(lastUA).toMatch(/^ruflo-http-fetch\//);
  });

  it('aborts on timeout', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({
      url: `http://127.0.0.1:${port}/slow`,
      timeoutMs: 100,
    });
    expect(result.success).toBe(false);
    expect(result.errorCode).toBe('TIMEOUT');
    expect(result.durationMs).toBeGreaterThanOrEqual(80);
    expect(result.durationMs).toBeLessThan(5_000);
  }, 10_000);

  it('truncates the response when body exceeds maxResponseBytes', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({
      url: `http://127.0.0.1:${port}/big`,
      maxResponseBytes: 1024,
    });
    expect(result.success).toBe(true);
    expect(result.bodyTruncated).toBe(true);
    expect(result.bytesRead).toBeLessThanOrEqual(1024);
    expect(result.body.length).toBeLessThanOrEqual(1024);
  }, 10_000);

  it('refuses to call when URL is private and flag is off', async () => {
    const result = await httpFetchExecute({ url: `http://127.0.0.1:${port}/ok` });
    expect(result.success).toBe(false);
    expect(result.errorCode).toBe('PRIVATE_ADDRESS');
  });

  it('refuses Authorization header without env flag', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({
      url: `http://127.0.0.1:${port}/ok`,
      headers: { Authorization: 'Bearer abc' },
    });
    expect(result.success).toBe(false);
    expect(result.errorCode).toBe('FORBIDDEN_HEADER');
  });

  it('POST with body echoes back through /echo', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({
      url: `http://127.0.0.1:${port}/echo`,
      method: 'POST',
      body: 'hello',
    });
    expect(result.success).toBe(true);
    expect(result.status).toBe(200);
    const parsed = JSON.parse(result.body);
    expect(parsed.method).toBe('POST');
    expect(parsed.body).toBe('hello');
  });

  it('reports non-2xx status without throwing', async () => {
    process.env.CLAUDE_FLOW_HTTP_FETCH_ALLOW_PRIVATE = '1';
    const result = await httpFetchExecute({ url: `http://127.0.0.1:${port}/500` });
    expect(result.success).toBe(true);
    expect(result.status).toBe(500);
    expect(result.body).toBe('server-error');
  });
});

