describe('tokenize', () => {
  it('lowercases + splits on non-alphanumeric', () => {
    const t = tokenize('Refactor src/Auth/middleware.ts to use jwt-verify!');
    // Keeps '/' '-' '.' for paths/identifiers; drops punctuation.
    expect(t).toContain('refactor');
