/**
 * CI regression guards for #2250 + #2251.
 *
 * #2250 — model-router.selectModel() used to escalate `sonnet → opus` and
 * `haiku → sonnet` on ~every trivial route because the `uncertainty` formula
 * is structurally large (~0.6-0.7) and the gate fires at 0.15. The fix:
 * skip escalation when the bandit has confidently learned the escalation
 * target is meaningfully worse than the selected model. This test loads
 * the EXACT suppressed-opus prior from the bug report (Beta(3.8, 17.2),
 * mean ≈ 0.18) into the low-complexity bucket and asserts (a) opus is
 * selected on <20% of trivial routes (was ~40% before the fix), and
 * (b) haiku appears as a final pick (was 0/N before the fix).
 *
 * #2251 — WorkerDaemon constructor kicked off `initHeadlessExecutor()`
 * fire-and-forget, so `daemon.triggerWorker()` called immediately after
 * construction would see `headlessAvailable = false` and fall through to
 * the local stub in ~2ms. The fix: store the init promise and await it
 * inside triggerWorker(). This test confirms triggerWorker() does not
 * resolve before initHeadlessExecutor() settles.
 */

import { describe, expect, it, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ModelRouter } from '../src/ruvector/model-router.js';
import { WorkerDaemon } from '../src/services/worker-daemon.js';

let cwdRestore: string;
let tmpDir: string;

beforeEach(() => {
  cwdRestore = process.cwd();
  tmpDir = mkdtempSync(join(tmpdir(), 'issue-2250-2251-'));
  process.chdir(tmpDir);
});

afterEach(() => {
  process.chdir(cwdRestore);
  rmSync(tmpDir, { recursive: true, force: true });
});

describe('#2250 — escalation does not override learned opus suppression', () => {
  it('routes trivial tasks to haiku/sonnet at least 80% with suppressed-opus prior', async () => {
    // Seed `.swarm/model-router-state.json` with the prior from the bug report
    // (opus mean ≈ 0.18, sonnet ≈ 0.64, haiku ≈ 0.60 in the low bucket).
    mkdirSync(join(tmpDir, '.swarm'), { recursive: true });
    const state = {
      priors: {
        low: {
          haiku:   { alpha: 3.0,  beta: 2.0  },
          sonnet:  { alpha: 12.2, beta: 6.8  },
          opus:    { alpha: 3.8,  beta: 17.2 },
          inherit: { alpha: 1,    beta: 1    },
        },
        med:  { haiku: { alpha: 1, beta: 1 }, sonnet: { alpha: 1, beta: 1 }, opus: { alpha: 1, beta: 1 }, inherit: { alpha: 1, beta: 1 } },
        high: { haiku: { alpha: 1, beta: 1 }, sonnet: { alpha: 1, beta: 1 }, opus: { alpha: 1, beta: 1 }, inherit: { alpha: 1, beta: 1 } },
      },
    };
    writeFileSync(join(tmpDir, '.swarm/model-router-state.json'), JSON.stringify(state));

    const router = new ModelRouter();
    const N = 50;
    const counts: Record<string, number> = { haiku: 0, sonnet: 0, opus: 0 };
    for (let i = 0; i < N; i++) {
      // Trivial low-complexity task (matches bug report's example).
      const r = await router.route(`Add a single option to a select dropdown ${i}`);
      counts[r.model] = (counts[r.model] ?? 0) + 1;
    }

    const opusRate = counts.opus / N;
    expect(opusRate).toBeLessThan(0.20); // before fix: ~0.40
    expect(counts.haiku + counts.sonnet).toBeGreaterThanOrEqual(N - counts.opus);
    expect(counts.haiku).toBeGreaterThan(0); // before fix: 0/N
  }, 30_000);

  it('still escalates on cold-start (Beta(1,1) priors)', async () => {
    // No state file → uniform priors → escalation guard should NOT trigger
    // (target mean ≈ selected mean), so the prior router behavior is preserved
    // for unlearned routers. We just assert the route succeeds without crashing
    // and returns one of the three valid models.
    const router = new ModelRouter();
    const r = await router.route('Refactor the entire authentication subsystem');
    expect(['haiku', 'sonnet', 'opus']).toContain(r.model);
  }, 10_000);

  it('respects CLAUDE_FLOW_MAX_UNCERTAINTY env override', async () => {
    // With maxUncertainty=0.99 the escalation gate effectively never fires,
    // so the selected model is always the Thompson-sampled winner unmodified.
    const old = process.env.CLAUDE_FLOW_MAX_UNCERTAINTY;
    process.env.CLAUDE_FLOW_MAX_UNCERTAINTY = '0.99';
    try {
      // The env is read at module load via `envMaxUncertainty()` in
      // DEFAULT_CONFIG. Pass it through config explicitly so the test
      // doesn't depend on module reload order.
      const router = new ModelRouter({ maxUncertainty: 0.99 });
      const r = await router.route('simple low-complexity task');
      expect(['haiku', 'sonnet', 'opus']).toContain(r.model);
    } finally {
      if (old === undefined) delete process.env.CLAUDE_FLOW_MAX_UNCERTAINTY;
      else process.env.CLAUDE_FLOW_MAX_UNCERTAINTY = old;
    }
  });
});

describe('#2251 — daemon.triggerWorker awaits headless init', () => {
  it('does not resolve triggerWorker before initHeadlessExecutor settles', async () => {
    const daemon = new WorkerDaemon(tmpDir);

    // Replace the field with a deferred promise we control so we can prove
    // triggerWorker waits for it before calling executeWorker.
    let initResolved = false;
    let resolveInit!: () => void;
    const gatedInit = new Promise<void>((resolve) => {
      resolveInit = () => {
        initResolved = true;
        resolve();
      };
    });
    // The trigger awaits this exact field per the #2251 fix.
    (daemon as unknown as { headlessInitPromise: Promise<void> }).headlessInitPromise = gatedInit;

    // Stub executeWorker so we can prove its call order vs init resolution
    // without actually running a worker.
    let executeCalledBeforeInit: boolean | null = null;
    (daemon as unknown as { executeWorker: (...a: unknown[]) => Promise<unknown> }).executeWorker =
      vi.fn(async () => {
        executeCalledBeforeInit = !initResolved; // record the order
        return { workerId: 'x', type: 'map', success: true, durationMs: 1, timestamp: new Date() };
      });

    const triggerP = daemon.triggerWorker('map');
    // Yield a tick so any non-awaited path would already have called executeWorker.
    await new Promise((r) => setImmediate(r));
    expect(executeCalledBeforeInit).toBeNull(); // executeWorker not called yet — still gated

    resolveInit();
    await triggerP;
    expect(executeCalledBeforeInit).toBe(false); // executeWorker called AFTER init
  });
});

/**
 * CI regression guard for #2566.
 *
 * isAnswerCorrect() in src/benchmarks/gaia-agent.ts originally had two
 * substring checks: forward (`normModel.includes(normExpected)`) and
 * reverse (`normExpected.includes(normModel)`). The reverse check scored
 * a fragmentary model answer as correct whenever its normalized form was
 * any substring of the expected answer — e.g. model `"a"` vs expected
 * `"Paris, France"` → true — inflating GAIA scores via a
 * normalization-collision (the exact vector ADR-167/169 R1 forbid).
 *
 * The fix removes the reverse-substring branch; only the forward
 * substring + numeric-tolerance paths remain.
 *
 * This test locks in the correct behavior so the reverse branch cannot
 * silently return. It FAILS on the original bug and PASSES on the fix.
 */

import { describe, expect, it } from 'vitest';
import { isAnswerCorrect } from '../src/benchmarks/gaia-agent.js';

describe('#2566 — isAnswerCorrect reverse-substring collision', () => {
  it('rejects a fragmentary single-letter model answer against a longer expected answer', () => {
    // The canonical regression case from the issue: model returned "a", the
    // expected answer is "Paris, France". Under the original reverse-substring
    // rule, "paris, france".includes("a") was true → false positive.
    expect(isAnswerCorrect('a', 'Paris, France')).toBe(false);
  });

  it('rejects other fragmentary substrings that would collide under the reverse rule', () => {
    // Every one of these would have returned true under the old reverse rule
    // because they normalize to a substring of the expected answer.
    expect(isAnswerCorrect('e', 'Eiffel Tower')).toBe(false);
    expect(isAnswerCorrect('the', 'the quick brown fox')).toBe(false);
    expect(isAnswerCorrect('19', '1969')).toBe(false);
    expect(isAnswerCorrect('.', '3.14159')).toBe(false);
  });

  it('still accepts exact matches (case + whitespace insensitive)', () => {
    expect(isAnswerCorrect('Paris', 'paris')).toBe(true);
    expect(isAnswerCorrect('  Paris  ', 'Paris')).toBe(true);
  });

  it('still accepts forward-substring matches (model contains expected)', () => {
    // The forward direction is the legitimate GAIA case:
    // model responded with extra context, expected is a substring of it.
    expect(isAnswerCorrect('Paris, France', 'Paris')).toBe(true);
    expect(isAnswerCorrect('The answer is 42.', '42')).toBe(true);
  });

  it('still accepts numeric answers within ±1% tolerance', () => {
    expect(isAnswerCorrect('3.14', '3.14159')).toBe(true);
    expect(isAnswerCorrect('100', '100.5')).toBe(true);
  });

  it('rejects numeric answers outside ±1% tolerance', () => {
    expect(isAnswerCorrect('50', '100')).toBe(false);
  });
});

/**
 * Regression guard for ruvnet/ruflo#2612.
 *
 * The canonical MCP registration name is `claude-flow` — this preserves the
 * `mcp__claude-flow__*` prefix that ~166 plugin tool references depend on
 * (#2206). `ruflo` is the legacy-duplicate name that pre-rename setup docs
 * (or a manual `claude mcp add ruflo`) can create alongside the canonical
 * entry. init/doctor must detect this coexistence so Claude Code does not
 * start two identical Ruflo MCP servers and load two identical tool schemas.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'fs';
import { tmpdir } from 'os';
import path from 'path';
import doctorCommand from '../src/commands/doctor.js';

describe('#2612 — ruflo MCP rename duplicate detection', () => {
  let home: string;
  let project: string;
  let oldHome: string | undefined;
  let oldUserProfile: string | undefined;
  let oldCwd: string;

  beforeEach(() => {
    home = mkdtempSync(path.join(tmpdir(), 'ruflo-2612-home-'));
    project = mkdtempSync(path.join(tmpdir(), 'ruflo-2612-project-'));
    oldHome = process.env.HOME;
    oldUserProfile = process.env.USERPROFILE;
    oldCwd = process.cwd();
    process.env.HOME = home;
    delete process.env.USERPROFILE;
    process.chdir(project);
  });

  afterEach(() => {
    process.chdir(oldCwd);
    if (oldHome === undefined) delete process.env.HOME;
    else process.env.HOME = oldHome;
    if (oldUserProfile === undefined) delete process.env.USERPROFILE;
    else process.env.USERPROFILE = oldUserProfile;
    rmSync(home, { recursive: true, force: true });
    rmSync(project, { recursive: true, force: true });
  });

  it('doctor warns when project .mcp.json has claude-flow and ~/.claude.json has ruflo', async () => {
    writeFileSync(
      path.join(project, '.mcp.json'),
      JSON.stringify({
        mcpServers: {
          'claude-flow': { command: 'npx', args: ['-y', 'ruflo@latest', 'mcp', 'start'] },
        },
      }),
      'utf-8',
    );
    writeFileSync(
      path.join(home, '.claude.json'),
      JSON.stringify({
        projects: {
          [project]: {
            mcpServers: {
              ruflo: { command: 'npx', args: ['-y', 'ruflo@latest', 'mcp', 'start'] },
            },
          },
        },
      }),
      'utf-8',
    );

    const result = await doctorCommand.action!({
      cwd: project,
      flags: { component: 'mcp', fix: false, install: false },
      args: [],
      interactive: false,
    } as any);

    const checks = (result.data as { results: Array<{ name: string; status: string; message: string }> }).results;
    const mcp = checks.find(check => check.name === 'MCP Servers');
    expect(mcp?.status).toBe('warn');
    expect(mcp?.message).toContain('Duplicate Ruflo MCP registrations found');
    expect(mcp?.message).toContain('claude-flow');
    expect(mcp?.message).toContain('ruflo');
  });
});

import { describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';

const HELPER = resolve(__dirname, '../.claude/helpers/intelligence.cjs');

type Entry = {
  id: string;
  content: string;
  namespace: string;
  metadata?: { sourceFile?: string };
};

function consolidate(root: string): { entries: number; edges: number } {
  const script = [
    `const intelligence = require(${JSON.stringify(HELPER)});`,
    'process.stdout.write(JSON.stringify(intelligence.consolidate()));',
  ].join('');
  const stdout = execFileSync(process.execPath, ['-e', script], {
    cwd: root,
    env: { ...process.env, CLAUDE_PROJECT_DIR: root },
    encoding: 'utf-8',
    timeout: 2_000,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  return JSON.parse(stdout);
}

function writeStore(root: string, entries: Entry[]): string {
  const dataDir = join(root, '.claude-flow', 'data');
  mkdirSync(dataDir, { recursive: true });
  writeFileSync(join(dataDir, 'auto-memory-store.json'), JSON.stringify(entries), 'utf-8');
  return dataDir;
}

describe('#2628 session-end intelligence consolidation', () => {
  it('deduplicates identical content with fresh IDs and persists the compacted store', () => {
    const root = mkdtempSync(join(tmpdir(), 'ruflo-2628-dedup-'));
    const unique = Array.from({ length: 10 }, (_, i) => ({
      content: `unique memory section ${i} with stable semantic content`,
      namespace: 'auto-memory',
    }));
    const entries = Array.from({ length: 12 }, (_, batch) =>
      unique.map((entry, i) => ({ ...entry, id: `fresh-${batch}-${i}` })),
    ).flat();

    try {
      const dataDir = writeStore(root, entries);
      const result = consolidate(root);
      const persisted = JSON.parse(
        readFileSync(join(dataDir, 'auto-memory-store.json'), 'utf-8'),
      ) as Entry[];
      const graph = JSON.parse(
        readFileSync(join(dataDir, 'graph-state.json'), 'utf-8'),
      ) as { nodeCount: number };

      expect(result.entries).toBe(unique.length);
      expect(persisted).toHaveLength(unique.length);
      expect(graph.nodeCount).toBe(unique.length);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });

  it('preserves temporal and similarity graph behavior for stores within the pair budget', () => {
    const root = mkdtempSync(join(tmpdir(), 'ruflo-2628-small-'));
    const entries: Entry[] = [
      {
        id: 'a',
        content: 'authentication token refresh security pattern',
        namespace: 'patterns',
        metadata: { sourceFile: 'auth.ts' },
      },
      {
        id: 'b',
        content: 'authentication token refresh security patterns',
        namespace: 'patterns',
        metadata: { sourceFile: 'auth.ts' },
      },
    ];

    try {
      const dataDir = writeStore(root, entries);
      consolidate(root);
      const graph = JSON.parse(
        readFileSync(join(dataDir, 'graph-state.json'), 'utf-8'),
      ) as { edges: Array<{ sourceId: string; targetId: string; type: string }> };

      expect(graph.edges).toEqual(
        expect.arrayContaining([
          { sourceId: 'a', targetId: 'b', type: 'temporal', weight: 0.5 },
          expect.objectContaining({ sourceId: 'a', targetId: 'b', type: 'similar' }),
        ]),
      );
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });

  it('bounds large unique stores while retaining their linear temporal graph', () => {
    const root = mkdtempSync(join(tmpdir(), 'ruflo-2628-bound-'));
    const entries: Entry[] = Array.from({ length: 600 }, (_, i) => ({
      id: `entry-${i}`,
      content: `distinct project fact number ${i} token-${i.toString(36)}`,
      namespace: 'one-large-category',
      metadata: { sourceFile: 'MEMORY.md' },
    }));

    try {
      const dataDir = writeStore(root, entries);
      const result = consolidate(root);
      const graph = JSON.parse(
        readFileSync(join(dataDir, 'graph-state.json'), 'utf-8'),
      ) as { edges: Array<{ type: string }> };

      expect(result.entries).toBe(entries.length);
      expect(graph.edges).toHaveLength(entries.length - 1);
      expect(graph.edges.every((edge) => edge.type === 'temporal')).toBe(true);
    } finally {
      rmSync(root, { recursive: true, force: true });
    }
  });
});

