/**
 * Regression test for issue #2694: the statusline CVE counter was fabricated.
 * `getSecurityStatus` hardcoded `totalCves = 3` and counted `.json` scan
 * *files* as "CVEs fixed", so every project unconditionally showed "⚠ 3 CVEs"
 * and reached CLEAN by writing 3 arbitrary JSON files. After the fix it reads
 * the NEWEST scan file and surfaces the real findings count.
 *
 * Pure unit test against funnel/local-signals.ts — no CLI binary, no network.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { getSecurityStatus } from '../src/funnel/local-signals.js';

let cwd: string;

beforeEach(() => {
  cwd = mkdtempSync(join(tmpdir(), 'issue-2694-cve-'));
});

afterEach(() => {
  rmSync(cwd, { recursive: true, force: true });
});

function scanDir() {
  return join(cwd, '.claude', 'security-scans');
}

describe('getSecurityStatus — issue #2694 (CVE counter not fabricated)', () => {
  it('returns PENDING/0/0 when no .claude/security-scans/ dir exists (NOT 3)', () => {
    const s = getSecurityStatus(cwd);
    expect(s).toEqual({ status: 'PENDING', findings: 0, cvesFixed: 0, totalCves: 0 });
    expect(s.totalCves).not.toBe(3);
  });

  it('returns PENDING/0/0 when the scan dir exists but has no .json files', () => {
    mkdirSync(scanDir(), { recursive: true });
    const s = getSecurityStatus(cwd);
    expect(s).toEqual({ status: 'PENDING', findings: 0, cvesFixed: 0, totalCves: 0 });
  });

  it('returns CLEAN/0/0 for a scan with 0 findings', () => {
    mkdirSync(scanDir(), { recursive: true });
    writeFileSync(
      join(scanDir(), 'scan-deps-quick.json'),
      JSON.stringify({ findings: [], totalFindings: 0, summary: { total: 0 } }),
    );
    const s = getSecurityStatus(cwd);
    expect(s).toMatchObject({ status: 'CLEAN', findings: 0, cvesFixed: 0, totalCves: 0 });
  });

  it('returns ISSUES with generic findings while keeping CVE compatibility fields at zero', () => {
    mkdirSync(scanDir(), { recursive: true });
    writeFileSync(
      join(scanDir(), 'scan-deps-quick.json'),
      JSON.stringify({ findings: [{}, {}], totalFindings: 2, summary: { total: 2 } }),
    );
    const s = getSecurityStatus(cwd);
    expect(s).toMatchObject({ status: 'ISSUES', findings: 2, cvesFixed: 0, totalCves: 0 });
  });

  it('does NOT produce totalCves:3 or CLEAN from 3 empty .json files (the old fabrication)', () => {
    // Pre-fix: 3 scan files -> cvesFixed = min(3, 3) = 3 -> status CLEAN.
    // Post-fix: each file has 0 findings -> totalCves = 0 -> CLEAN (real).
    // The key regression guard: totalCves must reflect findings, not file count.
    mkdirSync(scanDir(), { recursive: true });
    for (let i = 0; i < 3; i++) {
      writeFileSync(
        join(scanDir(), `scan-${i}.json`),
        JSON.stringify({ findings: [], totalFindings: 0, summary: { total: 0 } }),
      );
    }
    const s = getSecurityStatus(cwd);
    expect(s.totalCves).toBe(0);
    expect(s.cvesFixed).toBe(0);
    expect(s.findings).toBe(0);
    expect(s.status).toBe('CLEAN');
  });

  it('reads the NEWEST scan by mtime when several exist', async () => {
    mkdirSync(scanDir(), { recursive: true });
    // Old scan: 5 findings
    writeFileSync(
      join(scanDir(), 'scan-old.json'),
      JSON.stringify({ findings: [{}, {}, {}, {}, {}], totalFindings: 5, summary: { total: 5 } }),
    );
    // Bump mtime into the future so the newer file is unambiguously newest.
    const future = new Date(Date.now() + 60_000);
    writeFileSync(
      join(scanDir(), 'scan-new.json'),
      JSON.stringify({ findings: [{}], totalFindings: 1, summary: { total: 1 } }),
    );
    // statSync U2 the file's mtime to the future timestamp for determinism.
    const { utimesSync } = await import('fs');
    utimesSync(join(scanDir(), 'scan-new.json'), future, future);
    const s = getSecurityStatus(cwd);
    expect(s.findings).toBe(1);
    expect(s.totalCves).toBe(0);
    expect(s.status).toBe('ISSUES');
  });

  it('falls back to totalFindings / findings.length when summary.total is absent', () => {
    mkdirSync(scanDir(), { recursive: true });
    writeFileSync(
      join(scanDir(), 'scan-deps-quick.json'),
      JSON.stringify({ findings: [{}, {}, {}], totalFindings: 3 }),
    );
    const s = getSecurityStatus(cwd);
    expect(s.findings).toBe(3);
    expect(s.totalCves).toBe(0);
    expect(s.status).toBe('ISSUES');
  });

  it('returns PENDING/0/0 when the newest scan file is unparseable', () => {
    mkdirSync(scanDir(), { recursive: true });
    writeFileSync(join(scanDir(), 'scan-broken.json'), '{not valid json');
    const s = getSecurityStatus(cwd);
    expect(s).toEqual({ status: 'PENDING', findings: 0, cvesFixed: 0, totalCves: 0 });
  });
});

/**
 * Regression coverage for issue #2733: `hooks statusline`'s model-name
 * resolution was fully hardcoded (`const modelName = 'Opus 4.6 (1M context)'`)
 * and ignored the actual active model Claude Code passes on stdin entirely.
 *
 * The CLI is spawned as a real subprocess (not imported) because the
 * hardcoded value lived inside a large nested function in the command's
 * `action`, not a unit-testable export — the same reasoning documented in
 * memory-search-recall-2558.test.ts for using a real process here. Skipped
 * when the CLI hasn't been built (`bin/cli.js` absent) — standard flow is
 * `npm run build && npm test`.
 */
import { describe, it, expect } from 'vitest';
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const CLI = path.resolve(HERE, '..', 'bin', 'cli.js');
const CLI_BUILT = fs.existsSync(CLI);

function runStatusline(stdin: string): { user: { modelName: string } } {
  const raw = execFileSync('node', [CLI, 'hooks', 'statusline', '--json'], {
    input: stdin,
    encoding: 'utf8',
    timeout: 15_000,
  });
  // The CLI may print unrelated warnings (e.g. helper-integrity notices) to
  // stdout ahead of the JSON payload in some environments; the JSON object
  // itself is always the last well-formed `{...}` block in the output.
  const start = raw.indexOf('{');
  const parsed = JSON.parse(raw.slice(start));
  return parsed;
}

describe.skipIf(!CLI_BUILT)('hooks statusline model name — issue #2733', () => {
  it('reports the real active model from Claude Code stdin JSON', () => {
    const result = runStatusline(JSON.stringify({ model: { display_name: 'Sonnet 4.6 (1M context)' } }));
    expect(result.user.modelName).toBe('Sonnet 4.6 (1M context)');
    expect(result.user.modelName).not.toBe('Opus 4.6 (1M context)');
  });

  it('never renders the old hardcoded model string regardless of stdin', () => {
    const result = runStatusline(JSON.stringify({ model: { display_name: 'Haiku 4.5' } }));
    expect(result.user.modelName).toBe('Haiku 4.5');
  });

  it('falls back to a generic label (not a fixed fake model name) when stdin has no model field', () => {
    const result = runStatusline(JSON.stringify({}));
    expect(result.user.modelName).not.toBe('Opus 4.6 (1M context)');
    expect(result.user.modelName).toBe('Claude Code');
  });

  it('falls back gracefully on malformed stdin', () => {
    const result = runStatusline('not json');
    expect(result.user.modelName).not.toBe('Opus 4.6 (1M context)');
    expect(result.user.modelName).toBe('Claude Code');
  });
});

/**
 * Regression coverage for issue #2735: memory CRUD's sql.js fallback did a
 * whole-image read-modify-persist (export() + rename over the live
 * database path) with no regard for whether a native better-sqlite3 WAL
 * connection was already attached — corrupting the shared database or
 * silently losing an acknowledged write when the fallback fired while a
 * native writer (daemon, MCP server, another CLI invocation) held the file
 * open.
 *
 * This suite covers the scoped fix actually shipped: refuse the sql.js
 * fallback (`success: false`, typed error, never a whole-image write) when
 * `-wal`/`-shm` sidecar files are present next to the database — strong
 * evidence of a live native WAL connection, since a native connection keeps
 * its sidecars on disk for its entire lifetime. It does NOT cover the
 * fuller "scan live process holders" design also discussed in the issue —
 * that remains a documented follow-up, not part of this fix.
 *
 * The bridge is force-disabled via CLAUDE_FLOW_DISABLE_BRIDGE=1 (the
 * package's own documented switch, dist/src/memory/memory-initializer.js)
 * so every case below exercises the sql.js fallback path directly,
 * deterministically, without needing a real second native connection.
 */
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

let dir: string;
let dbPath: string;
const ORIGINAL_ENV = process.env.CLAUDE_FLOW_DISABLE_BRIDGE;

beforeEach(async () => {
  dir = mkdtempSync(path.join(tmpdir(), 'ruflo-2735-'));
  dbPath = path.join(dir, 'memory.db');
  process.env.CLAUDE_FLOW_DISABLE_BRIDGE = '1';
  // Reset the module registry so each test gets a fresh dynamic import —
  // the module under test is pure-functional (no top-level state this
  // suite depends on), but sql.js's own WASM init is safest re-run clean.
  const { initializeMemoryDatabase } = await import('../src/memory/memory-initializer.js');
  const initResult = await initializeMemoryDatabase({ dbPath, verbose: false });
  expect(initResult.success).toBe(true);
});

afterEach(() => {
  if (ORIGINAL_ENV === undefined) delete process.env.CLAUDE_FLOW_DISABLE_BRIDGE;
  else process.env.CLAUDE_FLOW_DISABLE_BRIDGE = ORIGINAL_ENV;
  rmSync(dir, { recursive: true, force: true });
});

describe('memory sql.js fallback WAL-sidecar guard — issue #2735', () => {
  it('storeEntry refuses the whole-image write when -wal sidecar is present', async () => {
    writeFileSync(`${dbPath}-wal`, '');
    const { storeEntry } = await import('../src/memory/memory-initializer.js');
    const result = await storeEntry({ key: 'k1', value: 'v1', dbPath });
    expect(result.success).toBe(false);
    expect(result.error).toMatch(/native WAL connection/i);
  });

  it('storeEntry refuses the whole-image write when -shm sidecar is present', async () => {
    writeFileSync(`${dbPath}-shm`, '');
    const { storeEntry } = await import('../src/memory/memory-initializer.js');
    const result = await storeEntry({ key: 'k1', value: 'v1', dbPath });
    expect(result.success).toBe(false);
    expect(result.error).toMatch(/native WAL connection/i);
  });

  it('storeEntry proceeds normally with no sidecars present', async () => {
    const { storeEntry } = await import('../src/memory/memory-initializer.js');
    const result = await storeEntry({ key: 'k1', value: 'v1', dbPath, generateEmbeddingFlag: false });
    expect(result.success).toBe(true);
    expect(result.id).not.toBe('');
  });

  it('getEntry refuses the whole-image access_count-bump write when sidecars are present', async () => {
