/**
 * Regression for #2652's native/fallback visibility disagreement.
 *
 * Databases created before the status column existed contain NULL after an
 * additive migration. list() has long treated those rows as legacy-active,
 * but native retrieve/delete required the literal string "active". Mock the
 * ControllerRegistry only — all SQL executes against a real better-sqlite3
 * fixture, so this pins the production bridge path deterministically.
 */
import { afterAll, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const root = mkdtempSync(join(tmpdir(), 'ruflo-2652-native-'));
const dbPath = join(root, 'memory.db');
let db: Database.Database | null = null;

function seedLegacyActiveRow(): void {
  const db = new Database(dbPath);
  db.exec(`
    CREATE TABLE memory_entries (
      id TEXT PRIMARY KEY,
      key TEXT NOT NULL,
      namespace TEXT DEFAULT 'default',
      content TEXT NOT NULL,
      type TEXT DEFAULT 'semantic',
      embedding TEXT,
      embedding_model TEXT DEFAULT 'local',
      embedding_dimensions INTEGER,
      tags TEXT,
      metadata TEXT,
      owner_id TEXT,
      created_at INTEGER,
      updated_at INTEGER,
      expires_at INTEGER,
      last_accessed_at INTEGER,
      access_count INTEGER DEFAULT 0,
      status TEXT,
      provenance_type TEXT DEFAULT 'unknown',
      UNIQUE(namespace, key)
    );
    INSERT INTO memory_entries (
      id, key, namespace, content, created_at, updated_at, status
    ) VALUES (
      'legacy-live-id', 'project-state-current', 'fixture', 'visible value',
      1, 1, NULL
    );
  `);
  db.close();
}

seedLegacyActiveRow();

afterAll(() => {
  db?.close();
  rmSync(root, { recursive: true, force: true });
});

describe('#2652 active-row visibility', () => {
  it('retrieves and deletes the same legacy-active row through the native bridge', async () => {
    const {
      __setMemoryBridgeRegistryForTests,
      bridgeGetEntry,
      bridgeDeleteEntry,
    } = await import('../src/memory/memory-bridge.js');

    db = new Database(dbPath);
    __setMemoryBridgeRegistryForTests({
      getAgentDB: () => ({ database: db, embedder: null }),
      get: () => null,
    });

    const retrieved = await bridgeGetEntry({
      key: 'project-state-current',
      namespace: 'fixture',
      dbPath,
    });
    expect(retrieved).toMatchObject({
      success: true,
      found: true,
      entry: {
        id: 'legacy-live-id',
        key: 'project-state-current',
        namespace: 'fixture',
        content: 'visible value',
      },
    });

    const deleted = await bridgeDeleteEntry({
      key: 'project-state-current',
      namespace: 'fixture',
      dbPath,
    });
    expect(deleted).toMatchObject({
      success: true,
      deleted: true,
      remainingEntries: 0,
    });

    const row = db
      .prepare('SELECT status FROM memory_entries WHERE id = ?')
      .get('legacy-live-id') as { status: string };
    expect(row.status).toBe('deleted');
  });
});

/**
 * Vector-memory DB backup service (nightly backup worker + `memory backup`).
 *
 * Proves the WAL-safe snapshot is consistent, non-destructive, rotated, and
 * degrades cleanly when there's nothing to back up.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { mkdtempSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { backupMemoryDb } from '../src/services/memory-backup.js';

let Database: any;
let haveNative = false;
try { Database = (await import('better-sqlite3')).default; haveNative = true; } catch { haveNative = false; }

function seedDb(dbPath: string, rows = 50): void {
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL'); // the mode a naive copy would corrupt
  db.exec('CREATE TABLE memory_entries (id INTEGER PRIMARY KEY, content TEXT)');
  const ins = db.prepare('INSERT INTO memory_entries (content) VALUES (?)');
  const tx = db.transaction(() => { for (let i = 0; i < rows; i++) ins.run('row ' + i); });
  tx();
  db.close();
}

describe.skipIf(!haveNative)('backupMemoryDb', () => {
  let workdir: string;
  beforeEach(() => { workdir = mkdtempSync(join(tmpdir(), 'mem-backup-')); });

  it('takes a consistent WAL-safe snapshot without mutating the source', async () => {
    const dbPath = join(workdir, 'memory.db');
    seedDb(dbPath, 50);
    const srcSize = statSync(dbPath).size;

    const r = await backupMemoryDb({ dbPath, timestamp: 1_700_000_000_000 });
    expect(r.backedUp).toBe(true);
    expect(existsSync(r.path!)).toBe(true);
    expect(r.sizeBytes!).toBeGreaterThan(0);

    // Source is unchanged (size stable) and the snapshot has all the rows.
    expect(statSync(dbPath).size).toBe(srcSize);
    const snap = new Database(r.path!, { readonly: true });
    const count = (snap.prepare('SELECT COUNT(*) AS c FROM memory_entries').get() as { c: number }).c;
    snap.close();
    expect(count).toBe(50);
  });

  it('defaults the destination to <db dir>/backups', async () => {
    const dbPath = join(workdir, 'memory.db');
    seedDb(dbPath);
    const r = await backupMemoryDb({ dbPath, timestamp: 1_700_000_000_000 });
    expect(r.path!.replace(/\\/g, '/')).toContain('/backups/memory-');
  });

  it('rotates — keeps only the newest N snapshots', async () => {
    const dbPath = join(workdir, 'memory.db');
    seedDb(dbPath);
    const destDir = join(workdir, 'backups');
    // 5 snapshots at increasing timestamps, keep=3.
    for (let i = 0; i < 5; i++) {
      await backupMemoryDb({ dbPath, destDir, keep: 3, timestamp: 1_700_000_000_000 + i * 86_400_000 });
    }
    const snaps = readdirSync(destDir).filter(f => /^memory-.*\.db$/.test(f));
    expect(snaps.length).toBe(3);
    // The three newest (largest timestamps) survive.
    expect(snaps.sort().slice(-1)[0]).toContain('memory-');
  });

  it('is a safe no-op when there is no DB to back up', async () => {
    const r = await backupMemoryDb({ dbPath: join(workdir, 'nope.db') });
    expect(r.backedUp).toBe(false);
    expect(r.skipped).toBe('no-db');
  });
});

/**
 * Regression: a failed bridge init must be diagnosable and recoverable.
 *
 * `getRegistry()` latches `bridgeAvailable = false` for the life of the
 * process, so one transient init failure routes every later write to the
 * sql.js whole-image fallback — which then refuses whenever -wal/-shm
 * sidecars are present. Observed in the wild: an MCP server silently dropped
 * every `memory_store` for hours while CLI writes through the same database
 * succeeded, and the only symptom was a refusal naming a cause the operator
 * could not check.
 *
 * Three properties close that:
 *   1. the failure reason is recorded rather than swallowed by a bare catch;
 *   2. `shutdownBridge()` clears the latch even when init never produced a
 *      registry — previously the reset sat inside `if (registryInstance)`,
 *      which is null in exactly the case needing a reset;
 *   3. a degradation notice is never filtered out as init noise.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';

// `@claude-flow/memory` is externalized in vitest.config.ts (it is a try/catch
// dynamic import that degrades to the sql.js path), so the import inside
// getRegistry() always throws here. That is the init failure under test — the
// assertions deliberately check the recorded/cleared behaviour rather than the
// flavour of the underlying error, which is not the property that matters.

describe('bridge failure diagnostics', () => {
  beforeEach(() => {
    vi.resetModules();
  });

  it('should report null before the bridge has been tried', async () => {
    const { getBridgeFailureReason } = await import('../src/memory/memory-bridge.js');

    expect(getBridgeFailureReason()).toBeNull();
  });

  it('should record why init failed instead of swallowing the error', async () => {
    const bridge = await import('../src/memory/memory-bridge.js');

    await bridge.bridgeStoreEntry({ key: 'k', value: 'v' });

    const reason = bridge.getBridgeFailureReason();
    expect(reason).toBeTruthy();
    expect(typeof reason).toBe('string');
  });

  it('should return null from bridgeStoreEntry so the caller falls back', async () => {
    const bridge = await import('../src/memory/memory-bridge.js');

    const result = await bridge.bridgeStoreEntry({ key: 'k', value: 'v' });

    expect(result).toBeNull();
  });

  it('should clear the latched failure on shutdown even with no registry instance', async () => {
    const bridge = await import('../src/memory/memory-bridge.js');
    await bridge.bridgeStoreEntry({ key: 'k', value: 'v' });
    expect(bridge.getBridgeFailureReason()).toBeTruthy();

    await bridge.shutdownBridge();

    expect(bridge.getBridgeFailureReason()).toBeNull();
  });

  it('should re-attempt init after shutdown rather than staying latched', async () => {
    const bridge = await import('../src/memory/memory-bridge.js');
    await bridge.bridgeStoreEntry({ key: 'k', value: 'v' });
    await bridge.shutdownBridge();
    expect(bridge.getBridgeFailureReason()).toBeNull();

    // A latched `bridgeAvailable === false` short-circuits getRegistry() before
    // it retries, so the reason would stay null. Repopulating it proves the
    // retry actually happened.
    await bridge.bridgeStoreEntry({ key: 'k2', value: 'v2' });

    expect(bridge.getBridgeFailureReason()).toBeTruthy();
  });
});

