/**
 * Regression: the bridge must migrate `provenance_type` onto a pre-ADR-323
 * `memory_entries` table.
 *
 * ADR-323 added `provenance_type` to bridgeStoreEntry()'s INSERT.
 * `ensureSchemaColumns()` backfills the column on the sql.js path, but the
 * bridge path only ran `CREATE TABLE IF NOT EXISTS` — a no-op on a table that
 * already exists. So on any database created before ADR-323, every bridge
 * write threw:
 *
 *   SqliteError: table memory_entries has no column named provenance_type
 *
 * which the catch at the end of bridgeStoreEntry() swallowed, returning null.
 * The caller then demoted to the sql.js whole-image path, whose WAL-sidecar
 * guard reported "memory database has an active native WAL connection …
 * restore the native better-sqlite3 bridge" — a cause with nothing to do with
 * the real failure. Observed live: an MCP server dropped every memory_store
 * for hours while better-sqlite3 was healthy the whole time.
 */
import { describe, it, expect, beforeAll, vi } from 'vitest';
import initSqlJs from 'sql.js';
import { ensureBridgeSchema } from '../src/memory/memory-bridge.js';

const LEGACY_TABLE = `CREATE TABLE memory_entries (
  id TEXT PRIMARY KEY,
  key TEXT NOT NULL,
  namespace TEXT DEFAULT 'default',
  content TEXT NOT NULL,
  type TEXT DEFAULT 'semantic',
  status TEXT DEFAULT 'active',
  UNIQUE(namespace, key)
)`;

let SQL: Awaited<ReturnType<typeof initSqlJs>>;

const columnsOf = (db: { exec: (sql: string) => Array<{ values: unknown[][] }> }): string[] => {
  const res = db.exec('PRAGMA table_info(memory_entries)');
  return res.length ? res[0].values.map((row) => String(row[1])) : [];
};

beforeAll(async () => {
  SQL = await initSqlJs();
});

describe('bridge schema migration (ADR-323 provenance_type)', () => {
  it('should add provenance_type to a pre-ADR-323 table', () => {
    const db = new SQL.Database();
    db.run(LEGACY_TABLE);
    expect(columnsOf(db)).not.toContain('provenance_type');

    ensureBridgeSchema(db);

    expect(columnsOf(db)).toContain('provenance_type');
  });

  it('should let the ADR-323 insert succeed after migration', () => {
    const db = new SQL.Database();
    db.run(LEGACY_TABLE);
    ensureBridgeSchema(db);

    const insert = () => db.run(
      'INSERT INTO memory_entries (id, key, namespace, content, provenance_type) VALUES (?, ?, ?, ?, ?)',
      ['id-1', 'k', 'ns', 'v', 'agent_output'],
    );

    expect(insert).not.toThrow();
  });

  it('should include provenance_type when creating the table fresh', () => {
    const db = new SQL.Database();

    ensureBridgeSchema(db);

    expect(columnsOf(db)).toContain('provenance_type');
  });

  it('should be idempotent across repeated calls', () => {
    const db = new SQL.Database();
    db.run(LEGACY_TABLE);

    ensureBridgeSchema(db);
    const second = () => ensureBridgeSchema(db);

    expect(second).not.toThrow();
    expect(columnsOf(db).filter((c) => c === 'provenance_type')).toHaveLength(1);
  });

  it('should report success when the schema is usable', () => {
    const db = new SQL.Database();
    db.run(LEGACY_TABLE);

    expect(ensureBridgeSchema(db)).toBe(true);
  });

  it('should fail closed when ALTER fails for a reason other than an existing column', () => {
    const exec = vi.fn((sql: string) => {
      if (sql.startsWith('ALTER TABLE')) {
        throw new Error('SQLITE_READONLY: attempt to write a readonly database');
      }
    });

    expect(ensureBridgeSchema({ exec })).toBe(false);
    expect(exec).toHaveBeenCalledTimes(2);
  });
});

/**
 * Regression guard for issue #2878 — concurrent sql.js whole-image writes
 * were acknowledged and then silently lost.
 *
 * sql.js has no incremental persistence: every mutator loads the entire db
 * image into memory, mutates it, and writes the whole image back. Two
 * writers whose load→mutate→persist windows overlap therefore both start
 * from the same predecessor image, and the last one to flush silently
 * discards the other's row — while both return `success: true`.
 * `PRAGMA integrity_check` still passes, because the file isn't corrupt;
 * the data is simply gone.
 *
 * #2666 introduced `withMemoryDbLock` but only `purgeNamespace` opted in.
 * These tests assert the whole-image read-modify-write paths now serialize
 * through it, so a success acknowledgement means the mutation is durable.
 *
 * Reproducing it needs an `await` between the image read and the image
 * write. `storeEntry` has one — embedding generation sits between them — so
 * N concurrent stores with embeddings enabled all read the same predecessor
 * image before any of them flushes. That is the exact lost-update shape the
 * issue reported with 12 processes, and it exercises the same `O_EXCL` lock
 * file (which is process-agnostic, so in-process contention is real
 * contention).
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import {
  initializeMemoryDatabase,
  storeEntry,
  listEntries,
  getEntry,
  deleteEntry,
  withMemoryDbLock,
} from '../src/memory/memory-initializer.js';

let tmp: string;
let dbPath: string;

beforeEach(async () => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'concurrent-write-2878-'));
  dbPath = path.join(tmp, 'memory.db');
  const init = await initializeMemoryDatabase({ dbPath, force: true, migrate: false });
  expect(init.success).toBe(true);
});

afterEach(() => {
  try { fs.rmSync(tmp, { recursive: true, force: true }); } catch { /* */ }
});

describe('concurrent memory.db writes (#2878)', () => {
  it('persists every acknowledged storeEntry when 12 writers overlap', async () => {
    const N = 12;
    const results = await Promise.all(
      Array.from({ length: N }, (_, i) =>
        storeEntry({
          key: `concurrent-${i}`,
          value: `value for concurrent writer number ${i}`,
          namespace: 'concurrency',
          dbPath,
          // Embedding generation is the await that opens the read→write
          // window every concurrent writer used to race through.
          generateEmbeddingFlag: true,
        })
      )
    );

    expect(results.filter((r) => r.success).length).toBe(N);

    const listed = await listEntries({ namespace: 'concurrency', dbPath, limit: 100 });
    const keys = new Set(listed.entries.map((e) => e.key));
    const missing = Array.from({ length: N }, (_, i) => `concurrent-${i}`).filter((k) => !keys.has(k));

    // Every acknowledged write must be on disk — no silent loss.
    expect(missing).toEqual([]);
    expect(listed.total).toBe(N);
  }, 60_000);

  it('does not lose a concurrent store while other writers hold the image', async () => {
    const [storeResults, lateResult] = await Promise.all([
      Promise.all(
        Array.from({ length: 6 }, (_, i) =>
          storeEntry({
            key: `batch-${i}`,
            value: `batch value ${i}`,
            namespace: 'concurrency',
            dbPath,
            generateEmbeddingFlag: true,
          })
        )
      ),
      storeEntry({
        key: 'written-during-batch',
        value: 'must survive',
        namespace: 'concurrency',
        dbPath,
        generateEmbeddingFlag: true,
      }),
    ]);

    expect(storeResults.every((r) => r.success)).toBe(true);
    expect(lateResult.success).toBe(true);

    const listed = await listEntries({ namespace: 'concurrency', dbPath, limit: 100 });
    const keys = new Set(listed.entries.map((e) => e.key));
    expect(keys.has('written-during-batch')).toBe(true);
    expect(listed.total).toBe(7);
  }, 60_000);

  it('serializes getEntry access_count bumps instead of losing them', async () => {
    await storeEntry({
      key: 'read-me',
      value: 'seed',
      namespace: 'concurrency',
      dbPath,
      generateEmbeddingFlag: false,
    });

    // getEntry rewrites the whole image to bump access_count, so N concurrent
    // reads are N concurrent writers. Every bump must land.
    const N = 8;
    const reads = await Promise.all(
      Array.from({ length: N }, () => getEntry({ key: 'read-me', namespace: 'concurrency', dbPath }))
    );
    expect(reads.every((r) => r.success && r.found)).toBe(true);

    const final = await getEntry({ key: 'read-me', namespace: 'concurrency', dbPath });
    // N concurrent bumps + this one; a lost update would leave it lower.
    expect(final.entry?.accessCount).toBe(N + 1);
  }, 60_000);

  it('does not resurrect concurrently deleted entries', async () => {
    const N = 6;
    for (let i = 0; i < N; i++) {
      const r = await storeEntry({
        key: `del-${i}`,
        value: `v${i}`,
        namespace: 'concurrency',
        dbPath,
        generateEmbeddingFlag: false,
      });
      expect(r.success).toBe(true);
    }

    const deletes = await Promise.all(
      Array.from({ length: N }, (_, i) =>
        deleteEntry({ key: `del-${i}`, namespace: 'concurrency', dbPath })
      )
    );
    expect(deletes.filter((d) => d.success && d.deleted).length).toBe(N);

    const listed = await listEntries({ namespace: 'concurrency', dbPath, limit: 100 });
    // A lost delete resurrects a tombstoned row from a stale predecessor image.
    expect(listed.entries.map((e) => e.key)).toEqual([]);
  }, 60_000);

  it('withMemoryDbLock is reentrant, so nested critical sections do not self-deadlock', async () => {
    // storeEntry/deleteEntry/purgeNamespace all call ensureSchemaColumns from
    // inside their own critical section. A non-reentrant O_EXCL lock would
    // block there until the acquire timeout.
    const inner = await withMemoryDbLock(dbPath, async () =>
      withMemoryDbLock(dbPath, async () => 'reached')
    );
    expect(inner).toBe('reached');
    // Lock file released on the way out.
    expect(fs.existsSync(`${dbPath}.lock`)).toBe(false);
  }, 20_000);

  it('normalizes the lock path so relative and absolute callers contend on one lock', async () => {
    const relative = path.relative(process.cwd(), dbPath);
    let innerRan = false;
    await withMemoryDbLock(dbPath, async () => {
      // Same file, different spelling — must be seen as already held, not as
      // a second independent lock.
      await withMemoryDbLock(relative, async () => { innerRan = true; });
    });
    expect(innerRan).toBe(true);
  }, 20_000);
});

/**
 * Integration test for ADR-096 Phase 4: memory-initializer DB encryption.
 *
 * Different shape from session/terminal tests because the memory store is
 * a Buffer-only sql.js SQLite blob (not a JSON.stringify of an object).
 * The fs-secure helpers handle Buffer payloads identically — these tests
 * pin that contract end-to-end without spinning up the real sql.js
 * dependency (which has a heavy WASM init path).
 *
 * What's pinned:
 *   - writeFileRestricted({encrypt:true}) on a Buffer payload produces
 *     the RFE1 wire format when the env gate is on
 *   - readFileMaybeEncrypted(path, null) returns a Buffer (not string)
 *     and decrypts transparently when the file IS encrypted
 *   - Round-trip: write Buffer → read Buffer matches byte-for-byte
 *   - Migration: a legacy plaintext SQLite header on disk is still
 *     readable after the gate flips on (magic-byte sniff returns false
 *     for the SQLite header, so the file passes through unchanged)
 *   - Tamper: a flipped byte inside an encrypted DB blob throws on read
 *     rather than producing a corrupted Buffer
 */

import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomBytes } from 'node:crypto';

import {
  readFileMaybeEncrypted,
  writeFileRestricted,
} from '../src/fs-secure.js';
import { MAGIC, isEncryptedBlob } from '../src/encryption/vault.js';

const SAVED_ENV: Record<string, string | undefined> = {};
function saveEnv(...names: string[]) {
  for (const n of names) SAVED_ENV[n] = process.env[n];
}
function restoreEnv() {
  for (const [n, v] of Object.entries(SAVED_ENV)) {
    if (v === undefined) delete process.env[n];
    else process.env[n] = v;
  }
}

// SQLite file format: first 16 bytes are "SQLite format 3\0". memory-initializer
// writes real sql.js exports (often multi-MB), but the encryption path doesn't
// care about content — only the Buffer shape. Use a plausible synthetic header
// + payload that exercises the same code path.
function makeSyntheticDbBuffer(payloadSize = 4096): Buffer {
  return Buffer.concat([
    Buffer.from('SQLite format 3\0', 'utf-8'),
    randomBytes(payloadSize - 16),
  ]);
}

describe('memory-initializer DB encryption (ADR-096 Phase 4)', () => {
  let workdir: string;
  let dbPath: string;

  beforeEach(() => {
    saveEnv('CLAUDE_FLOW_ENCRYPT_AT_REST', 'CLAUDE_FLOW_ENCRYPTION_KEY');
    workdir = mkdtempSync(join(tmpdir(), 'mem-db-enc-'));
    dbPath = join(workdir, 'memory.db');
  });

  afterEach(() => {
    rmSync(workdir, { recursive: true, force: true });
    restoreEnv();
  });

  describe('encryption disabled (legacy plaintext SQLite)', () => {
    beforeEach(() => {
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
    });

    it('writes the SQLite buffer unchanged to disk', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      const onDisk = readFileSync(dbPath);
      expect(onDisk.equals(db)).toBe(true);
      // First 16 bytes are the literal SQLite header
      expect(onDisk.subarray(0, 16).toString('utf-8')).toBe('SQLite format 3\0');
      expect(isEncryptedBlob(onDisk)).toBe(false);
    });

    it('round-trips a Buffer through readFileMaybeEncrypted(path, null)', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      const round = readFileMaybeEncrypted(dbPath, null);
      expect(Buffer.isBuffer(round)).toBe(true);
      expect(round.equals(db)).toBe(true);
    });
  });

  describe('encryption enabled (RFE1 wire format)', () => {
    beforeEach(() => {
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
    });

    it('writes a blob that starts with the RFE1 magic, NOT the SQLite header', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      const onDisk = readFileSync(dbPath);
      expect(onDisk.subarray(0, 4)).toEqual(MAGIC);
      // Critical: the SQLite header must NOT appear at offset 0 — the
      // encryption ran and replaced the on-disk bytes.
      expect(onDisk.subarray(0, 16).toString('utf-8')).not.toBe('SQLite format 3\0');
      expect(isEncryptedBlob(onDisk)).toBe(true);
    });

    it('round-trips a Buffer through write → read with the same key', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      const round = readFileMaybeEncrypted(dbPath, null);
      expect(Buffer.isBuffer(round)).toBe(true);
      expect(round.equals(db)).toBe(true);
    });

    it('round-trips a megabyte-scale buffer (real-world memory.db size)', () => {
      const db = makeSyntheticDbBuffer(1_048_576); // 1MB
      writeFileRestricted(dbPath, db, { encrypt: true });
      const round = readFileMaybeEncrypted(dbPath, null);
      expect(round.equals(db)).toBe(true);
    });

    it('does not leak embedding-bytes into the on-disk blob', () => {
      // Plant a recognizable signature inside the synthetic DB and confirm
      // it does not appear in the encrypted bytes.
      const signature = Buffer.from('TOPSECRET-EMBEDDING-VECTOR-AAAA', 'utf-8');
      const db = Buffer.concat([
        Buffer.from('SQLite format 3\0', 'utf-8'),
        signature,
        randomBytes(2048),
      ]);
      writeFileRestricted(dbPath, db, { encrypt: true });
      const onDisk = readFileSync(dbPath);
      expect(onDisk.includes(signature)).toBe(false);
    });
  });

  describe('migration: legacy plaintext SQLite still readable', () => {
    it('plaintext SQLite written before the gate flipped on is returned as-is', () => {
      // Step 1: plant a plaintext SQLite blob on disk (no env vars set
      // — direct writeFileSync would normally have done this).
      const db = makeSyntheticDbBuffer();
      writeFileSync(dbPath, db);

      // Step 2: enable encryption for the read.
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');

      // Step 3: readFileMaybeEncrypted's magic-byte sniff sees no RFE1
      // prefix, so it returns the Buffer unchanged. New SQL.Database()
      // would accept it directly.
      const round = readFileMaybeEncrypted(dbPath, null);
      expect(round.equals(db)).toBe(true);
      expect(round.subarray(0, 16).toString('utf-8')).toBe('SQLite format 3\0');
    });
  });

  describe('tamper detection on encrypted DB', () => {
    beforeEach(() => {
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
    });

    it('rejects a flipped ciphertext byte (GCM auth fails)', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      // Flip a byte deep inside the ciphertext region (after magic+iv,
      // before the trailing 16-byte tag)
      const bytes = readFileSync(dbPath);
      bytes[100] ^= 0xff;
      writeFileSync(dbPath, bytes);
      expect(() => readFileMaybeEncrypted(dbPath, null)).toThrow();
    });

    it('rejects a flipped magic byte (caught early with bad-magic error)', () => {
      const db = makeSyntheticDbBuffer();
      writeFileRestricted(dbPath, db, { encrypt: true });
      const bytes = readFileSync(dbPath);
      bytes[0] = 0x00;
      writeFileSync(dbPath, bytes);
      // The magic-sniff returns false (not RFE1 prefix anymore), so the
      // reader returns the bytes as-is. NB: this is the legacy-plaintext
      // path — the bytes are unreadable as SQLite but won't throw at the
      // fs-secure layer. That's correct: tamper detection on plaintext
      // SQLite is sql.js's job, not ours. The auth failure mode (above)
      // covers the case where the magic IS still RFE1 but content is bad.
      const round = readFileMaybeEncrypted(dbPath, null);
      expect(Buffer.isBuffer(round)).toBe(true);
      expect(round[0]).toBe(0x00); // tampered first byte propagates as-is
    });
  });
});

/**
 * ADR-174 Milestone 2 — `memory distill` CLI surface.
 *
 * Exercises the CLI command family (run|status|config) built on top of the
 * frozen M1 service (`../src/services/memory-distillation.ts`). The service
 * itself is proven by `memory-distillation.test.ts`; this file proves the CLI
 * wiring: flag → DistillOptions mapping, the ADR-172 fail-fast budget gate,
 * the aggressive/conservative presets, and the read-only `status` report.
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import type { Command, CommandContext } from '../src/types.js';
import { distillCommand, resolveDistillConfig } from '../src/commands/memory-distill.js';

let Database: any;
let haveNative = false;
try { Database = (await import('better-sqlite3')).default; haveNative = true; } catch { haveNative = false; }

/** Same fixture shape as __tests__/memory-distillation.test.ts. */
function seedDb(dbPath: string): void {
  const db = new Database(dbPath);
  db.exec(`CREATE TABLE memory_entries (
    id TEXT PRIMARY KEY, key TEXT, namespace TEXT DEFAULT 'default',
    content TEXT, embedding TEXT, status TEXT DEFAULT 'active'
  )`);
  db.exec(`CREATE TABLE episodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, session_id TEXT NOT NULL,
    task TEXT NOT NULL, input TEXT, output TEXT, critique TEXT, reward REAL DEFAULT 0,
    success BOOLEAN DEFAULT 0, latency_ms INTEGER, tokens_used INTEGER, tags TEXT,
    metadata JSON, created_at INTEGER DEFAULT 0
  )`);
  db.exec(`CREATE TABLE reasoning_patterns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, task_type TEXT NOT NULL,
    approach TEXT NOT NULL, success_rate REAL NOT NULL DEFAULT 0, uses INTEGER DEFAULT 0,
    avg_reward REAL DEFAULT 0, tags TEXT, metadata TEXT
  )`);
  db.exec(`CREATE TABLE pattern_embeddings (
    pattern_id INTEGER PRIMARY KEY, embedding BLOB NOT NULL
  )`);
  db.exec(`CREATE TABLE causal_edges (
    id INTEGER PRIMARY KEY AUTOINCREMENT, from_memory_id INTEGER NOT NULL, from_memory_type TEXT NOT NULL,
    to_memory_id INTEGER NOT NULL, to_memory_type TEXT NOT NULL, similarity REAL DEFAULT 0,
    confidence REAL DEFAULT 0.5, mechanism TEXT, metadata JSON, created_at INTEGER DEFAULT 0
  )`);

  const ins = db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)');
  const vec = (seed: number) => JSON.stringify(Array.from({ length: 8 }, (_, i) => Math.sin(seed + i)));
  ins.run('c1', 'k1', 'commands', 'refactor the auth module in src/auth.ts', vec(1));
  ins.run('c2', 'k2', 'commands', 'add validation to src/api/handler.ts', vec(2));
  ins.run('c3', 'k3', 'commands', 'optimize the query in src/db/store.ts', vec(3));
  ins.run('f1', 'k4', 'feedback', JSON.stringify({ taskId: 'edit-a', success: true }), vec(4));
  ins.run('f2', 'k5', 'feedback', JSON.stringify({ taskId: 'edit-b', success: false }), vec(5));
  db.close();
}

function countReasoningPatterns(dbPath: string): number {
  const db = new Database(dbPath, { readonly: true });
  const c = (db.prepare('SELECT COUNT(*) AS c FROM reasoning_patterns').get() as { c: number }).c;
  db.close();
  return c;
}

function makeCtx(flags: Record<string, unknown>, cwd: string): CommandContext {
  return { args: [], flags: { _: [], ...flags }, cwd, interactive: false } as CommandContext;
}

function sub(name: string): Command {
  const cmd = distillCommand.subcommands?.find((c) => c.name === name);
  if (!cmd?.action) throw new Error(`memory distill ${name} has no action`);
  return cmd;
}

describe.skipIf(!haveNative)('memory distill CLI (ADR-174 Milestone 2)', () => {
  let workdir: string;
  beforeAll(() => { workdir = mkdtempSync(join(tmpdir(), 'distill-cli-')); });

  it('registers run, status, and config as subcommands of `memory distill`', () => {
    const names = (distillCommand.subcommands ?? []).map((c) => c.name);
    expect(names).toEqual(expect.arrayContaining(['run', 'status', 'config']));
  });

  it('--dry-run makes no writes', async () => {
    const dbPath = join(workdir, 'dry.db');
    seedDb(dbPath);

    const result = await sub('run').action!(makeCtx({ dryRun: true, db: dbPath }, workdir));

    expect(result?.success).toBe(true);
    const data = result?.data as any;
    expect(data.report.patterns).toBeGreaterThan(0);
    expect(data.report.dryRun).toBe(true);
    expect(countReasoningPatterns(dbPath)).toBe(0); // no writes actually landed
  });

  it('--namespace scopes the run to the requested namespace(s)', async () => {
    const dbPath = join(workdir, 'ns.db');
    seedDb(dbPath);

    const result = await sub('run').action!(makeCtx({ namespace: 'feedback', db: dbPath }, workdir));

    expect(result?.success).toBe(true);
    const data = result?.data as any;
    expect(data.config.namespaces).toEqual(['feedback']);
    expect(data.report.processed).toBe(2); // only the 2 feedback rows
    expect(data.report.byProvenance['proxy:structural']).toBeUndefined();
  });

  it('--judge fable without --budget-usd fails fast (ADR-172 gate)', async () => {
    const dbPath = join(workdir, 'fable.db');
    seedDb(dbPath);

    const result = await sub('run').action!(makeCtx({ judge: 'fable', db: dbPath }, workdir));

    expect(result?.success).toBe(false);
    expect(result?.exitCode).toBe(1);
    expect(countReasoningPatterns(dbPath)).toBe(0); // refused before calling the service
  });

  it('--judge fable with --budget-usd > 0 passes the gate (service still reserves the tier)', async () => {
    const dbPath = join(workdir, 'fable-funded.db');
    seedDb(dbPath);

    const result = await sub('run').action!(makeCtx({ judge: 'fable', budgetUsd: 2, db: dbPath }, workdir));

    expect(result?.success).toBe(true);
    const data = result?.data as any;
    // The M1 service reserves judge:fable (ADR-172, not enabled here) — CLI must
    // surface that as a skip, not silently fall back to structural.
    expect(data.report.skipped).toContain('judge:fable');
  });

  it('--aggressive preset maps to dedup-distance 0.3 / batch-size 500', () => {
    const resolved = resolveDistillConfig(makeCtx({ aggressive: true }, workdir));
    expect(resolved.ok).toBe(true);
    if (resolved.ok) {
      expect(resolved.config.dedupDistance).toBe(0.3);
      expect(resolved.config.batchSize).toBe(500);
    }
  });

  it('--conservative preset maps to dedup-distance 0.1 / batch-size 100', () => {
    const resolved = resolveDistillConfig(makeCtx({ conservative: true }, workdir));
    expect(resolved.ok).toBe(true);
    if (resolved.ok) {
      expect(resolved.config.dedupDistance).toBe(0.1);
      expect(resolved.config.batchSize).toBe(100);
    }
  });

  it('rejects --aggressive and --conservative together', () => {
    const resolved = resolveDistillConfig(makeCtx({ aggressive: true, conservative: true }, workdir));
    expect(resolved.ok).toBe(false);
  });

  it('explicit --batch-size overrides the --aggressive preset', () => {
    const resolved = resolveDistillConfig(makeCtx({ aggressive: true, batchSize: 42 }, workdir));
    expect(resolved.ok).toBe(true);
    if (resolved.ok) {
      expect(resolved.config.batchSize).toBe(42);
      expect(resolved.config.dedupDistance).toBe(0.3); // untouched preset value
    }
  });

  it('`config` prints the effective merged config as JSON-serializable data', async () => {
    const result = await sub('config').action!(makeCtx({ aggressive: true, db: '/tmp/nonexistent.db' }, workdir));
    expect(result?.success).toBe(true);
    const data = result?.data as any;
    expect(data.dedupDistance).toBe(0.3);
    expect(data.batchSize).toBe(500);
    expect(data.dbPath).toBe('/tmp/nonexistent.db');
  });

  it('`status` reports table counts, cursor, and the promote-gate breakdown after a run', async () => {
    const dbPath = join(workdir, 'status.db');
    seedDb(dbPath);

    const runResult = await sub('run').action!(makeCtx({ db: dbPath }, workdir));
    expect(runResult?.success).toBe(true);

    const statusResult = await sub('status').action!(makeCtx({ db: dbPath }, workdir));
    expect(statusResult?.success).toBe(true);
    const data = statusResult?.data as any;

    expect(data.available).toBe(true);
    expect(data.counts.reasoning_patterns).toBeGreaterThan(0);
    expect(data.counts.episodes).toBeGreaterThan(0);
    expect(data.counts.pattern_embeddings).toBeGreaterThan(0);
    expect(data.promoted).toBeGreaterThan(0); // feedback rows promote (ADR-171)
    expect(data.proxy).toBeGreaterThan(0); // commands rows never promote
    expect(data.cursors.length).toBeGreaterThan(0);
  });

  it('`status` degrades gracefully when no DB exists at the path', async () => {
    const result = await sub('status').action!(makeCtx({ db: join(workdir, 'does-not-exist.db') }, workdir));
    expect(result?.success).toBe(true);
    const data = result?.data as any;
    expect(data.available).toBe(false);
    expect(data.reason).toBe('no-db');
  });
});

/**
 * ADR-174 memory distillation service.
 *
 * Proves the DISTILL/CONSOLIDATE pipeline turns raw `memory_entries` into the
 * structured intelligence tables (episodes / reasoning_patterns /
 * pattern_embeddings / causal_edges) that were empty because the daemon's
 * consolidate worker was a stub — while never mutating the source rows, staying
 * idempotent, and enforcing ADR-171 provenance discipline (proxy never promotes).
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { runDistillation } from '../src/services/memory-distillation.js';

let Database: any;
let haveNative = false;
try { Database = (await import('better-sqlite3')).default; haveNative = true; } catch { haveNative = false; }

/** Build a DB with the source + agentdb target schemas and some seeded memory. */
function seedDb(dbPath: string): void {
  const db = new Database(dbPath);
  db.exec(`CREATE TABLE memory_entries (
    id TEXT PRIMARY KEY, key TEXT, namespace TEXT DEFAULT 'default',
    content TEXT, embedding TEXT, status TEXT DEFAULT 'active'
  )`);
  db.exec(`CREATE TABLE episodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, session_id TEXT NOT NULL,
    task TEXT NOT NULL, input TEXT, output TEXT, critique TEXT, reward REAL DEFAULT 0,
    success BOOLEAN DEFAULT 0, latency_ms INTEGER, tokens_used INTEGER, tags TEXT,
    metadata JSON, created_at INTEGER DEFAULT 0
  )`);
  db.exec(`CREATE TABLE episode_embeddings (
    episode_id INTEGER PRIMARY KEY, embedding BLOB NOT NULL,
    embedding_model TEXT DEFAULT 'all-MiniLM-L6-v2',
    FOREIGN KEY(episode_id) REFERENCES episodes(id) ON DELETE CASCADE
  )`);
  db.exec(`CREATE TABLE reasoning_patterns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, task_type TEXT NOT NULL,
    approach TEXT NOT NULL, success_rate REAL NOT NULL DEFAULT 0, uses INTEGER DEFAULT 0,
    avg_reward REAL DEFAULT 0, tags TEXT, metadata TEXT
  )`);
  db.exec(`CREATE TABLE pattern_embeddings (
    pattern_id INTEGER PRIMARY KEY, embedding BLOB NOT NULL
  )`);
  db.exec(`CREATE TABLE causal_edges (
    id INTEGER PRIMARY KEY AUTOINCREMENT, from_memory_id INTEGER NOT NULL, from_memory_type TEXT NOT NULL,
    to_memory_id INTEGER NOT NULL, to_memory_type TEXT NOT NULL, similarity REAL DEFAULT 0,
    confidence REAL DEFAULT 0.5, mechanism TEXT, metadata JSON, created_at INTEGER DEFAULT 0
  )`);

  const ins = db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)');
  // Distinct vectors so clustering keeps them separate.
  const vec = (seed: number) => JSON.stringify(Array.from({ length: 8 }, (_, i) => Math.sin(seed + i)));
  // 3 'commands' (proxy tier), 2 'feedback' (execution tier, one success one fail).
  ins.run('c1', 'k1', 'commands', 'refactor the auth module in src/auth.ts', vec(1));
  ins.run('c2', 'k2', 'commands', 'add validation to src/api/handler.ts', vec(2));
  ins.run('c3', 'k3', 'commands', 'optimize the query in src/db/store.ts', vec(3));
  ins.run('f1', 'k4', 'feedback', JSON.stringify({ taskId: 'edit-a', success: true }), vec(4));
  ins.run('f2', 'k5', 'feedback', JSON.stringify({ taskId: 'edit-b', success: false }), vec(5));
  db.close();
}

function counts(dbPath: string): Record<string, number> {
  const db = new Database(dbPath, { readonly: true });
  const q = (t: string) => (db.prepare(`SELECT COUNT(*) AS c FROM ${t}`).get() as { c: number }).c;
  const r = {
    memory_entries: q('memory_entries'), episodes: q('episodes'),
    episode_embeddings: q('episode_embeddings'),
    reasoning_patterns: q('reasoning_patterns'), pattern_embeddings: q('pattern_embeddings'),
    causal_edges: q('causal_edges'),
  };
  db.close();
  return r;
}

describe.skipIf(!haveNative)('runDistillation — memory → structured intelligence', () => {
  let workdir: string;
  beforeAll(() => { workdir = mkdtempSync(join(tmpdir(), 'distill-')); });

  it('populates the empty target tables without mutating memory_entries', async () => {
    const dbPath = join(workdir, 'main.db');
    seedDb(dbPath);
    const before = counts(dbPath);
    expect(before.reasoning_patterns).toBe(0);

    const r = await runDistillation({ dbPath });
    expect(r.skipped).toBeUndefined();
    expect(r.processed).toBe(5);
    expect(r.patterns).toBeGreaterThan(0);
    expect(r.episodes).toBeGreaterThan(0);

    const after = counts(dbPath);
    expect(after.memory_entries).toBe(before.memory_entries); // source untouched
    expect(after.reasoning_patterns).toBeGreaterThan(0);
    expect(after.episodes).toBeGreaterThan(0);
    // ReflexionMemory uses an INNER JOIN, so episode coverage must be 1:1.
    expect(after.episode_embeddings).toBe(after.episodes);
    expect(r.episodeEmbeddings).toBe(r.episodes);
    // Every pattern with a source embedding gets a pattern_embedding.
    expect(after.pattern_embeddings).toBe(after.reasoning_patterns);

    const check = new Database(dbPath, { readonly: true });
    const feedbackWithCritique = (check.prepare(
      "SELECT COUNT(*) AS c FROM episodes WHERE session_id='distill:feedback' AND length(trim(coalesce(critique,''))) > 0",
    ).get() as { c: number }).c;
    expect(feedbackWithCritique).toBeGreaterThan(0);
    check.close();
  });

  it('enforces ADR-171 provenance: feedback promotes, proxy never does', async () => {
    const dbPath = join(workdir, 'prov.db');
    seedDb(dbPath);
    const r = await runDistillation({ dbPath });
    expect(r.byProvenance['proxy:structural']).toBeGreaterThan(0);
    expect(r.byProvenance['oracle:test-exec']).toBeGreaterThan(0);

    const db = new Database(dbPath, { readonly: true });
    const proxyPromoted = (db.prepare(
      "SELECT COUNT(*) AS c FROM reasoning_patterns WHERE json_extract(metadata,'$.provenance')='proxy:structural' AND json_extract(metadata,'$.promoted')=1",
    ).get() as { c: number }).c;
    expect(proxyPromoted).toBe(0); // proxy tier NEVER clears the promote gate
    db.close();
  });

  it('dry-run reports counts but writes nothing', async () => {
    const dbPath = join(workdir, 'dry.db');
    seedDb(dbPath);
    const r = await runDistillation({ dbPath, dryRun: true });
    expect(r.patterns).toBeGreaterThan(0);
    expect(counts(dbPath).reasoning_patterns).toBe(0); // no writes
  });

  it('is incremental/idempotent — a second run processes nothing new', async () => {
    const dbPath = join(workdir, 'idem.db');
    seedDb(dbPath);
    await runDistillation({ dbPath });
    const mid = counts(dbPath);
    const second = await runDistillation({ dbPath });
    expect(second.processed).toBe(0);
    expect(counts(dbPath).reasoning_patterns).toBe(mid.reasoning_patterns); // no duplicates
  });

  it('scopes to a namespace when asked', async () => {
    const dbPath = join(workdir, 'ns.db');
    seedDb(dbPath);
    const r = await runDistillation({ dbPath, namespaces: ['feedback'] });
    expect(r.processed).toBe(2); // only the 2 feedback rows
    expect(r.byProvenance['proxy:structural']).toBeUndefined();
  });

  it('migrates an older episodes-only store and makes distilled episodes retrievable', async () => {
    const dbPath = join(workdir, 'legacy-reflexion.db');
    seedDb(dbPath);
    const before = new Database(dbPath);
    before.prepare(
      'INSERT INTO episodes (session_id, task, input, metadata) VALUES (?,?,?,?)',
    ).run(
      'distill:feedback',
      'legacy unembedded episode',
      JSON.stringify({ taskId: 'legacy', success: false, error: 'old failure' }),
      JSON.stringify({ sourceIds: ['f2'], provenance: 'oracle:test-exec' }),
    );
    before.exec('DROP TABLE episode_embeddings');
    before.close();

    const r = await runDistillation({ dbPath });
    // Five new episodes plus the pre-existing legacy row are embedded.
    expect(r.episodeEmbeddings).toBeGreaterThan(r.episodes);

    const after = new Database(dbPath, { readonly: true });
    const coverage = after.prepare(`
      SELECT
        (SELECT COUNT(*) FROM episodes) AS episodes,
        (SELECT COUNT(*) FROM episode_embeddings) AS embeddings,
        (SELECT COUNT(*) FROM episodes e
          JOIN episode_embeddings ee ON ee.episode_id = e.id) AS retrievable
    `).get() as { episodes: number; embeddings: number; retrievable: number };
    expect(coverage.embeddings).toBe(coverage.episodes);
    expect(coverage.retrievable).toBe(coverage.episodes);
    const missingCritique = (after.prepare(
      "SELECT COUNT(*) AS c FROM episodes WHERE session_id LIKE 'distill:feedback%' AND length(trim(coalesce(critique,'')))=0",
    ).get() as { c: number }).c;
    expect(missingCritique).toBe(0);
    after.close();
  });

  it('skips (does not throw) when target tables are absent', async () => {
    const dbPath = join(workdir, 'bare.db');
    const db = new Database(dbPath);
    db.exec("CREATE TABLE memory_entries (id TEXT PRIMARY KEY, namespace TEXT, content TEXT, embedding TEXT)");
    db.close();
    const r = await runDistillation({ dbPath });
    expect(r.skipped).toBeTruthy();
    expect(r.patterns).toBe(0);
  });

  // ── ADR-174 operational invariant: embedding coverage is EXACTLY 1:1 ──
  it('every pattern has exactly one embedding, even when a source vector is malformed', async () => {
    const dbPath = join(workdir, 'embcov.db');
    seedDb(dbPath);
    // Add a row whose embedding column is non-null but unparseable — the old
    // code would create a pattern with no embedding (coverage gap).
    const db = new Database(dbPath);
    db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)')
      .run('bad1', 'kb', 'commands', 'refactor thing in src/x.ts', 'NOT VALID JSON');
    db.close();

    const r = await runDistillation({ dbPath });
    expect(r.patterns).toBeGreaterThan(0);
    expect(r.patternEmbeddings).toBe(r.patterns); // report-level 1:1

    // SQL invariant: zero patterns without an embedding.
    const check = new Database(dbPath, { readonly: true });
    const gap = (check.prepare(
      'SELECT COUNT(*) AS c FROM reasoning_patterns rp LEFT JOIN pattern_embeddings pe ON pe.pattern_id = rp.id WHERE pe.pattern_id IS NULL',
    ).get() as { c: number }).c;
    expect(gap).toBe(0);
    check.close();
  });

  // ── ADR-174 edge contract: edges are WEAK co-occurrence, never causal proof ──
  it('relational edges are typed cooccurrence / proxy-tier / non-promoted', async () => {
    const dbPath = join(workdir, 'edges.db');
    seedDb(dbPath);
    await runDistillation({ dbPath });

    const db = new Database(dbPath, { readonly: true });
    const edges = db.prepare('SELECT mechanism, confidence, metadata FROM causal_edges').all() as Array<{ mechanism: string; confidence: number; metadata: string }>;
    expect(edges.length).toBeGreaterThan(0);
    for (const e of edges) {
      expect(e.mechanism).toBe('co-occurrence');
      expect(e.confidence).toBeLessThan(0.5); // weak, never asserted as proof
      const m = JSON.parse(e.metadata);
      expect(m.edge_type).toBe('cooccurrence');
      expect(m.provenance_tier).toBe('proxy:structural');
      expect(m.promoted).toBe(false); // may rank retrieval, must NOT justify autonomous action
    }
    // No proxy edge is ever promoted.
    const promotedProxyEdges = edges.filter(e => JSON.parse(e.metadata).promoted === true).length;
    expect(promotedProxyEdges).toBe(0);
    db.close();
  });
});

/**
 * Data-durability regression tests for issue #2584 — AgentDB (sql.js) corruption
 * under torn/concurrent full-image flushes.
 *
 * Covers:
 *   1. writeFileAtomic() — the temp→fsync→rename primitive that makes every
 *      full-image DB flush crash-safe (no torn image, no leftover temp).
 *   2. restoreMemoryDbFromBackup() + recoverMemoryDatabase() — the missing
 *      recovery half: when the live image is torn badly enough that an in-place
 *      rebuild salvages nothing (the exact ruvultra failure mode), recovery must
 *      fall back to the newest integrity-ok backup instead of erroring forever.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { writeFileAtomic } from '../src/fs-secure.js';
import { backupMemoryDb, restoreMemoryDbFromBackup } from '../src/services/memory-backup.js';
import { recoverMemoryDatabase } from '../src/memory/memory-initializer.js';

async function loadSqlite(): Promise<any | null> {
  try { const mod = 'better-sqlite3'; return (await import(mod)).default; } catch { return null; }
}

function makeMemoryDb(Database: any, file: string, rows: number): void {
  const db = new Database(file);
  db.exec('CREATE TABLE memory_entries (id TEXT PRIMARY KEY, namespace TEXT, value TEXT, embedding BLOB)');
  const ins = db.prepare('INSERT INTO memory_entries (id, namespace, value) VALUES (?,?,?)');
  const tx = db.transaction((n: number) => { for (let i = 0; i < n; i++) ins.run('k' + i, 'default', 'v' + i); });
  tx(rows);
  db.close();
}

let tmp: string;
beforeEach(() => { tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'agentdb-2584-')); });
afterEach(() => { try { fs.rmSync(tmp, { recursive: true, force: true }); } catch { /* */ } });

describe('writeFileAtomic (#2584)', () => {
  it('writes content and leaves no temp file behind', () => {
    const p = path.join(tmp, 'a.bin');
    writeFileAtomic(p, Buffer.from('hello'));
    expect(fs.readFileSync(p, 'utf8')).toBe('hello');
    expect(fs.readdirSync(tmp).filter(f => f.includes('.tmp-'))).toHaveLength(0);
  });

  it('overwrites atomically — the new image fully replaces the old', () => {
    const p = path.join(tmp, 'a.bin');
    writeFileAtomic(p, Buffer.alloc(4096, 1));
    writeFileAtomic(p, Buffer.from('x'));
    expect(fs.statSync(p).size).toBe(1);
    expect(fs.readFileSync(p, 'utf8')).toBe('x');
  });

  it('cleans up the temp file if the write throws (bad target dir)', () => {
    // Writing into a non-existent directory throws; no temp should survive.
    const bad = path.join(tmp, 'does-not-exist', 'a.bin');
    expect(() => writeFileAtomic(bad, Buffer.from('x'))).toThrow();
    expect(fs.readdirSync(tmp)).not.toContain('does-not-exist');
  });
});

describe('backup auto-restore fallback (#2584)', () => {
  it('recoverMemoryDatabase restores the newest good backup when the live image is torn', async () => {
    const Database = await loadSqlite();
    if (!Database) return; // native recovery dep absent — nothing to exercise

    const dbPath = path.join(tmp, '.swarm', 'memory.db');
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    makeMemoryDb(Database, dbPath, 25);

    // A real, consistent backup via the shipped backup service.
    const bk = await backupMemoryDb({ dbPath, timestamp: 1000 });
    expect(bk.backedUp).toBe(true);

    // Tear the live image: overwrite the header + first pages with 0xFF so
    // integrity_check fails and an in-place rebuild salvages nothing — i.e. the
    // ruvultra case where `sqlite3 .recover` produced 0 rows.
    const size = fs.statSync(dbPath).size;
    const n = Math.min(size, 16384);
    const fd = fs.openSync(dbPath, 'r+');
    fs.writeSync(fd, Buffer.alloc(n, 0xff), 0, n, 0);
    fs.closeSync(fd);

    const rec = await recoverMemoryDatabase(dbPath, { verbose: false });
    expect(rec.recovered).toBe(true);
    expect(rec.restoredFromBackup).toBe(true);

    // The restored DB is healthy and has the data back.
    const db = new Database(dbPath, { readonly: true });
    const integ = String(db.pragma('integrity_check', { simple: true }));
    const count = (db.prepare('SELECT COUNT(*) AS c FROM memory_entries').get() as { c: number }).c;
    db.close();
    expect(integ.toLowerCase()).toBe('ok');
    expect(count).toBe(25);

    // The corrupt original was parked, not silently discarded.
    const parked = fs.readdirSync(path.dirname(dbPath)).some(f => f.startsWith('memory.db.corrupt-'));
    expect(parked).toBe(true);
  });

  it('restoreMemoryDbFromBackup reports no-backups when the dir is empty', async () => {
    const Database = await loadSqlite();
    if (!Database) return;
    const dbPath = path.join(tmp, '.swarm', 'memory.db');
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    makeMemoryDb(Database, dbPath, 3);
    const r = await restoreMemoryDbFromBackup(dbPath);
    expect(r.restored).toBe(false);
    expect(r.skipped).toMatch(/no-backups/);
  });

  it('restoreMemoryDbFromBackup skips a corrupt backup and picks an older good one', async () => {
    const Database = await loadSqlite();
    if (!Database) return;
    const dbPath = path.join(tmp, '.swarm', 'memory.db');
    const backups = path.join(tmp, '.swarm', 'backups');
    fs.mkdirSync(backups, { recursive: true });
    makeMemoryDb(Database, dbPath, 10);

    // Older good backup, newer torn backup — restore must pick the older good one.
    const good = path.join(backups, 'memory-2020-01-01T00-00-00-000Z.db');
    const bad = path.join(backups, 'memory-2020-01-02T00-00-00-000Z.db');
    makeMemoryDb(Database, good, 10);
    makeMemoryDb(Database, bad, 10);
    const fd = fs.openSync(bad, 'r+'); fs.writeSync(fd, Buffer.alloc(16384, 0xff), 0, 16384, 0); fs.closeSync(fd);

    const r = await restoreMemoryDbFromBackup(dbPath, { timestamp: 2000 });
    expect(r.restored).toBe(true);
    expect(r.from).toBe(good);
    expect(r.rows).toBe(10);
  });
});

