          { path: 'src/a.ts', lineCoverage: 95, branchCoverage: 90, functionCoverage: 95, statementCoverage: 95, uncoveredLines: [], totalLines: 100, coveredLines: 95 },
        ],
        lowestCoverage: [],
        highestCoverage: [],
        uncoveredCritical: [],
