// #2558 regression: `memory search` recall was broken in v3.19.0/3.20.0 —
// confirmed-stored entries were not recalled by keyword OR semantic search,
// while store/list/retrieve/delete worked, and the HNSW index reported 0
// vectors. Root cause was in the AgentDB bridge search path
// (`bridgeSearchEntries`): it fused
//   0.7 * cosine + 0.3 * (BM25 / 10)
// and BM25's IDF collapses toward zero when a term appears in most/all
// documents (routine on small memory corpora), so an exact-keyword hit scored
// well below the default 0.3 threshold and was dropped. Separately,
// better-sqlite3's WAL was never checkpointed and `vector_indexes.total_vectors`
// was never updated, so WAL-blind readers reported "HNSW index: 0 vectors".
//
// This is an end-to-end guard: it drives the built CLI in a throwaway cwd
// exactly like the bug report (store → list → search), because the AgentDB
// bridge (better-sqlite3 + embedder) is the path that regressed and it only
// activates in a real CLI process, not under the vitest transform.
//
// The test is skipped when the CLI has not been built (`bin/cli.js` absent).
// The documented flow is `npm run build && npm test`, so the guard is active
// in the standard dev/release pipeline.

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const CLI = path.resolve(HERE, '..', 'bin', 'cli.js');
const CLI_BUILT = fs.existsSync(CLI);

const NS = 'recall2558';
const ENTRIES = [
  { key: 'note/alpha', value: 'ruflo memory connectivity health probe alpha', unique: 'probe' },
  { key: 'note/beta', value: 'ruflo memory connectivity latency check beta', unique: 'latency' },
  { key: 'note/gamma', value: 'ruflo memory connectivity throughput report gamma', unique: 'throughput' },
];

let cwd = '';

function cli(args: string[]): string {
  return execFileSync('node', [CLI, ...args], {
    cwd,
    encoding: 'utf8',
    timeout: 90_000,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

// The CLI prints a human `[INFO] …` line before the JSON body; slice from the
// first `{` so we parse only the JSON document.
function searchJson(query: string): { results: Array<{ key: string; score: number }> } {
  const out = cli(['memory', 'search', '--query', query, '-n', NS, '--format', 'json']);
  const start = out.indexOf('{');
  expect(start).toBeGreaterThanOrEqual(0);
  return JSON.parse(out.slice(start));
}

describe.skipIf(!CLI_BUILT)('memory search recall (#2558, end-to-end)', () => {
  beforeAll(() => {
    cwd = fs.mkdtempSync(path.join(os.tmpdir(), 'cf-2558-'));
    cli(['memory', 'init']);
    for (const e of ENTRIES) {
      cli(['memory', 'store', '-k', e.key, '-n', NS, '--value', e.value]);
    }
  }, 180_000);

  afterAll(() => {
    if (cwd) {
      try { fs.rmSync(cwd, { recursive: true, force: true }); } catch { /* ignore */ }
    }
  });

  it('list shows all stored entries (CRUD path is unaffected)', () => {
    const out = cli(['memory', 'list', '-n', NS]);
    for (const e of ENTRIES) expect(out).toContain(e.key);
  });

  it('recalls EVERY stored entry by a shared keyword (the core regression)', () => {
    // Pre-fix this returned zero results at the default 0.3 threshold.
    const r = searchJson('connectivity');
    const keys = r.results.map((x) => x.key);
    for (const e of ENTRIES) expect(keys).toContain(e.key);
  });

  it('discriminates by a unique keyword (recall is targeted, not a blanket dump)', () => {
    const r = searchJson('throughput');
    const keys = r.results.map((x) => x.key);
    expect(keys).toContain('note/gamma');
    // Entries that never mention "throughput" must NOT be pulled in — otherwise
    // "recall" would be meaningless.
    expect(keys).not.toContain('note/alpha');
    expect(keys).not.toContain('note/beta');
  });

  it('reports N vectors, not 0, and is visible to WAL-blind readers', async () => {
    // The bridge writes via better-sqlite3 in WAL mode. sql.js does NOT apply
    // the -wal file, so reading the main DB file only sees rows that were
    // checkpointed into it — exactly the "0 vectors" failure mode. The
    // store-side WAL checkpoint (#2558) makes committed rows visible here.
    const dbPath = path.join(cwd, '.swarm', 'memory.db');
    expect(fs.existsSync(dbPath)).toBe(true);

    const initSqlJs = (await import('sql.js')).default;
    const SQL = await initSqlJs();
    const db = new SQL.Database(fs.readFileSync(dbPath));

    const rowCount = Number(
      db.exec(`SELECT COUNT(*) FROM memory_entries WHERE namespace = '${NS}'`)[0]
        ?.values?.[0]?.[0] ?? 0,
    );
    expect(rowCount).toBe(ENTRIES.length);

    const embedded = Number(
      db.exec(
        `SELECT COUNT(*) FROM memory_entries WHERE namespace = '${NS}' AND embedding IS NOT NULL`,
      )[0]?.values?.[0]?.[0] ?? 0,
    );

    // When the embedder produced vectors (the default), the surfaced vector
    // count must reflect them rather than staying pinned at 0.
    if (embedded > 0) {
      expect(embedded).toBe(ENTRIES.length);
      const totalVectors = db.exec(
        `SELECT total_vectors FROM vector_indexes WHERE name = '${NS}'`,
      )[0]?.values?.[0]?.[0];
      if (totalVectors !== undefined) {
        expect(Number(totalVectors)).toBe(ENTRIES.length);
      }
    }

    db.close();
  }, 30_000);
});

/**
 * Regression for #2982 / #2976 (duplicate reports, same root cause):
 * `bridgeSearchEntries()`'s pre-rank SELECT truncated the corpus to
 * `LIMIT 1000` with no `ORDER BY`, so SQLite returned rows in arbitrary
 * storage order — for a freshly-inserted rowid table with no deletes,
 * that's insertion order. On any corpus over 1000 rows, the newest entries
 * never reached BM25/embedding scoring at all, no matter how well they
 * matched the query. `bridgeListEntries()` already ordered by
 * `updated_at DESC` for the same reason; this pins the search path to the
 * same guarantee.
 *
 * All SQL executes against a real better-sqlite3 fixture (mocked
 * ControllerRegistry only), matching the #2652 test's harness pattern, so
 * this exercises the production bridge query, not a stand-in.
 */
import { afterAll, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const root = mkdtempSync(join(tmpdir(), 'ruflo-2982-truncation-'));
const dbPath = join(root, 'memory.db');
const ROW_COUNT = 1005;
const NEEDLE = 'zzzneedle2982';

let db: Database.Database | null = null;

function seedRows(): void {
  db = new Database(dbPath);
  db.exec(`
    CREATE TABLE memory_entries (
      id TEXT PRIMARY KEY,
      key TEXT NOT NULL,
      namespace TEXT DEFAULT 'default',
      content TEXT NOT NULL,
      type TEXT DEFAULT 'semantic',
      embedding TEXT,
      embedding_model TEXT DEFAULT 'local',
      embedding_dimensions INTEGER,
      tags TEXT,
      metadata TEXT,
      owner_id TEXT,
      created_at INTEGER,
      updated_at INTEGER,
      expires_at INTEGER,
      last_accessed_at INTEGER,
      access_count INTEGER DEFAULT 0,
      status TEXT,
      provenance_type TEXT DEFAULT 'unknown',
      UNIQUE(namespace, key)
    );
  `);
  const insert = db.prepare(`
    INSERT INTO memory_entries (id, key, namespace, content, created_at, updated_at, status)
    VALUES (?, ?, 'fixture', ?, ?, ?, 'active')
  `);
  const insertMany = db.transaction((n: number) => {
    for (let i = 1; i <= n; i++) {
      // updated_at increases monotonically with insertion order — row n is
      // both the last-inserted (storage-order-last) AND the newest by
      // timestamp, so ORDER BY updated_at DESC is what recovers it.
      const isNeedle = i === n;
      insert.run(
        `row-${i}`,
        `key/${i}`,
        isNeedle ? `entry number ${i} contains ${NEEDLE} as a unique marker` : `filler entry number ${i}`,
        i,
        i,
      );
    }
  });
  insertMany(ROW_COUNT);
  db.close();
}

seedRows();

afterAll(() => {
  db?.close();
  rmSync(root, { recursive: true, force: true });
});

describe('#2982/#2976 search truncation', () => {
  it('recalls the newest entry even when the corpus exceeds the 1000-row pre-rank LIMIT', async () => {
    const { __setMemoryBridgeRegistryForTests, bridgeSearchEntries } = await import(
      '../src/memory/memory-bridge.js'
    );

    db = new Database(dbPath);
    __setMemoryBridgeRegistryForTests({
      getAgentDB: () => ({ database: db, embedder: null }),
      get: () => null,
    });

    const result = await bridgeSearchEntries({
      query: NEEDLE,
      namespace: 'fixture',
      limit: 10,
      threshold: 0.1,
      dbPath,
    });

    expect(result).not.toBeNull();
    expect(result!.success).toBe(true);
    const keys = result!.results.map((r) => r.key);
    // Pre-fix: an unordered `LIMIT 1000` returns rows in insertion order on
    // this fixture, i.e. rows 1..1000 — row 1005 (the needle) is excluded
    // from the pre-rank set entirely and can never be scored or returned,
    // regardless of threshold. Post-fix: ORDER BY updated_at DESC recovers
    // the newest 1000 rows (6..1005), which includes it.
    expect(keys).toContain(`key/${ROW_COUNT}`);
  });
});

// #2246 fix: memory_search_unified namespace fan-out — verify the resolved
// namespace list correctly comes from each priority source:
//   1. param `namespace` (single)
//   2. param `namespaces` (array)
//   3. env CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES
//   4. dynamic enumeration via listEntries
//   5. legacy 6-namespace fallback
//
// The bug was step 4 collapsing to step 5, silently missing ~95% of an
// 8,789-entry store with custom namespaces.

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { memoryTools } from '../src/mcp-tools/memory-tools.js';

const tool = memoryTools.find((t) => t.name === 'memory_search_unified');

function snapshotEnv() {
  return process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES;
}

function restoreEnv(v: string | undefined) {
  if (v === undefined) delete process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES;
  else process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES = v;
}

describe('memory_search_unified namespace fan-out (#2246)', () => {
  let savedEnv: string | undefined;
  beforeEach(() => { savedEnv = snapshotEnv(); });
  afterEach(() => { restoreEnv(savedEnv); });

  it('exists and accepts the new `namespaces` array parameter', () => {
    expect(tool).toBeDefined();
    const props = (tool!.inputSchema as { properties: Record<string, unknown> }).properties;
    expect(props.namespaces).toBeDefined();
    expect((props.namespaces as { type: string }).type).toBe('array');
  });

  it('with no params, reports `namespaceSource` (not the legacy hardcode silently)', async () => {
    delete process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES;
    const r = await tool!.handler({ query: 'test query for the namespace fan-out' }) as {
      success?: boolean;
      searchedNamespaces?: string[];
      namespaceSource?: string;
      error?: string;
    };
    // We don't assert success — the fixture environment may not have memory
    // initialized. We DO assert that the new namespaceSource field is set
    // so callers can audit which list was used.
    expect(r.namespaceSource).toBeDefined();
    expect(['dynamic', 'legacy-fallback', 'env']).toContain(r.namespaceSource);
  });

  it('with explicit single `namespace`, reports namespaceSource=param-single', async () => {
    const r = await tool!.handler({ query: 'test', namespace: 'patterns' }) as {
      searchedNamespaces?: string[];
      namespaceSource?: string;
    };
    expect(r.searchedNamespaces).toEqual(['patterns']);
    expect(r.namespaceSource).toBe('param-single');
  });

  it('with explicit `namespaces` array, reports namespaceSource=param-list', async () => {
    const r = await tool!.handler({
      query: 'test',
      namespaces: ['brain-system', 'knowledge-graph', 'causal-edges'],
    }) as { searchedNamespaces?: string[]; namespaceSource?: string };
    expect(r.searchedNamespaces).toEqual(['brain-system', 'knowledge-graph', 'causal-edges']);
    expect(r.namespaceSource).toBe('param-list');
  });

  it('with env CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES, reports namespaceSource=env', async () => {
    process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES = 'foo,bar,baz';
    const r = await tool!.handler({ query: 'test' }) as {
      searchedNamespaces?: string[]; namespaceSource?: string;
    };
    expect(r.searchedNamespaces).toEqual(['foo', 'bar', 'baz']);
    expect(r.namespaceSource).toBe('env');
  });

  it('explicit `namespaces` array beats env (priority 2 > priority 3)', async () => {
    process.env.CLAUDE_FLOW_MEMORY_SEARCH_NAMESPACES = 'env-a,env-b';
    const r = await tool!.handler({ query: 'test', namespaces: ['param-only'] }) as {
      searchedNamespaces?: string[]; namespaceSource?: string;
    };
    expect(r.searchedNamespaces).toEqual(['param-only']);
    expect(r.namespaceSource).toBe('param-list');
  });

  it('single `namespace` beats `namespaces` array (priority 1 > priority 2)', async () => {
    const r = await tool!.handler({
      query: 'test',
      namespace: 'wins',
      namespaces: ['loses-a', 'loses-b'],
    }) as { searchedNamespaces?: string[]; namespaceSource?: string };
    expect(r.searchedNamespaces).toEqual(['wins']);
    expect(r.namespaceSource).toBe('param-single');
  });

  it('rejects path-traversal in namespace param (input validation preserved)', async () => {
    const r = await tool!.handler({ query: 'test', namespace: '../etc/passwd' }) as {
      success: boolean; error?: string;
    };
    expect(r.success).toBe(false);
    expect(r.error).toBeTruthy();
  });

  it('rejects path-traversal in any element of namespaces array', async () => {
    const r = await tool!.handler({
      query: 'test',
      namespaces: ['ok', '../etc/passwd'],
    }) as { success: boolean; error?: string };
    expect(r.success).toBe(false);
    expect(r.error).toBeTruthy();
  });
});

/**
 * Regression for #2968: `memory store` printed "Data stored successfully"
 * even when the underlying connection couldn't durably persist the write —
 * specifically the sql.js fallback driver (engaged when better-sqlite3's
 * native binding never got built, e.g. a skipped optionalDependency
 * postinstall), whose `.pragma()` shim rejects `wal_checkpoint(passive)`
 * with "Invalid PRAGMA command". `bridgeStoreEntry()` swallowed that error
 * unconditionally and reported unqualified success either way.
 *
 * This pins the fix: bridgeStoreEntry() now distinguishes that specific
 * failure signature from an ordinary "non-WAL / busy" pragma failure and
 * surfaces it via `persistWarning`, so callers stop claiming success blind.
 */
import { afterAll, describe, expect, it } from 'vitest';
import Database from 'better-sqlite3';
import { mkdtempSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const root = mkdtempSync(join(tmpdir(), 'ruflo-2968-persist-warning-'));
const dbPath = join(root, 'memory.db');

let db: Database.Database | null = null;

function makeDb(): Database.Database {
  const d = new Database(dbPath);
  d.exec(`
    CREATE TABLE IF NOT EXISTS memory_entries (
      id TEXT PRIMARY KEY,
      key TEXT NOT NULL,
      namespace TEXT DEFAULT 'default',
      content TEXT NOT NULL,
      type TEXT DEFAULT 'semantic',
      embedding TEXT,
      embedding_dimensions INTEGER,
      embedding_model TEXT,
      tags TEXT,
      metadata TEXT,
      provenance_type TEXT DEFAULT 'unknown',
      created_at INTEGER,
      updated_at INTEGER,
      expires_at INTEGER,
      status TEXT DEFAULT 'active',
      UNIQUE(namespace, key)
    );
  `);
  return d;
}

afterAll(() => {
  db?.close();
  rmSync(root, { recursive: true, force: true });
});

describe('#2968 store persistence warning', () => {
  it('surfaces persistWarning when the checkpoint throws "Invalid PRAGMA" (sql.js fallback signature)', async () => {
    const { __setMemoryBridgeRegistryForTests, bridgeStoreEntry } = await import(
      '../src/memory/memory-bridge.js'
    );

    db = makeDb();
    // Simulate the sql.js shim's pragma() rejecting an unrecognized command —
    // the exact signature `agentdb`'s sql.js fallback throws in the field
    // report, without needing to stand up a real sql.js-backed registry.
    (db as unknown as { pragma: (cmd: string) => unknown }).pragma = (cmd: string) => {
      throw new Error(
        `Invalid PRAGMA command: ${cmd}. Allowed: journal_mode, synchronous, cache_size, page_size, page_count, user_version, foreign_keys, temp_store, mmap_size, wal_autocheckpoint`,
      );
    };
    __setMemoryBridgeRegistryForTests({
      getAgentDB: () => ({ database: db, embedder: null }),
      get: () => null,
    });

    const result = await bridgeStoreEntry({
      key: 'k1',
      value: 'persistence probe',
      namespace: 'fixture',
      generateEmbeddingFlag: false,
      dbPath,
    });

    expect(result).not.toBeNull();
    expect(result!.success).toBe(true);
    expect(result!.persistWarning).toBeDefined();
    expect(result!.persistWarning).toMatch(/sql\.js fallback driver/i);
    expect(result!.persistWarning).toMatch(/#2968/);
  });

  it('does NOT set persistWarning on an ordinary pragma failure unrelated to the sql.js signature', async () => {
    const { __setMemoryBridgeRegistryForTests, bridgeStoreEntry } = await import(
      '../src/memory/memory-bridge.js'
    );

    const d2 = makeDb();
    (d2 as unknown as { pragma: (cmd: string) => unknown }).pragma = () => {
      throw new Error('database is busy');
    };
    __setMemoryBridgeRegistryForTests({
      getAgentDB: () => ({ database: d2, embedder: null }),
      get: () => null,
    });

    const result = await bridgeStoreEntry({
      key: 'k2',
      value: 'unrelated pragma failure',
      namespace: 'fixture',
      generateEmbeddingFlag: false,
      dbPath,
    });

    expect(result).not.toBeNull();
    expect(result!.success).toBe(true);
    expect(result!.persistWarning).toBeUndefined();
    d2.close();
  });
});

/**
 * Regression guard for issue #2594 — `memory store → memory delete → memory store`
 * on the same (namespace, key) crashed with `UNIQUE constraint failed:
 * memory_entries.namespace, memory_entries.key`.
 *
 * Root cause: `memory delete` is a soft delete (sets status='deleted', row
 * remains), the schema's `UNIQUE(namespace, key)` constraint does NOT exclude
 * deleted rows, and the CLI's `memory store` command previously defaulted
 * `--upsert` to `false` — so the second store issued a plain INSERT that
 * collided with the soft-deleted row.
 *
 * Fix (c36cb4d66): flip the CLI-surface default to `--upsert=true` so
 * store→delete→store just works. Users who want strict insert semantics pass
 * `--no-upsert`.
 *
 * This guard is a pure static assertion on the command definition — it fails
 * the moment someone flips the default back to `false`.
 */
import { describe, it, expect } from 'vitest';
import { memoryCommand } from '../src/commands/memory.js';

describe('memory store --upsert default (#2594)', () => {
  const storeCmd = memoryCommand.subcommands?.find(c => c.name === 'store');
  const upsertOpt = storeCmd?.options?.find(o => o.name === 'upsert');

  it('exposes the `store` subcommand with an `upsert` option', () => {
    expect(storeCmd).toBeDefined();
    expect(upsertOpt).toBeDefined();
    expect(upsertOpt?.type).toBe('boolean');
  });

  it('defaults --upsert to true so store→delete→store does not hit UNIQUE(namespace,key)', () => {
    // If this flips back to `false` (or `undefined`), issue #2594 reopens: any
    // `store → delete → store` on the same (namespace, key) will crash with
    // `UNIQUE constraint failed: memory_entries.namespace, memory_entries.key`
    // because the soft-deleted row still occupies the unique slot.
    expect(upsertOpt?.default).toBe(true);
  });
});

/**
 * Regression coverage for #2815: HNSW vectors are secondary indexes over
 * the authoritative (namespace,key) memory row. Upsert and delete therefore
 * have to invalidate every historical vector for that logical key, including
 * duplicates left by older releases.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

let root: string;
const originalRoot = process.env.CLAUDE_FLOW_MEMORY_PATH;
const originalDisableBridge = process.env.CLAUDE_FLOW_DISABLE_BRIDGE;

beforeEach(() => {
  root = mkdtempSync(path.join(tmpdir(), 'ruflo-memory-2815-'));
