describe('memory vector lifecycle (#2815)', () => {
  it('upsert and delete remove every historical vector for a logical key', async () => {
    const memory = await import('../src/memory/memory-initializer.js');
    const initialized = await memory.initializeMemoryDatabase({
      force: true,
      migrate: false,
    });
    expect(initialized.success).toBe(true);

    const first = await memory.storeEntry({
      key: 'routing-policy',
      namespace: 'patterns',
      value: 'first policy observation',
      upsert: true,
    });
    expect(first.success).toBe(true);

    // Reproduce the stale metadata state created by older versions: several
    // vector IDs resolve to the same logical memory key. The invalidation
    // primitive must remove all of them rather than stopping at the first.
    const vectors = new Map([
      ['current', { id: 'current', key: 'routing-policy', namespace: 'patterns', content: 'current' }],
      ['historical-a', { id: 'historical-a', key: 'routing-policy', namespace: 'patterns', content: 'stale A' }],
      ['historical-b', { id: 'historical-b', key: 'routing-policy', namespace: 'patterns', content: 'stale B' }],
      ['other', { id: 'other', key: 'other-key', namespace: 'patterns', content: 'keep' }],
    ]);
    expect(
      memory.removeHNSWEntriesByLogicalKey(vectors, 'routing-policy', 'patterns'),
    ).toBe(3);
    expect([...vectors.keys()]).toEqual(['other']);

    const replacement = await memory.storeEntry({
      key: 'routing-policy',
      namespace: 'patterns',
      value: 'replacement policy observation',
      upsert: true,
    });
    expect(replacement.success).toBe(true);
    const active = await memory.listEntries({
      namespace: 'patterns',
      includeContent: true,
    });
    expect(active.total).toBe(1);
    expect(active.entries[0]?.content).toBe('replacement policy observation');

    const deleted = await memory.deleteEntry({
      key: 'routing-policy',
      namespace: 'patterns',
    });
    expect(deleted.success).toBe(true);
    expect(deleted.deleted).toBe(true);
    const remaining = await memory.listEntries({ namespace: 'patterns' });
    expect(remaining.total).toBe(0);
  });
});

/**
 * Regression guard for issue #2596 — verifyMemoryInit() must be read-only.
 *
 * Root cause (pre-fix): verifyMemoryInit() ran read/write self-tests on the
 * sql.js in-memory copy, then unconditionally serialized and wrote the buffer
 * back via writeFileRestricted() → atomic rename(tmp, dbPath). initializeMemoryDatabase()
 * activates ControllerRegistry and repairVectorIndexes() (better-sqlite3 in WAL
 * mode), both of which keep native handles open on the same path. On POSIX,
 * rename over an open fd succeeds; on Windows, MoveFileEx onto a path with any
 * open handle in the same process returns EPERM — a Windows-only false negative.
 * The self-test also DELETEs its own inserts before the writeback, so the write
 * was pointless.
 *
 * This guard: initialize a DB via the same initializer, snapshot the on-disk
 * bytes + mtime, call verifyMemoryInit, and assert the file was not touched.
 * Fails on the buggy code (writeback re-serializes → different bytes/mtime);
 * passes on the fix (sql.js in-memory copy discarded on close(), on-disk image
 * untouched).
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { initializeMemoryDatabase, verifyMemoryInit } from '../src/memory/memory-initializer.js';

let tmp: string;

beforeEach(() => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'verify-readonly-2596-'));
});

afterEach(() => {
  try { fs.rmSync(tmp, { recursive: true, force: true }); } catch { /* */ }
});

describe('verifyMemoryInit is read-only (#2596)', () => {
  it('does not modify the on-disk DB file (no writeback race with better-sqlite3 handle)', async () => {
    const dbPath = path.join(tmp, 'memory.db');

    // Bootstrap a real DB the same way production does — this also activates the
    // ControllerRegistry / repairVectorIndexes handles that the writeback used to race.
    const init = await initializeMemoryDatabase({ dbPath, force: true, migrate: false });
    expect(init.success).toBe(true);
    expect(fs.existsSync(dbPath)).toBe(true);

    // Snapshot on-disk state BEFORE verify.
    const before = fs.readFileSync(dbPath);
    const beforeMtime = fs.statSync(dbPath).mtimeMs;

    // Give mtime resolution a chance to advance so any writeback would be visible.
    await new Promise(r => setTimeout(r, 20));

    const result = await verifyMemoryInit(dbPath);
    expect(result).toBeDefined();

    // Assertion: the DB image on disk is byte-identical after verification.
    // On the pre-fix code, sql.js re-serialization + writeFileRestricted(encrypt)
    // rewrote the file with a different byte image AND a bumped mtime — both
    // detectable here regardless of platform (the Windows-only failure was the
    // EPERM crash of the writeback itself; the writeback is the disease).
    const after = fs.readFileSync(dbPath);
    const afterMtime = fs.statSync(dbPath).mtimeMs;

    expect(after.length).toBe(before.length);
    expect(after.equals(before)).toBe(true);
    expect(afterMtime).toBe(beforeMtime);
  }, 60_000);
});

/**
 * Regression guard for #2727 dream-cycle IB+VQ-inspired message
 * compressor (v1 MVP — TF-IDF sparsification with must-preserve span
 * extraction; v2 will land a real VQ codec).
 *
 * Compressor must:
 *   1. Preserve code fences, inline code, URLs, and file paths verbatim.
 *   2. Reduce size when budgetTokens < original tokens.
 *   3. Reassemble kept sentences in original order (not score order).
 *   4. Report accurate stats.
 */

import { describe, it, expect } from 'vitest';
import { compressMessage, estimateTokens } from '../src/swarm/message-compressor.js';

const LONG_MESSAGE = [
  'The authentication module is currently unstable under high concurrency.',
  'When more than 20 concurrent sessions attempt token refresh, the JWT verifier throws.',
  'We think this is a race condition in the token cache eviction path.',
  'The relevant file is src/auth/jwt-verifier.ts and it uses the JWT library from npm.',
  'A code excerpt: ```ts\nconst t = verify(token, PUBLIC_KEY);\n```',
  'You can reproduce by running the load test at https://internal.example.com/loadtest/jwt.',
  'The problem does not appear with fewer than 10 concurrent sessions.',
  'We suspect the LRU cache does not lock on concurrent writes.',
  'One workaround is to switch to a mutex-protected cache implementation.',
  'The impact is that under peak load, roughly 3% of auth requests fail.',
  'Failed requests return a 500 with a generic error message.',
  'Users see a login prompt again which resets their session.',
  'The failure rate is unacceptable for production traffic.',
  'We need to prioritize this fix in the current sprint.',
  'The estimated engineering time is two person-days.',
].join(' ');

describe('#2727 message compressor', () => {
  it('preserves a code fence verbatim in the output', () => {
    const r = compressMessage(LONG_MESSAGE, { budgetTokens: 100 });
    expect(r.compressed).toContain('```ts');
    expect(r.compressed).toContain('verify(token, PUBLIC_KEY)');
    expect(r.stats.preservedSpans).toBeGreaterThan(0);
  });

  it('preserves URLs verbatim', () => {
    const r = compressMessage(LONG_MESSAGE, { budgetTokens: 100 });
    expect(r.compressed).toContain('https://internal.example.com/loadtest/jwt');
  });

  it('preserves file paths verbatim', () => {
    const r = compressMessage(LONG_MESSAGE, { budgetTokens: 100 });
    expect(r.compressed).toContain('src/auth/jwt-verifier.ts');
  });

  it('reduces token count when budget is < original', () => {
    const r = compressMessage(LONG_MESSAGE, { budgetTokens: 80 });
    expect(r.stats.compressedTokens).toBeLessThan(r.stats.originalTokens);
    expect(r.stats.compressionRatio).toBeLessThan(1);
  });

  it('reports accurate sentence counts', () => {
    const r = compressMessage(LONG_MESSAGE, { budgetTokens: 60 });
    expect(r.stats.sentencesTotal).toBeGreaterThan(5);
    expect(r.stats.sentencesKept).toBeGreaterThan(0);
    expect(r.stats.sentencesKept).toBeLessThanOrEqual(r.stats.sentencesTotal);
  });

  it('reassembles kept sentences in original order (not score order)', () => {
    const src = [
      'A quick short intro.',
      'This is the load-bearing middle sentence that mentions authentication and JWT and race.',
      'A trailing note.',
    ].join(' ');
    const r = compressMessage(src, { budgetTokens: 40 });
    // If kept, "quick short intro" must appear before "trailing note" (order preserved).
    if (r.compressed.includes('quick short intro') && r.compressed.includes('trailing note')) {
      const introIdx = r.compressed.indexOf('quick short intro');
      const trailIdx = r.compressed.indexOf('trailing note');
      expect(introIdx).toBeLessThan(trailIdx);
    }
  });

  it('is a no-op when budget already exceeds original size', () => {
    const short = 'Just a short handoff message with no compression needed.';
    const r = compressMessage(short, { budgetTokens: 1000 });
    expect(r.compressed).toContain('short handoff message');
    expect(r.stats.compressionRatio).toBeGreaterThanOrEqual(0.9);
  });

  it('estimateTokens matches the ~4-chars-per-token rule', () => {
    expect(estimateTokens('')).toBe(0);
    expect(estimateTokens('abcd')).toBe(1);
    expect(estimateTokens('abcdefgh')).toBe(2);
  });

  it('honors mode=keyword vs mode=sentence (may produce different outputs)', () => {
    const rk = compressMessage(LONG_MESSAGE, { budgetTokens: 60, mode: 'keyword' });
    const rs = compressMessage(LONG_MESSAGE, { budgetTokens: 60, mode: 'sentence' });
    // Both should be under the original size (main invariant).
    expect(rk.stats.compressionRatio).toBeLessThan(1);
    expect(rs.stats.compressionRatio).toBeLessThan(1);
  });
});

/**
 * ADR-382 Part B — removed-agent detection for `ruflo migrate status`.
 *
 * Tests target detectRemovedAgentGaps() directly (not the full statusCommand
 * action) because the production call path defaults to the REAL
 * os.homedir() plugin registry — asserting against that would make the
 * suite depend on whatever happens to be installed on the machine running
 * it. The homeDir override exists precisely so tests can supply an isolated
 * registry.
 */
import { describe, it, expect } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { detectRemovedAgentGaps, type RemovedAgentMapping } from '../src/commands/migrate-agent-detection.js';

const REMOVED_AGENTS: RemovedAgentMapping[] = [
  { basename: 'coder.md', plugin: 'ruflo-core' },
  { basename: 'researcher.md', plugin: 'ruflo-core' },
  { basename: 'reviewer.md', plugin: 'ruflo-core' },
  { basename: 'tester.md', plugin: 'ruflo-testgen' },
  { basename: 'memory-specialist.md', plugin: 'ruflo-rag-memory' },
  { basename: 'security-auditor.md', plugin: 'ruflo-security-audit' },
  { basename: 'sparc-orchestrator.md', plugin: 'ruflo-sparc' },
  { basename: 'goal-planner.md', plugin: 'ruflo-goals' },
  { basename: 'adr-architect.md', plugin: 'ruflo-adr' },
];

function project(): string {
  return mkdtempSync(join(tmpdir(), 'migrate-agent-gaps-'));
}

function emptyHome(): string {
  const home = mkdtempSync(join(tmpdir(), 'migrate-agent-gaps-home-'));
  return home;
}

function homeWithInstalledPlugins(plugins: Record<string, Array<{ scope?: string; projectPath?: string }>>): string {
  const home = emptyHome();
  mkdirSync(join(home, '.claude', 'plugins'), { recursive: true });
  writeFileSync(
    join(home, '.claude', 'plugins', 'installed_plugins.json'),
    JSON.stringify({ version: 2, plugins: plugins })
  );
  return home;
}

describe('detectRemovedAgentGaps', () => {
  it('surfaces all 9 suggestions when every agent is missing and no plugins are installed', () => {
    const cwd = project();
    const homeDir = emptyHome();

    const gaps = detectRemovedAgentGaps(cwd, REMOVED_AGENTS, { homeDir });

    expect(gaps).toHaveLength(9);
    expect(gaps.map(g => g.agent).sort()).toEqual(
      [...REMOVED_AGENTS.map(a => a.basename)].sort()
    );
    for (const gap of gaps) {
      // #2985: must be the Claude Code marketplace command — `ruflo plugins
      // install` targets the npm-package plugin system and cannot install
      // these marketplace plugins.
      expect(gap.installCommand).toBe(`/plugin install ${gap.plugin}@ruflo`);
    }
  });

  it('does not flag agents whose owning plugin is installed (user scope)', () => {
    const cwd = project();
    const homeDir = homeWithInstalledPlugins({
      'ruflo-core@ruflo': [{ scope: 'user' }],
    });

    const gaps = detectRemovedAgentGaps(cwd, REMOVED_AGENTS, { homeDir });

    const flaggedAgents = gaps.map(g => g.agent);
    expect(flaggedAgents).not.toContain('coder.md');
    expect(flaggedAgents).not.toContain('researcher.md');
    expect(flaggedAgents).not.toContain('reviewer.md');
    // The other 6 (different owning plugins) are still flagged.
    expect(gaps).toHaveLength(6);
  });

  it('honors project-scoped installs only for the matching project', () => {
    const cwd = project();
    const otherProject = project();
    const homeDir = homeWithInstalledPlugins({
      'ruflo-testgen@ruflo': [{ scope: 'project', projectPath: otherProject }],
    });

    const gaps = detectRemovedAgentGaps(cwd, REMOVED_AGENTS, { homeDir });

    // Installed for a different project — tester.md should still be flagged here.
    expect(gaps.map(g => g.agent)).toContain('tester.md');
  });

  it('reports no gaps when every agent basename is present on disk', () => {
    const cwd = project();
    const homeDir = emptyHome();
    const agentsDir = join(cwd, '.claude', 'agents');
    mkdirSync(join(agentsDir, 'core'), { recursive: true });
    mkdirSync(join(agentsDir, 'testing'), { recursive: true });
    mkdirSync(join(agentsDir, 'memory'), { recursive: true });

    for (const { basename } of REMOVED_AGENTS) {
      // Distribution across subdirectories doesn't matter — detection walks
      // the whole .claude/agents/ tree, matching the "**/basename.md" intent.
      writeFileSync(join(agentsDir, 'core', basename), '# stub agent\n');
    }

    const gaps = detectRemovedAgentGaps(cwd, REMOVED_AGENTS, { homeDir });

    expect(gaps).toEqual([]);
  });

  it('reports no gaps for a project with no .claude/agents directory at all once plugins cover everything', () => {
    const cwd = project();
    const homeDir = homeWithInstalledPlugins({
      'ruflo-core@ruflo': [{ scope: 'user' }],
      'ruflo-testgen@ruflo': [{ scope: 'user' }],
      'ruflo-rag-memory@ruflo': [{ scope: 'user' }],
      'ruflo-security-audit@ruflo': [{ scope: 'user' }],
      'ruflo-sparc@ruflo': [{ scope: 'user' }],
      'ruflo-goals@ruflo': [{ scope: 'user' }],
      'ruflo-adr@ruflo': [{ scope: 'user' }],
    });

    const gaps = detectRemovedAgentGaps(cwd, REMOVED_AGENTS, { homeDir });

    expect(gaps).toEqual([]);
  });
});

/**
 * #2985 — `ruflo migrate fix --agents` restore path.
 *
 * Same isolation discipline as migrate-agent-detection.test.ts: every test
 * gets a temp project and temp home, and the GitHub fallback is exercised
 * through an injected fetchImpl — no test touches the network or depends on
 * what is installed on the machine running the suite.
 */
import { describe, it, expect, vi } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { restoreRemovedAgents } from '../src/commands/migrate-agent-restore.js';
import type { RemovedAgentGap } from '../src/commands/migrate-agent-detection.js';

const CODER_GAP: RemovedAgentGap = {
  agent: 'coder.md',
  plugin: 'ruflo-core',
  installCommand: '/plugin install ruflo-core@ruflo',
};

const GOAL_GAP: RemovedAgentGap = {
  agent: 'goal-planner.md',
  plugin: 'ruflo-goals',
  installCommand: '/plugin install ruflo-goals@ruflo',
};

const PLUGIN_AGENT_CONTENT = [
  '---',
  'name: coder',
  'description: Implementation specialist',
  '---',
  'Use mcp__plugin_ruflo-core_ruflo__memory_store to persist decisions.',
  '',
].join('\n');

function project(): string {
  return mkdtempSync(join(tmpdir(), 'migrate-agent-restore-'));
}

function emptyHome(): string {
  return mkdtempSync(join(tmpdir(), 'migrate-agent-restore-home-'));
}

function homeWithMarketplaceClone(plugin: string, basename: string, content: string): string {
  const home = emptyHome();
  const agentsDir = join(home, '.claude', 'plugins', 'marketplaces', 'ruflo', 'plugins', plugin, 'agents');
  mkdirSync(agentsDir, { recursive: true });
  writeFileSync(join(agentsDir, basename), content);
  return home;
}

function failingFetch(): typeof fetch {
  return vi.fn(async () => ({ ok: false, status: 404, text: async () => '' })) as unknown as typeof fetch;
}

describe('restoreRemovedAgents', () => {
  it('restores from the marketplace clone, rewrites the namespace, and records provenance', async () => {
    const cwd = project();
    const homeDir = homeWithMarketplaceClone('ruflo-core', 'coder.md', PLUGIN_AGENT_CONTENT);

    const results = await restoreRemovedAgents(cwd, [CODER_GAP], { homeDir, fetchImpl: failingFetch() });

    expect(results).toEqual([
      expect.objectContaining({ agent: 'coder.md', status: 'restored', source: 'marketplace-clone' }),
    ]);
    const written = readFileSync(join(cwd, '.claude', 'agents', 'core', 'coder.md'), 'utf-8');
    expect(written).toContain('mcp__claude-flow__memory_store');
    expect(written).not.toContain('mcp__plugin_ruflo-core_ruflo__');
    expect(written).toContain('restored by `ruflo migrate fix --agents`');
    // Provenance lands after the frontmatter block, not before it.
    expect(written.startsWith('---\n')).toBe(true);
  });

  it('falls back to the GitHub tag URL, then main, when no local source exists', async () => {
    const cwd = project();
    const homeDir = emptyHome();
    const urls: string[] = [];
    const fetchImpl = vi.fn(async (url: string) => {
      urls.push(url);
      if (url.includes('/v9.9.9/')) return { ok: false, status: 404, text: async () => '' };
      return { ok: true, status: 200, text: async () => PLUGIN_AGENT_CONTENT };
    }) as unknown as typeof fetch;

    const results = await restoreRemovedAgents(cwd, [GOAL_GAP], { homeDir, fetchImpl, version: '9.9.9' });

    expect(results[0]).toEqual(
      expect.objectContaining({ agent: 'goal-planner.md', status: 'restored', source: 'github-main' })
    );
    expect(urls[0]).toBe('https://raw.githubusercontent.com/ruvnet/ruflo/v9.9.9/plugins/ruflo-goals/agents/goal-planner.md');
    expect(urls[1]).toBe('https://raw.githubusercontent.com/ruvnet/ruflo/main/plugins/ruflo-goals/agents/goal-planner.md');
    // goal-planner restores to its original init category.
    expect(existsSync(join(cwd, '.claude', 'agents', 'goal', 'goal-planner.md'))).toBe(true);
  });

  it('never overwrites an existing file', async () => {
    const cwd = project();
    const homeDir = homeWithMarketplaceClone('ruflo-core', 'coder.md', PLUGIN_AGENT_CONTENT);
    const dest = join(cwd, '.claude', 'agents', 'core');
    mkdirSync(dest, { recursive: true });
    writeFileSync(join(dest, 'coder.md'), 'hand-authored — do not touch\n');

    const results = await restoreRemovedAgents(cwd, [CODER_GAP], { homeDir, fetchImpl: failingFetch() });

    expect(results[0]).toEqual(expect.objectContaining({ agent: 'coder.md', status: 'skipped' }));
    expect(readFileSync(join(dest, 'coder.md'), 'utf-8')).toBe('hand-authored — do not touch\n');
  });

  it('reports failure with the marketplace-install alternative when offline and no local source', async () => {
    const cwd = project();
    const homeDir = emptyHome();
    const fetchImpl = vi.fn(async () => {
      throw new Error('network unreachable');
    }) as unknown as typeof fetch;

    const results = await restoreRemovedAgents(cwd, [CODER_GAP], { homeDir, fetchImpl });

    expect(results[0].status).toBe('failed');
    expect(results[0].error).toContain('/plugin install ruflo-core@ruflo');
    expect(existsSync(join(cwd, '.claude', 'agents', 'core', 'coder.md'))).toBe(false);
  });

  it('dry-run resolves and reports without writing', async () => {
    const cwd = project();
    const homeDir = homeWithMarketplaceClone('ruflo-core', 'coder.md', PLUGIN_AGENT_CONTENT);

    const results = await restoreRemovedAgents(cwd, [CODER_GAP], { homeDir, fetchImpl: failingFetch(), dryRun: true });

    expect(results[0]).toEqual(expect.objectContaining({ status: 'restored', source: 'marketplace-clone' }));
    expect(existsSync(join(cwd, '.claude', 'agents', 'core', 'coder.md'))).toBe(false);
  });
});

// Regression tests for #2232 — Opus 4.8 alias + literal-id silent downgrade.
//
// Before the fix:
//  - `opus` mapped to `claude-opus-4-7` (a version behind).
//  - executeAgentTask used `MODEL_MAP[x] || DEFAULT` directly, so any literal
//    `claude-*` id silently collapsed to Sonnet 4.6.
//
// After the fix:
//  - `opus` → `claude-opus-4-8`, `opus-4.7` reachable for the prior pin.
//  - Resolution funnels through `resolveAnthropicModel`, which passes literal
//    ids through unchanged.

import { describe, it, expect } from 'vitest';
import { resolveAnthropicModel, DEFAULT_ANTHROPIC_MODEL } from '../src/mcp-tools/agent-execute-core.js';

describe('model resolution (#2232)', () => {
  it('maps the `opus` alias to the current Opus (4.8)', () => {
    expect(resolveAnthropicModel('opus')).toBe('claude-opus-4-8');
  });

  it('keeps the prior Opus pin reachable via `opus-4.7`', () => {
    expect(resolveAnthropicModel('opus-4.7')).toBe('claude-opus-4-7');
  });

  it('maps `sonnet` and `haiku` aliases to current ids', () => {
    expect(resolveAnthropicModel('sonnet')).toBe('claude-sonnet-5');
    expect(resolveAnthropicModel('haiku')).toBe('claude-haiku-4-5-20251001');
  });

  it('keeps the prior Sonnet pin reachable via `sonnet-4.6`', () => {
    expect(resolveAnthropicModel('sonnet-4.6')).toBe('claude-sonnet-4-6');
  });

  it('passes a literal Anthropic model id through unchanged (no silent Sonnet fallback)', () => {
    expect(resolveAnthropicModel('claude-opus-4-8')).toBe('claude-opus-4-8');
    expect(resolveAnthropicModel('claude-opus-4-8')).not.toBe(DEFAULT_ANTHROPIC_MODEL);
    expect(resolveAnthropicModel('claude-opus-4-7')).toBe('claude-opus-4-7');
  });

  it('strips the `anthropic:` prefix', () => {
    expect(resolveAnthropicModel('anthropic:claude-opus-4-8')).toBe('claude-opus-4-8');
  });

  it('falls back to DEFAULT only when the input is undefined / empty', () => {
    expect(resolveAnthropicModel(undefined)).toBe(DEFAULT_ANTHROPIC_MODEL);
    expect(resolveAnthropicModel('')).toBe(DEFAULT_ANTHROPIC_MODEL);
  });
});

/**
 * @claude-flow/neural package bridge — Phase 1 convergence smoke (#1773).
 *
 * Proves the BRIDGE contract: lazy init, idempotent caching, graceful failure
 * when the package isn't resolvable. The actual package-loading is tested
 * conditionally because vitest's module resolver can disagree with Node's
 * runtime resolver for ESM workspace packages — direct `node` invocation
 * loads the package fine, vitest doesn't always. The bridge itself handles
 * both cases (returns null on failure), so these tests cover the contract
 * without depending on test-runtime resolution behavior.
 *
 * Direct package shape testing happens in @claude-flow/neural's own test
 * suite — not duplicated here.
 */

import { describe, expect, it, beforeEach } from 'vitest';
import {
  getNeuralPackage,
  isNeuralPackageLoaded,
  getNeuralPackageStats,
  resetNeuralPackageBridge,
} from '../src/memory/neural-package-bridge.js';

describe('@claude-flow/neural package bridge (#1773 Phase 1)', () => {
  beforeEach(() => {
    resetNeuralPackageBridge();
  });

  it('starts with the package not loaded (lazy init contract)', () => {
    expect(isNeuralPackageLoaded()).toBe(false);
  });

  it('returns the same instance/result on subsequent calls (idempotent)', async () => {
    const a = await getNeuralPackage();
    const b = await getNeuralPackage();
    // Whether the package loaded or not, both calls return identical refs.
    // (null === null is also true, so this works for the not-loaded case.)
    expect(a).toBe(b);
  }, 30_000);

  it('isNeuralPackageLoaded reflects post-load state', async () => {
    expect(isNeuralPackageLoaded()).toBe(false);
    const sys = await getNeuralPackage();
    if (sys) {
      // Package loaded — flag should be true now.
      expect(isNeuralPackageLoaded()).toBe(true);
    } else {
      // Package failed to load (vitest resolver, missing dep, etc.) —
      // the flag stays false. Bridge degrades gracefully.
      expect(isNeuralPackageLoaded()).toBe(false);
    }
  }, 30_000);

  it('getNeuralPackageStats returns the documented shape OR null', async () => {
    const stats = await getNeuralPackageStats();
    if (stats) {
      // Documented shape per @claude-flow/neural NeuralLearningSystem.getStats()
      expect(stats).toHaveProperty('sona');
      expect(stats).toHaveProperty('reasoningBank');
      expect(stats).toHaveProperty('patternLearner');
    } else {
      expect(stats).toBeNull();
    }
  }, 30_000);

  it('exposes accessors when the package loads', async () => {
    const sys = await getNeuralPackage();
    if (sys) {
      expect(typeof sys.getSONAManager).toBe('function');
      expect(typeof sys.getReasoningBank).toBe('function');
      expect(typeof sys.getPatternLearner).toBe('function');
      expect(sys.getSONAManager()).toBeTruthy();
      expect(sys.getReasoningBank()).toBeTruthy();
      expect(sys.getPatternLearner()).toBeTruthy();
    } else {
      // No package, no accessors — bridge correctly returned null.
      expect(sys).toBeNull();
    }
  }, 30_000);

  it('resetNeuralPackageBridge() clears the cache', async () => {
    await getNeuralPackage();
    resetNeuralPackageBridge();
    expect(isNeuralPackageLoaded()).toBe(false);
  }, 30_000);
});

/**
 * neural-router.test.ts — ADR-148 / #2334
 *
 * Verifies the gated, graceful integration of `@metaharness/router` (with
 * optional `@ruvector/tiny-dancer` acceleration) into the model-routing
 * path. The contract under test:
 *
 *   1. Default behavior is byte-identical: with no env vars set,
 *      `tryCostOptimalRoute()` returns null and `ModelRouter.route()` carries
 *      `routedBy: 'heuristic'`.
 *   2. Gate-open + corpus-present → a real cost-optimal pick is returned
 *      and `routedBy` reflects the active backend.
 *   3. Gate-open + invalid embedding (empty array) → null + bandit-fallback.
 *   4. Trajectory recorder writes only when its own gate is set.
 *   5. `task_hash` is deterministic across imports.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync, readFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { __resetNeuralRouterForTests, tryCostOptimalRoute, neuralRouterStatus } from '../src/ruvector/neural-router.js';
import { __resetTrajectoryRecorderForTests, recordDecision, taskHash, trajectoryRecorderStatus } from '../src/ruvector/router-trajectory.js';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function makeEmbedding(seed: number, dim = 32): number[] {
  // Mirror scripts/gen-seed-corpus.mjs signal channels so the synthetic
  // probe is on-distribution for the bundled seed corpus.
  let h = (seed | 1) >>> 0;
  const v: number[] = new Array(dim);
  const next = () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; h = h >>> 0; return ((h % 2_000_001) / 1_000_000) - 1; };
  for (let i = 0; i < dim; i++) v[i] = next() * 0.5;
  return v;
}
const ENV_KEYS = [
  'CLAUDE_FLOW_ROUTER_NEURAL',
  'CLAUDE_FLOW_ROUTER_TRAJECTORY',
  'CLAUDE_FLOW_ROUTER_MODEL_PATH',
  'CLAUDE_FLOW_ROUTER_TRAJECTORY_PATH',
  'CLAUDE_FLOW_ROUTER_SEED_CORPUS',
  'CLAUDE_FLOW_SWARM_DIR',
  'CLAUDE_FLOW_ROUTER_PROVIDER',
  'CLAUDE_FLOW_ROUTER_OPENROUTER_ALTS',
  'CLAUDE_FLOW_ROUTER_LATENCY_BUDGET_MS',
  'CLAUDE_FLOW_ROUTER_BANDIT_PER_MODEL',
  'CLAUDE_FLOW_ROUTER_CALIBRATE',           // iter 24 — default-on; tests should not leak overrides
  'CLAUDE_FLOW_ROUTER_CALIBRATOR_PATH',
  'CLAUDE_FLOW_ROUTER_COST_CEILING_USD_PER_MTOK',  // iter 29
  'CLAUDE_FLOW_ROUTER_AB',                          // iter 37
  'CLAUDE_FLOW_ROUTER_AB_SAMPLE_RATE',
  'CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD',  // iter 44
  'CLAUDE_FLOW_ROUTER_BANDIT_WARMUP_RANGE',           // iter 52
  'CLAUDE_FLOW_ROUTER_BANDIT_FULL_INFLUENCE',         // iter 53
  'CLAUDE_FLOW_ROUTER_BANDIT_SHRINKAGE_LAMBDA',       // iter 57
  'OPENROUTER_API_KEY',
  'ANTHROPIC_API_KEY',
];
function clearEnv() { for (const k of ENV_KEYS) delete process.env[k]; }

// ---------------------------------------------------------------------------
// neural-router
// ---------------------------------------------------------------------------
describe('neural-router (ADR-148)', () => {
  beforeEach(() => {
    clearEnv();
    __resetNeuralRouterForTests();
  });
  afterEach(() => clearEnv());

  it('returns null when CLAUDE_FLOW_ROUTER_NEURAL is not set (gate closed)', async () => {
    const result = await tryCostOptimalRoute(makeEmbedding(42));
    expect(result).toBeNull();
  });

  it('returns null when embedding is missing or empty (even with gate open)', async () => {
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';
    __resetNeuralRouterForTests();
    // @ts-expect-error — testing the invalid-input branch
    expect(await tryCostOptimalRoute(undefined)).toBeNull();
    expect(await tryCostOptimalRoute([])).toBeNull();
  });

  it('reports enabled=false when gate is closed in status()', async () => {
    const s = await neuralRouterStatus();
    expect(s.enabled).toBe(false);
    expect(s.routedBy).toBeNull();
  });

  it('returns a cost-optimal pick when gate is open and seed corpus loads', async () => {
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';
    __resetNeuralRouterForTests();
    // ADR-149 v2 — the seed corpus now carries real 384-dim MiniLM embeddings.
    // A zero-vector probe is a neutral query; we don't predict a specific tier
    // (the picked tier depends on the trained KRR's nearest neighbours), but
    // every routing contract still applies: a real modelId, a valid tier
    // label, ≥2 alternatives, non-negative latency.
    const e = new Array(384).fill(0);
    const r = await tryCostOptimalRoute(e);
    if (!r) {
      // If @metaharness/router isn't installed in CI, we expect null and a
      // diagnostic reason. Skip strict assertions on the cost-optimal pick.
      const s = await neuralRouterStatus();
      expect(s.available || s.reason.includes('not installed')).toBe(true);
      return;
    }
    expect(['metaharness-knn', 'metaharness-krr', 'fastgrnn']).toContain(r.routedBy);
    expect(typeof r.modelId).toBe('string');
    expect(r.modelId.length).toBeGreaterThan(0);
    expect(['haiku', 'sonnet', 'opus', 'inherit']).toContain(r.model);
    expect(r.inferenceTimeUs).toBeGreaterThanOrEqual(0);
    expect(r.alternatives.length).toBeGreaterThanOrEqual(2);
  });

  it('returns a per-model pick with modelId (ADR-149)', async () => {
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';
    __resetNeuralRouterForTests();
    const e = new Array(32).fill(0);
    e[0] = -0.85; e[1] = 0.7;
    const r = await tryCostOptimalRoute(e);
    if (!r) return; // dep absent in CI
    // ADR-149: the result must carry a concrete model id (a string), and
    // the picked model id must appear as one of the alternatives.
    expect(typeof r.modelId).toBe('string');
    expect(r.modelId.length).toBeGreaterThan(0);
    expect(r.alternatives.find(a => a.modelId === r.modelId)).toBeDefined();
    // The tier label (model) is derived from the modelId — must be a valid
    // ClaudeModel tier, not necessarily the "expected" tier (DRACO finding:
    // measured cheap models often beat expensive ones on terse tasks).
    expect(['haiku', 'sonnet', 'opus', 'inherit']).toContain(r.model);
  });

  it('caches the resolved backend across calls', async () => {
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';
    __resetNeuralRouterForTests();
    const e = makeEmbedding(3);
    e[0] = 0.85;
    const s1 = await neuralRouterStatus();
    const s2 = await neuralRouterStatus();
    // routedBy should be sticky across calls (single-init guarantee)
    expect(s1.routedBy).toBe(s2.routedBy);
  });

  it('calibration is default-ON; CLAUDE_FLOW_ROUTER_CALIBRATE=0 opts out (ADR-149 iter 24)', async () => {
    // Iter 23 OOS validation moved this from opt-in to opt-out: ECE 0.1604 →
    // 0.0335 with calibration enabled. Verify the env-var semantics flipped:
    //   unset      → calibration applied (status reason contains 'calibrated')
    //   = '1'      → calibration applied (back-compat)
    //   = '0'      → calibration bypassed (raw KRR behavior)
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';

    // Default: no env var → calibrated.
    __resetNeuralRouterForTests();
    const sDefault = await neuralRouterStatus();
    if (sDefault.routedBy !== 'metaharness-krr') return; // dep absent / KRR not loaded
    expect(sDefault.reason).toContain('calibrated');

    // Back-compat: '1' still works.
    process.env.CLAUDE_FLOW_ROUTER_CALIBRATE = '1';
    __resetNeuralRouterForTests();
    const sOn = await neuralRouterStatus();
    expect(sOn.reason).toContain('calibrated');

    // Opt-out: '0' bypasses.
    process.env.CLAUDE_FLOW_ROUTER_CALIBRATE = '0';
    __resetNeuralRouterForTests();
    const sOff = await neuralRouterStatus();
    expect(sOff.reason).not.toContain('calibrated');
  });

  it('A/B sample-rate is deterministic by task_hash (ADR-149 iter 37)', async () => {
    // Verify the deterministic-by-FNV sampling math directly. The integration
    // point (whether abPair ends up in the route result) depends on neural
    // backend availability — fragile in tests. We assert the sample-decision
    // math instead: same task → same decision, populations match the rate.

    // Reproduce the FNV-1a-32 + mod-10000 logic from model-router.ts.
    const sampleDecision = (task: string, rate: number): boolean => {
      let h = 0x811c9dc5 >>> 0;
      for (let i = 0; i < task.length; i++) {
        h ^= task.charCodeAt(i);
        h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
      }
      return (h % 10000) / 10000 < rate;
    };

    // Determinism: same task → same decision.
    expect(sampleDecision('the same task', 0.5)).toBe(sampleDecision('the same task', 0.5));
    expect(sampleDecision('another task', 0.5)).toBe(sampleDecision('another task', 0.5));

    // Population: 50% rate over 200 varied tasks should land between 35% and
    // 65% in-sample (loose Bernoulli bound).
    let inSample = 0;
    for (let i = 0; i < 200; i++) {
      if (sampleDecision(`task-${i}-${i * 17 + 3}`, 0.5)) inSample++;
    }
    expect(inSample).toBeGreaterThan(70);
    expect(inSample).toBeLessThan(130);

    // Rate=0 → never in sample.
    for (let i = 0; i < 50; i++) {
      expect(sampleDecision(`zero-task-${i}`, 0)).toBe(false);
    }
    // Rate=1 → always in sample.
    for (let i = 0; i < 50; i++) {
      expect(sampleDecision(`one-task-${i}`, 1)).toBe(true);
    }
  });

  it('continuous bandit warmup blends gradually with sample count (ADR-149 iter 52)', async () => {
    // The warmup math: weight = min(1, (samples - 2) / WARMUP_RANGE).
    // blendFactor = 0.5 * weight. blended_q = (1-bf)*neural + bf*bandit.
    // Verify the formula in isolation (selector flow is too integration-heavy
    // to assert deterministically without controlling Beta samples).
    const warmupRange = 8;
    const compute = (samples: number) => {
      if (samples <= 2) return { weight: 0, blendFactor: 0 };
      const w = Math.min(1, (samples - 2) / warmupRange);
      return { weight: w, blendFactor: 0.5 * w };
    };

    // samples=2 (uniform prior) → no blend
    expect(compute(2).blendFactor).toBe(0);
    // samples=3 (first observation) → tiny weight
    expect(compute(3).blendFactor).toBeCloseTo(0.5 * (1 / 8), 6);
    // samples=6 (mid-warmup) → halfway up the curve
    expect(compute(6).blendFactor).toBeCloseTo(0.5 * (4 / 8), 6);
    // samples=10 (fully warm) → max blend (matches iter 14 baseline 50/50)
    expect(compute(10).blendFactor).toBe(0.5);
    // samples=100 (very warm) → still capped at max (no over-trust)
    expect(compute(100).blendFactor).toBe(0.5);

    // The function MUST be monotone non-decreasing in samples — bandit gets
    // MORE influence as data accumulates, never less.
    let prev = -Infinity;
    for (let s = 2; s <= 20; s++) {
      const bf = compute(s).blendFactor;
      expect(bf).toBeGreaterThanOrEqual(prev);
      prev = bf;
    }
  });

  it('iter 57 cross-bucket shrinkage blends specific prior toward marginal (ADR-149 iter 57)', async () => {
    // Verify the shrinkage math in isolation. w_s = (n_s + 1) / (n_s + 1 + λ).
    // Blended (α, β) = w_s * specific + (1 - w_s) * marginal.
    //
    // Scenario: med-bucket gpt-4.1 has 3 samples (α=3, β=2, n=3).
    // Marginal across buckets has 50 samples (α=30, β=22, n=50).
    // Lambda = 4.
    const lambda = 4;
    const specific = { alpha: 3, beta: 2 }; // n = 3
    const marginal = { alpha: 30, beta: 22 }; // n = 50
    const nSpecific = specific.alpha + specific.beta - 2;  // 3
    const wSpecific = (nSpecific + 1) / (nSpecific + 1 + lambda);  // 4 / 8 = 0.5

    expect(wSpecific).toBeCloseTo(0.5, 6);

    const alphaBlended = wSpecific * specific.alpha + (1 - wSpecific) * marginal.alpha;
    const betaBlended  = wSpecific * specific.beta  + (1 - wSpecific) * marginal.beta;

    // With 50% specific + 50% marginal:
    //   α = 0.5 * 3 + 0.5 * 30 = 16.5
    //   β = 0.5 * 2 + 0.5 * 22 = 12
    expect(alphaBlended).toBeCloseTo(16.5, 6);
    expect(betaBlended).toBeCloseTo(12, 6);

    // Rich-cell case: specific has 100 samples → w_s ≈ 96/100 → mostly specific.
    const richSpec = { alpha: 60, beta: 42 }; // n = 100
    const nRich = richSpec.alpha + richSpec.beta - 2;
    const wRich = (nRich + 1) / (nRich + 1 + lambda);
    expect(wRich).toBeGreaterThan(0.95);  // ≈ 0.962
    expect(wRich).toBeLessThan(1);          // never quite 1

    // Cold-cell case: specific has 0 samples → w_s = 1/5 = 0.2 → mostly marginal.
    const cold = { alpha: 1, beta: 1 }; // n = 0
    const nCold = cold.alpha + cold.beta - 2;
    const wCold = (nCold + 1) / (nCold + 1 + lambda);
    expect(wCold).toBe(0.2);
    // Blended: 0.2 × (1,1) + 0.8 × (30, 22) = (24.2, 17.8)
    expect(0.2 * 1 + 0.8 * 30).toBeCloseTo(24.2, 6);

    // Monotone in n_s — more samples means more trust in specific.
    let prev = -Infinity;
    for (let n = 0; n <= 50; n += 5) {
      const w = (n + 1) / (n + 1 + lambda);
      expect(w).toBeGreaterThanOrEqual(prev);
      prev = w;
    }

    // λ=0 disables shrinkage — w_s = 1.0 regardless of n.
    expect((0 + 1) / (0 + 1 + 0)).toBe(1);
    expect((100 + 1) / (100 + 1 + 0)).toBe(1);
  });

  it('iter 53 full-influence curve asymptotes to 1.0 as samples grow (ADR-149 iter 53)', async () => {
    // Verify the alternate curve math: blendFactor = (s-2) / (s + WARMUP).
    // At s=10 with WARMUP=8: 8/18 ≈ 0.444 (slightly less aggressive than iter 52).
    // At s=100: 98/108 ≈ 0.907 (bandit dominates).
    // At s=1000: 998/1008 ≈ 0.990 (effectively pure bandit).
    // Monotone non-decreasing always.
    const W = 8;
    const fullInfluence = (s: number) => (s - 2) / (s + W);
    const capped       = (s: number) => 0.5 * Math.min(1, (s - 2) / W);

    expect(fullInfluence(3)).toBeCloseTo(1 / 11, 6);     // 0.091 — very modest at first observation
    expect(fullInfluence(10)).toBeCloseTo(8 / 18, 6);    // 0.444
    expect(fullInfluence(100)).toBeCloseTo(98 / 108, 4); // 0.907
    expect(fullInfluence(1000)).toBeCloseTo(998 / 1008, 4); // 0.990
    expect(fullInfluence(1000)).toBeGreaterThan(0.95);   // dominates at scale
    expect(fullInfluence(1000)).toBeLessThan(1);         // never quite reaches 1

    // The capped curve plateaus at 0.5 — full-influence overtakes it at s=10.
    expect(fullInfluence(10)).toBeLessThan(capped(10));
    expect(fullInfluence(20)).toBeGreaterThan(capped(20));
    expect(fullInfluence(100)).toBeGreaterThan(capped(100) + 0.4); // huge gap

    // Monotone non-decreasing.
    let prev = -Infinity;
    for (let s = 3; s <= 100; s += 5) {
      const v = fullInfluence(s);
      expect(v).toBeGreaterThanOrEqual(prev);
      prev = v;
    }
  });

  it('ensemble-uncertainty threshold triggers null/fallback when unified and specialist disagree (ADR-149 iter 44)', async () => {
    // Default behavior (no threshold) returns a result. Setting a very low
    // threshold (0.0001) forces ALMOST any non-zero ensemble disagreement
    // to fall back. With the bundled seed corpus, unified vs specialist
    // KRR rarely predict EXACTLY the same value, so the low threshold
    // should reliably trigger null.
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';
    const e = new Array(384).fill(0).map((_, i) => Math.cos(i * 0.07));

    // Baseline: no threshold → result returned (or skip if KRR not loadable).
    __resetNeuralRouterForTests();
    const baseline = await tryCostOptimalRoute(e, { complexityBucket: 'med' });
    if (!baseline) return; // KRR not available in this env
    expect(baseline.routedBy).toBe('metaharness-krr');

    // Tight threshold: ANY non-zero disagreement → null.
    process.env.CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD = '0.0001';
    __resetNeuralRouterForTests();
    const tight = await tryCostOptimalRoute(e, { complexityBucket: 'med' });
    // Either null (caught a disagreement) OR identical values (unlikely
    // with the bundled corpus, but allowed). The test contract is: with
    // a TIGHT threshold, the result is null-or-identical, never wildly
    // different from baseline.
    if (tight !== null) {
      // If non-null, it means unified and specialist agreed exactly on
      // this embedding. That's allowed but rare; assert the model is the
      // same as baseline (no spurious switch).
      expect(tight.modelId).toBe(baseline.modelId);
    }

    // Loose threshold: 0.99 → no realistic disagreement triggers, result
    // matches baseline.
    process.env.CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD = '0.99';
    __resetNeuralRouterForTests();
    const loose = await tryCostOptimalRoute(e, { complexityBucket: 'med' });
    expect(loose).not.toBeNull();
    expect(loose!.modelId).toBe(baseline.modelId);

    // No bucket → no ensemble check (no specialist queried) → baseline.
    process.env.CLAUDE_FLOW_ROUTER_ENSEMBLE_UNCERTAINTY_THRESHOLD = '0.0001';
    __resetNeuralRouterForTests();
    const noBucket = await tryCostOptimalRoute(e);   // no opts.complexityBucket
    expect(noBucket).not.toBeNull();                  // unified used as activeRouter; check disabled
  });

  it('cost-ceiling mode picks highest-quality candidate under budget (ADR-149 iter 29)', async () => {
    // When CLAUDE_FLOW_ROUTER_COST_CEILING_USD_PER_MTOK is set, the selector
    // changes from "cheapest above qualityBar" to "best quality under ceiling".
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';

    // Baseline (no ceiling) — pick is cost-optimal-above-bar.
    __resetNeuralRouterForTests();
    const e = new Array(384).fill(0).map((_, i) => Math.sin(i * 0.1));
    const baseline = await tryCostOptimalRoute(e);
    if (!baseline) return; // KRR not loadable in this env
    expect(typeof baseline.modelId).toBe('string');

    // Set a tight ceiling that excludes Sonnet ($48) and Opus ($240) but
    // keeps Haiku ($16), GPT-4.1 ($26), Gemini-Flash-Lite ($1.30), Llama-3.3
    // ($1.33), Ling-2.6 ($0.10). The selector should switch to picking the
    // HIGHEST-quality candidate among those — which on the bundled corpus
    // is typically GPT-4.1 or Haiku, not Ling (which is cheapest).
    process.env.CLAUDE_FLOW_ROUTER_COST_CEILING_USD_PER_MTOK = '30';
    __resetNeuralRouterForTests();
    const ceiling = await tryCostOptimalRoute(e);
    if (!ceiling) return;

    // Pick must satisfy the ceiling AND be the max-quality candidate under it.
    const picked = ceiling.alternatives.find(a => a.modelId === ceiling.modelId);
    expect(picked).toBeDefined();
    expect(picked!.costPerMTok).toBeLessThanOrEqual(30);

    // Among all candidates ≤ ceiling, picked one must have the max
    // predictedQuality (the new selection rule).
    const affordable = ceiling.alternatives.filter(a => a.costPerMTok <= 30);
    expect(affordable.length).toBeGreaterThan(0);
    const maxQ = Math.max(...affordable.map(a => a.predictedQuality));
    expect(picked!.predictedQuality).toBeCloseTo(maxQ, 6);

    // Negative test: cost above ceiling should never be picked.
    expect(ceiling.alternatives.some(a => a.modelId === ceiling.modelId && a.costPerMTok > 30)).toBe(false);
  });

  it('per-tier calibrators load when present and are reported in status reason (ADR-149 iter 25)', async () => {
    // Iter 25 ships seed-router.calibrator.{low,med,high}.json alongside the
    // unified calibrator. When all are present, status reason should reflect
    // every loaded calibrator. When CALIBRATE=0, none should load.
    process.env.CLAUDE_FLOW_ROUTER_NEURAL = '1';

    __resetNeuralRouterForTests();
    const s = await neuralRouterStatus();
    if (s.routedBy !== 'metaharness-krr') return; // dep absent / KRR not loaded

    // The reason string lists which calibrators loaded; with the bundled
    // artifacts, expect unified + low + med + high.
    expect(s.reason).toMatch(/calibrated: .*unified/);
    // At least one bucket must be present (best-effort — file existence
    // depends on whether iter 25 was run on this checkout).
    const hasBucket = /calibrated: .*(low|med|high)/.test(s.reason);
    expect(hasBucket).toBe(true);

    // Opt-out kills all calibrators.
    process.env.CLAUDE_FLOW_ROUTER_CALIBRATE = '0';
    __resetNeuralRouterForTests();
    const sOff = await neuralRouterStatus();
    expect(sOff.reason).not.toContain('calibrated');
  });
});

// ---------------------------------------------------------------------------
// router-trajectory
// ---------------------------------------------------------------------------
describe('router-trajectory (ADR-148)', () => {
  let tmpDir: string;

  beforeEach(() => {
    clearEnv();
    __resetTrajectoryRecorderForTests();
    tmpDir = mkdtempSync(join(tmpdir(), 'router-traj-test-'));
  });
  afterEach(() => {
    clearEnv();
    __resetTrajectoryRecorderForTests();
    if (existsSync(tmpDir)) rmSync(tmpDir, { recursive: true, force: true });
  });

  it('writes nothing when gate is closed', () => {
    const path = join(tmpDir, 'trajectories.jsonl');
    process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_PATH = path;
    __resetTrajectoryRecorderForTests();
    recordDecision({
      task: 'add console.log to cache',
      complexity: 0.1, model: 'haiku', confidence: 0.9, uncertainty: 0.1,
      routedBy: 'heuristic',
    });
    expect(existsSync(path)).toBe(false);
  });

  it('writes one JSONL row per call when gate is open', () => {
    const path = join(tmpDir, 'trajectories.jsonl');
    process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY = '1';
    process.env.CLAUDE_FLOW_ROUTER_TRAJECTORY_PATH = path;
    __resetTrajectoryRecorderForTests();
    recordDecision({
      task: 'add console.log to cache',
      embedding: [1, 2, 3],
      complexity: 0.1, model: 'haiku', confidence: 0.9, uncertainty: 0.1,
      routedBy: 'metaharness-knn',
    });
