  },
];

describe('pretrain-from-github wiring guard (#2245 regression)', () => {
  let before: Awaited<ReturnType<typeof getUnifiedLearningStats>>;
  let afterStats: Awaited<ReturnType<typeof getUnifiedLearningStats>>;
  let neuralBefore: Awaited<ReturnType<typeof getNeuralStoreStats>>;
  let neuralAfter: Awaited<ReturnType<typeof getNeuralStoreStats>>;
  let trainedCount = 0;

  beforeAll(async () => {
    before = await getUnifiedLearningStats();
    neuralBefore = await getNeuralStoreStats();

    for (const item of FIXTURE) {
      const distilled = distillAndSerialise(`${item.subject}\n\n${item.body}`);
      // Distillation must be non-empty for every item.
      expect(distilled.length).toBeGreaterThan(10);

      await recordTrajectory(
        [{
          type: 'result',
          content: distilled,
          metadata: { source: item.source, id: item.id, subject: item.subject.slice(0, 200) },
          timestamp: Date.now(),
        }],
        item.verdict,
      );
      trainedCount++;
    }

    await storeNeuralPatterns(
      FIXTURE.map((item) => ({
        name: item.subject.slice(0, 200),
        type: item.source === 'commit' ? 'history-commit' : 'history-issue',
        content: distillAndSerialise(`${item.subject}\n\n${item.body}`),
        metadata: { source: item.source, id: item.id, verdict: item.verdict },
      })),
    );

    flushIntelligenceStats();
    afterStats = await getUnifiedLearningStats();
    neuralAfter = await getNeuralStoreStats();
  });

  it('feeds every fixture item through recordTrajectory without errors', () => {
    expect(trainedCount).toBe(FIXTURE.length);
  });

  it('bumps globalStats.trajectoriesRecorded by at least the fixture size', () => {
    expect(afterStats.global.trajectoriesRecorded - before.global.trajectoriesRecorded)
      .toBeGreaterThanOrEqual(FIXTURE.length);
  });

  it('bumps globalStats.patternsLearned (Round B/C wiring still alive)', () => {
    expect(afterStats.global.patternsLearned - before.global.patternsLearned)
      .toBeGreaterThan(0);
  });

  it('populates the neural store (closes #2245 "neural_patterns stays empty" gap)', () => {
    expect(neuralAfter.patternCount - neuralBefore.patternCount)
      .toBeGreaterThanOrEqual(FIXTURE.length);
  });

  it('getUnifiedLearningStats returns the 4 documented sub-views', () => {
    expect(afterStats.global).toBeDefined();
    expect(afterStats.sona).toBeDefined();
    expect(afterStats.memoryBridge).toBeDefined();
    expect(afterStats.neuralPatterns).toBeDefined();
    expect(afterStats.consistency).toBeDefined();
    expect(Array.isArray(afterStats.consistency.notes)).toBe(true);
  });

  it('distillation captures issue/commit identifiers in the embedded form', () => {
    // The fixture intentionally includes recognisable tokens. The distilled
    // form should preserve them so downstream retrieval can match.
    const item = FIXTURE[3]; // issue-2245
    const distilled = distillAndSerialise(`${item.subject}\n\n${item.body}`);
    expect(distilled).toMatch(/2245|self-learning|persists/i);
  });

  // ADR-078 — hybrid retrieval should be at least as discriminative as cosine
  // alone on an exact-keyword query. We don't require a strict inequality
  // because on a 5-item fixture both modes can return the same top-1.
  it('hybrid search returns a non-empty result and respects mode parameter', async () => {
    const tool = neuralTools.find((t) => t.name === 'neural_patterns');
    expect(tool).toBeDefined();

    const hybrid = await tool!.handler({
      action: 'search',
      query: 'structured distillation 4-field schema',
      mode: 'hybrid',
      limit: 3,
    });
    expect(hybrid.mode).toBe('hybrid');
    expect(Array.isArray(hybrid.results)).toBe(true);
    expect(hybrid.results.length).toBeGreaterThan(0);
    // Top-1 of a query targeting commit-aaa3 (Structured Distillation, ADR-076)
    // should mention either 'structured', 'distillation', or 'ADR-076'.
    const top1Name = String(hybrid.results[0].name).toLowerCase();
    expect(top1Name).toMatch(/structured|distillation|adr-076|076/);
    // Hybrid path returns the extra ADR-078 fields.
    expect(hybrid.results[0]).toHaveProperty('hybridScore');
    expect(hybrid.results[0]).toHaveProperty('cosineScore');
    expect(hybrid.results[0]).toHaveProperty('bm25Score');

    const cosine = await tool!.handler({
      action: 'search',
      query: 'structured distillation 4-field schema',
      mode: 'cosine',
      limit: 3,
    });
    expect(cosine.mode).toBe('cosine');
    expect(Array.isArray(cosine.results)).toBe(true);
    // Cosine path does NOT include the hybrid breakdown.
    expect(cosine.results[0]).not.toHaveProperty('hybridScore');
  });
});

/**
 * Proven-configuration propagation to existing installs (ADR-177).
 * Adoption is doubly-gated (authenticity + suitability), fail-closed, additive.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { generateKeyPairSync } from 'node:crypto';
import { adoptSignedConfig, PROVEN_CONFIG_STAMP, ADOPTED_CONFIG_FILE } from '../src/config/proven-config-refresh.js';
import { signProvenConfig, type ProvenConfigManifest, type InstallEnv } from '../src/config/proven-config.js';

const kp = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });

function manifest(over: Partial<ProvenConfigManifest> = {}): ProvenConfigManifest {
  return {
    schema: 'ruflo.proven-config/v1',
    policy: { ref: 'sha256:' + 'a'.repeat(64) },
    platform: ['linux', 'macOS'],
    compatibility: { ruflo: '>=3.24.0' },
    rollback: { previousManifest: 'sha256:' + 'z'.repeat(64) },
    ...over,
  };
}
const env: InstallEnv = { platform: 'darwin', versions: { ruflo: '3.24.0' } };

function project(): string {
  const cwd = mkdtempSync(join(tmpdir(), 'pcfg-'));
  mkdirSync(join(cwd, '.claude'), { recursive: true });
  return cwd;
}

describe('adoptSignedConfig (ADR-177 propagation)', () => {
  it('adopts an authentic + suitable champion, records it, advances the stamp', () => {
    const cwd = project();
    const signed = signProvenConfig(manifest(), kp.privateKey);
    const r = adoptSignedConfig(cwd, signed, env, { pubkeyPem: kp.publicKey });
    expect(r.adopted).toBe(true);
    expect(readFileSync(join(cwd, '.claude', PROVEN_CONFIG_STAMP), 'utf-8').trim()).toBe(signed.manifest.policy.ref);
    const rec = JSON.parse(readFileSync(join(cwd, '.claude', ADOPTED_CONFIG_FILE), 'utf-8'));
    expect(rec.championId).toBe(signed.manifest.policy.ref);
    expect(rec.previous).toBe('sha256:' + 'z'.repeat(64)); // rollback pointer retained
  });

  it('REFUSES a bad signature (authenticity gate) and does not stamp', () => {
    const cwd = project();
    const other = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const r = adoptSignedConfig(cwd, signProvenConfig(manifest(), other.privateKey), env, { pubkeyPem: kp.publicKey });
    expect(r.adopted).toBe(false);
    expect(existsSync(join(cwd, '.claude', PROVEN_CONFIG_STAMP))).toBe(false);
  });

  it('SAFE-SKIPS a signed-but-unsuitable champion (backwards-compat version gate)', () => {
    const cwd = project();
    const signed = signProvenConfig(manifest({ compatibility: { ruflo: '>=9.9.9' } }), kp.privateKey);
    const r = adoptSignedConfig(cwd, signed, env, { pubkeyPem: kp.publicKey });
    expect(r.adopted).toBe(false);
    expect(r.skipped).toMatch(/not suitable/);
    expect(existsSync(join(cwd, '.claude', PROVEN_CONFIG_STAMP))).toBe(false); // never advanced
  });

  it('is a fast no-op when the stamp already matches (idempotent)', () => {
    const cwd = project();
    const signed = signProvenConfig(manifest(), kp.privateKey);
    writeFileSync(join(cwd, '.claude', PROVEN_CONFIG_STAMP), signed.manifest.policy.ref);
    const r = adoptSignedConfig(cwd, signed, env, { pubkeyPem: kp.publicKey });
    expect(r.adopted).toBe(false);
    expect(r.skipped).toBeUndefined();
  });

  it('is a no-op outside a ruflo project (no .claude)', () => {
    const cwd = mkdtempSync(join(tmpdir(), 'not-ruflo-'));
    const r = adoptSignedConfig(cwd, signProvenConfig(manifest(), kp.privateKey), env, { pubkeyPem: kp.publicKey });
    expect(r.adopted).toBe(false);
  });
});

/**
 * RVFA packaging for proven-config champions (ADR-177 final phase).
 * Roundtrip, tamper-evidence, fail-closed decode, and adopt-path parity.
 */
import { describe, it, expect } from 'vitest';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { generateKeyPairSync } from 'node:crypto';
import {
  packProvenConfigRvfa, unpackProvenConfigRvfa, isProvenConfigRvfa,
  PROVEN_CONFIG_SECTION,
} from '../src/config/proven-config-rvfa.js';
import { signProvenConfig, type ProvenConfigManifest } from '../src/config/proven-config.js';
import { adoptSignedConfig, loadShippedChampion, PROVEN_CONFIG_RVFA_FILE } from '../src/config/proven-config-refresh.js';

function keys() {
  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
  return {
    pub: publicKey.export({ type: 'spki', format: 'pem' }) as string,
    priv: privateKey.export({ type: 'pkcs8', format: 'pem' }) as string,
  };
}

const manifest: ProvenConfigManifest = {
  schema: 'ruflo.proven-config/v1',
  policy: { ref: 'sha256:abc123' },
  platform: ['linux', 'macOS'],
  compatibility: { ruflo: '>=3.24.0' },
  benchmark: { corpus: 'LAB-v1', corpusHash: 'deadbeef' },
  layer: 'framework/node-cli',
};

describe('packProvenConfigRvfa / unpackProvenConfigRvfa', () => {
  it('roundtrips a signed manifest through the RVFA envelope', () => {
    const { pub, priv } = keys();
    const signed = signProvenConfig(manifest, priv);
    const rvf = packProvenConfigRvfa(signed);

    expect(isProvenConfigRvfa(rvf)).toBe(true);
    const back = unpackProvenConfigRvfa(rvf);
    expect(back).not.toBeNull();
    expect(back!.signature).toBe(signed.signature);
    expect(back!.manifest.policy.ref).toBe('sha256:abc123');
    // Signature still verifies after the RVFA round-trip (byte-preserving).
    void pub;
  });

  it('rejects a non-RVFA buffer (fail-closed)', () => {
    expect(isProvenConfigRvfa(Buffer.from('{"not":"rvfa"}'))).toBe(false);
    expect(unpackProvenConfigRvfa(Buffer.from('garbage'))).toBeNull();
  });

  it('rejects a tampered envelope (integrity footer mismatch)', () => {
    const { priv } = keys();
    const rvf = packProvenConfigRvfa(signProvenConfig(manifest, priv));
    const tampered = Buffer.from(rvf);
    tampered[tampered.length - 5] ^= 0xff; // corrupt a byte inside the section-data/footer region
    expect(unpackProvenConfigRvfa(tampered)).toBeNull();
  });

  it('names the section canonically', () => {
    expect(PROVEN_CONFIG_SECTION).toBe('proven-config');
  });
});

describe('adopt path parity — RVFA-packed champion adopts like raw JSON', () => {
  it('loadShippedChampion decodes a .rvf and adoptSignedConfig accepts it', () => {
    const { pub, priv } = keys();
    const signed = signProvenConfig(manifest, priv);

    const cwd = mkdtempSync(join(tmpdir(), 'pcrvfa-'));
    mkdirSync(join(cwd, '.claude'), { recursive: true });
    const rvfPath = join(cwd, PROVEN_CONFIG_RVFA_FILE);
    writeFileSync(rvfPath, packProvenConfigRvfa(signed));

    const decoded = loadShippedChampion(rvfPath);
    expect(decoded).not.toBeNull();

    const env = { platform: 'linux', versions: { ruflo: '3.24.0' } };
    const res = adoptSignedConfig(cwd, decoded!, env, { pubkeyPem: pub });
    expect(res.adopted).toBe(true);
    expect(res.to).toBe('sha256:abc123');
    // The adopted record was written for the feedback applier.
    const record = JSON.parse(readFileSync(join(cwd, '.claude', 'proven-config.json'), 'utf-8'));
    expect(record.championId).toBe('sha256:abc123');
  });

  it('a forged manifest inside a well-formed RVFA is rejected at adoption (signed≠trusted)', () => {
    const { pub } = keys();            // adoption pubkey
    const attacker = keys();           // different key signs the payload
    const signed = signProvenConfig({ ...manifest, policy: { ref: 'sha256:evil' } }, attacker.priv);
    const rvf = packProvenConfigRvfa(signed);

    // Envelope decodes fine (integrity ok)…
    const decoded = unpackProvenConfigRvfa(rvf);
    expect(decoded).not.toBeNull();
    // …but adoption fails closed: the inner signature doesn't verify under pub.
    const cwd = mkdtempSync(join(tmpdir(), 'pcrvfa-'));
    mkdirSync(join(cwd, '.claude'), { recursive: true });
    const res = adoptSignedConfig(cwd, decoded!, { platform: 'linux', versions: { ruflo: '3.24.0' } }, { pubkeyPem: pub });
    expect(res.adopted).toBe(false);
  });
});

/**
 * Proven Configuration Manifest (ADR-176 proof #3 + ADR-177 core).
 *
 * The two adoption gates — authenticity (Ed25519) and suitability (the
 * constraint contract) — must BOTH pass, fail-closed. These tests pin both,
 * plus the "signed != suitable" invariant that a validly-signed but
 * environment-incompatible manifest is a safe non-adoption, not an error.
 */
import { describe, it, expect } from 'vitest';
import { generateKeyPairSync } from 'node:crypto';
import {
  signProvenConfig, verifyProvenConfig, isSuitable, evaluateForAdoption,
  satisfiesRange, canonicalManifestBytes, RUFLO_CONFIG_PUBKEY,
  type ProvenConfigManifest, type InstallEnv,
} from '../src/config/proven-config.js';

const kp = generateKeyPairSync('ed25519', {
  publicKeyEncoding: { type: 'spki', format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
});

function manifest(over: Partial<ProvenConfigManifest> = {}): ProvenConfigManifest {
  return {
    schema: 'ruflo.proven-config/v1',
    policy: { ref: 'sha256:' + 'a'.repeat(64) },
    host: { 'claude-code': '>=1.9' },
    platform: ['linux', 'macOS'],
    compatibility: { ruflo: '>=3.24.0' },
    benchmark: { corpus: 'LAB-v4', corpusHash: 'sha256:' + 'b'.repeat(64) },
    layer: 'framework/node-cli',
    receipt: { heldOutDelta: 0.03, redblue: 'PASS', drift: 0.01, receiptCoverage: 1 },
    rollback: { previousManifest: 'sha256:' + 'c'.repeat(64) },
    ...over,
  };
}

const env: InstallEnv = {
  platform: 'darwin',
  hosts: { 'claude-code': '1.9.3' },
  versions: { ruflo: '3.24.0' },
  layer: 'framework/node-cli/my-repo',
};

describe('proven-config — authenticity (Ed25519, fail-closed)', () => {
  it('verifies a validly-signed manifest', () => {
    const signed = signProvenConfig(manifest(), kp.privateKey);
    expect(verifyProvenConfig(JSON.stringify(signed), kp.publicKey)).not.toBeNull();
  });

  it('REJECTS a manifest tampered after signing', () => {
    const signed = signProvenConfig(manifest(), kp.privateKey);
    (signed.manifest.compatibility as Record<string, string>).ruflo = '>=1.0.0'; // widen after signing
    expect(verifyProvenConfig(JSON.stringify(signed), kp.publicKey)).toBeNull();
  });

  it('REJECTS a wrong-key signature, wrong algorithm, and malformed input', () => {
    const other = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    expect(verifyProvenConfig(JSON.stringify(signProvenConfig(manifest(), other.privateKey)), kp.publicKey)).toBeNull();
    expect(verifyProvenConfig(JSON.stringify({ manifest: manifest(), signature: 'x', algorithm: 'rsa' }), kp.publicKey)).toBeNull();
    expect(verifyProvenConfig('not json', kp.publicKey)).toBeNull();
    expect(verifyProvenConfig(JSON.stringify({ manifest: { schema: 'x' }, signature: 'y', algorithm: 'ed25519' }), kp.publicKey)).toBeNull(); // no policy.ref
  });

  it('canonical bytes are order-independent (deterministic signing)', () => {
    const a = canonicalManifestBytes(manifest({ platform: ['linux', 'macOS'] }));
    const b = canonicalManifestBytes(manifest({ platform: ['linux', 'macOS'] }));
    expect(a.equals(b)).toBe(true);
  });

  it('ships a valid baked config public key (PEM)', () => {
    expect(RUFLO_CONFIG_PUBKEY).toContain('BEGIN PUBLIC KEY');
  });
});

describe('proven-config — semver range satisfier', () => {
  it('handles >=, >, <=, <, =, and bare', () => {
    expect(satisfiesRange('3.24.0', '>=3.24.0')).toBe(true);
    expect(satisfiesRange('3.23.9', '>=3.24.0')).toBe(false);
    expect(satisfiesRange('1.9.3', '>=1.9')).toBe(true);
    expect(satisfiesRange('2.0.0', '>1.9.9')).toBe(true);
    expect(satisfiesRange('3.24.0', '<=3.24.0')).toBe(true);
    expect(satisfiesRange('3.24.1', '<3.24.1')).toBe(false);
    expect(satisfiesRange('3.24.0', '=3.24.0')).toBe(true);
    expect(satisfiesRange('3.24.0', '3.24.0')).toBe(true); // bare = >=
  });
});

describe('proven-config — suitability gate (signed != suitable)', () => {
  it('adopts a suitable environment', () => {
    expect(isSuitable(manifest(), env).suitable).toBe(true);
  });

  it('skips on platform mismatch', () => {
    const r = isSuitable(manifest({ platform: ['linux'] }), { ...env, platform: 'darwin' });
    expect(r.suitable).toBe(false);
    expect(r.reason).toMatch(/platform/);
  });

  it('skips when a required host is absent or too old', () => {
    expect(isSuitable(manifest(), { ...env, hosts: {} }).suitable).toBe(false);
    expect(isSuitable(manifest(), { ...env, hosts: { 'claude-code': '1.8.0' } }).suitable).toBe(false);
  });

  it('skips when a compatibility range is unmet (the version gate for backwards-compat)', () => {
    const r = isSuitable(manifest(), { ...env, versions: { ruflo: '3.23.0' } });
    expect(r.suitable).toBe(false);
    expect(r.reason).toMatch(/ruflo 3.23.0/);
  });

  it('applies the hierarchy layer (ancestor ok, sibling not)', () => {
    expect(isSuitable(manifest({ layer: 'framework/node-cli' }), { ...env, layer: 'framework/node-cli/repo' }).suitable).toBe(true);
    expect(isSuitable(manifest({ layer: 'framework/python' }), { ...env, layer: 'framework/node-cli/repo' }).suitable).toBe(false);
  });

  it('requires only the constraints the manifest declares', () => {
    const bare: ProvenConfigManifest = { schema: 'ruflo.proven-config/v1', policy: { ref: 'sha256:' + 'd'.repeat(64) } };
    expect(isSuitable(bare, { platform: 'win32' }).suitable).toBe(true);
  });
});

describe('proven-config — combined adoption decision', () => {
  it('adopts only when authentic AND suitable', () => {
    const signed = signProvenConfig(manifest(), kp.privateKey);
    const good = evaluateForAdoption(JSON.stringify(signed), env, kp.publicKey);
    expect(good.adopt).toBe(true);
  });

  it('refuses on bad signature (authenticity gate)', () => {
    const other = generateKeyPairSync('ed25519', { publicKeyEncoding: { type: 'spki', format: 'pem' }, privateKeyEncoding: { type: 'pkcs8', format: 'pem' } });
    const r = evaluateForAdoption(JSON.stringify(signProvenConfig(manifest(), other.privateKey)), env, kp.publicKey);
    expect(r.adopt).toBe(false);
    expect(r.reason).toMatch(/authenticity/);
  });

  it('safe-skips a signed-but-unsuitable manifest (not an error)', () => {
    const signed = signProvenConfig(manifest({ compatibility: { ruflo: '>=9.9.9' } }), kp.privateKey);
    const r = evaluateForAdoption(JSON.stringify(signed), env, kp.publicKey);
    expect(r.adopt).toBe(false);
    expect(r.manifest).toBeDefined(); // it WAS authentic
    expect(r.reason).toMatch(/not suitable/);
  });
});

/**
 * `proxy config --cloud/--local-only` (ADR-304). The `default_data_plane`
 * TOML values written here ("local"/"cloud") were confirmed against
 * meta-proxy's actual `DataPlane` enum (`src/config.rs`,
 * `#[serde(rename_all = "snake_case")]`) both by reading the source directly
 * and by a live behavioral test against the real v0.1.0 binary.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import type { CommandContext } from '../src/types.js';

let stateDir: string;
let savedEnv: NodeJS.ProcessEnv;

beforeEach(() => {
  stateDir = fs.mkdtempSync(path.join(os.tmpdir(), 'proxy-config-cmd-test-'));
  savedEnv = { ...process.env };
  process.env.RUFLO_STATE_DIR = stateDir;
});

afterEach(() => {
  process.env = savedEnv;
  fs.rmSync(stateDir, { recursive: true, force: true });
});

function ctxWithFlags(flags: Record<string, unknown>): CommandContext {
  return { args: [], flags: { _: [], ...flags }, cwd: process.cwd(), interactive: false };
}

async function getConfigSub() {
  const { proxyCommand } = await import('../src/commands/proxy.js');
  const sub = proxyCommand.subcommands?.find((c) => c.name === 'config');
  if (!sub) throw new Error('config subcommand not found');
  return sub;
}

describe('proxy config', () => {
  it('with no flags, reports the default plane (passthrough) when no config file exists', async () => {
    const configSub = await getConfigSub();
    const result = await configSub.action!(ctxWithFlags({}));
    expect(result?.success).toBe(true);
    expect((result?.data as { plane?: string })?.plane).toBe('passthrough');
  });

  it('rejects --cloud and --local-only together', async () => {
    const configSub = await getConfigSub();
    const result = await configSub.action!(ctxWithFlags({ cloud: true, localOnly: true }));
    expect(result?.success).toBe(false);
  });

  it('--cloud without --yes shows the disclosure and writes nothing', async () => {
    const configSub = await getConfigSub();
    const result = await configSub.action!(ctxWithFlags({ cloud: true }));
    expect(result?.success).toBe(true);
    expect((result?.data as { confirmed?: boolean })?.confirmed).toBe(false);
    expect(fs.existsSync(path.join(stateDir, 'proxy-config.toml'))).toBe(false);

    const { hasConsent } = await import('../src/funnel/index.js');
    expect(hasConsent('cloud-routing')).toBe(false);
  });

  it('--cloud --yes writes default_data_plane = "cloud" and grants consent', async () => {
    const configSub = await getConfigSub();
    const result = await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));
    expect(result?.success).toBe(true);

    const raw = fs.readFileSync(path.join(stateDir, 'proxy-config.toml'), 'utf-8');
    expect(raw).toContain('default_data_plane = "cloud"');

    const { hasConsent } = await import('../src/funnel/index.js');
    expect(hasConsent('cloud-routing')).toBe(true);
  });

  it('--local-only writes default_data_plane = "local" and revokes consent', async () => {
    const configSub = await getConfigSub();
    await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));
    await configSub.action!(ctxWithFlags({ localOnly: true }));

    const raw = fs.readFileSync(path.join(stateDir, 'proxy-config.toml'), 'utf-8');
    expect(raw).toContain('default_data_plane = "local"');

    const { hasConsent } = await import('../src/funnel/index.js');
    expect(hasConsent('cloud-routing')).toBe(false);
  });

  it('revoking via --local-only means a later --cloud (no --yes) re-shows the disclosure', async () => {
    const configSub = await getConfigSub();
    await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));
    await configSub.action!(ctxWithFlags({ localOnly: true }));

    const result = await configSub.action!(ctxWithFlags({ cloud: true }));
    expect((result?.data as { confirmed?: boolean })?.confirmed).toBe(false);
  });

  it('preserves unrelated lines already in proxy-config.toml (read-modify-write, not overwrite)', async () => {
    fs.writeFileSync(
      path.join(stateDir, 'proxy-config.toml'),
      'bind = "127.0.0.1:11435"\ndefault_data_plane = "local"\nsponsored_daily_cap_usd = 5.0\n',
    );
    const configSub = await getConfigSub();
    await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));

    const raw = fs.readFileSync(path.join(stateDir, 'proxy-config.toml'), 'utf-8');
    expect(raw).toContain('bind = "127.0.0.1:11435"');
    expect(raw).toContain('sponsored_daily_cap_usd = 5.0');
    expect(raw).toContain('default_data_plane = "cloud"');
  });
});

/**
 * `--routing-mode` (meta-proxy ADR-321 rev-2). Values match the Rust
 * `RoutingMode` enum. The invariant worth pinning is ADR-321 Revision 3's:
 * the plane choice and this Cloud-only tier setting are SEPARATE controls,
 * so selecting a tier must never activate Cloud.
 */
describe('proxy config --routing-mode', () => {
  const configPath = () => path.join(stateDir, 'proxy-config.toml');

  it('writes routing_mode without touching the data plane or granting consent', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ routingMode: 'high' }));

    expect(result?.success).toBe(true);
    const raw = fs.readFileSync(configPath(), 'utf-8');
    expect(raw).toContain('routing_mode = "high"');
    expect(raw).not.toContain('default_data_plane');

    const { hasConsent } = await import('../src/funnel/index.js');
    expect(hasConsent('cloud-routing')).toBe(false);
  });

  it('accepts every mode meta-proxy defines', async () => {
    const configSub = await getConfigSub();

    for (const mode of ['auto', 'low', 'mid', 'high']) {
      const result = await configSub.action!(ctxWithFlags({ routingMode: mode }));
      expect(result?.success, mode).toBe(true);
      expect(fs.readFileSync(configPath(), 'utf-8')).toContain(`routing_mode = "${mode}"`);
    }
  });

  it('rejects a mode meta-proxy would not understand, and writes nothing', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ routingMode: 'ultra' }));

    expect(result?.success).toBe(false);
    expect(fs.existsSync(configPath())).toBe(false);
  });

  it('refuses to pin a tier while --local-only is turning the cloud plane off', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ localOnly: true, routingMode: 'high' }));

    expect(result?.success).toBe(false);
    expect(fs.existsSync(configPath())).toBe(false);
  });

  it('applies alongside --cloud --yes in one command', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ cloud: true, yes: true, routingMode: 'low' }));

    expect(result?.success).toBe(true);
    const raw = fs.readFileSync(configPath(), 'utf-8');
    expect(raw).toContain('default_data_plane = "cloud"');
    expect(raw).toContain('routing_mode = "low"');
  });

  /** The unconfirmed path's whole promise is that nothing was written. */
  it('writes nothing when passed with an unconfirmed --cloud', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ cloud: true, routingMode: 'low' }));

    expect((result?.data as { confirmed?: boolean })?.confirmed).toBe(false);
    expect(fs.existsSync(configPath())).toBe(false);
  });

  it('reports the current mode with no flags, defaulting to auto when unset', async () => {
    const configSub = await getConfigSub();

    const unset = await configSub.action!(ctxWithFlags({}));
    expect((unset?.data as { routingMode?: string })?.routingMode).toBe('auto');

    await configSub.action!(ctxWithFlags({ routingMode: 'mid' }));
    const set = await configSub.action!(ctxWithFlags({}));
    expect((set?.data as { routingMode?: string })?.routingMode).toBe('mid');
  });

  it('treats an unrecognized routing_mode already in the file as auto', async () => {
    fs.writeFileSync(configPath(), 'routing_mode = "ultra"\n');
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({}));

    expect((result?.data as { routingMode?: string })?.routingMode).toBe('auto');
  });

  it('preserves unrelated lines when writing routing_mode', async () => {
    fs.writeFileSync(configPath(), 'bind = "127.0.0.1:11435"\nsponsored_daily_cap_usd = 5.0\n');
    const configSub = await getConfigSub();

    await configSub.action!(ctxWithFlags({ routingMode: 'high' }));

    const raw = fs.readFileSync(configPath(), 'utf-8');
    expect(raw).toContain('bind = "127.0.0.1:11435"');
    expect(raw).toContain('sponsored_daily_cap_usd = 5.0');
    expect(raw).toContain('routing_mode = "high"');
  });
});

/**
 * meta-proxy#43 M5b — "add equivalent disclosure to any terminal flow that
 * explicitly activates Cloud". The console got this in M5a (#60); this
 * command is the terminal flow, and these are the three questions
 * activating Cloud actually decides.
 */
describe('cloud routing disclosure', () => {
  async function disclosureShownOnUnconfirmedCloud(): Promise<string> {
    const lines: string[] = [];
    const { output } = await import('../src/output.js');
    const spy = vi.spyOn(output, 'writeln').mockImplementation((line?: string) => {
      lines.push(String(line ?? ''));
    });
    try {
      const configSub = await getConfigSub();
      await configSub.action!(ctxWithFlags({ cloud: true }));
    } finally {
      spy.mockRestore();
    }
    return lines.join('\n');
  }

  it('says who processes the prompts', async () => {
    expect(await disclosureShownOnUnconfirmedCloud()).toContain('api.cognitum.one');
  });

  it("says who pays, and that Passthrough uses the user's own subscription instead", async () => {
    const text = await disclosureShownOnUnconfirmedCloud();

    expect(text).toContain('metered against your Cognitum account');
    expect(text).toContain('Passthrough');
  });

  /**
   * The omission that mattered: on the Cloud plane the client's requested
   * model is deliberately not used, and before this the disclosure never
   * said so — a user could enable Cloud believing their model choice held.
   */
  it('says the plane picks the tier rather than using the requested model, and how to override', async () => {
    const text = await disclosureShownOnUnconfirmedCloud();

    expect(text).toContain('instead of using the model');
    expect(text).toContain('ruflo proxy config --routing-mode');
  });

  /**
   * "Disable anytime: --local-only" was a single command for a choice with
   * two destinations, and the one it named silently drops the user's own
   * subscription. The disclosure must offer both.
   */
  it('offers both ways off the cloud plane, not just the local one', async () => {
    const text = await disclosureShownOnUnconfirmedCloud();

    expect(text).toContain('ruflo proxy config --passthrough');
    expect(text).toContain('ruflo proxy config --local-only');
  });
});

/**
 * `--passthrough`. Turning cloud routing OFF is a choice of destination:
 * `local` is the user's own backend, `passthrough` is their own Claude
 * subscription (meta-proxy's `DataPlane::Passthrough`, and its own default).
 * Before this, `--local-only` was the only exit, so a user who started on
 * passthrough, enabled cloud, and turned it back off silently lost their
 * subscription — and with it automatic quota failover, which meta-proxy
 * (`routing.rs`) only applies while the plane is passthrough.
 */
describe('proxy config --passthrough', () => {
  const configPath = () => path.join(stateDir, 'proxy-config.toml');
  const planeInFile = () => fs.readFileSync(configPath(), 'utf-8').match(/default_data_plane = "([^"]*)"/)?.[1];

  it('writes default_data_plane = "passthrough" and revokes cloud-routing consent', async () => {
    const configSub = await getConfigSub();
    await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));

    const result = await configSub.action!(ctxWithFlags({ passthrough: true }));

    expect(result?.success).toBe(true);
    expect(planeInFile()).toBe('passthrough');

    const { hasConsent } = await import('../src/funnel/index.js');
    expect(hasConsent('cloud-routing')).toBe(false);
  });

  /** The defect, stated as a round trip: leave passthrough, come back to it. */
  it('restores the subscription plane after a cloud round trip', async () => {
    fs.writeFileSync(configPath(), 'default_data_plane = "passthrough"\n');
    const configSub = await getConfigSub();

    await configSub.action!(ctxWithFlags({ cloud: true, yes: true }));
    expect(planeInFile()).toBe('cloud');
    await configSub.action!(ctxWithFlags({ passthrough: true }));

    expect(planeInFile()).toBe('passthrough');
  });

  it('--local-only still means the local backend, unchanged', async () => {
    const configSub = await getConfigSub();

    await configSub.action!(ctxWithFlags({ localOnly: true }));

    expect(planeInFile()).toBe('local');
  });

  it('refuses more than one plane flag rather than silently picking one', async () => {
    const configSub = await getConfigSub();

    for (const flags of [
      { cloud: true, passthrough: true },
      { localOnly: true, passthrough: true },
      { cloud: true, localOnly: true, passthrough: true },
    ]) {
      const result = await configSub.action!(ctxWithFlags(flags));
      expect(result?.success, JSON.stringify(flags)).toBe(false);
    }
    expect(fs.existsSync(configPath())).toBe(false);
  });

  it('refuses to pin a tier while --passthrough is turning the cloud plane off', async () => {
    const configSub = await getConfigSub();

    const result = await configSub.action!(ctxWithFlags({ passthrough: true, routingMode: 'high' }));

    expect(result?.success).toBe(false);
    expect(fs.existsSync(configPath())).toBe(false);
  });

  it('reports passthrough distinctly from local, not as one "cloud is off" state', async () => {
    const configSub = await getConfigSub();

    await configSub.action!(ctxWithFlags({ passthrough: true }));
    const onPassthrough = await configSub.action!(ctxWithFlags({}));
    await configSub.action!(ctxWithFlags({ localOnly: true }));
    const onLocal = await configSub.action!(ctxWithFlags({}));

    expect((onPassthrough?.data as { plane?: string })?.plane).toBe('passthrough');
    expect((onLocal?.data as { plane?: string })?.plane).toBe('local');
  });

  it('preserves unrelated lines when writing the plane', async () => {
    fs.writeFileSync(configPath(), 'bind = "127.0.0.1:11435"\nrouting_mode = "high"\n');
    const configSub = await getConfigSub();

    await configSub.action!(ctxWithFlags({ passthrough: true }));

    const raw = fs.readFileSync(configPath(), 'utf-8');
    expect(raw).toContain('bind = "127.0.0.1:11435"');
    expect(raw).toContain('routing_mode = "high"');
    expect(raw).toContain('default_data_plane = "passthrough"');
  });
});

describe('plane guidance', () => {
  async function linesFrom(flags: Record<string, unknown>): Promise<string> {
    const lines: string[] = [];
    const { output } = await import('../src/output.js');
    const write = vi.spyOn(output, 'writeln').mockImplementation((line?: string) => {
