      const coverageReport = coverageRouter.parseCoverage({
        'order.ts': {
          lineCoverage: 60,
          branchCoverage: 50,
          functionCoverage: 100,
          statementCoverage: 60,
          uncoveredLines: [3, 4],
          totalLines: 10,
          coveredLines: 6,
        },
      }, 'json');

      const coverageResult = coverageRouter.route(coverageReport);

      // 4. Route to appropriate agent
