/**
 * `security scan` persists its result (commit 7cf3b1084) so the statusline's
 * getSecurityStatus (funnel/local-signals.ts) can reflect real scan state
 * instead of being permanently stuck at PENDING/0 no matter how many real
 * scans run. Black-box against the real built CLI binary — the same
 * invocation shape used to manually verify this feature — rather than
 * reconstructing CommandContext by hand (no existing test in this repo does
 * that for any command; the CLI-binary route is the well-trodden path).
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execFileSync } from 'child_process';
import { mkdtempSync, rmSync, writeFileSync, existsSync, readFileSync, readdirSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { fileURLToPath } from 'url';
import { getSecurityStatus } from '../src/funnel/local-signals.js';

const CLI_BIN = fileURLToPath(new URL('../bin/cli.js', import.meta.url));

let scanTarget: string;

beforeEach(() => {
  // A tiny, throwaway target with no real vulnerabilities and no source
  // files to pattern-scan — keeps the real `npm audit` + secret/code scan
  // fast and deterministic instead of running against this whole repo.
  scanTarget = mkdtempSync(join(tmpdir(), 'security-scan-persist-'));
  writeFileSync(
    join(scanTarget, 'package.json'),
    JSON.stringify({ name: 'security-scan-persist-fixture', version: '1.0.0' }),
  );
});

afterEach(() => {
  rmSync(scanTarget, { recursive: true, force: true });
});

describe('security scan — result persistence (statusline CVE counter wiring)', () => {
  it('getSecurityStatus is PENDING/0 before any scan has run', () => {
    const before = getSecurityStatus(scanTarget);
    expect(before.status).toBe('PENDING');
    expect(before.cvesFixed).toBe(0);
  });

  it('a real scan writes .claude/security-scans/scan-<type>-<depth>.json', () => {
    execFileSync(
      process.execPath,
      [CLI_BIN, 'security', 'scan', '--target', scanTarget, '--depth', 'quick', '--type', 'deps'],
      { encoding: 'utf-8', timeout: 30_000 },
    );
    const outFile = join(scanTarget, '.claude', 'security-scans', 'scan-deps-quick.json');
    expect(existsSync(outFile)).toBe(true);
    const record = JSON.parse(readFileSync(outFile, 'utf-8'));
    expect(record.target).toBe(scanTarget);
    expect(record.depth).toBe('quick');
    expect(record.type).toBe('deps');
    expect(typeof record.timestamp).toBe('string');
    expect(record.summary).toMatchObject({
      critical: expect.any(Number),
      high: expect.any(Number),
      medium: expect.any(Number),
      low: expect.any(Number),
      total: expect.any(Number),
    });
  });

  it('getSecurityStatus reflects the real scan afterward — CLEAN when 0 findings', () => {
    // The scan target is an empty fixture (no deps, no source) so it has 0
    // findings. Pre-#2694 this returned cvesFixed>=1 because the old code
    // counted scan *files* as fixed CVEs; now it reads the scan's findings.
    execFileSync(
      process.execPath,
      [CLI_BIN, 'security', 'scan', '--target', scanTarget, '--depth', 'quick', '--type', 'deps'],
      { encoding: 'utf-8', timeout: 30_000 },
    );
    const after = getSecurityStatus(scanTarget);
    expect(after.cvesFixed).toBe(0);
    expect(after.totalCves).toBe(0);
    expect(after.status).toBe('CLEAN');
  });

  it('repeated scans overwrite the deterministic filename rather than accumulate', () => {
    for (let i = 0; i < 3; i++) {
      execFileSync(
        process.execPath,
        [CLI_BIN, 'security', 'scan', '--target', scanTarget, '--depth', 'quick', '--type', 'deps'],
        { encoding: 'utf-8', timeout: 30_000 },
      );
    }
    const scanDir = join(scanTarget, '.claude', 'security-scans');
    const files = readdirSync(scanDir).filter((f: string) => f.endsWith('.json'));
    expect(files).toEqual(['scan-deps-quick.json']);
  }, 20_000);
});

/**
 * #2931: `security scan`'s hardcoded-secret regex for Stripe/OpenAI-shaped
 * keys (`sk-`/`sk_live_`/`sk_test_`) had two false-negative gaps:
 *
 * 1. Required 20+ chars after the prefix — missed shorter-but-real keys
 *    like `sk-1234567890abcdef` (16 chars).
 * 2. Required a quote literally adjacent to the prefix (`['"]sk-...['"]`)
 *    — missed the extremely common `Authorization: "Bearer sk_live_..."`
 *    shape, where the quote sits next to "Bearer", not the key.
 *
 * Fixed with lookaround boundaries instead of a length floor + quote
 * anchor, so the prefix matches as a standalone token wherever it
 * appears. Black-box against the real built CLI (same pattern as
 * security-scan-persistence.test.ts) — reconstructing CommandContext by
 * hand isn't done anywhere else in this repo's tests.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { execFileSync } from 'child_process';
import { mkdtempSync, rmSync, writeFileSync, readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { fileURLToPath } from 'url';

const CLI_BIN = fileURLToPath(new URL('../bin/cli.js', import.meta.url));

let scanTarget: string;

beforeEach(() => {
  scanTarget = mkdtempSync(join(tmpdir(), 'security-scan-secret-regex-'));
  writeFileSync(
    join(scanTarget, 'package.json'),
    JSON.stringify({ name: 'security-scan-secret-regex-fixture', version: '1.0.0' }),
  );
  writeFileSync(
    join(scanTarget, 'config.ts'),
    [
      "const API_KEY = 'sk-1234567890abcdef';",
      'const headers = { Authorization: "Bearer sk_live_51234567890abcdef" };',
    ].join('\n'),
  );
});

afterEach(() => {
  rmSync(scanTarget, { recursive: true, force: true });
});

describe('#2931 security scan catches shorter/embedded Stripe-shaped secrets', () => {
  it('flags both repro shapes as "API Key (Stripe/OpenAI)" findings', () => {
    // Finding real HIGH-severity secrets makes the command exit non-zero
    // (security.ts: `success: criticalCount === 0 && highCount === 0`) —
    // that's expected here, the persisted report is what this test checks.
    try {
      execFileSync(
        process.execPath,
        [CLI_BIN, 'security', 'scan', '--target', scanTarget, '--depth', 'standard', '--type', 'code'],
        { encoding: 'utf-8', timeout: 30_000 },
      );
    } catch { /* non-zero exit expected when secrets are found */ }

    const outFile = join(scanTarget, '.claude', 'security-scans', 'scan-code-standard.json');
    expect(existsSync(outFile)).toBe(true);
    const record = JSON.parse(readFileSync(outFile, 'utf-8'));

    const stripeFindings = record.findings.filter(
      (f: { description: string }) => f.description === 'API Key (Stripe/OpenAI)',
    );
    // Pre-fix: 0 — neither line matched (one too short, one quote-detached).
    expect(stripeFindings.length).toBe(2);
  });
});

/**
 * Security & Performance Verification Tests
 *
 * Validates all 10 user-facing scenarios from the critical fixes implementation.
 * Mix of:
 * - Behavioral tests: exercise real code paths with hostile inputs
 * - Source-guard tests: regression guards ensuring dangerous patterns don't return
 */

import { describe, it, expect } from 'vitest';

// ============================================================================
// Scenario 1: SQL Injection in Memory Search (CRIT-01)
// ============================================================================
describe('Scenario 1: SQL injection in embeddings search', () => {
  // Source-guard: ensure parameterized queries are used
  it('should use parameterized queries for namespace filtering', async () => {
    const { readFileSync } = await import('fs');
    const source = readFileSync(
      new URL('../src/commands/embeddings.ts', import.meta.url),
      'utf-8'
    );

    // Must NOT have string interpolation in SQL for namespace
    expect(source).not.toMatch(/WHERE.*namespace\s*=\s*'\$\{/);
    expect(source).not.toMatch(/WHERE.*namespace\s*=\s*'"\s*\+/);

    // Must use bind parameters
    expect(source).toContain('.bind(');
    expect(source).toContain('.prepare(');

    // The old vulnerable pattern must be gone
    expect(source).not.toMatch(/namespace\s*=\s*''\s*\+\s*namespace/);
  });

  it('should use parameterized queries for keyword search', async () => {
    const { readFileSync } = await import('fs');
    const source = readFileSync(
      new URL('../src/commands/embeddings.ts', import.meta.url),
      'utf-8'
    );

    // Keyword search must use LIKE with bind parameter, not string concat
    expect(source).toContain('LIKE ?');
    expect(source).not.toMatch(/LIKE\s*'%'\s*\+/);
  });

  // Behavioral: formatEmbedding rejects non-numeric array elements (Finding 2 fix)
  it('formatEmbedding should reject non-numeric embedding values', async () => {
    const { readFileSync } = await import('fs');
    // We can't easily import the function directly (it's not exported),
    // so we test the validation logic inline matching the implementation
    function formatEmbedding(embedding: number[], dimensions: number = 384): string {
      for (let i = 0; i < embedding.length; i++) {
        if (typeof embedding[i] !== 'number' || !Number.isFinite(embedding[i])) {
          throw new Error(`Invalid embedding value at index ${i}: expected finite number, got ${typeof embedding[i]}`);
        }
      }
      const padded = [...embedding];
      while (padded.length < dimensions) padded.push(0);
      if (padded.length > dimensions) padded.length = dimensions;
      return `'[${padded.join(',')}]'::ruvector(${dimensions})`;
    }

    // Valid embedding
    expect(() => formatEmbedding([0.1, 0.2, 0.3], 3)).not.toThrow();

    // SQL injection via crafted string element
    const malicious = [1, 2] as unknown as number[];
    (malicious as unknown[])[1] = '3); DROP TABLE users; --';
    expect(() => formatEmbedding(malicious, 3)).toThrow('Invalid embedding value');

    // NaN and Infinity should be rejected
    expect(() => formatEmbedding([1, NaN, 3], 3)).toThrow('Invalid embedding value');
    expect(() => formatEmbedding([1, Infinity, 3], 3)).toThrow('Invalid embedding value');
    expect(() => formatEmbedding([1, -Infinity, 3], 3)).toThrow('Invalid embedding value');
  });

  // Behavioral: source file must contain the validation guard
  it('import.ts formatEmbedding must validate array elements', async () => {
    const { readFileSync } = await import('fs');
    const source = readFileSync(
      new URL('../src/commands/ruvector/import.ts', import.meta.url),
      'utf-8'
    );

    // Must validate each element is a finite number
    expect(source).toContain('Number.isFinite');
    expect(source).toContain('Invalid embedding value');
  });
});

// ============================================================================
// Scenario 2: Prototype Pollution via JSON (HIGH-03)
// ============================================================================
describe('Scenario 2: Prototype pollution prevention', () => {
  it('safeJsonParse should strip __proto__ keys', async () => {
    const { safeJsonParse } = await import(
      '../../memory/src/json-security.js'
    );

    const malicious = '{"__proto__": {"polluted": true}, "safe": "value"}';
    const result = safeJsonParse(malicious) as Record<string, unknown>;

    expect(result.safe).toBe('value');
    // __proto__ key should not exist as an own property
    expect(Object.hasOwn(result, '__proto__')).toBe(false);
    // Prototype chain should be untouched (standard Object.prototype)
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    // Verify prototype was NOT actually polluted on other objects
    expect(({} as any).polluted).toBeUndefined();
  });

  it('safeJsonParse should strip constructor keys', async () => {
    const { safeJsonParse } = await import(
      '../../memory/src/json-security.js'
    );

    const malicious = '{"constructor": {"prototype": {"pwned": true}}}';
    const result = safeJsonParse(malicious) as Record<string, unknown>;

    // constructor key should not exist as own property
    expect(Object.hasOwn(result, 'constructor')).toBe(false);
    expect(({} as any).pwned).toBeUndefined();
  });

  it('safeJsonParse should handle nested __proto__', async () => {
    const { safeJsonParse } = await import(
      '../../memory/src/json-security.js'
    );

    const nested = '{"a": {"__proto__": {"x": 1}}, "b": 2}';
    const result = safeJsonParse(nested) as any;

    expect(result.b).toBe(2);
    // Nested __proto__ key should not exist as own property
    expect(Object.hasOwn(result.a, '__proto__')).toBe(false);
  });

  it('memory backends must use safeJsonParse, not JSON.parse for row data', async () => {
    const { readFileSync } = await import('fs');

    const backends = [
      '../../memory/src/agentdb-backend.ts',
      '../../memory/src/sqlite-backend.ts',
      '../../memory/src/sqljs-backend.ts',
    ];

    for (const backend of backends) {
      const source = readFileSync(
        new URL(backend, import.meta.url),
        'utf-8'
      );

      // Must import safeJsonParse
      expect(source).toContain('safeJsonParse');

      // Must NOT use raw JSON.parse on row data (tags, metadata, references)
      // Allow JSON.parse for other uses (like config), but row.tags/metadata must be safe
      const dangerousPatterns = [
        /JSON\.parse\(row\.tags/,
        /JSON\.parse\(row\.metadata/,
        /JSON\.parse\(row\.references/,
        /JSON\.parse\(entry\.tags/,
      ];

      for (const pattern of dangerousPatterns) {
        expect(source).not.toMatch(pattern);
      }
    }
  });
});

