/**
 * #2661 invariant 5 — cross-worktree AI job dedup registry.
 * Same repositoryId + HEAD + worker + config → at most one run per
 * freshness window, shared across registry instances (daemons).
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import {
  AiJobDedupRegistry,
  computeAiJobKey,
  hashWorkerConfig,
} from '../../src/services/ai-job-dedup.js';

const PARTS = {
  repositoryId: 'repo-abc',
  head: 'deadbeef',
  workerType: 'audit',
  configHash: 'cfg-1',
};

describe('#2661 — AI job dedup registry', () => {
  let dir: string;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'ai-jobs-test-'));
    delete process.env.RUFLO_AI_DEDUP_DISABLE;
  });

  afterEach(() => {
    delete process.env.RUFLO_AI_DEDUP_DISABLE;
    rmSync(dir, { recursive: true, force: true });
  });

  describe('computeAiJobKey', () => {
    it('is stable for identical parts and distinct when any part changes', () => {
      const base = computeAiJobKey(PARTS);
      expect(computeAiJobKey({ ...PARTS })).toBe(base);
      expect(computeAiJobKey({ ...PARTS, head: 'other' })).not.toBe(base);
      expect(computeAiJobKey({ ...PARTS, workerType: 'optimize' })).not.toBe(base);
      expect(computeAiJobKey({ ...PARTS, repositoryId: 'repo-xyz' })).not.toBe(base);
      expect(computeAiJobKey({ ...PARTS, configHash: 'cfg-2' })).not.toBe(base);
    });
  });

  describe('hashWorkerConfig', () => {
    it('is insensitive to object key order', () => {
      expect(hashWorkerConfig({ a: 1, b: { c: 2, d: 3 } }))
        .toBe(hashWorkerConfig({ b: { d: 3, c: 2 }, a: 1 }));
    });

    it('changes when values change', () => {
      expect(hashWorkerConfig({ a: 1 })).not.toBe(hashWorkerConfig({ a: 2 }));
    });
  });

  describe('freshness', () => {
    it('a recorded success is fresh within the window and shared across instances', () => {
      const key = computeAiJobKey(PARTS);
      const daemonA = new AiJobDedupRegistry({ baseDir: dir });
      const daemonB = new AiJobDedupRegistry({ baseDir: dir });

      expect(daemonA.isFresh(key, 60_000).fresh).toBe(false);
      daemonA.recordSuccess(key, { workerType: 'audit', repositoryId: PARTS.repositoryId, workspace: '/tmp/wt-a' });

      // Sibling worktree's daemon sees the same registry.
      const seen = daemonB.isFresh(key, 60_000);
      expect(seen.fresh).toBe(true);
      expect(seen.lastRunAt).toBeTypeOf('number');
    });

    it('goes stale outside the freshness window', () => {
      const key = computeAiJobKey(PARTS);
      const reg = new AiJobDedupRegistry({ baseDir: dir });
      reg.recordSuccess(key, { workerType: 'audit', repositoryId: PARTS.repositoryId, workspace: '/tmp/wt' });
      expect(reg.isFresh(key, 0).fresh).toBe(false);
    });

    it('a different HEAD is a different job (never deduped)', () => {
      const reg = new AiJobDedupRegistry({ baseDir: dir });
      const keyA = computeAiJobKey(PARTS);
      reg.recordSuccess(keyA, { workerType: 'audit', repositoryId: PARTS.repositoryId, workspace: '/tmp/wt' });
      const keyB = computeAiJobKey({ ...PARTS, head: 'cafebabe' });
      expect(reg.isFresh(keyB, 60_000).fresh).toBe(false);
    });

    it('RUFLO_AI_DEDUP_DISABLE=1 turns dedup off', () => {
      const key = computeAiJobKey(PARTS);
      const reg = new AiJobDedupRegistry({ baseDir: dir });
      reg.recordSuccess(key, { workerType: 'audit', repositoryId: PARTS.repositoryId, workspace: '/tmp/wt' });
      process.env.RUFLO_AI_DEDUP_DISABLE = '1';
      expect(reg.isFresh(key, 60_000).fresh).toBe(false);
    });
  });
});

/**
 * #2661 root-fix — structured per-launch token telemetry.
 *
 * parseClaudePrintJsonEnvelope() is deliberately lenient: `claude --print
 * --output-format json`'s schema isn't a versioned public contract, so any
 * mismatch must degrade to "no usage captured" (null) rather than throw —
 * the caller then falls back to the raw stdout text, preserving today's
 * behavior for every existing worker.
 */

import { describe, it, expect } from 'vitest';
import { parseClaudePrintJsonEnvelope } from '../../src/services/headless-worker-executor.js';

describe('#2661 root-fix — parseClaudePrintJsonEnvelope', () => {
  it('extracts result text, usage, cost, and duration from a well-formed envelope', () => {
    const raw = JSON.stringify({
      type: 'result',
      is_error: false,
      result: 'the actual analysis text',
      total_cost_usd: 0.0031,
      duration_ms: 4521,
      usage: { input_tokens: 1200, output_tokens: 340 },
    });
    const parsed = parseClaudePrintJsonEnvelope(raw);
    expect(parsed).toEqual({
      result: 'the actual analysis text',
      inputTokens: 1200,
      outputTokens: 340,
      costUsd: 0.0031,
      durationMs: 4521,
    });
  });

  it('tolerates camelCase field-name variants', () => {
    const raw = JSON.stringify({
      result: 'text',
      totalCostUsd: 0.01,
      durationMs: 100,
      usage: { inputTokens: 10, outputTokens: 5 },
    });
    const parsed = parseClaudePrintJsonEnvelope(raw);
    expect(parsed).toEqual({ result: 'text', inputTokens: 10, outputTokens: 5, costUsd: 0.01, durationMs: 100 });
  });

  it('returns null for plain (non-JSON) text output — the common case before this feature existed', () => {
    expect(parseClaudePrintJsonEnvelope('Just a plain analysis report, no JSON here.')).toBeNull();
  });

  it('returns null for malformed JSON rather than throwing', () => {
    expect(parseClaudePrintJsonEnvelope('{not: valid, json')).toBeNull();
  });

  it('returns null when the parsed JSON has no `result` field (unexpected schema)', () => {
    expect(parseClaudePrintJsonEnvelope(JSON.stringify({ foo: 'bar' }))).toBeNull();
  });

  it('returns null for an empty string', () => {
    expect(parseClaudePrintJsonEnvelope('')).toBeNull();
    expect(parseClaudePrintJsonEnvelope('   ')).toBeNull();
  });

  it('still returns the result text even when usage/cost/duration are absent', () => {
    const parsed = parseClaudePrintJsonEnvelope(JSON.stringify({ result: 'text only' }));
    expect(parsed).toEqual({
      result: 'text only',
      inputTokens: undefined,
      outputTokens: undefined,
      costUsd: undefined,
      durationMs: undefined,
    });
  });

  it('ignores non-numeric usage fields instead of propagating garbage', () => {
    const raw = JSON.stringify({ result: 'text', usage: { input_tokens: 'not-a-number', output_tokens: null } });
    const parsed = parseClaudePrintJsonEnvelope(raw);
    expect(parsed?.inputTokens).toBeUndefined();
    expect(parsed?.outputTokens).toBeUndefined();
  });

  it('handles a JSON array (not an object) gracefully', () => {
    expect(parseClaudePrintJsonEnvelope('[1,2,3]')).toBeNull();
  });
});

/**
 * distill-oracle.test.ts — unit tests for the tiered `resolved` labeler.
 *
 * Every external boundary is MOCKED: the Tier-1 SSH runner is injected (no real
 * ssh), and the Tier-2 Fable harness is injected (no real claude / spend). The
 * suite asserts:
 *   • the ZERO-EXTERNAL-CALL default path (no opts ⇒ dry-run + structural proxy)
 *   • provenance tagging on every tier (oracle:test-exec / judge:fable / proxy:structural)
 *   • tier fallback order (oracle → fable → proxy) per trajectory
 *   • Tier-1 command construction + remote parameterization (no hard-coded host)
 *   • graceful degradation (probe failure, harness omission → proxy fallback)
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import {
  labelResolved,
  reflectFailures,
  buildOraclePlan,
  hasMechanicalSpec,
  resolveRemote,
  createSshOracleRunner,
  MH_DARWIN_PIN,
  type Trajectory,
  type OracleRunner,
  type CommandExec,
} from '../../src/services/distill-oracle.js';
import type { FableHarness, JudgeResult, ReflectResult } from '../../src/services/fable-harness.js';

// A trajectory with a mechanical spec (SWE-bench shape).
const specTraj = (id: string): Trajectory => ({
  id,
  task: 'Fix the null deref in parser',
  output: 'export function parse(x){ return x?.value ?? null; }',
  testSpec: { failToPass: ['test_parse_null'], repo: 'acme/parser', baseCommit: 'abc123', patch: 'diff --git a b' },
});

// A trajectory with NO mechanical spec (only task/output).
const proseTraj = (id: string, output = 'export function add(a,b){ return a+b; }'): Trajectory => ({
  id,
  task: 'Implement add',
  output,
});

/** A runner spy that records calls and returns canned outcomes. */
function spyRunner(overrides: Partial<OracleRunner> = {}): OracleRunner & { probeCalls: number; evalCalls: number } {
  const r = {
    probeCalls: 0,
    evalCalls: 0,
    async preflight() { r.probeCalls++; return { ok: true, reason: 'ok' }; },
    async runEval() { r.evalCalls++; return { resolved: true, reason: 'FAIL_TO_PASS green' }; },
    ...overrides,
  } as OracleRunner & { probeCalls: number; evalCalls: number };
  return r;
}

/** A harness stub with only the methods labelResolved uses. */
function stubHarness(verdicts: JudgeResult[], reflections: ReflectResult[] = []): FableHarness {
  return {
    isEnabled: () => true,
    judgeBatch: vi.fn(async () => verdicts),
    reflectFailures: vi.fn(async () => reflections),
    getSpentUsd: () => 0,
  } as unknown as FableHarness;
}

describe('labelResolved — ZERO-external-call default path', () => {
  it('labels a spec trajectory via dry-run preflight + structural proxy, touching nothing', async () => {
    const runner = spyRunner();
    const harness = stubHarness([]);
    const [out] = await labelResolved([specTraj('a')], { runner, harness });

    // Provenance is the structural proxy — the honest weakest tier.
    expect(out.resolvedBy).toBe('proxy:structural');
    // The oracle plan is attached as a DRY-RUN preflight (transparency)…
    expect(out.oraclePreflight?.dryRun).toBe(true);
    expect(out.oraclePreflight?.plan.evalCommands.length).toBeGreaterThan(0);
    // …but NEITHER the SSH runner NOR the Fable harness was ever invoked.
    expect(runner.probeCalls).toBe(0);
    expect(runner.evalCalls).toBe(0);
    expect(harness.judgeBatch).not.toHaveBeenCalled();
    expect(typeof out.resolved).toBe('boolean');
    expect(typeof out.resolvedConfidence).toBe('number');
  });

  it('labels a prose trajectory via structural proxy only', async () => {
    const [good] = await labelResolved([proseTraj('g')]);
    expect(good.resolvedBy).toBe('proxy:structural');
    expect(good.resolved).toBe(true); // clean code passes structural signals

    const [bad] = await labelResolved([proseTraj('b', 'I cannot help with that.')]);
    expect(bad.resolvedBy).toBe('proxy:structural');
    expect(bad.resolved).toBe(false); // refusal → not resolved
  });

  it('preserves passthrough fields and ids', async () => {
    const t: Trajectory = { id: 'keep', task: 'x', output: 'export const y=1;', extra: 42 };
    const [out] = await labelResolved([t]);
    expect(out.id).toBe('keep');
    expect((out as { extra?: number }).extra).toBe(42);
  });
});

describe('labelResolved — Tier 1 mechanical oracle (execute)', () => {
  it('runs the real eval and tags oracle:test-exec on success', async () => {
    const runner = spyRunner();
    const [out] = await labelResolved([specTraj('a')], { remote: 'testhost', execute: true, runner });
    expect(out.resolvedBy).toBe('oracle:test-exec');
    expect(out.resolved).toBe(true);
    expect(out.resolvedConfidence).toBe(1);
    expect(out.oraclePreflight?.dryRun).toBe(false);
    expect(runner.probeCalls).toBe(1);
    expect(runner.evalCalls).toBe(1);
  });

  it('propagates a failing eval as resolved=false with oracle provenance', async () => {
    const runner = spyRunner({ async runEval() { return { resolved: false, reason: 'still red' }; } });
    const [out] = await labelResolved([specTraj('a')], { remote: 'testhost', execute: true, runner });
    expect(out.resolvedBy).toBe('oracle:test-exec');
    expect(out.resolved).toBe(false);
    expect(out.resolvedReason).toContain('still red');
  });

  it('falls through to the proxy when the preflight probe fails (non-fatal)', async () => {
    const runner = spyRunner({ async preflight() { return { ok: false, reason: 'ssh unreachable' }; } });
    const [out] = await labelResolved([specTraj('a')], { remote: 'testhost', execute: true, runner });
    expect(out.resolvedBy).toBe('proxy:structural'); // probe failed → fell through
    expect(runner.evalCalls).toBe(0); // never ran the eval after a failed probe
    expect(out.oraclePreflight?.probe?.ok).toBe(false);
    expect(out.oraclePreflight?.fellThroughBecause).toContain('preflight failed');
  });
});

describe('labelResolved — Tier 2 Fable judge (opt-in + budget)', () => {
  it('judges prose trajectories via the harness and tags judge:fable', async () => {
    const harness = stubHarness([{ id: 'g', resolved: true, confidence: 0.77, reason: 'looks correct' }]);
    const [out] = await labelResolved([proseTraj('g')], { fableJudge: true, maxBudgetUsd: 1, harness });
