/**
 * #2661 root-fix — one elected repository-level supervisor.
 *
 * Exactly one daemon per repositoryId should own the recurring AI-worker
 * schedule at a time. Election must never let two live daemons both believe
 * they are supervisor, must take over promptly when the current supervisor
 * dies, and must never downgrade a healthy supervisor just because another
 * process asked.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync, symlinkSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { RepoSupervisorRegistry, SUPERVISOR_STALE_MS } from '../../src/services/repo-supervisor.js';

describe('#2661 root-fix — RepoSupervisorRegistry', () => {
  let dir: string;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'repo-supervisor-test-'));
  });

  afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
    vi.useRealTimers();
  });

  const makeRegistry = () => new RepoSupervisorRegistry({ baseDir: dir });

  it('the first daemon to elect for a repository becomes supervisor', async () => {
    const registry = makeRegistry();
    const result = await registry.electOrRenew('repo-1', '/tmp/wt-1');
    expect(result.isSupervisor).toBe(true);
    expect(result.record?.pid).toBe(process.pid);
    expect(registry.isSupervisor('repo-1', '/tmp/wt-1')).toBe(true);
  });

  it('a second (different) worktree does NOT become supervisor while the first is healthy', async () => {
    const registry = makeRegistry();
    await registry.electOrRenew('repo-1', '/tmp/wt-1');

    // Same test process (same real PID) attempting election under a
    // DIFFERENT worktreeRoot — isSupervisor() distinguishes by worktreeRoot,
    // not just PID, so this exercises the "never overwrite a healthy
    // supervisor" branch even though the PID matches.
    const second = await registry.electOrRenew('repo-1', '/tmp/wt-2');
    expect(second.isSupervisor).toBe(false);
    expect(second.record?.worktreeRoot).toBe('/tmp/wt-1'); // unchanged
    expect(registry.isSupervisor('repo-1', '/tmp/wt-1')).toBe(true); // still supervisor
    expect(registry.isSupervisor('repo-1', '/tmp/wt-2')).toBe(false);
  });

  it('renewing as the current supervisor keeps supervisor status (never a downgrade)', async () => {
    const registry = makeRegistry();
    const first = await registry.electOrRenew('repo-1', '/tmp/wt-1');
    expect(first.isSupervisor).toBe(true);

    const renewed = await registry.electOrRenew('repo-1', '/tmp/wt-1');
    expect(renewed.isSupervisor).toBe(true);
    expect(renewed.record!.electedAt).toBe(first.record!.electedAt); // election time unchanged, only heartbeat renews
  });

  it('leases for different repositories elect independently', async () => {
    const registry = makeRegistry();
    const a = await registry.electOrRenew('repo-1', '/tmp/wt-1');
    const b = await registry.electOrRenew('repo-2', '/tmp/wt-2');
    expect(a.isSupervisor).toBe(true);
    expect(b.isSupervisor).toBe(true);
  });

  it('release() clears supervisor status so another worktree can take over immediately', async () => {
    const registry = makeRegistry();
    await registry.electOrRenew('repo-1', '/tmp/wt-1');
    expect(registry.isSupervisor('repo-1', '/tmp/wt-1')).toBe(true);

    await registry.release('repo-1', '/tmp/wt-1');
    expect(registry.isSupervisor('repo-1', '/tmp/wt-1')).toBe(false);
    expect(registry.getRecord('repo-1')).toBeNull();
  });

  it('release() only clears a record this exact worktree owns, never someone else\'s', async () => {
    const registry = makeRegistry();
    await registry.electOrRenew('repo-1', '/tmp/wt-1');
    // A different (non-owning) worktree attempting release must be a no-op.
    await registry.release('repo-1', '/tmp/wt-2');
    expect(registry.isSupervisor('repo-1', '/tmp/wt-1')).toBe(true);
  });

  it('a supervisor record with a dead PID is treated as stale — takeover is allowed', async () => {
    const registry = makeRegistry();
    const supDir = join(dir, 'supervisors');
    mkdirSync(supDir, { recursive: true });
    writeFileSync(
      join(supDir, 'repo-1.json'),
      JSON.stringify({ worktreeRoot: '/tmp/wt-dead', pid: 999999, electedAt: Date.now(), lastHeartbeat: Date.now() }),
    );
    expect(registry.isSupervisor('repo-1', '/tmp/wt-dead')).toBe(false); // dead pid never reads as supervisor

    const result = await registry.electOrRenew('repo-1', '/tmp/wt-live');
    expect(result.isSupervisor).toBe(true);
    expect(result.record?.worktreeRoot).toBe('/tmp/wt-live');
  });

  it('a supervisor record whose heartbeat is older than SUPERVISOR_STALE_MS allows takeover, even with a live PID', async () => {
    const registry = makeRegistry();
    const supDir = join(dir, 'supervisors');
    mkdirSync(supDir, { recursive: true });
    // Use OUR OWN pid so isProcessAlive() would say "alive" — staleness must
    // still win on the heartbeat age alone.
    writeFileSync(
      join(supDir, 'repo-1.json'),
      JSON.stringify({
        worktreeRoot: '/tmp/wt-old',
        pid: process.pid,
        electedAt: Date.now() - SUPERVISOR_STALE_MS - 1000,
        lastHeartbeat: Date.now() - SUPERVISOR_STALE_MS - 1000,
      }),
    );
    const result = await registry.electOrRenew('repo-1', '/tmp/wt-new');
    expect(result.isSupervisor).toBe(true);
    expect(result.record?.worktreeRoot).toBe('/tmp/wt-new');
  });

  it('getRecord() returns null once the record is stale, without mutating anything', async () => {
    const registry = makeRegistry();
    const supDir = join(dir, 'supervisors');
    mkdirSync(supDir, { recursive: true });
    writeFileSync(
      join(supDir, 'repo-1.json'),
      JSON.stringify({ worktreeRoot: '/tmp/wt-old', pid: 999999, electedAt: Date.now(), lastHeartbeat: Date.now() }),
    );
    expect(registry.getRecord('repo-1')).toBeNull();
  });

  it('rejects a symlinked supervisor file (invariant 9) and fails closed (not supervisor)', async () => {
    const registry = makeRegistry();
    const supDir = join(dir, 'supervisors');
    mkdirSync(supDir, { recursive: true });
    const real = join(dir, 'evil.json');
    writeFileSync(real, JSON.stringify({ worktreeRoot: '/x', pid: 1, electedAt: 0, lastHeartbeat: 0 }));
    symlinkSync(real, join(supDir, 'repo-1.json'));

    const result = await registry.electOrRenew('repo-1', '/tmp/wt-1');
    expect(result.isSupervisor).toBe(false); // fails closed, never overwrites/uses a symlinked path
  });
});

/**
 * ADR-174 Milestone 3 — daemon wiring for the consolidate worker.
 *
 * The daemon previously wrote a hardcoded { patternsConsolidated: 0 } stub
 * every 30 minutes and touched no database — the root cause of the
 * intelligence tables (reasoning_patterns, episodes, causal_edges) staying
 * empty. `runConsolidateWorker()` now calls the frozen M1 service
 * (memory-distillation.ts's runDistillation) against `.swarm/memory.db` and
 * persists the REAL report to .claude-flow/metrics/consolidation.json.
 *
 * These tests prove:
 *  - the worker actually increases reasoning_patterns row count
 *  - it writes non-zero, real metrics (not the old hardcoded zeros)
 *  - running it twice is idempotent (distill_state cursor drains once)
 *  - the RUFLO_DAEMON_NO_DISTILL opt-out skips distillation without crashing
 *  - a corrupt/unusable DB is reported via metrics, never thrown
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, mkdirSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { WorkerDaemon } from '../../src/services/worker-daemon.js';

let Database: any;
let haveNative = false;
try {
  Database = (await import('better-sqlite3')).default;
  haveNative = true;
} catch {
  haveNative = false;
}

/** Same schema/fixtures as __tests__/memory-distillation.test.ts. */
function seedDb(dbPath: string): void {
  const db = new Database(dbPath);
  db.exec(`CREATE TABLE memory_entries (
    id TEXT PRIMARY KEY, key TEXT, namespace TEXT DEFAULT 'default',
    content TEXT, embedding TEXT, status TEXT DEFAULT 'active'
  )`);
  db.exec(`CREATE TABLE episodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, session_id TEXT NOT NULL,
    task TEXT NOT NULL, input TEXT, output TEXT, critique TEXT, reward REAL DEFAULT 0,
    success BOOLEAN DEFAULT 0, latency_ms INTEGER, tokens_used INTEGER, tags TEXT,
    metadata JSON, created_at INTEGER DEFAULT 0
  )`);
  db.exec(`CREATE TABLE reasoning_patterns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER DEFAULT 0, task_type TEXT NOT NULL,
    approach TEXT NOT NULL, success_rate REAL NOT NULL DEFAULT 0, uses INTEGER DEFAULT 0,
    avg_reward REAL DEFAULT 0, tags TEXT, metadata TEXT
  )`);
  db.exec(`CREATE TABLE pattern_embeddings (
    pattern_id INTEGER PRIMARY KEY, embedding BLOB NOT NULL
  )`);
  db.exec(`CREATE TABLE causal_edges (
    id INTEGER PRIMARY KEY AUTOINCREMENT, from_memory_id INTEGER NOT NULL, from_memory_type TEXT NOT NULL,
    to_memory_id INTEGER NOT NULL, to_memory_type TEXT NOT NULL, similarity REAL DEFAULT 0,
    confidence REAL DEFAULT 0.5, mechanism TEXT, metadata JSON, created_at INTEGER DEFAULT 0
  )`);

  const ins = db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)');
  const vec = (seed: number) => JSON.stringify(Array.from({ length: 8 }, (_, i) => Math.sin(seed + i)));
  ins.run('c1', 'k1', 'commands', 'refactor the auth module in src/auth.ts', vec(1));
  ins.run('c2', 'k2', 'commands', 'add validation to src/api/handler.ts', vec(2));
  ins.run('c3', 'k3', 'commands', 'optimize the query in src/db/store.ts', vec(3));
  ins.run('f1', 'k4', 'feedback', JSON.stringify({ taskId: 'edit-a', success: true }), vec(4));
  ins.run('f2', 'k5', 'feedback', JSON.stringify({ taskId: 'edit-b', success: false }), vec(5));
  db.close();
}

function reasoningPatternCount(dbPath: string): number {
  const db = new Database(dbPath, { readonly: true });
  const c = (db.prepare('SELECT COUNT(*) AS c FROM reasoning_patterns').get() as { c: number }).c;
  db.close();
  return c;
}

describe.skipIf(!haveNative)('WorkerDaemon consolidate worker — ADR-174 M3 wiring', () => {
  let tempDir: string;
  let dbPath: string;
  let metricsFile: string;

  beforeEach(() => {
    tempDir = mkdtempSync(join(tmpdir(), 'worker-daemon-consolidate-'));
    mkdirSync(join(tempDir, '.claude-flow', 'logs'), { recursive: true });
    mkdirSync(join(tempDir, '.swarm'), { recursive: true });
    dbPath = join(tempDir, '.swarm', 'memory.db');
    metricsFile = join(tempDir, '.claude-flow', 'metrics', 'consolidation.json');
    delete process.env.RUFLO_DAEMON_NO_DISTILL;
  });

  afterEach(() => {
    delete process.env.RUFLO_DAEMON_NO_DISTILL;
    rmSync(tempDir, { recursive: true, force: true });
  });

  it('distills memory_entries into reasoning_patterns and writes real (non-zero) metrics', async () => {
    seedDb(dbPath);
    expect(reasoningPatternCount(dbPath)).toBe(0);

    const daemon = new WorkerDaemon(tempDir);
    const result = await (daemon as any).runConsolidateWorker();

    // The worker must have actually written new rows, not a stub.
    expect(reasoningPatternCount(dbPath)).toBeGreaterThan(0);

    // Metrics file reflects the real report — not the old hardcoded zeros.
    expect(existsSync(metricsFile)).toBe(true);
    const metrics = JSON.parse(readFileSync(metricsFile, 'utf-8'));
    expect(metrics.distillationEnabled).toBe(true);
    expect(metrics.patternsConsolidated).toBeGreaterThan(0);
    expect(metrics.memoryCleaned).toBeGreaterThan(0);
    expect(metrics.episodes).toBeGreaterThan(0);

    // Same values surfaced on the returned worker result (used by
    // `daemon trigger -w consolidate` to print output.printJson(result.output)).
    expect((result as any).patternsConsolidated).toBe(metrics.patternsConsolidated);
  });

  it('is idempotent — a second tick processes nothing new (cursor-driven)', async () => {
    seedDb(dbPath);
    const daemon = new WorkerDaemon(tempDir);

    const first = await (daemon as any).runConsolidateWorker() as any;
    const patternsAfterFirst = reasoningPatternCount(dbPath);
    expect(patternsAfterFirst).toBeGreaterThan(0);

    const second = await (daemon as any).runConsolidateWorker() as any;

    // No new source rows since the first tick -> nothing new processed.
    expect(second.memoryCleaned).toBe(0);
    expect(reasoningPatternCount(dbPath)).toBe(patternsAfterFirst);
  });

  it('bounds each tick via maxEntries so a large backlog cannot be scanned in one call', async () => {
    seedDb(dbPath);
    const daemon = new WorkerDaemon(tempDir);
    // Sanity: the tick-bound constant used by the worker must be a small,
    // finite number — this is what keeps the worker well under
    // DEFAULT_WORKER_TIMEOUT_MS (16 min) regardless of backlog size.
    const result = await (daemon as any).runConsolidateWorker() as any;
    expect(result.memoryCleaned).toBeLessThanOrEqual(1000);
  });

  it('honors RUFLO_DAEMON_NO_DISTILL=1 and skips distillation entirely', async () => {
    seedDb(dbPath);
    process.env.RUFLO_DAEMON_NO_DISTILL = '1';

    const daemon = new WorkerDaemon(tempDir);
    const result = await (daemon as any).runConsolidateWorker() as any;

    expect(result.distillationEnabled).toBe(false);
    expect(reasoningPatternCount(dbPath)).toBe(0);

    const metrics = JSON.parse(readFileSync(metricsFile, 'utf-8'));
    expect(metrics.distillationEnabled).toBe(false);
    expect(metrics.patternsConsolidated).toBe(0);
  });

  it('never throws on a missing/absent memory DB — reports skipped in metrics', async () => {
    // No .swarm/memory.db written at all.
    const daemon = new WorkerDaemon(tempDir);
    await expect((daemon as any).runConsolidateWorker()).resolves.toBeDefined();

    const metrics = JSON.parse(readFileSync(metricsFile, 'utf-8'));
    expect(metrics.distillationEnabled).toBe(true);
    expect(metrics.skipped).toBeTruthy();
    expect(metrics.patternsConsolidated).toBe(0);
  });

  it('never throws on a corrupt memory DB — reports corrupt in metrics', async () => {
    // Write garbage bytes where a sqlite DB is expected.
    writeFileSync(dbPath, 'not a real sqlite file — corrupt on purpose');

    const daemon = new WorkerDaemon(tempDir);
    await expect((daemon as any).runConsolidateWorker()).resolves.toBeDefined();

    const metrics = JSON.parse(readFileSync(metricsFile, 'utf-8'));
    expect(metrics.distillationEnabled).toBe(true);
    expect(metrics.patternsConsolidated).toBe(0);
  });

  it('is dispatched via runWorkerLogic for the "consolidate" worker type (back-compat wiring)', async () => {
    seedDb(dbPath);
    const daemon = new WorkerDaemon(tempDir);
    const output = await (daemon as any).runWorkerLogic({ type: 'consolidate' } as any);
    expect((output as any).distillationEnabled).toBe(true);
    expect(reasoningPatternCount(dbPath)).toBeGreaterThan(0);
  });
});

/**
 * WorkerDaemon Resource Thresholds Tests
 *
 * Validates CPU-proportional defaults, config priority chain,
 * state persistence, resource gating, and input validation.
 *
 * Uses real temp directories for filesystem isolation.
 * All resource gating tests use explicit constructor config
 * to avoid host-machine dependency.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { WorkerDaemon } from '../../src/services/worker-daemon.js';
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { tmpdir, cpus } from 'os';

describe('WorkerDaemon resource thresholds', () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = mkdtempSync(join(tmpdir(), 'worker-daemon-test-'));
    mkdirSync(join(tempDir, '.claude-flow', 'logs'), { recursive: true });
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.doUnmock('os');
    rmSync(tempDir, { recursive: true, force: true });
    // Clean up signal listeners to prevent MaxListenersExceededWarning
    process.removeAllListeners('SIGTERM');
    process.removeAllListeners('SIGINT');
    process.removeAllListeners('SIGHUP');
  });

  // =========================================================================
  // Smart CPU-proportional defaults
  // =========================================================================
  describe('smart CPU-proportional defaults', () => {
    it('should compute maxCpuLoad as max(cpuCount * 0.8, 2.0)', () => {
      const daemon = new WorkerDaemon(tempDir);
      const config = daemon.getStatus().config;

      const cpuCount = cpus().length || 1;
      const expected = Math.max(cpuCount * 0.8, 2.0);

      expect(config.resourceThresholds.maxCpuLoad).toBeCloseTo(expected, 1);
    });

    it('should always be at least 2.0 regardless of CPU count', () => {
      const daemon = new WorkerDaemon(tempDir);
      const config = daemon.getStatus().config;

      expect(config.resourceThresholds.maxCpuLoad).toBeGreaterThanOrEqual(2.0);
    });

    it('should scale above 2.0 on multi-core machines', () => {
      const cpuCount = cpus().length;
      if (cpuCount <= 3) return; // skip on small machines

      const daemon = new WorkerDaemon(tempDir);
      const config = daemon.getStatus().config;

      expect(config.resourceThresholds.maxCpuLoad).toBeGreaterThan(2.0);
    });

    it('should use platform-aware default for minFreeMemoryPercent', () => {
      const daemon = new WorkerDaemon(tempDir);
      const config = daemon.getStatus().config;

      const expectedMinFreeMem = process.platform === 'darwin' ? 5 : 10;
      expect(config.resourceThresholds.minFreeMemoryPercent).toBe(expectedMinFreeMem);
    });
  });

  // =========================================================================
  // Resource gating via canRunWorker
  // =========================================================================
  describe('resource gating', () => {
    it('should allow workers when CPU load is below threshold', async () => {
      // Explicitly set threshold — decoupled from host machine
      const daemon = new WorkerDaemon(tempDir, {
        resourceThresholds: { maxCpuLoad: 9.6, minFreeMemoryPercent: 20 },
      });

      vi.doMock('os', () => ({
        default: {
          loadavg: () => [3.5, 3.0, 2.5],
          totalmem: () => 16e9,
          freemem: () => 8e9, // 50% free
        },
        loadavg: () => [3.5, 3.0, 2.5],
        totalmem: () => 16e9,
        freemem: () => 8e9,
      }));

      const result = await (daemon as any).canRunWorker();
      expect(result.allowed).toBe(true);
    });

    it('should block workers when CPU load exceeds threshold', async () => {
      const daemon = new WorkerDaemon(tempDir, {
