  // =========================================================================
  // #2356 — Self-terminating lifecycle (TTL + idle shutdown)
  // Caps how long a forgotten daemon can keep dispatching headless worker
  // sweeps. Precedence: constructor arg > config.json (seconds) > env
  // (RUFLO_DAEMON_TTL_SECS / RUFLO_DAEMON_IDLE_SECS) > built-in default.
  // =========================================================================
  describe('self-terminating lifecycle (ttl/idle)', () => {
    const TTL_ENV = 'RUFLO_DAEMON_TTL_SECS';
    const IDLE_ENV = 'RUFLO_DAEMON_IDLE_SECS';
    let savedTtl: string | undefined;
    let savedIdle: string | undefined;

    beforeEach(() => {
      savedTtl = process.env[TTL_ENV];
      savedIdle = process.env[IDLE_ENV];
      delete process.env[TTL_ENV];
      delete process.env[IDLE_ENV];
    });

    afterEach(() => {
      if (savedTtl === undefined) delete process.env[TTL_ENV]; else process.env[TTL_ENV] = savedTtl;
      if (savedIdle === undefined) delete process.env[IDLE_ENV]; else process.env[IDLE_ENV] = savedIdle;
    });

    it('defaults ttlMs to 12h and idleShutdownMs to 30m (#2834)', () => {
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(12 * 60 * 60 * 1000);
      expect(config.idleShutdownMs).toBe(30 * 60 * 1000);
    });

    it('honors RUFLO_DAEMON_TTL_SECS env override (seconds → ms)', () => {
      process.env[TTL_ENV] = '3600';
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(3600 * 1000);
    });

    it('honors an explicit RUFLO_DAEMON_TTL_SECS=0 as "disabled" (not falling back to default)', () => {
      process.env[TTL_ENV] = '0';
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(0);
    });

    it('falls back to default for an invalid/negative env value', () => {
      process.env[TTL_ENV] = '-5';
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(12 * 60 * 60 * 1000);
    });

    it('honors RUFLO_DAEMON_IDLE_SECS env override', () => {
      process.env[IDLE_ENV] = '7200';
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.idleShutdownMs).toBe(7200 * 1000);
    });

    it('reads daemon.ttlSecs / daemon.idleSecs from config.json (seconds → ms)', () => {
      const configFile = join(tempDir, '.claude-flow', 'config.json');
      writeFileSync(configFile, JSON.stringify({
        'daemon.ttlSecs': 1800,
        'daemon.idleSecs': 900,
      }));
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(1800 * 1000);
      expect(config.idleShutdownMs).toBe(900 * 1000);
    });

    it('honors config.json daemon.ttlSecs=0 as disabled', () => {
      const configFile = join(tempDir, '.claude-flow', 'config.json');
      writeFileSync(configFile, JSON.stringify({ 'daemon.ttlSecs': 0 }));
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(0);
    });

    it('prefers constructor arg over config.json and env', () => {
      process.env[TTL_ENV] = '3600';
      const configFile = join(tempDir, '.claude-flow', 'config.json');
      writeFileSync(configFile, JSON.stringify({ 'daemon.ttlSecs': 1800 }));
      const config = new WorkerDaemon(tempDir, { ttlMs: 60_000 }).getStatus().config;
      expect(config.ttlMs).toBe(60_000);
    });

    it('prefers config.json over env', () => {
      process.env[TTL_ENV] = '3600';
      const configFile = join(tempDir, '.claude-flow', 'config.json');
      writeFileSync(configFile, JSON.stringify({ 'daemon.ttlSecs': 1800 }));
      const config = new WorkerDaemon(tempDir).getStatus().config;
      expect(config.ttlMs).toBe(1800 * 1000);
    });

    it('arms the lifecycle monitor even when ttl/idle are disabled (#2661 workspace-removal check)', () => {
      const daemon = new WorkerDaemon(tempDir, { ttlMs: 0, idleShutdownMs: 0 });
      // Pre-#2661 this was a no-op with both limits at 0. The monitor now
      // always runs so a daemon whose worktree is deleted shuts itself
      // down; ttl/idle remain opt-in inside the shared predicate.
      (daemon as any).startLifecycleMonitor();
      expect((daemon as any).lifecycleTimer).toBeDefined();
      // But with the workspace present and both limits off, the predicate
      // must not request a shutdown.
      expect((daemon as any).lifecycleShutdownReason(Date.now())).toBeNull();
      clearInterval((daemon as any).lifecycleTimer);
      (daemon as any).lifecycleTimer = undefined;
    });

    it('arms (and can clear) the lifecycle monitor when a TTL is set', () => {
      const daemon = new WorkerDaemon(tempDir, { ttlMs: 60_000, idleShutdownMs: 0 });
      (daemon as any).startLifecycleMonitor();
      expect((daemon as any).lifecycleTimer).toBeDefined();
      // The monitor timer must be unref'd so it never keeps the process alive.
      clearInterval((daemon as any).lifecycleTimer);
      (daemon as any).lifecycleTimer = undefined;
    });
  });
});

/**
 * #2661 root-fix — worktree leases.
 *
 * A lease is how a worktree's daemon says "I'm alive" to the rest of the
 * repository. It must expire (15 min, no heartbeat) so a removed worktree
 * or a crashed daemon becomes ineligible instead of lingering forever.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync, symlinkSync, writeFileSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { WorkspaceLeaseRegistry, LEASE_TTL_MS } from '../../src/services/workspace-lease.js';

describe('#2661 root-fix — WorkspaceLeaseRegistry', () => {
  let dir: string;

  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'workspace-lease-test-'));
  });

  afterEach(() => {
    rmSync(dir, { recursive: true, force: true });
    vi.useRealTimers();
  });

  const makeRegistry = () => new WorkspaceLeaseRegistry({ baseDir: dir });

  it('ships the 15-minute TTL from the issue spec', () => {
    expect(LEASE_TTL_MS).toBe(15 * 60 * 1000);
  });

  it('a freshly-heartbeated lease is active', async () => {
    const registry = makeRegistry();
    await registry.heartbeat('repo-1', '/tmp/wt-1');
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(true);
    expect(registry.listActive('repo-1')).toHaveLength(1);
    expect(registry.listActive('repo-1')[0].worktreeRoot).toBe('/tmp/wt-1');
  });

  it('a worktree with no lease is not active', () => {
    const registry = makeRegistry();
    expect(registry.isLeaseActive('repo-1', '/tmp/never-registered')).toBe(false);
  });

  it('multiple worktrees of the same repository all show as active', async () => {
    const registry = makeRegistry();
    await registry.heartbeat('repo-1', '/tmp/wt-1');
    await registry.heartbeat('repo-1', '/tmp/wt-2');
    await registry.heartbeat('repo-1', '/tmp/wt-3');
    const active = registry.listActive('repo-1');
    expect(active).toHaveLength(3);
    expect(active.map((l) => l.worktreeRoot).sort()).toEqual(['/tmp/wt-1', '/tmp/wt-2', '/tmp/wt-3']);
  });

  it('leases for different repositories do not leak into each other', async () => {
    const registry = makeRegistry();
    await registry.heartbeat('repo-1', '/tmp/wt-1');
    await registry.heartbeat('repo-2', '/tmp/wt-2');
    expect(registry.listActive('repo-1')).toHaveLength(1);
    expect(registry.listActive('repo-2')).toHaveLength(1);
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-2')).toBe(false);
  });

  it('release() removes the lease immediately, not just letting it expire', async () => {
    const registry = makeRegistry();
    await registry.heartbeat('repo-1', '/tmp/wt-1');
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(true);
    await registry.release('repo-1', '/tmp/wt-1');
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(false);
  });

  it('a lease older than the 15-minute TTL is no longer active', async () => {
    const registry = makeRegistry();
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-01-01T00:00:00Z'));
    await registry.heartbeat('repo-1', '/tmp/wt-1');
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(true);

    vi.setSystemTime(new Date('2026-01-01T00:16:00Z')); // 16 minutes later
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(false);
    expect(registry.listActive('repo-1')).toHaveLength(0);
  });

  it('a heartbeat renews the TTL window', async () => {
    const registry = makeRegistry();
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-01-01T00:00:00Z'));
    await registry.heartbeat('repo-1', '/tmp/wt-1');

    vi.setSystemTime(new Date('2026-01-01T00:14:00Z')); // just under TTL
    await registry.heartbeat('repo-1', '/tmp/wt-1'); // renew

    vi.setSystemTime(new Date('2026-01-01T00:20:00Z')); // 6 min after renewal, 20 after registration
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-1')).toBe(true);
  });

  it('a lease whose owning PID is dead is treated as inactive even within the TTL window', async () => {
    const registry = makeRegistry();
    // Write a lease record directly with a PID that (almost certainly) does
    // not exist, bypassing heartbeat()'s use of the real process.pid.
    const leasesDir = join(dir, 'leases');
    const crypto = await import('crypto');
    const key = crypto.createHash('sha256').update('/tmp/wt-dead').digest('hex').slice(0, 16);
    const { mkdirSync } = await import('fs');
    mkdirSync(leasesDir, { recursive: true });
    writeFileSync(
      join(leasesDir, 'repo-1.json'),
      JSON.stringify({ version: 1, leases: { [key]: { worktreeRoot: '/tmp/wt-dead', pid: 999999, registeredAt: Date.now(), lastHeartbeat: Date.now() } } }),
    );
    expect(registry.isLeaseActive('repo-1', '/tmp/wt-dead')).toBe(false);
  });

  it('rejects a symlinked lease file (invariant 9)', async () => {
    const registry = makeRegistry();
    const { mkdirSync } = await import('fs');
    const leasesDir = join(dir, 'leases');
    mkdirSync(leasesDir, { recursive: true });
    const real = join(dir, 'evil.json');
    writeFileSync(real, JSON.stringify({ version: 1, leases: {} }));
    symlinkSync(real, join(leasesDir, 'repo-1.json'));

    // heartbeat() is best-effort and must not throw even though the write
    // path refuses the symlinked target.
    await expect(registry.heartbeat('repo-1', '/tmp/wt-1')).resolves.toBeUndefined();
  });
});

/**
 * Integration test for ADR-096 Phase 2: session-tools wired to vault.
 *
 * Exercises the full save → on-disk → load round-trip across both modes
 * (plaintext + encrypted) AND the migration path (legacy plaintext file
 * still readable after the encryption gate flips on).
 *
 * The vault primitives themselves are unit-tested in encryption-vault.test.ts.
 * This file pins the contract that session-tools honors the env-var gate
 * AND that the magic-byte format is what actually lands on disk.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomBytes } from 'node:crypto';

import { sessionTools } from '../src/mcp-tools/session-tools.js';
import { MAGIC, isEncryptedBlob } from '../src/encryption/vault.js';

// Per-test working directory so the in-process getProjectCwd() points at
// a clean tree. session-tools uses process.cwd() (via getProjectCwd) for
// the sessions dir.
const SAVED_ENV: Record<string, string | undefined> = {};
function saveEnv(...names: string[]) {
  for (const n of names) SAVED_ENV[n] = process.env[n];
}
function restoreEnv() {
  for (const [n, v] of Object.entries(SAVED_ENV)) {
    if (v === undefined) delete process.env[n];
    else process.env[n] = v;
  }
}

const sessionSaveTool = sessionTools.find(t => t.name === 'session_save')!;
const sessionRestoreTool = sessionTools.find(t => t.name === 'session_restore')!;
const sessionListTool = sessionTools.find(t => t.name === 'session_list')!;

function pickSessionFile(workdir: string): string {
  const dir = join(workdir, '.claude-flow', 'sessions');
  // Find the lone JSON file the save tool produces (filename is
  // `session-<ts>-<rand>.json`).
  const fs = readFileSync; void fs; // (silence unused-import linters)
  const { readdirSync } = require('node:fs') as typeof import('node:fs');
  const files = readdirSync(dir).filter(f => f.endsWith('.json'));
  expect(files.length).toBe(1);
  return join(dir, files[0]);
}

async function runSave(name: string) {
  return sessionSaveTool.handler({ name } as Record<string, unknown>);
}
async function runRestore(sessionId: string) {
  return sessionRestoreTool.handler({ sessionId } as Record<string, unknown>);
}

describe('session-tools encryption-at-rest (ADR-096 Phase 2)', () => {
  let workdir: string;
  let cwdSpy: ReturnType<typeof vi.spyOn> | null = null;

  beforeEach(() => {
    saveEnv('CLAUDE_FLOW_ENCRYPT_AT_REST', 'CLAUDE_FLOW_ENCRYPTION_KEY');
    workdir = mkdtempSync(join(tmpdir(), 'session-enc-'));
    // Pin process.cwd() so session-tools writes into our temp dir
    cwdSpy = vi.spyOn(process, 'cwd').mockReturnValue(workdir);
  });

  afterEach(() => {
    cwdSpy?.mockRestore();
    rmSync(workdir, { recursive: true, force: true });
    restoreEnv();
  });

  describe('encryption disabled (legacy plaintext)', () => {
    beforeEach(() => {
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
    });

    it('writes plaintext JSON to disk', async () => {
      const r = (await runSave('audit-test')) as { sessionId: string };
      const onDisk = readFileSync(pickSessionFile(workdir));
      // First byte is "{" not "R" — definitely not encrypted
      expect(onDisk[0]).toBe(0x7b);
      expect(isEncryptedBlob(onDisk)).toBe(false);
      // Sanity: the JSON parses and the sessionId round-trips
      const parsed = JSON.parse(onDisk.toString('utf-8'));
      expect(parsed.sessionId).toBe(r.sessionId);
      expect(parsed.name).toBe('audit-test');
    });

    it('round-trips save → restore', async () => {
      const saved = (await runSave('rt-plain')) as { sessionId: string };
      const restored = (await runRestore(saved.sessionId)) as {
        restored?: boolean;
        name?: string;
      };
      expect(restored.restored).toBe(true);
      expect(restored.name).toBe('rt-plain');
    });
  });

  describe('encryption enabled (RFE1 wire format)', () => {
    beforeEach(() => {
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
    });

    it('writes a blob that starts with the RFE1 magic', async () => {
      await runSave('encrypted-test');
      const onDisk = readFileSync(pickSessionFile(workdir));
      expect(onDisk.subarray(0, 4)).toEqual(MAGIC);
      expect(isEncryptedBlob(onDisk)).toBe(true);
    });

    it('produces a blob that does not contain the plaintext name', async () => {
      // Defense-in-depth check: the plaintext name shouldn't appear
      // anywhere in the on-disk bytes if encryption actually ran.
      const secretName = `top-secret-${randomBytes(8).toString('hex')}`;
      await runSave(secretName);
      const onDisk = readFileSync(pickSessionFile(workdir));
      expect(onDisk.includes(Buffer.from(secretName, 'utf-8'))).toBe(false);
    });

    it('round-trips save → restore using the same key', async () => {
      const saved = (await runSave('rt-encrypted')) as { sessionId: string };
      const restored = (await runRestore(saved.sessionId)) as {
        restored?: boolean;
        name?: string;
      };
      expect(restored.restored).toBe(true);
      expect(restored.name).toBe('rt-encrypted');
    });
  });

  describe('migration: encrypt-on-write only, plaintext stays readable', () => {
    it('reads a legacy plaintext file even after encryption is enabled', async () => {
      // Step 1: save with encryption OFF → plaintext on disk
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
      const saved = (await runSave('legacy-plain')) as { sessionId: string };

      // Step 2: turn encryption ON for the read
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');

      // Step 3: restore should still find the plaintext file via the
      // magic-byte sniff (legacy file → not encrypted → returned as-is)
      const restored = (await runRestore(saved.sessionId)) as {
        restored?: boolean;
        name?: string;
      };
      expect(restored.restored).toBe(true);
      expect(restored.name).toBe('legacy-plain');
    });
  });

  describe('listSessions handles a mixed dir', () => {
    it('enumerates plaintext + encrypted sessions in one call', async () => {
      // First session: plaintext
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
      await runSave('plain-1');

      // Second session: encrypted
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
      await runSave('encrypted-1');

      const result = (await sessionListTool.handler({} as Record<string, unknown>)) as {
        sessions: Array<{ name?: string }>;
      };
      const names = result.sessions.map(s => s.name).filter(Boolean).sort();
      expect(names).toEqual(['encrypted-1', 'plain-1']);
    });
  });
});

