/**
 * Integration test for ADR-096 Phase 3: terminal-tools wired to vault.
 *
 * Mirrors session-encryption.test.ts structure: full save → on-disk →
 * load round-trip across plaintext + encrypted modes plus the migration
 * path (legacy plaintext readable after the gate flips on).
 *
 * Terminal stores are higher-stakes than session JSON because the command
 * history routinely contains pasted shell commands with credentials —
 * the on-disk-doesn't-leak-the-secret assertion is therefore stricter
 * than the equivalent session test (we plant a known credential string
 * and assert it never appears in the encrypted bytes).
 */

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomBytes } from 'node:crypto';

import { terminalTools } from '../src/mcp-tools/terminal-tools.js';
import { MAGIC, isEncryptedBlob } from '../src/encryption/vault.js';

const SAVED_ENV: Record<string, string | undefined> = {};
function saveEnv(...names: string[]) {
  for (const n of names) SAVED_ENV[n] = process.env[n];
}
function restoreEnv() {
  for (const [n, v] of Object.entries(SAVED_ENV)) {
    if (v === undefined) delete process.env[n];
    else process.env[n] = v;
  }
}

const terminalCreateTool = terminalTools.find(t => t.name === 'terminal_create')!;
const terminalListTool = terminalTools.find(t => t.name === 'terminal_list')!;

function getStoreFile(workdir: string): string {
  return join(workdir, '.claude-flow', 'terminals', 'store.json');
}

async function runCreate(name: string) {
  return terminalCreateTool.handler({ name } as Record<string, unknown>);
}

describe('terminal-tools encryption-at-rest (ADR-096 Phase 3)', () => {
  let workdir: string;
  let cwdSpy: ReturnType<typeof vi.spyOn> | null = null;

  beforeEach(() => {
    saveEnv('CLAUDE_FLOW_ENCRYPT_AT_REST', 'CLAUDE_FLOW_ENCRYPTION_KEY');
    workdir = mkdtempSync(join(tmpdir(), 'term-enc-'));
    cwdSpy = vi.spyOn(process, 'cwd').mockReturnValue(workdir);
  });

  afterEach(() => {
    cwdSpy?.mockRestore();
    rmSync(workdir, { recursive: true, force: true });
    restoreEnv();
  });

  describe('encryption disabled (legacy plaintext)', () => {
    beforeEach(() => {
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
    });

    it('writes plaintext JSON to disk', async () => {
      await runCreate('legacy-term');
      const onDisk = readFileSync(getStoreFile(workdir));
      // First byte is "{" not "R" — plaintext JSON
      expect(onDisk[0]).toBe(0x7b);
      expect(isEncryptedBlob(onDisk)).toBe(false);
      const parsed = JSON.parse(onDisk.toString('utf-8')) as {
        sessions: Record<string, { name: string }>;
      };
      const names = Object.values(parsed.sessions).map(s => s.name);
      expect(names).toContain('legacy-term');
    });

    it('round-trips create → list', async () => {
      await runCreate('rt-plain');
      const result = (await terminalListTool.handler({} as Record<string, unknown>)) as {
        sessions?: Array<{ name?: string }>;
      };
      const names = (result.sessions ?? []).map(s => s?.name).filter(Boolean);
      expect(names).toContain('rt-plain');
    });
  });

  describe('encryption enabled (RFE1 wire format)', () => {
    beforeEach(() => {
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
    });

    it('writes a blob that starts with the RFE1 magic', async () => {
      await runCreate('encrypted-term');
      const onDisk = readFileSync(getStoreFile(workdir));
      expect(onDisk.subarray(0, 4)).toEqual(MAGIC);
      expect(isEncryptedBlob(onDisk)).toBe(true);
    });

    it('does not leak the plaintext name into the on-disk bytes', async () => {
      // Defense-in-depth: terminal stores carry pasted credentials in the
      // history field. If encryption ran, NO part of the plaintext should
      // appear in the on-disk file.
      const secretName = `creds-${randomBytes(8).toString('hex')}`;
      await runCreate(secretName);
      const onDisk = readFileSync(getStoreFile(workdir));
      expect(onDisk.includes(Buffer.from(secretName, 'utf-8'))).toBe(false);
    });

    it('round-trips create → list using the same key', async () => {
      await runCreate('rt-enc');
      const result = (await terminalListTool.handler({} as Record<string, unknown>)) as {
        sessions?: Array<{ name?: string }>;
      };
      const names = (result.sessions ?? []).map(s => s?.name).filter(Boolean);
      expect(names).toContain('rt-enc');
    });
  });

  describe('migration: legacy plaintext readable after gate flips on', () => {
    it('reads a legacy plaintext store after encryption is enabled', async () => {
      // Step 1: write plaintext (gate off)
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
      await runCreate('legacy-readable');

      // Step 2: flip encryption on for the read
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');

      // Step 3: list should still find the legacy session via the
      // magic-byte sniff (legacy file → not encrypted → returned as-is)
      const result = (await terminalListTool.handler({} as Record<string, unknown>)) as {
        sessions?: Array<{ name?: string }>;
      };
      const names = (result.sessions ?? []).map(s => s?.name).filter(Boolean);
      expect(names).toContain('legacy-readable');
    });
  });

  describe('mixed: same store, plaintext write then encrypted overwrite', () => {
    it('rewrites the file as encrypted on the next write after gate flips on', async () => {
      // Step 1: legacy plaintext write
      delete process.env.CLAUDE_FLOW_ENCRYPT_AT_REST;
      delete process.env.CLAUDE_FLOW_ENCRYPTION_KEY;
      await runCreate('plain-first');
      expect(isEncryptedBlob(readFileSync(getStoreFile(workdir)))).toBe(false);

      // Step 2: enable encryption and add a second session — saveTerminalStore
      // rewrites the WHOLE file, so the result is encrypted bytes that
      // contain both sessions.
      process.env.CLAUDE_FLOW_ENCRYPT_AT_REST = '1';
      process.env.CLAUDE_FLOW_ENCRYPTION_KEY = randomBytes(32).toString('hex');
      await runCreate('encrypted-second');

      const onDisk = readFileSync(getStoreFile(workdir));
      expect(isEncryptedBlob(onDisk)).toBe(true);

      // Both sessions still visible via list (decrypts on read)
      const result = (await terminalListTool.handler({} as Record<string, unknown>)) as {
        sessions?: Array<{ name?: string }>;
      };
      const names = (result.sessions ?? []).map(s => s?.name).filter(Boolean);
      expect(names).toContain('plain-first');
      expect(names).toContain('encrypted-second');
    });
  });
});

/**
 * ADR-174 follow-up: capture FAILURES in the learning substrate.
 *
 * The DB analysis found 898 feedback records, 100% success, 0 failures — the
 * post-edit/post-task hooks recorded a hardcoded `success:true` and never
 * inspected the tool outcome, so the oracle tier had no negative examples.
 *
 * `isToolFailure()` is the detector the generated hook + the shipped
 * hook-handler.cjs both inline. It reads Claude Code's PostToolUse
 * `tool_response` and returns true only on a POSITIVE error signal.
 */
import { describe, it, expect } from 'vitest';
import { isToolFailure } from '../src/init/helpers-generator.js';

describe('isToolFailure — PostToolUse outcome detection', () => {
  it('treats missing/ambiguous payloads as success (conservative)', () => {
    expect(isToolFailure(undefined)).toBe(false);
    expect(isToolFailure(null)).toBe(false);
    expect(isToolFailure({})).toBe(false);
    expect(isToolFailure({ tool_response: null })).toBe(false);
    expect(isToolFailure({ tool_response: { content: 'edited ok' } })).toBe(false);
    expect(isToolFailure({ tool_response: 'File updated successfully' })).toBe(false);
  });

  it('detects the structured error markers Claude Code sets on tool failure', () => {
    expect(isToolFailure({ tool_response: { is_error: true, content: 'String to replace not found' } })).toBe(true);
    expect(isToolFailure({ toolResponse: { isError: true } })).toBe(true);
    expect(isToolFailure({ tool_response: { success: false } })).toBe(true);
    expect(isToolFailure({ tool_response: { error: 'ENOENT' } })).toBe(true);
  });

  it('detects a non-zero Bash exit code as failure', () => {
    expect(isToolFailure({ tool_response: { exit_code: 1 } })).toBe(true);
    expect(isToolFailure({ tool_response: { exitCode: 127 } })).toBe(true);
    expect(isToolFailure({ tool_response: { code: 2 } })).toBe(true);
    expect(isToolFailure({ tool_response: { exit_code: 0 } })).toBe(false); // success
  });

  it('detects error strings in a plain-string tool_response', () => {
    expect(isToolFailure({ tool_response: 'Error: string to replace not found in file' })).toBe(true);
    expect(isToolFailure({ result: 'bash: command not found' })).toBe(true);
    expect(isToolFailure({ tool_response: 'Traceback (most recent call last):' })).toBe(true);
    expect(isToolFailure({ tool_response: 'permission denied' })).toBe(true);
  });

  it('does not false-positive on benign content that merely mentions success', () => {
    expect(isToolFailure({ tool_response: 'Successfully wrote 42 lines' })).toBe(false);
    expect(isToolFailure({ tool_response: { content: [{ type: 'text', text: 'done' }] } })).toBe(false);
  });
});

/**
 * Tests for the MAGE-style execution-state-tree prototype
 * (src/ruvector/trajectory-tree.ts) and its opt-in MCP surface
 * (hooks_intelligence_pattern-search strategy:"state-tree").
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { TrajectoryTree, getTrajectoryTree, resetTrajectoryTree } from '../src/ruvector/trajectory-tree.js';
import { hooksPatternSearch } from '../src/mcp-tools/hooks-tools.js';

let dir: string;
let persistPath: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), 'traj-tree-'));
  persistPath = join(dir, 'tree.json');
  resetTrajectoryTree();
});

afterEach(() => {
  resetTrajectoryTree();
  rmSync(dir, { recursive: true, force: true });
});

function buildThreeLevelTrajectory(tree: TrajectoryTree) {
  // Level 1: session root, Level 2: trajectory, Level 3: steps
  tree.openTrajectory({ sessionId: 'sess-1', trajectoryId: 'traj-A', task: 'Build the feature', agent: 'coder' });
  tree.appendStep({ trajectoryId: 'traj-A', stepId: 'step-1', action: 'read spec', quality: 0.9 });
  tree.appendStep({ trajectoryId: 'traj-A', stepId: 'step-2', action: 'write module', quality: 0.8 });
  tree.appendStep({ trajectoryId: 'traj-A', stepId: 'step-3', action: 'run tests', quality: 0.95 });
}

describe('TrajectoryTree — recallPath', () => {
  it('returns the exact root→current path for a synthetic 3-level trajectory', () => {
    const tree = new TrajectoryTree(persistPath);
    buildThreeLevelTrajectory(tree);

    const recall = tree.recallPath({ sessionId: 'sess-1' });
    expect(recall.path.map(n => n.id)).toEqual(['session:sess-1', 'traj-A', 'step-3']);
    expect(recall.path.map(n => n.kind)).toEqual(['session', 'trajectory', 'step']);
    expect(recall.currentId).toBe('step-3');
    expect(recall.strategy).toBe('state-tree');
  });

  it('returns recent siblings of the current node (oldest→newest, windowed)', () => {
    const tree = new TrajectoryTree(persistPath);
    buildThreeLevelTrajectory(tree);

    const recall = tree.recallPath({ sessionId: 'sess-1', siblingWindow: 2 });
    expect(recall.siblings.map(n => n.id)).toEqual(['step-1', 'step-2']);
  });

  it('honors depth (deepest levels win)', () => {
    const tree = new TrajectoryTree(persistPath);
    buildThreeLevelTrajectory(tree);

    const recall = tree.recallPath({ sessionId: 'sess-1', depth: 2 });
    expect(recall.path.map(n => n.id)).toEqual(['traj-A', 'step-3']);
  });

  it('nests a trajectory started while another is open, and pops on close', () => {
    const tree = new TrajectoryTree(persistPath);
    tree.openTrajectory({ sessionId: 'sess-1', trajectoryId: 'traj-outer', task: 'outer task' });
    tree.openTrajectory({ sessionId: 'sess-1', trajectoryId: 'traj-inner', task: 'inner sub-task' });
    tree.appendStep({ trajectoryId: 'traj-inner', stepId: 'step-i1', action: 'inner work' });

    let recall = tree.recallPath({ sessionId: 'sess-1' });
    expect(recall.path.map(n => n.id)).toEqual(['session:sess-1', 'traj-outer', 'traj-inner', 'step-i1']);

    tree.closeTrajectory({ trajectoryId: 'traj-inner', success: true });
    recall = tree.recallPath({ sessionId: 'sess-1' });
    expect(recall.currentId).toBe('traj-outer');
    expect(recall.path.map(n => n.id)).toEqual(['session:sess-1', 'traj-outer']);
  });

  it('returns an empty path for an unknown session', () => {
    const tree = new TrajectoryTree(persistPath);
    const recall = tree.recallPath({ sessionId: 'nope' });
    expect(recall.path).toEqual([]);
    expect(recall.siblings).toEqual([]);
    expect(recall.currentId).toBeNull();
  });
});

describe('TrajectoryTree — persistence', () => {
  it('round-trips through the JSON snapshot', () => {
    const tree = new TrajectoryTree(persistPath);
    buildThreeLevelTrajectory(tree);
    tree.closeTrajectory({ trajectoryId: 'traj-A', success: true });

    const reloaded = new TrajectoryTree(persistPath);
    expect(reloaded.size).toBe(tree.size);
    const recall = reloaded.recallPath({ sessionId: 'sess-1' });
    // current popped to the trajectory's parent (the session root) on close
    expect(recall.currentId).toBe('session:sess-1');
    expect(recall.path.map(n => n.id)).toEqual(['session:sess-1']);
    // …and the closed trajectory survived the round-trip with its metadata
    const reloadedRecall = reloaded.recallPath({ sessionId: 'sess-1', depth: 1 });
    expect(reloadedRecall.path[0].kind).toBe('session');
  });
});

describe('hooks_intelligence_pattern-search — strategy flag', () => {
  it('default strategy is untouched (no state-tree fields in the response)', async () => {
    // Seed the singleton with a tmp persist path so nothing touches the repo.
    getTrajectoryTree(persistPath);
    const result = await hooksPatternSearch.handler({ query: 'authentication patterns' }) as Record<string, unknown>;
    expect(result.backend).not.toBe('state-tree');
    expect(result.path).toBeUndefined();
    expect(result.strategy).toBeUndefined();
    expect(Array.isArray(result.results)).toBe(true);
  });

  it('strategy:"state-tree" returns the positional path without embedding search', async () => {
    const tree = getTrajectoryTree(persistPath);
    buildThreeLevelTrajectory(tree);

    const result = await hooksPatternSearch.handler({
      query: 'irrelevant for positional recall',
      strategy: 'state-tree',
      sessionId: 'sess-1',
    }) as Record<string, unknown>;

    expect(result.backend).toBe('state-tree');
    expect(result.strategy).toBe('state-tree');
    const path = result.path as Array<{ id: string }>;
    expect(path.map(n => n.id)).toEqual(['session:sess-1', 'traj-A', 'step-3']);
    expect(result.currentId).toBe('step-3');
  });
});

