/**
 * Regression test for audit_1776853149979: terminal_create previously merged
 * caller-supplied env straight into execSync's environment for every command
 * in the session. Setting LD_PRELOAD or NODE_OPTIONS via that path was
 * functionally RCE on the host. validateEnv enforces a denylist + POSIX
 * shape — these tests pin the contract so the denylist can't silently
 * regress.
 */

import { describe, it, expect } from 'vitest';
import { validateEnv } from '../src/mcp-tools/validate-input.js';

describe('validateEnv (audit_1776853149979)', () => {
  describe('happy path', () => {
    it('accepts undefined / null as empty env', () => {
      expect(validateEnv(undefined)).toEqual({ valid: true, sanitized: {} });
      expect(validateEnv(null)).toEqual({ valid: true, sanitized: {} });
    });

    it('accepts an empty object', () => {
      expect(validateEnv({})).toEqual({ valid: true, sanitized: {} });
    });

    it('passes through a valid env unchanged', () => {
      const r = validateEnv({ FOO: 'bar', MY_VAR: '1', _UNDERSCORE: 'ok' });
      expect(r.valid).toBe(true);
      expect(r.sanitized).toEqual({ FOO: 'bar', MY_VAR: '1', _UNDERSCORE: 'ok' });
    });
  });

  describe('loader-hijack denylist', () => {
    // Names that let an attacker hijack a child process before any user code
    // runs. Each MUST be rejected — adding an exemption is a real CVE.
    const denylisted = [
      'LD_PRELOAD',
      'LD_LIBRARY_PATH',
      'LD_AUDIT',
      'DYLD_INSERT_LIBRARIES',
      'DYLD_LIBRARY_PATH',
      'DYLD_FALLBACK_LIBRARY_PATH',
      'DYLD_FORCE_FLAT_NAMESPACE',
      'NODE_OPTIONS',
      'NODE_PATH',
    ];

    for (const name of denylisted) {
      it(`rejects ${name}`, () => {
        const r = validateEnv({ [name]: '/tmp/whatever' });
        expect(r.valid).toBe(false);
        expect(r.error).toContain(name);
        expect(r.error).toContain('denylisted');
        expect(r.sanitized).toEqual({});
      });
    }
  });

  describe('shape validation', () => {
    it('rejects a name containing =', () => {
      const r = validateEnv({ 'A=B': 'x' });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('not a valid POSIX env name');
    });

    it('rejects a digit-first name', () => {
      const r = validateEnv({ '1FOO': 'x' });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('not a valid POSIX env name');
    });

    it('rejects a name with whitespace', () => {
      const r = validateEnv({ 'BAD NAME': 'x' });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('not a valid POSIX env name');
    });

    it('rejects an array (not an object)', () => {
      const r = validateEnv(['FOO', 'BAR'] as unknown);
      expect(r.valid).toBe(false);
      expect(r.error).toContain('object of string→string');
    });

    it('rejects a non-string value', () => {
      const r = validateEnv({ FOO: 42 });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('FOO');
      expect(r.error).toContain('must be a string');
    });

    it('rejects a value with a null byte', () => {
      const value = ['a', String.fromCharCode(0), 'b'].join('');
      const r = validateEnv({ FOO: value });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('null byte');
    });

    it('rejects a value over 32K', () => {
      const r = validateEnv({ FOO: 'x'.repeat(40_000) });
      expect(r.valid).toBe(false);
      expect(r.error).toContain('exceeds 32768');
    });
  });
});

/**
 * Regression test for #2352 (Bug A): validatePath used to reject every
 * absolute Windows path because backslash was in the general SHELL_META set.
 * Claude Code hook events deliver absolute paths in `tool_input.file_path`,
 * so every forwarded `hooks post-edit` call failed on Windows — and Bug B
 * hid the failure behind a "[OK]" log.
 *
 * Pin the contract: Windows-shaped paths are accepted, dangerous shell
 * metacharacters and path traversal are still rejected.
 */

import { describe, it, expect } from 'vitest';
import { validatePath } from '../src/mcp-tools/validate-input.js';

describe('validatePath (#2352)', () => {
  describe('Windows paths (the regression)', () => {
    it('accepts an absolute Windows path with a drive letter', () => {
      const r = validatePath('E:\\Repos\\my-app\\middleware.ts', 'filePath');
      expect(r.valid).toBe(true);
      // Sanitized form normalizes backslashes to forward slashes
      expect(r.sanitized).toBe('E:/Repos/my-app/middleware.ts');
    });

    it('accepts a UNC-style Windows path', () => {
      const r = validatePath('\\\\server\\share\\file.txt', 'filePath');
      expect(r.valid).toBe(true);
    });

    it('accepts mixed separators', () => {
      const r = validatePath('C:\\Users\\ruv/Projects\\ruflo/file.ts', 'filePath');
      expect(r.valid).toBe(true);
    });
  });

  describe('POSIX paths (must keep working)', () => {
    it('accepts a relative forward-slash path', () => {
      const r = validatePath('app/page.tsx', 'filePath');
      expect(r.valid).toBe(true);
      expect(r.sanitized).toBe('app/page.tsx');
    });

    it('accepts an absolute POSIX path', () => {
      const r = validatePath('/home/ruv/repo/src/file.ts', 'filePath');
      expect(r.valid).toBe(true);
    });
  });

  describe('still rejects dangerous input', () => {
    it('rejects path traversal with forward slashes', () => {
      const r = validatePath('../etc/passwd', 'filePath');
      expect(r.valid).toBe(false);
      expect(r.error).toMatch(/path traversal/);
    });

    it('rejects path traversal with backslashes (Windows form)', () => {
      const r = validatePath('..\\windows\\system32\\config', 'filePath');
      expect(r.valid).toBe(false);
      expect(r.error).toMatch(/path traversal/);
    });

    it.each([
      ['semicolon', 'foo;rm -rf /'],
      ['pipe',      'foo|cat /etc/passwd'],
      ['ampersand', 'foo&calc.exe'],
      ['backtick',  'foo`whoami`'],
      ['dollar',    'foo$BAR'],
      ['parens',    'foo$(echo bar)'],
      ['braces',    'foo{a,b}.txt'],
      ['brackets',  'foo[1].txt'],
      ['redirect',  'foo>out.txt'],
      ['append',    'foo<in.txt'],
      ['bang',      'foo!bar'],
      ['hash',      'foo#bar'],
    ])('rejects %s in path', (_label, value) => {
      const r = validatePath(value, 'filePath');
      expect(r.valid).toBe(false);
      expect(r.error).toMatch(/shell metacharacters/);
    });

    it('rejects an empty string', () => {
      expect(validatePath('', 'filePath').valid).toBe(false);
    });

    it('rejects non-string input', () => {
      expect(validatePath(null, 'filePath').valid).toBe(false);
      expect(validatePath(undefined, 'filePath').valid).toBe(false);
      expect(validatePath(42, 'filePath').valid).toBe(false);
    });

    it('rejects an over-long path', () => {
      const long = 'a/'.repeat(2500) + 'file.ts';
      expect(validatePath(long, 'filePath').valid).toBe(false);
    });
  });
});

/**
 * Regression: statusline "Vectors ●0" despite thousands of real vectors.
 *
 * Root cause (two layers):
 *   1. DISPLAY — the statusline fetched the vector count and the HNSW row count
 *      in ONE combined SQL statement. On a DB with no `vector_indexes` table
 *      (older CLI / agentdb-written DBs), the statement failed at PREPARE time
 *      and the valid `memory_entries` count was discarded too → shown as 0.
 *   2. DATA — such a DB genuinely lacks the `vector_indexes` table + per-
 *      namespace rows, so the HNSW flag and #1941 namespace routing break.
 *
 * Fix: statusline splits the two counts (covered by statusline-generator), and
 * `repairVectorIndexes()` self-heals the DB on init / MCP start. This test
 * pins the DATA-layer self-heal: a `vector_indexes`-less DB with embedded rows
 * is provisioned + backfilled idempotently, and the read-only queries the
 * statusline runs then return the real count (never zero) with the HNSW flag up.
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { mkdtempSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

import { repairVectorIndexes, recoverMemoryDatabase } from '../src/memory/memory-initializer.js';

// better-sqlite3 is the same engine the repair uses; skip the suite if the
// native module can't load on this host (WASM-only) — the repair no-ops there.
let Database: any;
let haveNative = false;
try { Database = (await import('better-sqlite3')).default; haveNative = true; } catch { haveNative = false; }

/** Build a DB that mimics an old install: memory_entries with embeddings, NO vector_indexes. */
function seedLegacyDb(dbPath: string): void {
  const db = new Database(dbPath);
  db.exec(`CREATE TABLE memory_entries (
    id TEXT PRIMARY KEY, key TEXT, namespace TEXT DEFAULT 'default',
    content TEXT, embedding TEXT, status TEXT DEFAULT 'active'
  )`);
  const ins = db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)');
  const vec = JSON.stringify(Array.from({ length: 8 }, (_, i) => i / 8));
  // 3 in 'commands', 2 in 'feedback', 1 with NO embedding (must not be counted)
  ins.run('a', 'k1', 'commands', 'alpha', vec);
  ins.run('b', 'k2', 'commands', 'beta', vec);
  ins.run('c', 'k3', 'commands', 'gamma', vec);
  ins.run('d', 'k4', 'feedback', 'delta', vec);
  ins.run('e', 'k5', 'feedback', 'epsilon', vec);
  ins.run('f', 'k6', 'commands', 'no-embedding', null);
  db.close();
}

describe.skipIf(!haveNative)('repairVectorIndexes — self-heal missing vector_indexes', () => {
  let workdir: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'vidx-heal-'));
  });

  it('provisions vector_indexes and backfills accurate per-namespace counts', async () => {
    const dbPath = join(workdir, 'legacy.db');
    seedLegacyDb(dbPath);

    // Precondition: table genuinely absent.
    const pre = new Database(dbPath);
    const preCount = pre.prepare("SELECT COUNT(*) AS c FROM sqlite_master WHERE type='table' AND name='vector_indexes'").get() as { c: number };
    expect(preCount.c).toBe(0);
    pre.close();

    const res = await repairVectorIndexes(dbPath);
    expect(res.tableCreated).toBe(true);
    expect(res.repaired).toBe(true);
    expect(res.namespaces.sort()).toEqual(['commands', 'feedback']);

    // total_vectors reflects ONLY embedded rows (the null-embedding row excluded).
    const db = new Database(dbPath);
    const counts = Object.fromEntries(
      (db.prepare('SELECT name, total_vectors FROM vector_indexes').all() as Array<{ name: string; total_vectors: number }>)
        .map(r => [r.name, r.total_vectors]),
    );
    expect(counts.commands).toBe(3);
    expect(counts.feedback).toBe(2);
    // Fresh-install parity seed rows exist too.
    expect(counts.default).toBeDefined();
    expect(counts.patterns).toBeDefined();
    db.close();
  });

  it('the read-only queries the statusline runs now return the real count + HNSW flag', async () => {
    const dbPath = join(workdir, 'statusline.db');
    seedLegacyDb(dbPath);
    await repairVectorIndexes(dbPath);

    const db = new Database(dbPath, { readonly: true });
    // Statusline query 1 (count) — always worked, must be non-zero.
    const c = db.prepare("SELECT COUNT(*) AS c FROM memory_entries WHERE embedding IS NOT NULL").get() as { c: number };
    expect(c.c).toBe(5);
    // Statusline query 2 (HNSW flag) — now succeeds (table present) and is > 0.
    const h = db.prepare('SELECT COUNT(*) AS c FROM vector_indexes').get() as { c: number };
    expect(h.c).toBeGreaterThan(0);
    db.close();
  });

  it('is idempotent — a second run is a clean no-op (no writes) once healed', async () => {
    const dbPath = join(workdir, 'idem.db');
    seedLegacyDb(dbPath);
    const first = await repairVectorIndexes(dbPath);
    expect(first.repaired).toBe(true);
    // Already healed: table exists and every embedded namespace has a row, so
    // the second run must NOT write (avoids touching the live DB every start).
    const second = await repairVectorIndexes(dbPath);
    expect(second.tableCreated).toBe(false);
    expect(second.repaired).toBe(false);
    expect(second.namespaces).toEqual([]);

    // Counts from the first heal remain correct.
    const db = new Database(dbPath);
    const commands = db.prepare("SELECT total_vectors AS t FROM vector_indexes WHERE name='commands'").get() as { t: number };
    expect(commands.t).toBe(3);
    db.close();
  });

  it('is a safe no-op when the DB file does not exist', async () => {
    const res = await repairVectorIndexes(join(workdir, 'nope-does-not-exist.db'));
    expect(res.repaired).toBe(false);
    expect(res.tableCreated).toBe(false);
    expect(res.namespaces).toEqual([]);
  });

  it('is a safe no-op when memory_entries is absent (nothing to key off)', async () => {
    const dbPath = join(workdir, 'empty.db');
    const db = new Database(dbPath);
    db.exec('CREATE TABLE unrelated (x INTEGER)');
    db.close();
    const res = await repairVectorIndexes(dbPath);
    expect(res.repaired).toBe(false);
    expect(res.tableCreated).toBe(false);
  });
});

describe.skipIf(!haveNative)('recoverMemoryDatabase — auto-recover a corrupt memory DB', () => {
  let workdir: string;

  beforeAll(() => {
    workdir = mkdtempSync(join(tmpdir(), 'vidx-recover-'));
  });

  /** Write many rows so the b-tree spans multiple pages, then scribble a page to corrupt it. */
  function seedAndCorrupt(dbPath: string): { rows: number } {
    const db = new Database(dbPath);
    db.pragma('journal_mode = DELETE'); // single-file, no WAL — simpler to corrupt deterministically
    db.pragma('page_size = 4096');
    db.exec(`CREATE TABLE memory_entries (
      id TEXT PRIMARY KEY, key TEXT, namespace TEXT DEFAULT 'default',
      content TEXT, embedding TEXT, status TEXT DEFAULT 'active'
    )`);
    db.exec("CREATE TABLE skills (id TEXT PRIMARY KEY, body TEXT)");
    const ins = db.prepare('INSERT INTO memory_entries (id, key, namespace, content, embedding) VALUES (?,?,?,?,?)');
    const vec = JSON.stringify(Array.from({ length: 8 }, (_, i) => i / 8));
    const N = 500;
    const many = db.transaction(() => {
      for (let i = 0; i < N; i++) {
        ins.run('id' + i, 'k' + i, i % 2 ? 'commands' : 'feedback', 'content number ' + i + ' '.repeat(40), vec);
      }
    });
    many();
    db.close();

    // Scribble over a page in the middle of the file to induce b-tree corruption
    // that quick_check detects but that leaves most rows individually readable.
    const buf = readFileSync(dbPath);
    const pageSize = 4096;
    const targetPage = 6; // past the schema/first pages, into memory_entries data
    const off = targetPage * pageSize + 16;
    for (let i = 0; i < 80; i++) buf[off + i] = 0x00;
    writeFileSync(dbPath, buf);
    return { rows: N };
  }

  it('backs up, rebuilds, verifies, and atomically swaps a corrupt DB', async () => {
    const dbPath = join(workdir, 'corrupt.db');
    const { rows } = seedAndCorrupt(dbPath);

    // Precondition: quick_check must now report corruption.
    const pre = new Database(dbPath);
    const qc = String(pre.pragma('quick_check(1)', { simple: true }));
    pre.close();
    // If our synthetic corruption didn't take on this SQLite build, skip rather
    // than assert a false negative — the recovery path is still exercised below.
    if (qc.toLowerCase() === 'ok') return;

    const rec = await recoverMemoryDatabase(dbPath, { verbose: false });
    expect(rec.recovered).toBe(true);
    expect(rec.backupPath).toBeTruthy();
    expect(existsSync(rec.backupPath!)).toBe(true); // corrupt original preserved

    // The swapped-in DB is clean and retains the readable rows.
    const db = new Database(dbPath, { readonly: true });
    expect(String(db.pragma('integrity_check', { simple: true })).toLowerCase()).toBe('ok');
    const c = (db.prepare('SELECT COUNT(*) AS c FROM memory_entries').get() as { c: number }).c;
    expect(c).toBeGreaterThan(0);
    expect(c).toBeLessThanOrEqual(rows);
    db.close();
  });

  it('is a no-op on a healthy DB (never rewrites a good database)', async () => {
    const dbPath = join(workdir, 'healthy.db');
    const db = new Database(dbPath);
    db.exec("CREATE TABLE memory_entries (id TEXT PRIMARY KEY, content TEXT)");
    db.prepare('INSERT INTO memory_entries VALUES (?, ?)').run('a', 'hello');
    db.close();

    const rec = await recoverMemoryDatabase(dbPath);
    expect(rec.recovered).toBe(false);
    expect(rec.reason).toBe('not-corrupt');
  });

  it('repairVectorIndexes({autoRecover}) recovers then heals in one call', async () => {
    const dbPath = join(workdir, 'corrupt-autoheal.db');
    const { rows } = seedAndCorrupt(dbPath);
    const pre = new Database(dbPath);
    const qc = String(pre.pragma('quick_check(1)', { simple: true }));
    pre.close();
    if (qc.toLowerCase() === 'ok') return; // synthetic corruption didn't take — skip

    const out = await repairVectorIndexes(dbPath, { autoRecover: true });
    expect(out.corrupt).toBe(true);
    expect(out.recovered).toBe(true);
    // After recovery it provisioned vector_indexes on the clean rebuild.
    const db = new Database(dbPath, { readonly: true });
    expect(String(db.pragma('integrity_check', { simple: true })).toLowerCase()).toBe('ok');
    const vidx = (db.prepare('SELECT COUNT(*) AS c FROM vector_indexes').get() as { c: number }).c;
    expect(vidx).toBeGreaterThan(0);
    db.close();
    expect(rows).toBe(500);
  });
});

/**
 * `ruflo version` — ANV (Agent-Native Versioning) Phase 1.
 * https://gist.github.com/ruvnet/0d858ad440a4439b4a2281a40c39b1a0
 *
 * Black-box against the real built CLI binary (same pattern as
 * security-scan-persistence.test.ts) since the command's manifest
 * resolution walks real package/dev-checkout paths — reconstructing that
 * via mocks would test the mock, not the resolution logic.
 */
import { describe, it, expect } from 'vitest';
import { execFileSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { buildAdvisorySuffix } from '../src/commands/version.js';

const CLI_BIN = fileURLToPath(new URL('../bin/cli.js', import.meta.url));
const CLI_BUILT = existsSync(CLI_BIN);
const MANIFEST_PATH = fileURLToPath(new URL('../catalog-manifest.json', import.meta.url));

function cli(args: string[]): { out: string; code: number } {
  try {
    const out = execFileSync(process.execPath, [CLI_BIN, ...args], { encoding: 'utf-8', timeout: 15_000 });
    return { out, code: 0 };
  } catch (e) {
    const err = e as { stdout?: string; status?: number };
    return { out: err.stdout ?? '', code: err.status ?? 1 };
  }
}

describe('buildAdvisorySuffix — pure function', () => {
  it('omits the hal segment when no benchmark exists', () => {
    const suffix = buildAdvisorySuffix({
      schemaVersion: 1, generation: 5, generatedAt: '2026-01-01T00:00:00.000Z',
      gitSha: 'abc12345', catalog: { agents: 1, tools: 2, skills: 3 }, benchmark: null,
    });
    expect(suffix).toBe('+ad.1.gabc12345.cat5');
  });

  it('appends the hal segment only when a real benchmark is present', () => {
    const suffix = buildAdvisorySuffix({
      schemaVersion: 1, generation: 5, generatedAt: '2026-01-01T00:00:00.000Z',
      gitSha: 'abc12345', catalog: { agents: 1, tools: 2, skills: 3 },
      benchmark: { tier: 74, verifiedAt: '2026-01-01T00:00:00.000Z' },
    }, 2);
    expect(suffix).toBe('+ad.2.gabc12345.cat5.hal74');
  });

  it('is legal semver build metadata — starts with a bare "+", npm-range-safe', () => {
    const suffix = buildAdvisorySuffix({
      schemaVersion: 1, generation: 1, generatedAt: '2026-01-01T00:00:00.000Z',
      gitSha: 'deadbeef', catalog: { agents: 0, tools: 0, skills: 0 }, benchmark: null,
    });
    expect(suffix.startsWith('+')).toBe(true);
    expect(suffix).not.toMatch(/[^a-z0-9.+-]/i);
  });
});

describe.skipIf(!CLI_BUILT)('ruflo version — CLI black-box', () => {
  it('bare "version" prints plain semver, no suffix', () => {
    const { out, code } = cli(['version']);
    expect(code).toBe(0);
    expect(out.trim()).toMatch(/^\d+\.\d+\.\d+$/);
  });

  it('bare "--version" global flag is unaffected by ANV (still plain semver)', () => {
    const { out, code } = cli(['--version']);
    expect(code).toBe(0);
    expect(out).toMatch(/v\d+\.\d+\.\d+/);
    expect(out).not.toContain('+ad.');
  });

  it('"version --explain" renders the catalog breakdown when catalog-manifest.json exists', () => {
    if (!existsSync(MANIFEST_PATH)) return; // dev checkout without a generated manifest — see next test
    const { out, code } = cli(['version', '--explain']);
    expect(code).toBe(0);
    expect(out).toContain('Era:       AD (Agent Descent)');
    expect(out).toMatch(/Catalog:\s+generation \d+ \(agents: \d+ types, tools: \d+ MCP, skills: \d+\)/);
    expect(out).toContain('+ad.1.g');
  });

  it('catalog-manifest.json counts are real numbers, never fabricated benchmark data', () => {
    if (!existsSync(MANIFEST_PATH)) return;
    const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf-8'));
    expect(manifest.catalog.agents).toBeGreaterThan(0);
    expect(manifest.catalog.tools).toBeGreaterThan(0);
    expect(manifest.catalog.skills).toBeGreaterThan(0);
    // No benchmark tier without a real signed submission for this generation.
    if (manifest.benchmark !== null) {
      expect(manifest.benchmark).toHaveProperty('tier');
      expect(manifest.benchmark).toHaveProperty('verifiedAt');
    }
  });

  it('"--require-catalog-gte" gates cleanly: pass at/under, fail over', () => {
    if (!existsSync(MANIFEST_PATH)) return;
    const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf-8'));
    const under = cli(['version', '--require-catalog-gte', String(manifest.generation)]);
    expect(under.code).toBe(0);
    expect(under.out).toContain('OK');

    const over = cli(['version', '--require-catalog-gte', String(manifest.generation + 1000)]);
    expect(over.code).toBe(1);
  });
});

